// Content for Raising Neurodiverse Kids (node g67, Parent Layer, Chapter 8): NEW v2 build to GDD 67
// (mechanic-embodying), a Parent-Layer pillar and a warm callback to Same Same, Different (g04): difference is
// wonderful, grown up for parents. It reframes neurodivergence as DIFFERENCE, not deficiency: strengths-first and
// never deficit-shaming. 84 researched, India-grounded scenarios across understand-your-child → accommodate →
// advocate → drop-the-shame → strengths-and-wellbeing → support-and-you, each encoded as one of the shared v2 play
// actions (strike-rewrite / branch / sort / reflect / match / role-play / spot): no binary "tap the right card".
// Lead: strike-rewrite (bust the myth), branch (your move), sort. Six modes: understand your child (the common
// neurodivergences, strengths-first, your child's own profile & pace; different, not less; brains naturally vary),
// accommodate (adjust the environment & expectations to the child rather than forcing them to mask; sensory,
// attention, transitions, routines; accommodations give fair access like glasses, they don't spoil), advocate (you
// are your child's key advocate; school accommodations, family understanding, services: with rights under the
// Rights of Persons with Disabilities Act 2016, which recognises autism & learning disabilities and mandates
// reasonable accommodation; seek assessment without shame), drop the shame and blame (it's no one's fault: NOT
// caused by parenting, screens or vaccines; meltdowns are overwhelm not naughtiness; you don't grow out of it;
// stop hiding it), strengths and wellbeing (build on strengths & passions, meet meltdowns with calm co-regulation
// not punishment, take co-occurring anxiety seriously, see the whole wonderful child not a label), support and you
// (parent wellbeing matters and it is demanding: lean on peer parents & professionals; routes parent burnout to
// Looking After You g63). Strengths-based and NEVER deficit-shaming, never blaming parent or child, accurate &
// expert-reviewed; NOT a diagnostic tool: points to professionals. Builds on Same Same, Different (g04); a
// Parent-Layer pillar alongside Break the Cycle (g65) and Raising Gender-Diverse Kids (g66). India: neurodiversity
// is heavily stigmatised & under-recognised, with delayed diagnoses often blamed on parenting and school
// accommodations a fight: the node de-stigmatises, helps parents seek assessment & support without shame, and
// points to rights under the RPwD Act 2016. gameId "raising-neurodiverse-kids".
import type { V2GameConfig, Scenario } from "./v2-schema";

const SCENARIOS: Scenario[] = [
  {"id":"nd-001","cat":"understand-your-child","type":"strike-rewrite","hook":"\"A neurodiverse child is broken or less than other children.\"","myth":{"un":"A neurodiverse child is broken or less than other children.","re":"Neurodivergence is a different way a brain is wired, not a fault or a lesser version; different, not less.","why":"Different wiring isn't damaged wiring."},"relearn":"A neurodiverse child isn't broken or less; their brain is wired differently, different, not less.","persona":"Meena","source":"different not less"},
  {"id":"nd-002","cat":"understand-your-child","type":"strike-rewrite","hook":"\"Autism, ADHD and dyslexia are just labels for naughty or lazy kids.\"","myth":{"un":"Autism, ADHD and dyslexia are just labels for naughty or lazy kids.","re":"They're real, recognised ways of being and learning, not naughtiness or laziness; understanding them changes everything.","why":"A profile isn't a character flaw."},"relearn":"Autism, ADHD and dyslexia are real ways of being and learning, not naughtiness or laziness.","persona":"Meena","source":"real not naughty"},
  {"id":"nd-003","cat":"understand-your-child","type":"reflect","hook":"Lensy: understanding how your child is actually wired is the first, biggest act of love. Sit right?","prompt":"What do you think?","options":["Sits right","Understand first","Act of love"],"affirm":"Truly understanding how your child is wired, rather than judging them by a typical template, is a foundational act of love.","relearn":"Understanding how your child is actually wired is the first, biggest act of love.","persona":"Meena","source":"understand first"},
  {"id":"nd-004","cat":"understand-your-child","type":"sort","hook":"Sort: a strength a neurodiverse child may bring, or a 'deficit' the old view focuses on?","items":[{"id":"a","text":"Deep focus on a passion"},{"id":"b","text":"Only 'won't sit still'"},{"id":"c","text":"Pattern-spotting and memory"},{"id":"d","text":"Only 'can't pay attention'"},{"id":"e","text":"Honest, says what's true"},{"id":"f","text":"Only 'always in his own world'"}],"bins":[{"id":"strength","label":"A real strength","valence":"pos"},{"id":"deficit","label":"The deficit-only view","valence":"neg"}],"key":{"a":"strength","b":"deficit","c":"strength","d":"deficit","e":"strength","f":"deficit"},"relearn":"Deep focus, pattern-spotting and honesty are real strengths; 'won't sit still, can't focus, own world' sees only deficits.","persona":"any","source":"strength vs deficit"},
  {"id":"nd-005","cat":"understand-your-child","type":"match","hook":"Match each neurodivergence to a common strength (every child is individual).","pairs":[{"left":"Autism","right":"Deep focus, honesty, pattern recognition"},{"left":"ADHD","right":"Energy, creativity, quick thinking"},{"left":"Dyslexia","right":"Big-picture and spatial thinking"},{"left":"Dyspraxia","right":"Creative, determined problem-solving"},{"left":"Dyscalculia","right":"Strong words and storytelling"}],"relearn":"Autism, ADHD, dyslexia and other profiles each commonly come with real strengths, though every child's profile is their own.","persona":"any","source":"strengths by profile"},
  {"id":"nd-006","cat":"understand-your-child","type":"branch","persona":"Divya","source":"their own pace","hook":"Your child grows at their own pace, but checking milestone charts has become a nightly habit.","steps":[{"prompt":"Tonight the chart shows another unticked line, and your worry grows. What do you do?","options":[{"text":"Keep scanning for what they haven't done yet","then":"You tick and cross each line. The crosses pile up, and it is past midnight."},{"text":"Message a friend whose child is the same age","then":"Your friend replies with her child's new words. You feel more behind than before."},{"text":"Close it and note what your child does well","then":"You list three things. One is that they hum every tune they hear.","best":true},{"text":"Book an extra class so they catch up quickly","then":"The class is costly and starts next week. Your child asks why they have to go."}],"why":"Noting your child's own strengths gives a truer picture than a chart does."},{"prompt":"At a family function, an aunt says her grandson already writes his name. How do you respond?","options":[{"text":"Say they will catch up soon","then":"The aunt smiles. You feel pressure to make it true."},{"text":"Change the subject and leave early","then":"You reach home sooner, but the comparison follows you in your head."},{"text":"Agree and say you are worried too","then":"The aunt sighs and lists tutors. Your worry deepens."},{"text":"Share one thing your child loves and say they go at their own pace","then":"The aunt listens, then asks what they enjoy. The talk turns kinder.","best":true}],"why":"Speaking of their pace and joys shields your child and shifts the talk."},{"prompt":"At bedtime, your partner asks how your child is really doing. What do you share?","options":[{"text":"Which milestones they still haven't reached","then":"Your partner grows quiet. The night ends on a worried note."},{"text":"That they are fine, so there's no need to discuss it","then":"Your partner turns off the light. You are alone with your worries again."},{"text":"That other children are ahead, but it's fine","then":"Your partner asks: \"Ahead of what?\" Neither of you has an answer."},{"text":"What they enjoyed today","then":"Your partner smiles. \"Tell me more. I missed that.\"","best":true}],"why":"Sharing real moments keeps both of you seeing your actual child."},{"prompt":"A month later, the school asks for a chat about your child's progress. What do you do?","options":[{"text":"Ask the teacher how they compare with the class","then":"The teacher shows a class chart. Your child sits low on it and your chest tightens."},{"text":"Skip it, since nothing new will come out","then":"The school assumes all is well. Your child's needs go unspoken."},{"text":"Ask for a plan to speed them up to catch the class","then":"The teacher hesitates. \"I can add homework. Is that what they need?\""},{"text":"Bring notes on their strengths and pace, and ask what fits","then":"The teacher reads them. \"This is useful. We can plan around it.\"","best":true}],"why":"Your notes on their profile help the school support them, not just measure them."}],"debrief":"Support your child's own profile and pace, not a typical template; if worries persist, a qualified professional can help.","relearn":"Meet your actual child's profile and pace, not a one-size template that misses them."},
  {"id":"nd-007","cat":"understand-your-child","type":"strike-rewrite","hook":"\"There's one normal way for a child's brain to work, and my child should fit it.\"","myth":{"un":"There's one normal way for a child's brain to work, and my child should fit it.","re":"Brains naturally vary; neurodiversity is part of human variation, and your child's way of thinking is valid.","why":"Variation is the norm, not the exception."},"relearn":"There's no single 'normal' brain; neurodiversity is natural human variation, and your child's mind is valid.","persona":"Meena","source":"variation is natural"},
  {"id":"nd-008","cat":"understand-your-child","type":"reflect","hook":"Lensy: when you see your child's strengths, not just their struggles, you change how they see themselves. Resonate?","prompt":"What's your take?","options":["Resonates","See strengths","Changes them"],"affirm":"Seeing a neurodiverse child's strengths, not only their struggles, shapes how they come to see themselves.","relearn":"When you see your child's strengths, not just struggles, you change how they see themselves.","persona":"Meena","source":"see strengths"},
  {"id":"nd-009","cat":"understand-your-child","type":"spot","hook":"Spot the two lines that fail to understand a neurodiverse child.","scene":[{"id":"a","text":"'Her brain works differently, that's okay'","trick":false},{"id":"b","text":"'She's being difficult on purpose'","trick":true},{"id":"c","text":"'Let me learn how she sees the world'","trick":false},{"id":"d","text":"'She'll be fine once I make her act normal'","trick":true},{"id":"e","text":"'What strengths can I build on?'","trick":false}],"why":"'Difficult on purpose' and 'make her act normal' misunderstand the child; the others understand and build on strengths.","relearn":"Serve a neurodiverse child by understanding their experience and strengths, not labelling them 'difficult' or forcing 'normal'.","persona":"Meena","source":"serving understanding"},
  {"id":"nd-010","cat":"understand-your-child","type":"branch","persona":"Meena","source":"a key not a sentence","hook":"Your son has just been identified as neurodivergent, and you feel overwhelmed.","steps":[{"prompt":"You leave the clinic with his report in your hand. What do you do first?","options":[{"text":"Search every symptom online until you understand everything","then":"Hours pass. Some pages are frightening and some contradict each other."},{"text":"Put the report away until you feel ready","then":"The report stays in the drawer. The worry sits with you at every meal."},{"text":"Read it slowly at home and write down questions","then":"You find words about strengths too. Your list has six questions.","best":true},{"text":"Tell everyone you know before you have taken it in","then":"Calls start at once. Everyone has an opinion, and none have read it."}],"why":"Reading it calmly and noting questions makes it information you can use."},{"prompt":"Your mother-in-law calls in tears and says this is a tragedy. What do you say?","options":[{"text":"Say you are devastated too","then":"You both cry for an hour. She calls the next day to cry again."},{"text":"Say you won't talk about it until you know more","then":"She sighs, hurt. The calls go on with less warmth."},{"text":"Say it is information to help you support him","then":"She sniffles. \"Then what can we do?\"","best":true},{"text":"Ask her to stop being dramatic","then":"She goes quiet, and her silence hurts. The tension stays."}],"why":"Calling it information keeps the family focused on support, not fear."},{"prompt":"The next day, your son lines up his toy cars as he always does. How do you see it?","options":[{"text":"As a symptom to watch, with a checklist in your head","then":"You watch him with a checklist in your head. He senses it and stops playing."},{"text":"As something to stop before it gets worse","then":"You move the cars. He cries, and the morning goes badly."},{"text":"As his way of thinking, worth watching with him","then":"You sit beside him. He shows you the order of the cars.","best":true},{"text":"As nothing to think about until the next appointment","then":"You look away. The chance to know him better passes."}],"why":"He is unchanged, and watching his play shows you how he thinks."},{"prompt":"A neighbour asks what the doctor said. How do you answer?","options":[{"text":"Say it was nothing serious","then":"The neighbour smiles. The secret feels heavier."},{"text":"Say you are hoping to fix it soon","then":"She says she will pray for a cure. You wince."},{"text":"Say you would rather never talk about it","then":"She nods, but avoids you at the gate after that."},{"text":"Share what feels right, and say he is the same lovely boy","then":"She nods. \"He is a lovely boy. Tell me if I can help.\"","best":true}],"why":"Sharing on your terms, with pride in him, lets support in without shame."}],"debrief":"Treat a neurodivergence as information that helps you support your child, not a tragedy or verdict.","relearn":"A diagnosis is a key to understanding and support, not a verdict; your child is unchanged."},
  {"id":"nd-011","cat":"accommodate","type":"strike-rewrite","hook":"\"My child must be forced to fit the standard environment and behave 'normally'.\"","myth":{"un":"My child must be forced to fit the standard environment and behave 'normally'.","re":"It works far better to adjust the environment and expectations to the child than to force the child to mask who they are.","why":"Flex the setting, not the child."},"relearn":"Adjust the environment and expectations to your child rather than forcing them to mask and fit a standard mould.","persona":"Meena","source":"flex the setting"},
  {"id":"nd-012","cat":"accommodate","type":"sort","hook":"Sort: a supportive accommodation, or forcing the child to mask?","items":[{"id":"a","text":"Noise-cancelling headphones for sensory overload"},{"id":"b","text":"Punishing stimming"},{"id":"c","text":"A visual schedule and routine"},{"id":"d","text":"Demanding constant eye contact"},{"id":"e","text":"Short tasks with movement breaks"},{"id":"f","text":"Forcing him to sit perfectly still"}],"bins":[{"id":"support","label":"Supportive accommodation","valence":"pos"},{"id":"mask","label":"Forcing masking","valence":"neg"}],"key":{"a":"support","b":"mask","c":"support","d":"mask","e":"support","f":"mask"},"relearn":"Headphones, visual schedules and movement breaks support; punishing stimming, demanding eye contact or forcing stillness force masking.","persona":"Meena","source":"support vs mask"},
  {"id":"nd-013","cat":"accommodate","type":"match","hook":"Match each need to a practical home accommodation.","pairs":[{"left":"Sensory overload","right":"A calm, low-stimulation space"},{"left":"Trouble with transitions","right":"Warnings and a visual routine"},{"left":"Attention differences","right":"Short steps, movement breaks"},{"left":"Mealtime stress","right":"Respect food needs, no forcing"},{"left":"Big feelings","right":"A calm-down space, not a scolding"}],"relearn":"Sensory overload, transitions, attention, mealtimes and big feelings each have a simple, practical accommodation that helps.","persona":"any","source":"need to accommodation"},
  {"id":"nd-014","cat":"accommodate","type":"strike-rewrite","hook":"\"Accommodations spoil a child or are unfair to others.\"","myth":{"un":"Accommodations spoil a child or are unfair to others.","re":"Accommodations give a child fair access to the same chances, like glasses for sight; they level the ground, not tilt it.","why":"Fair isn't always identical."},"relearn":"Accommodations don't spoil a child; like glasses, they give fair access to the same chances.","persona":"Vikram","source":"fair access"},
  {"id":"nd-015","cat":"accommodate","type":"branch","persona":"Meena","source":"prevent overload","hook":"Your son melts down in loud, crowded places, and a family function is coming.","steps":[{"prompt":"The function is in a noisy hall with a band. How do you prepare?","options":[{"text":"Skip the function so he never has to face the noise at all","then":"He stays calm at home. Later he asks quietly why he could not see the cousins he likes."},{"text":"Go as usual and hope this time goes better than the last","then":"The band starts and he covers his ears within minutes. You have no plan."},{"text":"Tell him firmly that he must behave in front of the family","then":"He nods tight-lipped and grips your hand. His shoulders stay high all the way there."},{"text":"Pack his headphones, find a quiet spot and plan an early exit","then":"You spot a side room near the hall and tell your husband the plan. He nods.","best":true}],"why":"Preparing supports and an exit lets him join without being pushed past his limit."},{"prompt":"A week later, at a busy market, he suddenly drops to the floor and screams. What do you do?","options":[{"text":"Tell him sharply to get up because people are staring at you","then":"He screams louder and covers his face. Passers-by slow down to watch."},{"text":"Move him to a quieter spot and stay close while he settles","then":"Away from the crowd, his breathing slows. After a while he leans into you.","best":true},{"text":"Buy him a treat from the nearest stall so that he stops","then":"He quiets for a moment, then melts down again at the next stall."},{"text":"Say you will never bring him to a market again after this","then":"He calms in the car. The next trip out feels harder for both of you."}],"why":"Less noise and a calm adult help an overwhelmed child settle. A treat or scolding does not."},{"prompt":"Later he asks in a small voice if he is bad. What do you say?","options":[{"text":"Of course you are not bad. But next time please try to stay calm","then":"His face falls. He looks at the floor and says nothing more."},{"text":"Let us leave it now. It is over and we will forget about it","then":"He goes quiet and picks at his sleeve. The question stays with him."},{"text":"Tell him he must say sorry for the scene he made","then":"He mumbles a sorry without understanding why. His eyes stay wet all evening."},{"text":"You are not in trouble. It got too loud, and I am here","then":"He lets out a long breath and leans on you. \"Too loud,\" he repeats softly.","best":true}],"why":"Reassurance, not reproach, rebuilds his sense of safety after a meltdown."},{"prompt":"His teacher plans a school trip to a noisy science fair. What do you do?","options":[{"text":"Say he cannot go, to spare him the noise altogether","then":"He stays behind and watches his class leave, hurt and confused."},{"text":"Ask what to expect, then request a quiet break spot and headphones","then":"The teacher notes it down and names a helper to walk beside him.","best":true},{"text":"Say he will be fine, since it is only a single day","then":"At the fair a loud show starts, and he sits down with his hands over his ears."},{"text":"Ask him if he wants to go and leave the rest to chance","then":"He says yes, then freezes at the entrance with no plan to fall back on."}],"why":"Asking about the day and arranging supports lets him join without overload."}],"debrief":"Prevent sensory overload by adjusting plans and bringing supports.","relearn":"Adjust for sensory overload instead of forcing it; a meltdown is overwhelm, not misbehaviour."},
  {"id":"nd-016","cat":"accommodate","type":"reflect","hook":"Lensy: a child who is accommodated can show you their best; one who is forced to mask is just surviving. Sit right?","prompt":"What do you think?","options":["Sits right","Their best","Not just surviving"],"affirm":"When a child's environment is accommodated they can flourish and show their strengths, rather than exhausting themselves masking.","relearn":"An accommodated child can show you their best; a child forced to mask is just surviving.","persona":"Meena","source":"show their best"},
  {"id":"nd-017","cat":"accommodate","type":"spot","hook":"Spot the two moves that drain your child instead of helping them thrive.","scene":[{"id":"a","text":"Adjusting the environment to their needs","trick":false},{"id":"b","text":"Forcing them to suppress who they are","trick":true},{"id":"c","text":"Building on their strengths and interests","trick":false},{"id":"d","text":"Punishing them for self-soothing","trick":true},{"id":"e","text":"A quiet break when overstimulated","trick":false}],"why":"Forcing suppression and punishing self-soothing drain a child; adjusting the setting and strengths help them thrive.","relearn":"Forcing suppression and punishing self-soothing drain a child; adjusting the setting and strengths help them thrive.","persona":"Meena","source":"thrive accommodation"},
  {"id":"nd-018","cat":"accommodate","type":"match","hook":"Match each setting to an accommodation that helps.","pairs":[{"left":"Mealtimes","right":"Respect food sensitivities, no force"},{"left":"Bedtime","right":"A predictable, calming routine"},{"left":"Homework","right":"Chunked tasks and breaks"},{"left":"Outings","right":"Headphones and a quiet exit plan"},{"left":"Mornings","right":"A visual step-by-step checklist"}],"relearn":"Mealtimes, bedtime, homework, outings and mornings each go better with accommodations that fit the child's wiring.","persona":"any","source":"setting to support"},
  {"id":"nd-019","cat":"accommodate","type":"strike-rewrite","hook":"\"If I accommodate my child, they'll never learn to cope with the real world.\"","myth":{"un":"If I accommodate my child, they'll never learn to cope with the real world.","re":"Accommodation builds the security and skills from which real coping grows; forcing distress teaches fear, not coping.","why":"Support is the launchpad, not the crutch."},"relearn":"Accommodation builds the security from which coping grows; forced distress teaches fear, not real-world skills.","persona":"Vikram","source":"support builds coping"},
  {"id":"nd-020","cat":"accommodate","type":"branch","persona":"Divya","source":"find what works","hook":"You are unsure which accommodations your son actually needs.","steps":[{"prompt":"He keeps covering his ears at home but will not say why. What do you do?","options":[{"text":"Order the headphones that an online list recommends","then":"They arrive in two days. He turns them over, puts them down and keeps covering his ears."},{"text":"Tell him to stop, since it is really not that loud","then":"He lowers his hands, then flinches at the next clatter from the kitchen."},{"text":"Wait and see if he grows out of it by himself soon","then":"Weeks pass. The ear-covering continues and mornings feel tenser."},{"text":"Watch when it happens and ask him what bothers him","then":"You notice it happens when the mixer runs. He points at it and says, \"Loud.\"","best":true}],"why":"Watching and asking shows what really bothers him, so the support can fit."},{"prompt":"A week later, his teacher says he covers his ears in assembly too. What do you try?","options":[{"text":"Ask the teacher to excuse him from assemblies for good","then":"She agrees for now. He misses the songs he likes and asks why he is not there."},{"text":"Try soft earmuffs at home and school, and note what helps","then":"He wears them in assembly and stays seated. You note that the hall echo is the worst.","best":true},{"text":"Ask him to bear it, since assemblies are only a short time","then":"He sits through it stiffly and comes home tired and snappish."},{"text":"Start all ten supports from the list on the very same day","then":"He resists every change at once. You cannot tell which one helps."}],"why":"Trying one support at a time and noting the result shows what truly helps him."},{"prompt":"A month later, at a cousin's loud party, he pushes away the earmuffs you brought. What do you do?","options":[{"text":"Insist he wears them, since they are meant to help","then":"He shakes his head and stays near the door with his hands over his ears."},{"text":"Drop all supports for good, since he is clearly refusing them","then":"Without anything, the noise builds and he asks to leave within minutes."},{"text":"Ask the cousins to keep the music down all evening long","then":"The music dips, then creeps back up. He still has not said what he needs."},{"text":"Ask him why, then change the support to fit what he says","then":"He says they feel tight and look odd. You try something softer and he agrees.","best":true}],"why":"Needs change, so ask him and adjust rather than assume a support still fits."}],"debrief":"Find the right accommodations by watching, asking your child and trying supports.","relearn":"Tailor accommodations by observing and asking your child, not by applying a generic checklist."},
  {"id":"nd-021","cat":"advocate","type":"strike-rewrite","hook":"\"It's not my place to push for support; I should just accept whatever school gives.\"","myth":{"un":"It's not my place to push for support; I should just accept whatever school gives.","re":"You are your child's most important advocate; pushing kindly but firmly for the support they need is part of the job.","why":"No one will champion your child like you."},"relearn":"You are your child's key advocate; pushing kindly but firmly for the support they need is part of parenting.","persona":"Meena","source":"you are the advocate"},
  {"id":"nd-022","cat":"advocate","type":"strike-rewrite","hook":"\"My neurodiverse child has no real rights to support in India.\"","myth":{"un":"My neurodiverse child has no real rights to support in India.","re":"The Rights of Persons with Disabilities Act 2016 recognises autism and learning disabilities and mandates reasonable accommodation, including in schools.","why":"The law is on your child's side."},"relearn":"Your child has rights: the RPwD Act 2016 recognises autism and learning disabilities and mandates reasonable accommodation.","persona":"Meena","source":"RPwD rights"},
  {"id":"nd-023","cat":"advocate","type":"sort","persona":"any","source":"advocate vs giveup","hook":"Sort: effective advocacy, or giving up your child's support?","items":[{"id":"a","text":"Requesting accommodations in writing"},{"id":"b","text":"Accepting 'he's just naughty'"},{"id":"c","text":"Bringing evidence and staying calm"},{"id":"d","text":"Hiding the diagnosis from teachers"},{"id":"e","text":"Following up after a 'we'll see'"},{"id":"f","text":"Giving up after one 'no'"}],"bins":[{"id":"advocate","label":"Effective advocacy","valence":"pos"},{"id":"giveup","label":"Gives up support","valence":"neg"}],"key":{"a":"advocate","b":"giveup","c":"advocate","d":"giveup","e":"advocate","f":"giveup"},"relearn":"Written requests, calm evidence and following up are effective advocacy; accepting 'naughty', hiding it or giving up surrender support."},
  {"id":"nd-024","cat":"advocate","type":"branch","persona":"Meena","source":"explain and request","hook":"The school calls your son's needs bad behaviour.","steps":[{"prompt":"His teacher writes \"bad behaviour\" in his diary again. What do you do?","options":[{"text":"Accept the note and promise to punish him for it at home","then":"He reads your face and shrinks. The note stays true in his mind."},{"text":"Write back a sharp note saying she does not understand children","then":"She replies coldly, and the next note in the diary is longer."},{"text":"Wait and see if it happens again before doing anything","then":"It happens twice more that week. He starts refusing to go."},{"text":"Ask for a meeting to explain how he is wired and what helps","then":"She agrees, a little stiffly. \"Yes, we can meet on Thursday.\"","best":true}],"why":"A calm meeting and a clear explanation shift the school from blame to support."},{"prompt":"When you next speak, the teacher says she has a full class and can do little. What do you say?","options":[{"text":"Say the school should hire another teacher just for him","then":"She looks tired. \"That is beyond my hands.\""},{"text":"Ask for two or three small changes and offer to help","then":"She thinks about it. \"A front seat and warnings I can do.\"","best":true},{"text":"Agree that she has enough on her plate and ask for nothing","then":"She looks relieved. Nothing changes for him."},{"text":"Say you will complain to the principal if nothing improves","then":"She stiffens. The talk ends, and neither of you looks at the other."}],"why":"Small, specific requests give her something she can actually do."},{"prompt":"A month later, he has a good week and then one hard day. What do you do?","options":[{"text":"Decide nothing is working and ask for a different teacher","then":"She looks hurt. He moves to a new class and starts again from nothing."},{"text":"Assume it will improve by itself and stop following up","then":"Within a week, his diary fills with notes again."},{"text":"Tell him to try harder for his teacher's sake","then":"He nods, ashamed. His next hard day, he hides his face."},{"text":"Thank her for the good week, note what helped and set a review","then":"She smiles. \"Yes, let us look again in two weeks.\" She writes the date down.","best":true}],"why":"A thank-you and a review date keep the support going even after a bad day."},{"prompt":"Next term, a new coordinator says any support for him must now be approved in writing. What do you do?","options":[{"text":"Say it is unfair and refuse to fill in any more forms","then":"He stiffens. \"Rules are rules,\" he says, and nothing is approved."},{"text":"Ask what it needs, and send it with a note on what helps him","then":"He hands you a short form. \"Fill this in and I will approve it this week.\"","best":true},{"text":"Accept it and wait for the school to sort it out on its own","then":"Weeks pass, and nothing is approved. The diary notes return."},{"text":"Tell your son to behave so no support will be needed","then":"He tries hard and comes home shaking at the end of each day."}],"why":"Asking what is needed and sending what helps him keeps his support in force."},{"prompt":"At year end, the teacher asks what to tell next year's teacher about him. What do you do?","options":[{"text":"Say there is nothing to pass on, and start fresh next year","then":"The new term starts from scratch, and the old problems return."},{"text":"Keep his notes at home and explain it all yourself later","then":"Next year's teacher starts without them, and the first weeks are rough."},{"text":"Thank her, list what helped and ask her to pass it on","then":"She smiles. \"I will add my own notes before I hand it over.\"","best":true},{"text":"Say the school only did what it owed you anyway","then":"She looks stung. The goodwill that helped him cools."}],"why":"Passing on what helped, with thanks, keeps the partnership going next year."}],"debrief":"When school calls needs 'bad behaviour', explain the profile and request accommodations.","relearn":"Reframe 'bad behaviour' by explaining the profile and requesting accommodations."},
  {"id":"nd-025","cat":"advocate","type":"match","persona":"Meena","source":"arena to move","hook":"Match each arena to an advocacy move.","pairs":[{"left":"School","right":"Request a learning-support plan"},{"left":"Family","right":"Share understanding, set respectful limits"},{"left":"Services","right":"Seek assessment and ongoing support"},{"left":"Exam board","right":"Apply for concessions with a report"},{"left":"Co-parent","right":"Agree the plan and share the load"}],"relearn":"School, family, services, the exam board and your co-parent each call for accommodations, understanding, assessment, concessions, shared load."},
  {"id":"nd-026","cat":"advocate","type":"role-play","persona":"Meena","source":"calm advocacy","hook":"Your son had a hard evening at a family dinner, and not everyone was kind about it.","setup":"After dinner, your brother-in-law corners you by the window.","steps":[{"prompt":"Your brother-in-law says: \"That boy needs discipline, not softness.\"","options":[{"text":"\"You are right. Maybe I have been too soft on him.\"","then":"He nods. \"Good. Boys need a firm hand.\""},{"text":"\"His brain works differently. Support helps more than fear.\"","then":"He blinks. \"Differently? He looks like any other boy to me.\"","best":true},{"text":"\"You have no idea what you are talking about.\"","then":"He bristles. \"I raised two boys, thank you.\""},{"text":"\"The doctor says it is not about discipline, so drop it.\"","then":"\"Doctors,\" he snorts. \"They have not raised children.\""}],"why":"Explaining calmly that support, not punishment, helps him protects him from harsh advice."},{"prompt":"He adds: \"A smack taught us right from wrong. It did us no harm.\"","options":[{"text":"\"Maybe. I do not know what else would work for him.\"","then":"\"Then try my way,\" he says, and you find no answer."},{"text":"\"He already knows. He is smarter than you think, bhaiya.\"","then":"\"Then why does he behave so?\" he asks, and the point stays open."},{"text":"\"I will start disciplining him harder from tomorrow.\"","then":"\"Good,\" he says. Your son watches you across the room."},{"text":"\"He learns from calm, clear rules, not from fear.\"","then":"He thinks. \"Clear rules I can follow. Fear I never liked myself.\"","best":true}],"why":"Clear, calm rules teach him better than fear does."},{"prompt":"He asks: \"So what do I do if he acts up at my house?\"","options":[{"text":"\"Tell him firmly to stop, like you would your own boys.\"","then":"He does. Your son covers his ears, and your brother-in-law is confused."},{"text":"\"Stay calm, give him a quiet corner and call me.\"","then":"\"A quiet corner. That is simple enough,\" he says.","best":true},{"text":"\"We will not visit if it is a problem for you.\"","then":"He looks startled. \"I did not say that. You are family.\""},{"text":"\"Do whatever you think is best. I will not interfere.\"","then":"He nods, and next visit he raises his voice at your son."}],"why":"A simple way to help turns a critic into an ally."}],"relearn":"Calmly explaining that support, not harsher punishment, is what helps protects your child from misguided 'discipline'."},
  {"id":"nd-027","cat":"advocate","type":"reflect","hook":"Lensy: every time you advocate, you teach your child that they're worth fighting for. Worth it?","prompt":"What do you think?","options":["Worth it","Worth fighting for","Yes"],"affirm":"Each act of advocacy teaches a neurodiverse child that they matter and are worth standing up for.","relearn":"Every time you advocate, you teach your child that they're worth fighting for.","persona":"Meena","source":"worth fighting for"},
  {"id":"nd-028","cat":"advocate","type":"spot","persona":"any","source":"effective advocacy","hook":"Spot the two red flags: 'advocacy' that leaves your child unsupported.","scene":[{"id":"a","text":"Knowing their rights and asking clearly","trick":false},{"id":"b","text":"Staying silent to avoid being 'that parent'","trick":true},{"id":"c","text":"Partnering with teachers on a plan","trick":false},{"id":"d","text":"Apologising until you drop the request","trick":true},{"id":"e","text":"Putting the agreed support in writing","trick":false}],"why":"Staying silent and over-apologising until you drop the ask leave your child unsupported; the rest get real support.","relearn":"Staying silent or apologising the request away give up support; knowing rights, partnering and writing it down secure it."},
  {"id":"nd-029","cat":"advocate","type":"branch","persona":"Divya","source":"seek assessment","hook":"You suspect your son is neurodivergent, and worry that an assessment would be making a problem.","steps":[{"prompt":"Your mother says he is a late bloomer and a label will follow him. What do you do?","options":[{"text":"Wait a year and see whether he catches up on his own","then":"The year passes. His speech is behind his cousin's, and you worry more each month."},{"text":"Ask relatives and friends what they think he might have","then":"Everyone has a different opinion, and you end up more confused than before."},{"text":"Book a qualified professional to assess and understand him","then":"The clinic offers a date in three weeks. You feel nervous, and a little lighter.","best":true},{"text":"Search online and decide for yourself what he probably has","then":"You read late into the night. Every list seems to fit him, and nothing helps."}],"why":"A qualified assessment gives real information where waiting and guessing do not."},{"prompt":"Your husband fears that once he is assessed, people will see only a diagnosis. What do you say?","options":[{"text":"It is information, not a verdict, and it can open doors to support","then":"He is quiet, then nods. \"Information. Alright, that I can understand.\"","best":true},{"text":"You are right. Let us skip the assessment and see how it goes","then":"He relaxes. Months pass, and nothing about school or home gets easier."},{"text":"We will get the label just to make the school stop complaining","then":"He agrees. The label stays a paper, and nobody asks what he needs."},{"text":"Let us keep this between us and not tell anyone at all","then":"He agrees. Both of you carry it alone, and it starts to weigh on you."}],"why":"Seeing a label as information, not a verdict, keeps the focus on his support."},{"prompt":"Some evenings you feel guilty and wonder if you should have acted sooner. What do you tell yourself?","options":[{"text":"I should have seen it earlier. I have let him down","then":"The thought loops all night. You feel drained the next day."},{"text":"Maybe it is something I did while I was carrying him","then":"You go back over every day of the pregnancy, and sleep does not come."},{"text":"I did not cause this. What matters is getting him support now","then":"Your shoulders drop. You note down a call to make to the clinic tomorrow.","best":true},{"text":"I will not think about it at all, and I will not talk about it","then":"The feeling waits, and it returns at bedtime, stronger."}],"why":"It is no one's fault. Your energy is best spent finding him support."},{"prompt":"Some weeks later, a friend says you should wait until he is older before doing anything. What do you say?","options":[{"text":"Thank her, and say that understanding him now opens support sooner","then":"She looks unsure. \"Sooner is better, I suppose. I did not think of that.\"","best":true},{"text":"Agree, and wait another year before deciding anything","then":"The year passes. His difficulties at school grow while you wait."},{"text":"Say you will ask the whole family before you decide","then":"Everyone has an opinion, and the decision drags on for months."},{"text":"Say she has no right to advise you on your own child","then":"She looks hurt and stops calling. Your worry stays with you."}],"why":"Understanding him early opens the door to support, and waiting only delays it."}],"debrief":"Seek assessment if you suspect neurodivergence. It opens the door to support and is not 'making a problem'.","relearn":"Pursue assessment rather than dodging a 'label'; understanding unlocks support."},
  {"id":"nd-030","cat":"advocate","type":"strike-rewrite","hook":"\"Asking for help with my child marks me as a failing parent.\"","myth":{"un":"Asking for help with my child marks me as a failing parent.","re":"Seeking support and accommodations is exactly what good, informed parents of neurodiverse kids do; it's strength, not failure.","why":"Getting help is wise parenting."},"relearn":"Asking for help and accommodations is what good parents of neurodiverse kids do; it's strength, not failure.","persona":"Vikram","source":"help is strength"},
  {"id":"nd-031","cat":"drop-the-shame","type":"strike-rewrite","hook":"\"My child's neurodivergence is caused by my bad parenting.\"","myth":{"un":"My child's neurodivergence is caused by my bad parenting.","re":"Neurodivergence isn't caused by parenting, screens, vaccines or anything you did; it's simply how your child is wired.","why":"It's no one's fault, least of all yours."},"relearn":"Neurodivergence isn't caused by your parenting or by screens or vaccines; it's simply how your child is wired.","persona":"Meena","source":"not your fault"},
  {"id":"nd-032","cat":"drop-the-shame","type":"strike-rewrite","hook":"\"A child who melts down or can't sit still is just badly behaved.\"","myth":{"un":"A child who melts down or can't sit still is just badly behaved.","re":"Meltdowns and restlessness are often the brain overwhelmed or wired differently, not naughtiness to be punished.","why":"Behaviour is communication, not defiance."},"relearn":"Meltdowns and restlessness are usually overwhelm or different wiring, not bad behaviour to punish.","persona":"Meena","source":"not bad behaviour"},
  {"id":"nd-033","cat":"drop-the-shame","type":"strike-rewrite","hook":"\"They'll just grow out of it if we ignore it.\"","myth":{"un":"They'll just grow out of it if we ignore it.","re":"Neurodivergence is lifelong; understanding and support help a child thrive, while ignoring it leaves them struggling alone.","why":"Support helps; waiting it out doesn't."},"relearn":"A child doesn't 'grow out of' neurodivergence; understanding and support help them thrive, ignoring it doesn't.","persona":"Vikram","source":"not grow out of it"},
  {"id":"nd-034","cat":"drop-the-shame","type":"sort","hook":"Sort each line: a fact that lifts shame, or a myth that piles it on.","items":[{"id":"a","text":"It's no one's fault"},{"id":"b","text":"'You spoiled or caused this'"},{"id":"c","text":"Your child can thrive with support"},{"id":"d","text":"'A good family hides it'"},{"id":"e","text":"A diagnosis is a key to support"},{"id":"f","text":"'Screens made him this way'"}],"bins":[{"id":"lifts","label":"Lifts shame","valence":"pos"},{"id":"piles","label":"Piles on shame","valence":"neg"}],"key":{"a":"lifts","b":"piles","c":"lifts","d":"piles","e":"lifts","f":"piles"},"relearn":"'No one's fault', 'can thrive with support' and 'a key to support' lift shame; 'you caused it', 'hide it' and 'screens' pile it on unfairly.","persona":"any","source":"lifts vs piles"},
  {"id":"nd-035","cat":"drop-the-shame","type":"reflect","hook":"Lensy: you didn't cause this, you can't 'cure' it, and you absolutely can help your child flourish. Land okay?","prompt":"What do you think?","options":["Lands okay","Not my fault","I can help"],"affirm":"You didn't cause your child's neurodivergence and can't cure it, but you can absolutely help them flourish.","relearn":"You didn't cause it, you can't cure it, and you can help your child flourish.","persona":"Meena","source":"didnt cause it"},
  {"id":"nd-036","cat":"drop-the-shame","type":"branch","persona":"Meena","source":"shield from blame","hook":"Relatives blame you for the way your son is.","steps":[{"prompt":"At a family dinner, an aunt says you spoiled him. What do you do?","options":[{"text":"Say nothing and hope she stops soon enough on her own","then":"She goes on. Your son watches your face and stops eating."},{"text":"Tell your son to stop being difficult so she will stop","then":"He shrinks in his chair. The aunt smirks, and he feels blamed."},{"text":"Say calmly it is no one's fault. Parenting did not cause it","then":"She purses her lips. \"Hmm. I only said what I have seen.\"","best":true},{"text":"Blame your husband's side of the family for it in return","then":"The room goes tense. Two aunts start taking sides across the table."}],"why":"A calm correction shields your son and shows that no one caused it."},{"prompt":"That night, your son asks if he made Aunty angry. What do you say?","options":[{"text":"No. Nothing is wrong with you. Aunty does not understand yet","then":"He relaxes. \"Okay,\" he says, and leans against your shoulder.","best":true},{"text":"Aunty was upset because you make so much noise at dinner","then":"His face falls. He whispers, \"Sorry,\" and hides under the blanket."},{"text":"Do not worry about big people's talk. Go to sleep now","then":"He nods. The question goes unanswered and stays with him."},{"text":"Aunty is a bad person. We will not talk to her again","then":"His eyes widen. He gets anxious when the doorbell rings."}],"why":"Telling him nothing is wrong with him keeps the blame from landing on him."},{"prompt":"Late at night, you replay her words and wonder if she is right. What do you do?","options":[{"text":"Read more about how parents cause this to find your mistakes","then":"You read until dawn. Every list has something that fits, and none helps."},{"text":"Decide never to go to family events again after this","then":"The week feels lighter. The invitations begin to pile up unanswered."},{"text":"Remind yourself it is no one's fault and tell your husband","then":"He listens. \"It was never you,\" he says, and holds your hand.","best":true},{"text":"Push the thought away and say nothing to anyone at all","then":"The thought comes back at the next family call, heavier."}],"why":"Naming that it is no one's fault, and sharing it, loosens the grip of blame."}],"debrief":"Correct relatives' blame calmly and protect your child from it; it's no one's fault.","relearn":"Shield your child from blame by correcting it calmly; don't pass undeserved shame on to them."},
  {"id":"nd-037","cat":"drop-the-shame","type":"spot","hook":"Spot the two shame-keeping moves (the ones that pile blame on the family).","scene":[{"id":"a","text":"Knowing it's no one's fault","trick":false},{"id":"b","text":"Hiding the child from relatives","trick":true},{"id":"c","text":"Talking about it openly and kindly","trick":false},{"id":"d","text":"Blaming yourself for 'causing' it","trick":true},{"id":"e","text":"Focusing energy on his support","trick":false}],"why":"Hiding the child and self-blame keep the shame alive; the rest, knowing it's no one's fault, openness, support, drop it.","relearn":"Catch shame-keeping moves like hiding the child and self-blame; families drop the shame by openness and support.","persona":"any","source":"catch shame-keepers"},
  {"id":"nd-038","cat":"drop-the-shame","type":"reflect","hook":"Lensy: shame helps no one; your energy is better spent understanding and championing your child. Agree?","prompt":"What's your take?","options":["Agree","Champion not shame","Energy well spent"],"affirm":"Shame and blame help no one; that energy is far better spent understanding and championing your child.","relearn":"Shame helps no one; spend that energy understanding and championing your child instead.","persona":"Meena","source":"champion not shame"},
  {"id":"nd-039","cat":"drop-the-shame","type":"strike-rewrite","hook":"\"I should hide my child's diagnosis so people don't judge us.\"","myth":{"un":"I should hide my child's diagnosis so people don't judge us.","re":"Hiding it reinforces stigma and isolates you both; openness, on your own terms, lets support and understanding in.","why":"Secrecy feeds the shame it fears."},"relearn":"Hiding a diagnosis reinforces stigma and isolation; sharing on your own terms lets in support and understanding.","persona":"Vikram","source":"openness over hiding"},
  {"id":"nd-040","cat":"drop-the-shame","type":"branch","persona":"Meena","source":"drop the guilt","hook":"You feel grief and guilt about your son's diagnosis.","steps":[{"prompt":"Late at night, the word \"diagnosis\" keeps replaying in your mind. What do you do?","options":[{"text":"Keep replaying what you might have done differently","then":"The list grows longer. You still cannot sleep at dawn."},{"text":"Let yourself cry, drop the guilt and talk to someone","then":"You call your sister. She cries with you. You sleep at last.","best":true},{"text":"Push the feelings away and stay busy with chores all night","then":"The house is spotless by morning. The feelings are still there."},{"text":"Search for reasons and causes online until you find one","then":"Each page names a different cause. You feel more guilty and no wiser."}],"why":"Allowing the feelings and dropping the guilt frees you to support him."},{"prompt":"The next morning, your son runs to show you his new train drawing. What do you do?","options":[{"text":"Glance at it and go on thinking about the diagnosis","then":"He waits, then quietly folds the paper and walks away."},{"text":"Praise it, then remind him to practise his handwriting","then":"He nods. The smile drops slightly from his face."},{"text":"Say you are busy and go back to reading about therapies","then":"He goes to his room. The drawing is left on the sofa."},{"text":"Sit down beside him and ask him about the trains","then":"He explains every carriage. \"This one is the fast one,\" he says.","best":true}],"why":"Seeing your son as he is, and enjoying his interests, matters most."},{"prompt":"A friend says the diagnosis is a tragedy and offers sympathy. What do you say?","options":[{"text":"Agree that his life will be sad and hard from now on","then":"She squeezes your hand. On the way home, you see only hard years ahead."},{"text":"Thank her. It is a key to support, and he is still himself","then":"She pauses. \"A key. That is a kinder way to see it,\" she says.","best":true},{"text":"Admit you wonder if too much screen time caused it","then":"She says many people blame screens, and last night's guilt creeps back."},{"text":"Say it is no big deal and change the topic quickly","then":"She looks confused. Your real feelings go unspoken again."}],"why":"Screens did not cause it and no one is at fault. A diagnosis is a key to support, and he is unchanged."}],"debrief":"Allow grief but drop the guilt, and refocus on supporting the child in front of you.","relearn":"Feel what you feel. Drop the guilt and refocus on your child as they are; what-ifs help no one."},
  {"id":"nd-041","cat":"strengths-and-wellbeing","type":"strike-rewrite","hook":"\"I should focus only on fixing my neurodiverse child's weaknesses.\"","myth":{"un":"I should focus only on fixing my neurodiverse child's weaknesses.","re":"Building on a child's strengths and passions does more for their confidence and growth than fixating on deficits.","why":"Strengths are the foundation to build on."},"relearn":"Build on your child's strengths and passions, not only their weaknesses; that grows confidence and skills.","persona":"Meena","source":"build on strengths"},
  {"id":"nd-042","cat":"strengths-and-wellbeing","type":"sort","hook":"Sort: nurtures a neurodiverse child's wellbeing, or chips at their self-worth?","items":[{"id":"a","text":"Celebrating their passions"},{"id":"b","text":"Constantly comparing them to others"},{"id":"c","text":"Praising effort and strengths"},{"id":"d","text":"Making them feel like a problem"},{"id":"e","text":"Noticing one small win out loud"},{"id":"f","text":"Sighing 'why aren't you normal'"}],"bins":[{"id":"nurture","label":"Nurtures wellbeing","valence":"pos"},{"id":"chip","label":"Chips at self-worth","valence":"neg"}],"key":{"a":"nurture","b":"chip","c":"nurture","d":"chip","e":"nurture","f":"chip"},"relearn":"Celebrating passions and praising strengths nurture wellbeing; constant comparison and 'a problem' framing chip at self-worth.","persona":"Meena","source":"nurture vs chip"},
  {"id":"nd-043","cat":"strengths-and-wellbeing","type":"strike-rewrite","hook":"\"A meltdown is my child trying to manipulate or defy me.\"","myth":{"un":"A meltdown is my child trying to manipulate or defy me.","re":"A meltdown is usually distress and overwhelm spilling over, not manipulation; your child needs co-regulation, not punishment.","why":"Overwhelm needs comfort, not consequences."},"relearn":"A meltdown is overwhelm spilling over, not manipulation; your child needs calm co-regulation, not punishment.","persona":"Meena","source":"meltdown is distress"},
  {"id":"nd-044","cat":"strengths-and-wellbeing","type":"branch","persona":"Meena","source":"co-regulate","hook":"It has been a loud, tiring evening at home, and your patience is thin.","steps":[{"prompt":"Your child is on the floor screaming and your temples throb. What do you do?","options":[{"text":"Take a slow breath, keep them safe, and stay near","then":"The screaming goes on, but your steady voice slowly reaches them.","best":true},{"text":"Raise your voice to match theirs and end it","then":"Their screams rise and they curl up, frightened."},{"text":"Order them to their room until they calm down","then":"They scream alone behind the door, and it lasts longer."},{"text":"Try to reason with them about what went wrong","then":"They can't take in a word. The screaming carries on over your voice."}],"why":"Calm and safety help the wave pass, while anger adds fear to their overload."},{"prompt":"The screaming fades into hiccuping breaths. What do you do next?","options":[{"text":"Sit close and speak softly, with no questions","then":"After a minute they shuffle against your side. Their breathing evens.","best":true},{"text":"Ask them right away why they got so upset","then":"They can't put it into words and start to cry again."},{"text":"Tell them they must never scream like that again","then":"They nod, tearful, though they can't promise anything."},{"text":"Hold them tight even as they try to pull away","then":"They squirm and push harder, and the crying starts again."}],"why":"Quiet closeness lets them settle at their own pace, without demands."},{"prompt":"Later, your partner asks how to handle the next one. What do you say?","options":[{"text":"Stay calm, keep them safe, and talk after it passes","then":"Your partner nods and writes it on a card for the fridge: calm, safe, wait.","best":true},{"text":"Ignore it completely, since attention only feeds it","then":"Your partner tries it. The screaming grows and your child looks frightened."},{"text":"Take a favourite toy away after each meltdown","then":"The next meltdown comes with no toy and even more tears."},{"text":"One of you should scold and the other comfort","then":"Your partner tries it. Your child no longer knows whom to trust."}],"why":"A steady, shared plan means your child meets calm from both of you."}],"debrief":"Meet a meltdown with calm co-regulation and safety, not anger; ride out the storm together.","relearn":"Co-regulate a meltdown with calm and safety; meeting overwhelm with anger only escalates it."},
  {"id":"nd-045","cat":"strengths-and-wellbeing","type":"match","hook":"Match each strength to a way to nurture it.","pairs":[{"left":"An intense interest in trains","right":"Give it space and resources"},{"left":"Honesty and a strong sense of fairness","right":"Praise and model it back"},{"left":"Creative, out-of-the-box thinking","right":"Open-ended play and projects"},{"left":"Deep focus on one task","right":"Protect quiet, uninterrupted time"},{"left":"Big-picture, spatial thinking","right":"Drawing, building and maps"}],"relearn":"An intense interest, honesty, creative thinking, deep focus and spatial thinking each grow when a parent nurtures rather than discourages them.","persona":"any","source":"nurture strengths"},
  {"id":"nd-046","cat":"strengths-and-wellbeing","type":"reflect","hook":"Lensy: a neurodiverse child who feels celebrated, not just corrected, grows up liking who they are. Worth it?","prompt":"What do you think?","options":["Worth it","Celebrated","Likes who they are"],"affirm":"A neurodiverse child who feels celebrated, not constantly corrected, grows up with self-worth and confidence.","relearn":"A child who feels celebrated, not just corrected, grows up liking who they are.","persona":"Meena","source":"feel celebrated"},
  {"id":"nd-047","cat":"strengths-and-wellbeing","type":"spot","hook":"Spot the two lines that harm a neurodiverse child's wellbeing.","scene":[{"id":"a","text":"Noticing and easing their anxiety","trick":false},{"id":"b","text":"Dismissing their distress as drama","trick":true},{"id":"c","text":"Celebrating who they are","trick":false},{"id":"d","text":"'Stop being so dramatic and sit still'","trick":true},{"id":"e","text":"Sitting close until the panic passes","trick":false}],"why":"Dismissing distress as drama and demanding they 'stop being dramatic' harm wellbeing; easing anxiety, celebrating them and sitting close all support it.","relearn":"Support a neurodiverse child's wellbeing by easing anxiety and celebrating them, not dismissing their distress.","persona":"any","source":"support wellbeing"},
  {"id":"nd-048","cat":"strengths-and-wellbeing","type":"branch","persona":"Meena","source":"wellbeing matters","hook":"Lately your child has been quiet after school and picks at dinner.","steps":[{"prompt":"Tonight they say they feel worried and sad a lot. What do you do?","options":[{"text":"Listen closely and take it seriously","then":"They open up about noisy corridors and a friend who moved away.","best":true},{"text":"Tell them it's just part of their diagnosis","then":"They go quiet. The worry doesn't leave, and they stop mentioning it."},{"text":"Tell them to cheer up and think of good things","then":"They nod and hide the feeling. It surfaces at bedtime."},{"text":"Give them extra screen time to lift their mood","then":"They brighten while the screen is on. The worry returns as soon as it's off."}],"why":"Listening seriously shows you what they carry, so it can be helped."},{"prompt":"A month on, the low mood lingers and their sleep is worse. What do you do?","options":[{"text":"Book a visit with their doctor or therapist","then":"The professional asks gentle questions and makes a plan with you both.","best":true},{"text":"Assume it will fade with the next school break","then":"The break arrives. The sleep gets worse, and so does the mood."},{"text":"Try a herbal tonic a neighbour swears by","then":"The bottle empties. The mood and sleep stay the same."},{"text":"Read online about anxiety and treat it at home","then":"You try three tips from a forum. One helps a little, and the rest do nothing."}],"why":"Lasting low mood is worth a professional's eyes, and asking for help is strength."},{"prompt":"Weeks later, the school counsellor asks what helps your child feel safe. What do you share?","options":[{"text":"What you've noticed: quiet, warnings, favourite things","then":"The counsellor writes it all down and builds a calm plan around it.","best":true},{"text":"That they are usually fine and this is a phase","then":"The counsellor nods and suggests waiting, and your worry grows."},{"text":"That other children manage without any fuss","then":"Your child hears it and looks at the floor."},{"text":"Nothing, and leave it to the counsellor to find out","then":"The counsellor asks your child alone. They shrug, and the session ends thin."}],"why":"Your daily observations help the counsellor tailor support to your child."}],"debrief":"Take a neurodiverse child's anxiety or low mood seriously; co-occurring needs are real.","relearn":"Don't dismiss persistent anxiety as 'just the diagnosis'; take wellbeing seriously and seek support."},
  {"id":"nd-049","cat":"strengths-and-wellbeing","type":"reflect","hook":"Lensy: your child is so much more than a diagnosis; seeing the whole, wonderful person is everything. Sit right?","prompt":"What's your take?","options":["Sits right","Whole person","More than a label"],"affirm":"A neurodiverse child is a whole, wonderful person, not a diagnosis; seeing all of them is what matters most.","relearn":"Your child is so much more than a diagnosis; seeing the whole, wonderful person is everything.","persona":"Meena","source":"whole person"},
  {"id":"nd-050","cat":"support-and-you","type":"strike-rewrite","hook":"\"A devoted parent of a neurodiverse child should run on empty and never need support.\"","myth":{"un":"A devoted parent of a neurodiverse child should run on empty and never need support.","re":"Supporting a neurodiverse child can be exhausting; looking after yourself and getting support helps you keep showing up.","why":"Your wellbeing is part of your child's support."},"relearn":"Parenting a neurodiverse child is demanding; caring for yourself and getting support is essential, not optional.","persona":"Meena","source":"your wellbeing matters"},
  {"id":"nd-051","cat":"support-and-you","type":"match","hook":"Match each support to what it offers a parent.","pairs":[{"left":"Other parents of neurodiverse kids","right":"Understanding and practical tips"},{"left":"Professionals and therapists","right":"Assessment and tailored strategies"},{"left":"Your own wellbeing care (Looking After You)","right":"Energy to keep going"},{"left":"Willing family members","right":"Extra hands and shared love"},{"left":"Tele-MANAS","right":"Free mental-health help, 14416"}],"relearn":"Peer parents, professionals, your own wellbeing care, family and Tele-MANAS each give a parent real, different support.","persona":"any","source":"the supports"},
  {"id":"nd-052","cat":"support-and-you","type":"branch","persona":"Divya","source":"sustain yourself","hook":"You are burning out from the daily demands and the fight for support.","steps":[{"prompt":"Your child needs dinner, and you have not sat down all day. What do you do?","options":[{"text":"Ask a relative to take over for an hour","then":"Your sister-in-law comes over. You sit on the balcony with chai, unused to the quiet.","best":true},{"text":"Push through, and rest once your child is asleep","then":"You finish dinner, bath and bedtime. At ten you are too tired to eat."},{"text":"Tell yourself you'll rest properly at the weekend","then":"The weekend arrives with its own tasks. Your rest is pushed to next week."},{"text":"Blame yourself for being too weak to cope","then":"You stir the dal and feel smaller. The tiredness sits heavier than before."}],"why":"Sharing the load for an hour is how a parent refills before running dry."},{"prompt":"A week later, a friend invites you to a parent support group. What do you say?","options":[{"text":"Yes. I'll come this Saturday and see how it feels","then":"Three parents nod as you talk. One shares a tip that works that very night.","best":true},{"text":"No. Others have it worse, so I'll manage alone","then":"Your friend nods, unsure. You stay in the same tired loop."},{"text":"Maybe later, when things calm down","then":"Things never calm down. The invitation slides off your calendar."},{"text":"I'll read about the group online first","then":"You read for an hour. The group's page has forty tabs and no answer."}],"why":"Peers who understand ease the load in ways advice from outsiders rarely does."},{"prompt":"A month on, your husband offers to do the school run on Thursdays. What do you say?","options":[{"text":"Yes, please. That gives me a morning to myself","then":"He takes the first Thursday. You walk to the tea stall with no bag and no list.","best":true},{"text":"No, it's easier if I do it. I know the routine","then":"He shrugs, relieved and a little hurt. You keep every school run."},{"text":"Yes, but I'll write you a list of twenty things","then":"He reads the list, frowns, and calls you at nine with questions."},{"text":"Maybe next month, when things are calmer","then":"He nods. Next month arrives, and so does another reason to wait."}],"why":"Accepting real help, with a real gap, gives your body and mind room to recover."},{"prompt":"That Sunday you feel a wave of tears and tiredness for no clear reason. What do you do?","options":[{"text":"Let it out, rest, and tell someone you trust","then":"Your sister listens for an hour. You cry, laugh, and feel lighter for the first time in weeks.","best":true},{"text":"Wipe your tears and tell nobody, since you cope","then":"You hold it in. The tears return as soon as you are alone."},{"text":"Fill the day with chores to keep busy","then":"The house shines by evening. So does the numb tiredness."},{"text":"Tell yourself others are worse off and stop crying","then":"You stop crying and feel guilty for having started."}],"why":"Letting feelings out with someone you trust keeps stress from building unseen."},{"prompt":"Weeks later, your child's therapist asks how you are doing. What do you say?","options":[{"text":"Honestly, I'm tired. I need more rest and help","then":"The therapist listens and suggests a shared schedule and a support group for you.","best":true},{"text":"I'm fine. Please just focus on my child","then":"She smiles and moves on. Your tiredness stays unspoken."},{"text":"I'm exhausted, but that's what a parent does","then":"She nods. \"Parents burn out, though,\" she says, and lets it go for now."},{"text":"I'm coping. Please don't change anything for me","then":"She notes it down. Nobody asks again for weeks."}],"why":"Being honest about needing help is part of your child's support, not a distraction."}],"debrief":"Protect your wellbeing and reach for support; a sustained parent sustains their child.","relearn":"Get support and tend your wellbeing; pushing on alone to a crash serves no one (see Looking After You)."},
  {"id":"nd-053","cat":"support-and-you","type":"strike-rewrite","hook":"\"This game can diagnose my child or replace a professional.\"","myth":{"un":"This game can diagnose my child or replace a professional.","re":"This offers understanding and support, not diagnosis; a qualified professional assesses and guides specific care.","why":"Understanding tools point to professionals; they don't replace them."},"relearn":"This supports understanding but doesn't diagnose; a qualified professional assesses and guides your child's care.","persona":"any","source":"not a diagnosis"},
  {"id":"nd-054","cat":"support-and-you","type":"sort","hook":"Sort: a wise step for a parent, or one to rethink?","items":[{"id":"a","text":"Joining a parent support group"},{"id":"b","text":"Trying a miracle 'cure' online"},{"id":"c","text":"Seeing a qualified professional"},{"id":"d","text":"Coping in isolation and silence"},{"id":"e","text":"Being honest you need help"},{"id":"f","text":"Running on empty, alone"}],"bins":[{"id":"wise","label":"Wise step","valence":"pos"},{"id":"rethink","label":"Rethink it","valence":"neg"}],"key":{"a":"wise","b":"rethink","c":"wise","d":"rethink","e":"wise","f":"rethink"},"relearn":"Support groups, professionals and honest asks are wise; miracle 'cures', silent isolation and running on empty need a rethink.","persona":"any","source":"wise step"},
  {"id":"nd-055","cat":"support-and-you","type":"reflect","hook":"Lensy: you don't have to know everything or do it perfectly; a learning, loving, supported parent is enough. Resonate?","prompt":"What do you think?","options":["Resonates","Enough","Learning is okay"],"affirm":"A learning, loving, supported parent is exactly what a neurodiverse child needs; you don't have to be perfect or all-knowing.","relearn":"You don't have to be perfect; a learning, loving, supported parent is enough.","persona":"any","source":"enough"},
  {"id":"nd-056","cat":"support-and-you","type":"role-play","persona":"Priya","source":"support a parent","hook":"Sunita's son is in your child's class, and she has seemed worn out for weeks.","setup":"You are sitting together after a school event.","steps":[{"prompt":"Sunita says: \"I feel so alone in this. Nobody else understands.\"","options":[{"text":"\"At least your child is doing better than some.\"","then":"Sunita goes quiet. \"I suppose. It doesn't feel that way.\""},{"text":"\"You're not alone. Let's swap what helps.\"","then":"Her shoulders drop. \"I'd like that. I have so many questions.\"","best":true},{"text":"\"I know. It's impossible. I don't know how anyone does it.\"","then":"She looks down. \"Yes. That's exactly how it feels.\""},{"text":"\"You should see a specialist. They will sort it out.\"","then":"Sunita sighs. \"I have. It's the hours in between that are hard.\""}],"why":"Saying she's not alone and offering to swap what helps connects you, instead of dwelling on the load."},{"prompt":"Sunita says: \"Last week my son had a meltdown at a wedding. Everyone stared.\"","options":[{"text":"\"Ignore the stares. People are just ignorant.\"","then":"Sunita nods. \"I try. It still stings.\""},{"text":"\"My son does that too. Let me tell you what happened to us.\"","then":"Sunita listens politely, but her own story stays unsaid."},{"text":"\"That sounds hard. What helped him afterwards?\"","then":"She smiles a little. \"Headphones and a quiet corner, actually.\"","best":true},{"text":"\"Maybe skip big functions for a while.\"","then":"She frowns. \"But then we lose everyone.\""}],"why":"Asking what helped lets her share too, and it makes the exchange go both ways."},{"prompt":"As you both pick up your bags, Sunita sighs: \"I should go. Tomorrow it all starts again.\"","options":[{"text":"\"Take care. Call me if you need anything.\"","then":"Sunita nods. \"I will.\" Neither of you brings up meeting again."},{"text":"\"I'll send you a list of therapists tonight.\"","then":"Sunita smiles thinly. \"Thanks.\" Her list of contacts is already long."},{"text":"\"Don't worry. It will get easier soon.\"","then":"She manages a small smile. \"I hope so.\""},{"text":"\"Let's meet again. I'll message you tonight.\"","then":"She brightens. \"Yes, please. I'd like that.\"","best":true}],"why":"A plan to meet again turns comfort into a network that holds you both."}],"relearn":"Telling an isolated parent they're not alone and offering to share what helps builds the network that sustains them both."},
  {"id":"nd-057","cat":"support-and-you","type":"spot","hook":"Spot the 2 red flags: the ways that don't sustain raising a neurodiverse child.","scene":[{"id":"a","text":"Understanding, accommodating and advocating over time","trick":false},{"id":"b","text":"Chasing a 'cure' and burning out","trick":true},{"id":"c","text":"Building a support network for you both","trick":false},{"id":"d","text":"Carrying it all alone in silence","trick":true},{"id":"e","text":"Looking after your own wellbeing too","trick":false}],"why":"Chasing a 'cure' and carrying it alone in silence are the red flags: neither sustains a parent or child.","relearn":"Understanding, accommodation, advocacy, a network and self-care sustain you; chasing a 'cure' and silent isolation don't.","persona":"any","source":"sustainable way"},
  {"id":"nd-058","cat":"support-and-you","type":"reflect","hook":"Lensy: understand, accommodate, advocate, drop the shame, and look after yourself too. Your child is lucky to have you. Ready?","prompt":"What's your take?","options":["Ready","Lucky to have me","Let's go"],"affirm":"Understanding, accommodating, advocating, dropping the shame and caring for yourself is how you raise a neurodiverse child well.","relearn":"Understand, accommodate, advocate, drop the shame, and look after yourself; that's the whole of it.","persona":"any","source":"the whole of it"},
  {"id":"nd-059","cat":"support-and-you","type":"role-play","persona":"Vikram","source":"bring co-parent in","hook":"Your partner Sneha finds the diagnosis hard to accept and has stayed on the edges of your child's care.","setup":"Tonight the two of you are alone after bedtime.","steps":[{"prompt":"Sneha says: \"I keep thinking they will grow out of it. Why make it a big thing?\"","options":[{"text":"\"They won't grow out of it. You need to face facts.\"","then":"Sneha stiffens. \"Don't lecture me. I'm trying.\""},{"text":"\"Fine. I'll deal with all of it myself then.\"","then":"Sneha says quietly, \"If you say so,\" and turns back to her phone."},{"text":"\"Our child needs us both. Let's learn this together.\"","then":"Sneha looks up. \"Together. Okay. I'd like to.\"","best":true},{"text":"\"Let's wait for the next school report first.\"","then":"Sneha nods, relieved. The talk is pushed to another day."}],"why":"It's lifelong, so inviting her to learn as a team brings her in without blaming her."},{"prompt":"A few days later, Sneha says: \"I read the report again. I don't know where to start.\"","options":[{"text":"\"Just read what I send you. I've done the research.\"","then":"Sneha sighs. \"You always know more than me.\""},{"text":"\"Don't stress. Be there at bedtime and I'll handle the rest.\"","then":"\"Okay,\" she says, looking a little relieved and a little left out."},{"text":"\"Come to the next appointment. We'll ask questions together.\"","then":"She takes a breath. \"Okay. I'll write my questions down.\"","best":true},{"text":"\"Maybe talk to your mother about it.\"","then":"Sneha's face tightens. \"She'll only say we spoiled them.\""}],"why":"Going together gives her a concrete first step and shows you are a team."},{"prompt":"Sneha asks: \"What can I actually do that helps?\"","options":[{"text":"\"Anything is fine. Do what feels right.\"","then":"Sneha frowns. \"That's not much to go on.\""},{"text":"\"Come to every appointment and take notes.\"","then":"Sneha's eyes widen. \"Every one? I have work.\""},{"text":"\"You're great at the bedtime story. Could that be yours?\"","then":"A smile. \"I can do that. Every night?\"","best":true},{"text":"\"Nothing much. It's easier if I just do it.\"","then":"Sneha shrugs. \"Okay then.\""}],"why":"A small, clear role that fits her strengths draws her in and shares the load."}],"relearn":"Inviting a co-parent to learn and support together shares the load and doubles a neurodiverse child's champions."},
  {"id":"nd-060","cat":"understand-your-child","type":"role-play","persona":"Divya","source":"reframe weird","hook":"Your older son Aarav calls his younger brother \"weird\", and you want to reframe it with warmth.","setup":"It is dinner time and the brothers are squabbling.","steps":[{"prompt":"Aarav says: \"He's weird. He hums all through dinner.\"","options":[{"text":"\"Yes, he's a bit odd. Just ignore it.\"","then":"Aarav smirks. His brother stops humming."},{"text":"\"Don't call your brother names. Say sorry.\"","then":"Aarav mutters \"Sorry\" with folded arms. The humming stops."},{"text":"\"He can't help it. Be patient with him.\"","then":"Aarav sighs. \"He always gets a pass.\""},{"text":"\"Different isn't weird. We love it.\"","then":"Aarav frowns. \"But it's loud.\"","best":true}],"why":"Reframing weird as different teaches acceptance and shields his brother."},{"prompt":"Later, the humming starts again. Aarav asks: \"Why does he even do that?\"","options":[{"text":"\"He just does. Don't think about it.\"","then":"Aarav shrugs. His curiosity goes unanswered."},{"text":"\"Ignore him. He wants attention.\"","then":"Aarav nods and glares at his brother."},{"text":"\"The doctor says he has a condition.\"","then":"Aarav's eyes widen. \"Is he sick?\""},{"text":"\"Humming calms him when it gets too loud.\"","then":"Aarav's face changes. \"Oh. Like when I bite my nails?\"","best":true}],"why":"A simple, true reason helps Aarav see humming as calming, not annoying."},{"prompt":"Aarav asks: \"Can he stop humming when my friends come over?\"","options":[{"text":"\"No. He can hum whenever he likes.\"","then":"Aarav slams his cup down. \"It's always about him.\""},{"text":"\"Fine. I'll tell him to stop when they are here.\"","then":"Aarav smiles. His brother hears it from the doorway."},{"text":"\"Why are you so ashamed of him?\"","then":"Aarav's eyes fill. \"I'm not! I just want them to like me.\""},{"text":"\"Let's find a way together. What would help?\"","then":"Aarav thinks. \"My friends and I could play in my room. He can hum out here.\"","best":true}],"why":"Solving it together respects both boys' needs, and neither is shamed."},{"prompt":"At bedtime, Aarav says: \"Sorry I called him weird. Was I bad?\"","options":[{"text":"\"Yes, that was unkind. Don't do it again.\"","then":"Aarav's face crumples. \"I'll never say anything again.\""},{"text":"\"It's fine. Forget it.\"","then":"Aarav nods. \"Okay.\" He looks unsure."},{"text":"\"Just say sorry to him and it's over.\"","then":"Aarav says: \"Okay.\" He mumbles a quick sorry the next day."},{"text":"\"You're not bad. You're learning. I love how you care.\"","then":"Aarav hugs you. \"Can I sit next to him at breakfast tomorrow?\"","best":true}],"why":"Reassuring a sibling that he is learning, not bad, keeps his door open to helping."}],"relearn":"Reframing 'weird' as a different, valued way of being teaches a sibling acceptance instead of othering."},
  {"id":"nd-061","cat":"understand-your-child","type":"role-play","persona":"Meena","source":"nothing is wrong","hook":"Your son has had a hard week at school and has barely spoken since Monday.","setup":"He climbs onto your lap after school.","steps":[{"prompt":"Your son asks: \"Mumma, is something wrong with me?\"","options":[{"text":"\"We're working on fixing it. Please don't worry about it, beta.\"","then":"He whispers: \"So there is something to fix.\""},{"text":"\"Who said that? Tell me their name right now.\"","then":"He shrinks back. \"Nobody. Forget it.\""},{"text":"\"Of course not. Eat your snack and stop worrying.\"","then":"He nods and eats. The question stays inside."},{"text":"\"Nothing is wrong with you. Your brain works its own way.\"","then":"He looks up. \"Then why is school so hard?\"","best":true}],"why":"Telling him plainly that nothing is wrong protects his sense of worth."},{"prompt":"Later, your son says: \"Other kids finish quickly. Why is school so hard for me?\"","options":[{"text":"\"You're just not trying hard enough at your work.\"","then":"His lip trembles. \"I am trying.\""},{"text":"\"It's hard for everyone. It gets easier with time.\"","then":"He shrugs. \"Not for me, it doesn't.\""},{"text":"\"The doctor will tell us what's wrong with you.\"","then":"He goes very still. \"So there is something wrong.\""},{"text":"\"Your brain learns differently. We'll find ways.\"","then":"He perks up. \"Like drawing my answers?\"","best":true}],"why":"Naming his different way of learning turns hard days into a search for what suits him."},{"prompt":"At bedtime, he says: \"Will I always be like this?\"","options":[{"text":"\"No. You'll grow out of it.\"","then":"He looks hopeful. \"When?\" You have no answer."},{"text":"\"Let's not think about that tonight.\"","then":"He turns to the wall. The question stays."},{"text":"\"Only if we work hard on fixing it.\"","then":"He nods. \"I'll work harder, then.\""},{"text":"\"You'll always be you. I love that.\"","then":"He smiles sleepily. \"Okay, Mumma.\"","best":true}],"why":"Telling him he will always be himself, and loved, gives him something to hold on to."}],"relearn":"Telling a child nothing is wrong, their brain just works its own way with real gifts, protects their self-worth."},
  {"id":"nd-062","cat":"understand-your-child","type":"sort","hook":"Sort: an accurate understanding of neurodivergence, or a myth?","items":[{"id":"a","text":"Brains naturally vary"},{"id":"b","text":"It's contagious or a trend"},{"id":"c","text":"Every profile is individual"},{"id":"d","text":"It means low intelligence"},{"id":"e","text":"Real strengths come with it"},{"id":"f","text":"Bad parenting causes it"}],"bins":[{"id":"accurate","label":"Accurate","valence":"pos"},{"id":"myth","label":"Myth","valence":"neg"}],"key":{"a":"accurate","b":"myth","c":"accurate","d":"myth","e":"accurate","f":"myth"},"relearn":"Brains varying, individual profiles and real strengths are accurate; 'contagious, low intelligence, bad parenting' are myths.","persona":"any","source":"accurate or myth"},
  {"id":"nd-063","cat":"understand-your-child","type":"spot","hook":"Spot the two lenses that fail to help you understand your child.","scene":[{"id":"a","text":"'How does my child experience the world?'","trick":false},{"id":"b","text":"'Why won't they just act normal?'","trick":true},{"id":"c","text":"'What are their strengths and needs?'","trick":false},{"id":"d","text":"'What did I do to cause this?'","trick":true},{"id":"e","text":"'How can I support who they really are?'","trick":false}],"why":"'Why won't they act normal' and 'what did I do' don't help; asking how they experience things, their strengths and needs does.","relearn":"Understand your child by asking how they experience the world and what they need, not 'why won't they act normal' or self-blame.","persona":"Meena","source":"helpful lens"},
  {"id":"nd-064","cat":"accommodate","type":"role-play","persona":"Vikram","source":"not pandering","hook":"Your son wears headphones and keeps a fixed routine, and your uncle does not approve.","setup":"Over tea, he leans back with a frown.","steps":[{"prompt":"Your uncle says: \"You are pandering to him. He must toughen up.\"","options":[{"text":"\"Maybe you are right. I will let him tough it out.\"","then":"Uncle nods, satisfied. \"Good.\" Your son quietly tucks his headphones away."},{"text":"\"You do not know his life. Mind your own business.\"","then":"His face hardens. \"I was only saying it for his good.\""},{"text":"\"The doctor said so, so there is nothing to discuss.\"","then":"Uncle shrugs. \"Doctors say many things, beta.\""},{"text":"\"They are like glasses. They help him do his best.\"","then":"Uncle frowns. \"Glasses? Hmm. But he looks fine to me.\"","best":true}],"why":"Comparing supports to glasses explains fair access without a fight."},{"prompt":"Uncle asks: \"Why should he get what the other children do not?\"","options":[{"text":"\"You are right. I will cut some of it to keep things fair.\"","then":"\"Good, good.\" Your son's headphones stay in the drawer all week."},{"text":"\"Fair does not mean the same. He gets what lets him join in.\"","then":"He scratches his chin. \"Hmm. Your aunt uses her stick, after all.\"","best":true},{"text":"\"Other children are not your concern. Please leave us be.\"","then":"He sits back, offended, then looks over at your son and sighs."},{"text":"\"It keeps him quiet, honestly. That is all it really does.\"","then":"\"Ah, so it is a convenience,\" he says, unimpressed."}],"why":"Fair access means giving each child what lets them take part."},{"prompt":"Uncle asks: \"What should I do when he covers his ears at my house?\"","options":[{"text":"\"Nothing. We will stop visiting so we do not trouble you.\"","then":"He looks hurt. \"I did not say that.\""},{"text":"\"Tell him to stop. He will listen to you, Uncle.\"","then":"\"Stop it, beta,\" he says gruffly. Your son covers his ears harder."},{"text":"\"Ask his mother. She handles all of that.\"","then":"\"Ah, alright.\" He drops it, and nothing changes."},{"text":"\"Just let him sit in a quiet room. He will come back.\"","then":"\"A quiet room. That I can do,\" he says slowly.","best":true}],"why":"A simple way to help turns a critic into a helper."},{"prompt":"Uncle says: \"My grandson struggles too. Could such headphones help him?\"","options":[{"text":"\"Buy the same ones. They are a cure for noise.\"","then":"He nods eagerly. He buys the pair and expects a miracle."},{"text":"\"Maybe. Let him try them, and watch what actually helps him.\"","then":"He nods. \"Try and watch. That is sensible. I will ask his mother.\"","best":true},{"text":"\"I cannot say. Please ask someone else about it.\"","then":"He shrugs. \"As you like.\" The chance to help fades."},{"text":"\"Every child needs them. Buy pairs for all your grandchildren.\"","then":"He laughs. \"All of them? Now you are exaggerating.\""}],"why":"Trying supports and watching what helps is how to find what fits any child."}],"relearn":"Framing accommodations as fair access, like glasses, defends them against the 'pandering' myth without a fight."},
  {"id":"nd-065","cat":"accommodate","type":"sort","hook":"Sort: respects how the child is wired, or forces them to mask?","items":[{"id":"a","text":"Letting them fidget to focus"},{"id":"b","text":"Forcing stillness and 'normal' behaviour"},{"id":"c","text":"Quiet breaks when overstimulated"},{"id":"d","text":"Punishing self-soothing"},{"id":"e","text":"Respecting their safe foods"},{"id":"f","text":"Mocking their stims till they stop"}],"bins":[{"id":"respect","label":"Respects the wiring","valence":"pos"},{"id":"mask","label":"Forces masking","valence":"neg"}],"key":{"a":"respect","b":"mask","c":"respect","d":"mask","e":"respect","f":"mask"},"relearn":"Fidgeting, quiet breaks and respected foods honour the wiring; forcing stillness, punishing self-soothing or mocking stims force masking.","persona":"Meena","source":"respect or mask"},
  {"id":"nd-066","cat":"accommodate","type":"branch","persona":"Divya","source":"ease transitions","hook":"Your son copes best with strict routine, but today the plans are changing.","steps":[{"prompt":"His school van is cancelled and you will drive him instead. How do you tell him?","options":[{"text":"Tell him at the door just as you are leaving the house","then":"He freezes on the step. \"Why?\" he asks, and you are already late."},{"text":"Show a picture card of the change and say what is next","then":"He studies the card, then asks, \"Then school?\" You say yes and he nods.","best":true},{"text":"Promise the van will be back tomorrow, to calm him down","then":"He relaxes for now. You are not sure it will be true, and it sits uneasily."},{"text":"Say it is no big deal and that he will cope with it","then":"He looks at you, unsure, and holds on to the door frame."}],"why":"Early warning with a picture gives him time to see what changes and what stays."},{"prompt":"Next week the school plans a loud fire drill. What do you ask the teacher for?","options":[{"text":"Keep him home on the day of the drill, so he is spared it","then":"She agrees. He misses school, and the alarm is still going to sound some day."},{"text":"Nothing at all, since fire drills are for everyone alike","then":"She treats him like the rest. Nobody plans anything for him."},{"text":"Tell him just before the alarm sounds, so he is ready","then":"She agrees. He hears the words seconds before, and his eyes go wide."},{"text":"A heads-up for him, a picture of the steps and earmuffs","then":"The teacher agrees and draws a picture strip. He learns the steps before the day.","best":true}],"why":"A picture of the steps and a heads-up let him prepare instead of being startled."},{"prompt":"Your husband says he should learn to take changes as they come, without warnings. What do you say?","options":[{"text":"Agree, and let changes come without warning from now on","then":"The next surprise ends in a long meltdown. Nobody is sure why."},{"text":"Warning makes change easier and shows him how to cope","then":"He thinks it over. \"Let us try it for a month,\" he says.","best":true},{"text":"That the therapist says to warn him, and leave it there","then":"He goes quiet, unconvinced. Neither of you brings it up again."},{"text":"That you know best, since you are with him all day long","then":"He steps back, stung. You end up handling the routine alone."}],"why":"Explaining why warning helps brings your husband along and keeps the support steady."}],"debrief":"Ease sudden changes for a routine-reliant child with warning and a visual.","relearn":"Prepare a routine-reliant child for change with warning and a visual; don't spring it."},
  {"id":"nd-067","cat":"accommodate","type":"match","hook":"Match each tricky moment to the accommodation that helps.","pairs":[{"left":"Overwhelming party","right":"A quiet exit plan and headphones"},{"left":"New place","right":"Visit or preview it in advance"},{"left":"Big feelings","right":"A calm-down space, not a telling-off"},{"left":"Sudden change","right":"A warning and a visual of it"},{"left":"Long wait","right":"A fidget toy and a known wait-time"}],"relearn":"Parties, new places, big feelings, sudden change and long waits each go better with a simple accommodation than with force.","persona":"any","source":"moment to accommodation"},
  {"id":"nd-068","cat":"advocate","type":"role-play","persona":"Meena","source":"partner with teacher","hook":"You are meeting your son's teacher to ask for support.","setup":"She sits down across the table with his file.","steps":[{"prompt":"The teacher says: \"Thank you for coming. What would you like to discuss?\"","options":[{"text":"\"Your class is failing my child, and it is your fault.\"","then":"Her face closes. \"That is not fair. I have tried.\""},{"text":"\"Please tell me what he has done wrong this week.\"","then":"She reads out a list. The meeting becomes a list of his faults."},{"text":"\"I only want him treated like everyone else in the class.\"","then":"\"Of course. He is treated the same as the rest,\" she says. Nothing changes."},{"text":"\"I would love to work with you. Here is what helps him.\"","then":"She smiles. \"I would like that. Tell me what works at home.\"","best":true}],"why":"Opening as a partner, with what helps, gets a teacher on your side."},{"prompt":"She says: \"He struggles to sit through a whole lesson.\"","options":[{"text":"\"That is just how he is. There is nothing to be done.\"","then":"She sighs. \"Then I will have to keep telling him off.\""},{"text":"\"Yes. A short movement break helps him. Could we try that?\"","then":"She thinks. \"A short break every so often. I can do that.\"","best":true},{"text":"\"Then send him out of the class when he cannot sit.\"","then":"She nods. He spends the lesson in the corridor, alone."},{"text":"\"He only does that because you are too strict with him.\"","then":"She stiffens. \"I am not strict. I am trying to teach a full class.\""}],"why":"A specific, doable suggestion gives her something to try in class."},{"prompt":"She asks: \"If we try something, how will we know it is working?\"","options":[{"text":"\"He will tell you himself when he is happy in the class.\"","then":"\"He never says much,\" she says. \"Hard to tell.\""},{"text":"\"You will see. He will stop causing trouble in class.\"","then":"\"That is a low bar for him,\" she says. \"I hope for more.\""},{"text":"\"I will watch his marks. If they rise, it is working.\"","then":"\"Marks may take a long time,\" she says. \"They are only one sign.\""},{"text":"\"Let us note it for a month and then review it together.\"","then":"She writes the date. \"Good. Let us look at it together.\"","best":true}],"why":"A shared note and a review date show what is helping, not only marks."}],"relearn":"Opening as a collaborative partner, with what helps, gets a teacher on side far better than blame."},
  {"id":"nd-069","cat":"advocate","type":"sort","persona":"any","source":"strong or weak","hook":"Sort: strengthens your advocacy, or weakens it?","items":[{"id":"a","text":"Documenting needs and what works"},{"id":"b","text":"Giving up after one 'no'"},{"id":"c","text":"Knowing your child's legal protections"},{"id":"d","text":"Apologising for asking at all"},{"id":"e","text":"Bringing your partner to the meeting"},{"id":"f","text":"Relying only on memory in the room"}],"bins":[{"id":"strong","label":"Strengthens it","valence":"pos"},{"id":"weak","label":"Weakens it","valence":"neg"}],"key":{"a":"strong","b":"weak","c":"strong","d":"weak","e":"strong","f":"weak"},"relearn":"Documentation, knowing the law and bringing your partner strengthen advocacy; giving up, over-apologising or relying on memory weaken it."},
  {"id":"nd-070","cat":"advocate","type":"branch","persona":"Divya","source":"persist politely","hook":"A service is slow and dismissive about assessing your son.","steps":[{"prompt":"The clinic says the waiting list is full and to try next year. What do you do?","options":[{"text":"Ask to be added to the list and for a date to check back","then":"The receptionist adds his name and says the clinic will be in touch.","best":true},{"text":"Say that is fine and stop trying to get him assessed","then":"Weeks go by. His teacher raises the same worries again."},{"text":"Demand to see the head doctor now or you will complain","then":"The receptionist stiffens and says the doctor is not available. Nothing moves."},{"text":"Book the first clinic that promises a fast result, unchecked","then":"The new clinic promises much. You cannot tell who is qualified."}],"why":"Getting on the list and a date to follow up keeps the path open."},{"prompt":"A month on, there is still no date for his assessment at the first clinic. What do you do?","options":[{"text":"Assume nothing will come of it and give up on this clinic","then":"You put the file away. Weeks go by without a plan."},{"text":"Send an angry message saying the clinic is useless","then":"They reply once, briefly. The tone of every later call is cold."},{"text":"Call politely and ask for the next step and a timeline","then":"\"Let me check,\" she says. She notes your call on his file and gives you a date.","best":true},{"text":"Wait another month in case they are just busy","then":"The second month passes. Still no call, and calling now feels harder."}],"why":"A polite, specific follow-up keeps his file moving and the door open."},{"prompt":"You then learn the clinic cannot see him for six more months. What do you try?","options":[{"text":"Ask for another route: a second centre or a parent group","then":"The clinic gives you two names. A parent group tells you a third.","best":true},{"text":"Wait the six months quietly, since that is what they said","then":"The months pass. His difficulties at school continue in the meantime."},{"text":"Decide that no real help exists for him in your city","then":"You stop looking. Each month makes it feel more true."},{"text":"Take him to someone who promises a quick cure","then":"The fee is high. The promise fades after two weeks, and so does your money."}],"why":"One long wait is not the end. Other routes can start support sooner."},{"prompt":"Months later, a parent tells you about a centre that may have a slot. What do you do?","options":[{"text":"Assume it will be the same as the others and skip it","then":"You do not call. A month later the parent asks if you tried."},{"text":"Turn up unannounced and demand to be seen today","then":"They ask you to wait outside. The staff seem tense and firm."},{"text":"Call politely, say what you need and ask about the timeline","then":"The centre says a slot may open next month, and takes your number.","best":true},{"text":"Ask the parent to book it and stay out of it yourself","then":"She books it under her name. The centre has no way to reach you."}],"why":"A polite call with a clear ask keeps every route to support open."}],"debrief":"Persist politely and seek other routes when a service is slow; don't give up on the support needed.","relearn":"Keep advocating through slow services; one dismissal isn't the end of the road to support."},
  {"id":"nd-071","cat":"advocate","type":"match","persona":"Meena","source":"right to place","hook":"Match each right or support to where it applies.","pairs":[{"left":"Reasonable accommodation","right":"School and services"},{"left":"A learning-support plan","right":"The classroom"},{"left":"Family understanding","right":"The home and gatherings"},{"left":"Exam concessions on assessment","right":"The exam board"},{"left":"Tailored strategies","right":"A qualified professional"}],"relearn":"Reasonable accommodation, a support plan, family understanding, exam concessions and tailored strategies each apply where your child needs championing."},
  {"id":"nd-072","cat":"drop-the-shame","type":"role-play","persona":"Meena","source":"no punishment","hook":"At a family puja, some relatives are gossiping about your son's diagnosis.","setup":"Afterwards, an aunt catches you alone in the kitchen.","steps":[{"prompt":"Aunty Sudha whispers: \"This must be karma. What did your family do?\"","options":[{"text":"\"It's no one's fault and no punishment. It's how his brain works.\"","then":"She blinks. \"Oh. I only heard it from others,\" she mumbles.","best":true},{"text":"\"Maybe. I do wonder what we did wrong.\"","then":"Aunty Sudha nods. \"These things happen for a reason,\" she says."},{"text":"\"Not karma, just bad luck. It could have happened to anyone.\"","then":"She sighs and pats your arm. \"Poor thing. Bad luck, yes.\""},{"text":"\"How dare you? Get out of my kitchen.\"","then":"She gasps and leaves. By morning half the family knows you shouted."}],"why":"Saying it is no one's fault, and no punishment, protects you both from baseless blame."},{"prompt":"At the next dinner, Aunty Sudha says: \"People say you should do a puja to remove it.\"","options":[{"text":"\"You're welcome to pray for us. It won't change who he is.\"","then":"She softens. \"I'll pray for his happiness, then,\" she says.","best":true},{"text":"\"Fine, we'll do the puja, just to keep everyone quiet.\"","then":"She smiles, pleased. The puja is planned, and your son is told it will fix him."},{"text":"\"Let me ask his doctor whether that's a good idea.\"","then":"She looks confused. \"Doctors don't do pujas,\" she says, and the moment passes."},{"text":"\"I don't believe in any of that nonsense. Please stop.\"","then":"Her face falls. \"Your generation has no respect,\" she says, and turns away."}],"why":"You can honour her faith and still say plainly that it doesn't change who he is."},{"prompt":"A cousin tells you: \"Aunty Sudha is telling others it was karma.\"","options":[{"text":"\"Thanks for telling me. I'll talk to her again, calmly.\"","then":"Your cousin nods. \"I'll say it's not true if it comes up,\" she says.","best":true},{"text":"\"Give me their names. I'll call each one and explain.\"","then":"Your cousin lists four names. You spend the evening on calls, and the story still spreads."},{"text":"\"Let her talk. It's only words and she means no harm.\"","then":"Your cousin shrugs. By evening three more people have heard it."},{"text":"\"Then I'll tell the whole family she is a gossip.\"","then":"Your cousin winces. The family splits into two camps."}],"why":"Talking to her again, calmly, stops the story and keeps the family door open."}],"relearn":"Naming that it's no one's fault and no punishment protects both you and your child from cruel, baseless blame."},
  {"id":"nd-073","cat":"drop-the-shame","type":"sort","hook":"Sort each statement: a true, shame-lifting line, or a harmful blame myth.","items":[{"id":"a","text":"'You didn't cause this'"},{"id":"b","text":"'Bad mothers raise such kids'"},{"id":"c","text":"'Your child can thrive'"},{"id":"d","text":"'Hide it from everyone'"},{"id":"e","text":"'It's no one's fault'"},{"id":"f","text":"'It's karma for past sins'"}],"bins":[{"id":"true","label":"True, lifts shame","valence":"pos"},{"id":"blame","label":"Harmful blame","valence":"neg"}],"key":{"a":"true","b":"blame","c":"true","d":"blame","e":"true","f":"blame"},"relearn":"'You didn't cause this', 'your child can thrive' and 'no one's fault' lift shame; blaming mothers, 'hide it' and 'karma' are harmful.","persona":"any","source":"true or blame"},
  {"id":"nd-074","cat":"drop-the-shame","type":"spot","hook":"Spot the two moves that keep a family stuck in shame.","scene":[{"id":"a","text":"Accepting it's no one's fault","trick":false},{"id":"b","text":"Blaming yourself endlessly","trick":true},{"id":"c","text":"Focusing energy on support","trick":false},{"id":"d","text":"Hiding him so neighbours don't talk","trick":true},{"id":"e","text":"Telling him he's wonderful as he is","trick":false}],"why":"Endless self-blame and hiding the child keep a family stuck; accepting it's no one's fault and focusing on support free them.","relearn":"Catch the stuck-in-shame moves, self-blame and hiding; freedom comes from 'no one's fault' and focusing on support.","persona":"any","source":"catch the stuck moves"},
  {"id":"nd-075","cat":"drop-the-shame","type":"branch","persona":"Vikram","source":"share on your terms","hook":"Your father is shaken by your child's diagnosis and fears what the neighbours will say.","steps":[{"prompt":"Your father asks you to tell no one, not even relatives. What do you do?","options":[{"text":"Choose a few people who can help and tell them","then":"Your father grumbles, but you feel steadier with a plan of your own.","best":true},{"text":"Agree, so your father stays calm at home","then":"Your father relaxes. You start rehearsing what to say if someone asks."},{"text":"Post the news in the family WhatsApp group tonight","then":"Replies flood in, some warm and some nosy. You wonder if you were ready for that."},{"text":"Tell one friend, but make her swear to secrecy","then":"She promises and keeps her word. It helps a little, and you still feel you are hiding."}],"why":"Choosing who to tell keeps the decision yours and lets real support in."},{"prompt":"A week later, your child's teacher asks if something is going on at home. What do you say?","options":[{"text":"Share the diagnosis and ask what would help in class","then":"The teacher listens, jots notes, and offers a quieter seat and clearer instructions.","best":true},{"text":"Say everything is fine at home","then":"She nods. The trouble in class carries on without anyone knowing why."},{"text":"Say your child is only shy and needs time","then":"She smiles and waits. The same struggles show up again by Friday."},{"text":"Tell her, but beg her to tell nobody else at school","then":"She agrees, then says it will be hard to arrange help quietly."}],"why":"A teacher who knows can adjust the class, and you still choose how much to share."},{"prompt":"At a cousin's engagement, an aunty asks why your child stays away from the crowd. What do you say?","options":[{"text":"Say crowds tire them, so you plan quiet breaks","then":"Aunty says she didn't know, and points you to a quiet room upstairs.","best":true},{"text":"Say it's nothing and steer her to the buffet","then":"Aunty lets it go, but her eyes follow your child across the hall."},{"text":"Explain the full diagnosis to everyone at the table","then":"The table goes silent. Every face turns to your child, who shrinks into a chair."},{"text":"Promise to make your child mingle from now on","then":"Aunty smiles. Your child is nudged into the crowd and clings to your sleeve."}],"why":"Sharing what helps, and no more, keeps you in charge of your own story."}],"debrief":"Share the diagnosis on your own terms with supportive people; secrecy isolates you and feeds stigma.","relearn":"Choose openness on your terms over secrecy; hiding it carries the shame it's trying to avoid."},
  {"id":"nd-076","cat":"strengths-and-wellbeing","type":"role-play","persona":"Meena","source":"honour the passion","hook":"Your child talks about planets all day, and others call it obsessive.","setup":"Tonight they climb onto the sofa beside you, eyes shining.","steps":[{"prompt":"Your child says: \"Mummy, want to hear why Saturn has rings?\"","options":[{"text":"\"Yes! Tell me everything, and I'll get us a book on it.\"","then":"They beam and start at the beginning, using their hands to show the rings.","best":true},{"text":"\"Okay, but only five minutes, then homework.\"","then":"They race through it, gulping air, and stop unfinished."},{"text":"\"Sure, but please don't tell your friends all this.\"","then":"They nod, though they can't see why. Their eagerness dims."},{"text":"\"Enough of that. Talk about normal things.\"","then":"They stop mid-sentence. The room goes quiet."}],"why":"Feeding the interest shows them their way of loving a topic is welcome."},{"prompt":"The next morning at the gate, your neighbour says: \"Your child is obsessed. It can't be healthy.\"","options":[{"text":"\"It's a strength. It may become something amazing for them.\"","then":"The neighbour raises her eyebrows. \"Well, they do know a lot,\" she says.","best":true},{"text":"\"You're right. I'll try to widen their interests soon.\"","then":"She nods, satisfied. Your child, listening, wonders what they did wrong."},{"text":"\"They're just a child. They'll grow out of it.\"","then":"She shrugs. \"Let's hope so,\" she says, and your child hears that it should stop."},{"text":"\"Please mind your own business.\"","then":"She huffs. \"Only trying to help,\" she says, and leaves."}],"why":"Naming the interest as a strength changes how others see it, and how your child does."},{"prompt":"Their teacher writes: \"They talk about planets in maths. Please stop this.\"","options":[{"text":"\"Can their interest be used in maths lessons?\"","then":"The teacher calls you back, intrigued. \"Planet sums would work,\" she says.","best":true},{"text":"\"It's their passion, and you must simply accept it.\"","then":"The teacher replies coolly. The friction stays and the interest stays a problem."},{"text":"\"I promise I'll stop them talking about planets.\"","then":"You promise. The next day your child is told off for breaking the rule."},{"text":"\"I'll take away their planet books until it stops.\"","then":"The books go on a high shelf. The next day they say nothing in class at all."}],"why":"Bringing their interest into lessons turns a clash into a strength for everyone."},{"prompt":"Weeks later, your child asks: \"Can I show my class my planets?\"","options":[{"text":"\"Yes. Let's ask the teacher for a slot and practise together.\"","then":"The teacher gives them ten minutes. Classmates ask questions, and they glow.","best":true},{"text":"\"I'll ask the teacher myself, and you can stay out of it.\"","then":"The teacher agrees. Your child hears about it after and feels sidelined."},{"text":"\"Only if you keep it very short and normal.\"","then":"They rush through, drop half the facts, and sit down flushed."},{"text":"\"No, they might laugh at you.\"","then":"They nod, and the planets go back in their bag."}],"why":"Helping them share their passion, with a plan, lets classmates see their gift."}],"relearn":"Honouring an intense interest as a strength to feed builds confidence, unlike dismissing it as 'obsessive'."},
  {"id":"nd-077","cat":"strengths-and-wellbeing","type":"role-play","persona":"Meena","source":"reconnect after meltdown","hook":"After a meltdown has passed, your child looks ashamed.","setup":"They are sitting very still, eyes on the floor.","steps":[{"prompt":"Your child says in a small voice: \"I'm sorry I'm so much trouble.\"","options":[{"text":"\"You're not trouble. It's over, and I love you.\"","then":"They lean into you and breathe out. \"Okay,\" they whisper.","best":true},{"text":"\"You're not trouble. Just try to stay calmer next time.\"","then":"They nod, then whisper that they'll try. Their shoulders stay up around their ears."},{"text":"\"It's fine. Let's not talk about it again.\"","then":"They nod and look away. The shame stays in the room."},{"text":"\"You should be sorry. Everyone was upset today.\"","then":"They pull their knees in and stop speaking."}],"why":"Words that say you are not in trouble and are loved rebuild their sense of safety."},{"prompt":"Your child asks: \"Why did I scream so much?\"","options":[{"text":"\"Your body got too full of noise and feelings.\"","then":"They think. \"Like a balloon,\" they say, and hold their arms wide.","best":true},{"text":"\"You lost control. We need to work on that.\"","then":"They look down. \"I don't like it when I do that,\" they say."},{"text":"\"Because you didn't get what you wanted.\"","then":"They frown. \"But I did want it,\" they whisper, confused and ashamed."},{"text":"\"I don't know. Let's not think about it.\"","then":"They shrug, and the question stays unanswered."}],"why":"Naming overwhelm gives them a word for it, and takes the blame off them."},{"prompt":"At bedtime, they say: \"What if it happens at school tomorrow?\"","options":[{"text":"\"We'll pick a signal and a quiet spot together.\"","then":"They nod. \"Can the signal be a blue card?\" they ask.","best":true},{"text":"\"It won't happen. You'll be fine, I promise.\"","then":"They nod, but check the clock twice in the next hour."},{"text":"\"Then try really hard not to scream.\"","then":"They lie stiff in bed, promising themselves to try harder."},{"text":"\"Then tell yourself to be brave, like everyone.\"","then":"They pull the sheet to their chin and go quiet."}],"why":"A concrete plan gives them a way out, which lowers the fear of it happening."},{"prompt":"Next morning, your child asks: \"Will you still love me if it happens again?\"","options":[{"text":"\"Always. Loud or quiet, I love you.\"","then":"They hug you tight. \"Even when I'm loud?\" they ask. \"Especially then,\" you say.","best":true},{"text":"\"Of course. But you should try not to.\"","then":"They nod. They carry the 'but' all the way to school."},{"text":"\"Yes, though others may be less patient.\"","then":"They frown, worried, and hold your hand harder at the gate."},{"text":"\"Let's not think about that now.\"","then":"They shrug on their bag and leave without meeting your eyes."}],"why":"Love that doesn't depend on behaviour tells them they are safe, always."}],"relearn":"Reconnecting after a meltdown with reassurance, not reproach, rebuilds safety and self-worth."},
  {"id":"nd-078","cat":"strengths-and-wellbeing","type":"sort","hook":"Sort: builds a neurodiverse child's confidence, or erodes it?","items":[{"id":"a","text":"Naming what they're great at"},{"id":"b","text":"Only ever pointing out problems"},{"id":"c","text":"Celebrating small wins"},{"id":"d","text":"Comparing them to 'normal' kids"},{"id":"e","text":"Trusting them with a real task"},{"id":"f","text":"Mocking how they speak or move"}],"bins":[{"id":"build","label":"Builds confidence","valence":"pos"},{"id":"erode","label":"Erodes it","valence":"neg"}],"key":{"a":"build","b":"erode","c":"build","d":"erode","e":"build","f":"erode"},"relearn":"Naming strengths and celebrating wins build confidence; problem-only focus and comparisons erode it.","persona":"any","source":"build or erode"},
  {"id":"nd-079","cat":"strengths-and-wellbeing","type":"match","hook":"Match each sign to what your child may need.","pairs":[{"left":"Overwhelmed and melting down","right":"Calm, co-regulation, less stimulation"},{"left":"Anxious before a change of plan","right":"Preparation and reassurance"},{"left":"Lighting up over an interest","right":"Encouragement and space"},{"left":"Ashamed after a hard moment","right":"Reconnection, not reproach"},{"left":"Low and withdrawn for weeks","right":"Taken seriously, maybe support"}],"relearn":"Overwhelm, anxiety, a lit-up interest, post-meltdown shame and lasting low mood each tell you what your child needs.","persona":"Meena","source":"sign to need"},
  {"id":"nd-080","cat":"strengths-and-wellbeing","type":"spot","hook":"Spot the two lines that erode a neurodiverse child's self-worth.","scene":[{"id":"a","text":"Seeing and naming their gifts","trick":false},{"id":"b","text":"Treating them as a list of deficits","trick":true},{"id":"c","text":"Loving them for exactly who they are","trick":false},{"id":"d","text":"'You're nothing but trouble for me'","trick":true},{"id":"e","text":"Telling them you're proud of them","trick":false}],"why":"Treating a child as a list of deficits and calling them 'nothing but trouble' erode self-worth; seeing their gifts, loving and praising them build it.","relearn":"Nurture a neurodiverse child's self-worth by seeing their gifts and loving who they are, not listing deficits.","persona":"Meena","source":"nurture self-worth"},
  {"id":"nd-081","cat":"support-and-you","type":"role-play","persona":"Divya","source":"be honest","hook":"You have been running on empty for weeks, and your friend Kavya has noticed.","setup":"You are on a park bench while the children play.","steps":[{"prompt":"Kavya asks: \"How are you, really?\"","options":[{"text":"\"Oh, we're fine. Busy, but fine. Nothing to worry about.\"","then":"Kavya nods and starts talking about her week. The moment passes."},{"text":"\"Honestly, it's hard. I could use some support.\"","then":"Kavya's face softens. \"Thank you for telling me. What would help?\"","best":true},{"text":"\"Hard, but everyone has their own troubles to carry.\"","then":"Kavya laughs awkwardly. \"True. Anyway.\""},{"text":"\"I'm exhausted, and I feel like I'm failing him.\"","then":"Kavya squeezes your hand. \"You're not failing.\" Neither of you knows what would help."}],"why":"Saying it's hard and asking for support lets a friend actually help."},{"prompt":"Later, Kavya messages: \"Been thinking of you. Can I help with anything?\"","options":[{"text":"\"Thanks, we're okay. I don't want to be any trouble to you.\"","then":"Kavya writes: \"Okay. Shout if that changes.\" You know you won't."},{"text":"\"Could you take him for an hour on Saturdays?\"","then":"\"Done,\" she writes. \"I'll bring snacks.\"","best":true},{"text":"\"Just hearing from you helps. That's honestly enough.\"","then":"\"Any time,\" she writes. Nothing else is planned."},{"text":"\"Can you tell my family I'm fine? They worry.\"","then":"Kavya hesitates. \"I will, if you're sure.\""}],"why":"A specific ask gives your friend something real to do, so help actually arrives."},{"prompt":"That evening, your mother-in-law asks: \"You look tired. Is everything okay?\"","options":[{"text":"\"Just a headache. I'll be fine. Don't worry about me.\"","then":"She nods and turns back to the TV. Nothing changes."},{"text":"\"Kavya knows how it's been. Ask her.\"","then":"She frowns. \"Why bring Kavya into it?\""},{"text":"\"I'm tired because no one else understands him.\"","then":"Her face hardens. \"Everyone is tired. We managed.\""},{"text":"\"I'm tired, Ma. Could you help on weekends?\"","then":"She pauses. \"I didn't know. I can do Sundays.\"","best":true}],"why":"Naming one simple need at home turns honesty into help."}],"relearn":"Being honest that it's hard and you need support opens the door to the help that sustains you for your child."},
  {"id":"nd-082","cat":"support-and-you","type":"sort","hook":"Sort: sustains a parent for the long haul, or burns them out?","items":[{"id":"a","text":"Sharing the load and resting"},{"id":"b","text":"Doing everything alone, always"},{"id":"c","text":"Leaning on a support network"},{"id":"d","text":"Never asking for help"},{"id":"e","text":"Taking short breaks to recharge"},{"id":"f","text":"Ignoring your own needs entirely"}],"bins":[{"id":"sustain","label":"Sustains you","valence":"pos"},{"id":"burn","label":"Burns you out","valence":"neg"}],"key":{"a":"sustain","b":"burn","c":"sustain","d":"burn","e":"sustain","f":"burn"},"relearn":"Sharing the load, a network and short breaks sustain you; doing it all alone, never asking and ignoring your needs burn you out.","persona":"any","source":"sustain or burn"},
  {"id":"nd-083","cat":"support-and-you","type":"match","hook":"Match a parent need to the support for it.","pairs":[{"left":"Feeling alone","right":"A parent support group"},{"left":"Needing strategies","right":"A professional or therapist"},{"left":"Running on empty","right":"Your own wellbeing care (g63)"},{"left":"Unsure about a diagnosis","right":"A qualified assessment"},{"left":"A low night you can't shake","right":"Tele-MANAS, 14416"}],"relearn":"Loneliness, strategies, empty energy, diagnosis doubts and a low night each have a support that fits.","persona":"any","source":"need to support"},
  {"id":"nd-084","cat":"support-and-you","type":"role-play","persona":"Priya","source":"guide grandparent","hook":"Your child's grandmother, Dadi, has been staying with you since the diagnosis last month.","setup":"She sits beside you with a cup of tea.","steps":[{"prompt":"Dadi says: \"I want to help, beta. But I don't understand this diagnosis.\"","options":[{"text":"\"It's complicated. Let's not get into all of that.\"","then":"Dadi nods slowly. \"As you say, beta.\" Her eyes stay on him."},{"text":"\"Read these articles first, then we'll talk.\"","then":"Dadi peers at your phone. \"So many. Where do I even begin?\""},{"text":"\"His brain works in its own way. Let me show you.\"","then":"Dadi leans in. \"Yes, show me. I'll try.\"","best":true},{"text":"\"Don't worry about it. I'll manage him myself.\"","then":"Dadi's face falls. \"Oh. Okay, beta.\""}],"why":"A simple explanation, offered warmly, opens the door for her instead of closing it."},{"prompt":"Later, the TV blares and he covers his ears. Dadi asks: \"What do I do when he does that?\"","options":[{"text":"\"Tell him to stop and listen to you.\"","then":"Dadi says softly: \"Alright, I'll try.\" She looks unsure."},{"text":"\"Just switch off the TV and he'll be fine.\"","then":"Dadi nods. \"Only the TV? What about the pressure cooker?\""},{"text":"\"The noise is too much for him. Give him a quiet corner.\"","then":"Dadi nods. \"So it isn't rudeness. I thought he was ignoring me.\"","best":true},{"text":"\"Don't worry. He will grow out of it soon.\"","then":"Dadi smiles, relieved. \"Then I'll just wait for it to pass.\""}],"why":"He won't grow out of it, so one clear reason and one thing to do make her a partner."},{"prompt":"Dadi says: \"I'd love to do something regular with him. What would be best?\"","options":[{"text":"\"Anything you like. He's fine with everyone.\"","then":"Dadi hesitates. \"Alright. I'll see what he wants.\""},{"text":"\"Teach him to sit still and behave at meals.\"","then":"Dadi nods, though her forehead creases. \"I'll try, beta.\""},{"text":"\"Let me check with the therapist and tell you next month.\"","then":"Dadi says, \"Of course, beta. I'll wait.\""},{"text":"\"Could you take him for a garden walk after school?\"","then":"Her face lights up. \"Every day at four. I'll bring biscuits.\"","best":true}],"why":"A concrete task he enjoys turns her goodwill into steady support."}],"relearn":"Warmly explaining and giving a concrete way to help turns a willing grandparent into real support, not a closed door."},
  {"id":"nd-900","cat":"accommodate","type":"strike-rewrite","hook":"\"A bright tube-light, blaring TV and crowd are fine; he should just get used to it.\"","myth":{"un":"A bright tube-light, blaring TV and crowd are fine; he should just get used to it.","re":"Dimming lights, lowering noise and easing the crowd lets an overloaded child cope; you adjust the setting, not the child.","why":"You flex the room, not the wiring."},"relearn":"Lower the lights, sound and crowd for an overloaded child; adjust the setting, not the child.","persona":"Meena","source":"dial down the room"},
  {"id":"nd-901","cat":"accommodate","type":"strike-rewrite","hook":"\"Letting him wear headphones in the market is babying him; he must toughen up.\"","myth":{"un":"Letting him wear headphones in the market is babying him; he must toughen up.","re":"Noise-cancelling headphones aren't babying; they cut painful sensory overload so he can actually be there with you.","why":"They turn down pain, not effort."},"relearn":"Headphones in a loud market aren't babying; they cut sensory overload so your child can cope and stay.","persona":"Meena","source":"headphones not babying"},
  {"id":"nd-902","cat":"accommodate","type":"strike-rewrite","hook":"\"Only fussy children need special food; he must finish whatever is served.\"","myth":{"un":"Only fussy children need special food; he must finish whatever is served.","re":"Some textures and smells genuinely overwhelm a child's senses; respecting food needs isn't fussiness, it's accommodation.","why":"A real sensory need isn't a tantrum."},"relearn":"Respecting your child's food textures isn't pampering fussiness; it honours a real sensory need.","persona":"Divya","source":"food needs not fussy"},
  {"id":"nd-903","cat":"accommodate","type":"strike-rewrite","hook":"\"He should learn to do homework in one long sitting like everyone else.\"","myth":{"un":"He should learn to do homework in one long sitting like everyone else.","re":"Breaking work into short chunks with movement breaks matches how his attention is wired and gets more done, not less.","why":"Chunks fit the wiring, not laziness."},"relearn":"Chunk homework into short steps with movement breaks; it fits how attention is wired and gets more done.","persona":"Meena","source":"chunk the work"},
  {"id":"nd-904","cat":"accommodate","type":"strike-rewrite","hook":"\"A calm-down corner at home just rewards bad behaviour.\"","myth":{"un":"A calm-down corner at home just rewards bad behaviour.","re":"A calm-down space gives an overwhelmed child somewhere safe to settle; it isn't a reward, it's a place to regulate.","why":"Settling isn't the same as a treat."},"relearn":"A calm-down corner isn't rewarding bad behaviour; it gives an overwhelmed child a safe place to regulate.","persona":"Meena","source":"calm corner not reward"},
  {"id":"nd-905","cat":"accommodate","type":"strike-rewrite","hook":"\"If I let him stim and fidget, he'll never learn to sit properly.\"","myth":{"un":"If I let him stim and fidget, he'll never learn to sit properly.","re":"Stimming and fidgeting often help a child self-regulate and focus; allowing them supports him rather than holding him back.","why":"The movement is helping, not hindering."},"relearn":"Letting your child stim and fidget often helps them regulate and focus; it supports them, not spoils them.","persona":"Vikram","source":"stim helps focus"},
  {"id":"nd-906","cat":"accommodate","type":"strike-rewrite","hook":"\"Forcing him to look me in the eye when I talk teaches respect.\"","myth":{"un":"Forcing him to look me in the eye when I talk teaches respect.","re":"For many autistic children eye contact is overwhelming; he can listen well without it, and forcing it only adds stress.","why":"Listening doesn't need a forced gaze."},"relearn":"Don't force eye contact; many autistic children listen better without it, and forcing it only adds stress.","persona":"Meena","source":"eye contact not forced"},
  {"id":"nd-907","cat":"accommodate","type":"strike-rewrite","hook":"\"Surprises build flexibility, so I shouldn't warn him before plans change.\"","myth":{"un":"Surprises build flexibility, so I shouldn't warn him before plans change.","re":"A warning and a simple visual before a change let a routine-reliant child adjust; surprise just floods him with overwhelm.","why":"A heads-up eases change, it doesn't weaken him."},"relearn":"Warn a routine-reliant child before changes with a heads-up and a visual; surprise floods them, not strengthens them.","persona":"Divya","source":"warn before change"},
  {"id":"nd-908","cat":"accommodate","type":"strike-rewrite","hook":"\"Other kids manage school uniforms and tags, so his complaints are drama.\"","myth":{"un":"Other kids manage school uniforms and tags, so his complaints are drama.","re":"Scratchy tags and seams can feel genuinely painful to a sensory-sensitive child; softer clothes or removed tags is real relief.","why":"His skin truly feels it differently."},"relearn":"Scratchy tags can genuinely hurt a sensory-sensitive child; softer clothes or removed tags is real relief, not drama.","persona":"any","source":"clothing sensitivity"},
  {"id":"nd-909","cat":"accommodate","type":"strike-rewrite","hook":"\"Giving him a visual timetable means he'll never cope without one.\"","myth":{"un":"Giving him a visual timetable means he'll never cope without one.","re":"A visual schedule lowers the daily anxiety of not-knowing, and that security is what coping skills grow from over time.","why":"Security is the launchpad for coping."},"relearn":"A visual timetable lowers daily anxiety; that security is exactly what real coping skills grow from.","persona":"Meena","source":"visual timetable security"},
  {"id":"nd-910","cat":"accommodate","type":"strike-rewrite","hook":"\"A quiet exit from the wedding is rude; he must sit through the whole function.\"","myth":{"un":"A quiet exit from the wedding is rude; he must sit through the whole function.","re":"Planning a quiet exit lets an overstimulated child leave before a meltdown; it prevents overload, it isn't bad manners.","why":"Leaving early beats a forced breakdown."},"relearn":"A planned quiet exit from a loud function prevents overload for an overstimulated child; it isn't rudeness.","persona":"any","source":"quiet exit plan"},
  {"id":"nd-911","cat":"accommodate","type":"sort","hook":"Sort: a supportive accommodation, or forcing the child to mask who they are?","items":[{"id":"a","text":"Noise-cancelling headphones in a loud hall"},{"id":"b","text":"Punishing him for flapping his hands"},{"id":"c","text":"A visual schedule for the day"},{"id":"d","text":"Demanding he hold eye contact"},{"id":"e","text":"A movement break between tasks"},{"id":"f","text":"Forcing him to sit perfectly still"}],"bins":[{"id":"support","label":"Supportive accommodation","valence":"pos"},{"id":"mask","label":"Forcing masking","valence":"neg"}],"key":{"a":"support","b":"mask","c":"support","d":"mask","e":"support","f":"mask"},"relearn":"Headphones, visual schedules and movement breaks support; punishing stimming or forcing eye contact and stillness force masking.","persona":"Meena","source":"support vs mask six"},
  {"id":"nd-912","cat":"accommodate","type":"sort","hook":"Sort: respects how the child is wired, or forces them to mask it?","items":[{"id":"a","text":"Letting her fidget with a spinner to focus"},{"id":"b","text":"Forcing 'normal' stillness in class"},{"id":"c","text":"Quiet breaks when she's overstimulated"},{"id":"d","text":"Punishing her for rocking to self-soothe"},{"id":"e","text":"Respecting her need for the same lunch"},{"id":"f","text":"Mocking her hand-flapping till she stops"}],"bins":[{"id":"respect","label":"Respects the wiring","valence":"pos"},{"id":"mask","label":"Forces masking","valence":"neg"}],"key":{"a":"respect","b":"mask","c":"respect","d":"mask","e":"respect","f":"mask"},"relearn":"Fidget tools, quiet breaks and respected routines honour the wiring; forcing stillness or punishing self-soothing force masking.","persona":"Meena","source":"respect or mask six"},
  {"id":"nd-913","cat":"accommodate","type":"sort","hook":"Sort: a sensory accommodation that helps, or piling on more sensory load?","items":[{"id":"a","text":"Dimming a harsh tube-light"},{"id":"b","text":"Turning the TV up over his protest"},{"id":"c","text":"Soft tags-removed clothes"},{"id":"d","text":"A crowded, noisy surprise outing"},{"id":"e","text":"A quiet low-stimulation corner"},{"id":"f","text":"Strong perfume in a small room"}],"bins":[{"id":"eases","label":"Eases the senses","valence":"pos"},{"id":"overloads","label":"Overloads the senses","valence":"neg"}],"key":{"a":"eases","b":"overloads","c":"eases","d":"overloads","e":"eases","f":"overloads"},"relearn":"Dimming lights, soft clothes and a quiet corner ease the senses; loud TV, surprise crowds and strong smells pile on overload.","persona":"any","source":"ease vs overload senses"},
  {"id":"nd-914","cat":"accommodate","type":"match","hook":"Match each need to a practical home accommodation that helps.","pairs":[{"left":"Sensory overload","right":"A calm, low-stimulation corner"},{"left":"Trouble with transitions","right":"A warning and a visual routine"},{"left":"Attention differences","right":"Short steps and movement breaks"},{"left":"Food sensitivities","right":"Respect safe foods, no forcing"},{"left":"Loud outings","right":"Noise-cancelling headphones"}],"relearn":"Sensory overload, transitions, attention, food needs and loud outings each have a simple home accommodation that helps.","persona":"any","source":"need to accommodation five"},
  {"id":"nd-915","cat":"accommodate","type":"match","hook":"Match each daily setting to the accommodation that helps it go better.","pairs":[{"left":"Mealtimes","right":"Respect food sensitivities, no force"},{"left":"Bedtime","right":"A predictable, calming routine"},{"left":"Homework","right":"Chunked tasks and breaks"},{"left":"Morning rush","right":"A visual step-by-step checklist"},{"left":"Bath time","right":"Warn first, control water and light"}],"relearn":"Meals, bedtime, homework, mornings and bath time each go better with an accommodation that fits the child's wiring.","persona":"any","source":"setting to support five"},
  {"id":"nd-916","cat":"accommodate","type":"match","hook":"Match each tricky moment out and about to the accommodation that helps.","pairs":[{"left":"Overwhelming party","right":"A quiet exit plan and headphones"},{"left":"New place","right":"Preview or visit it in advance"},{"left":"Big feelings","right":"A calm-down space, not a scolding"},{"left":"Long queue","right":"A fidget toy and a known wait-time"},{"left":"Crowded bus","right":"A window seat and a calm playlist"}],"relearn":"Parties, new places, big feelings, queues and crowded buses each go better with a simple accommodation than with force.","persona":"any","source":"moment to accommodation five"},
  {"id":"nd-917","cat":"accommodate","type":"match","hook":"Match each sense that overloads your child to a way to ease it.","pairs":[{"left":"Bright glare","right":"Dim lights or a cap with a brim"},{"left":"Sudden loud noise","right":"Headphones or a warning first"},{"left":"Scratchy fabric","right":"Soft clothes with tags removed"},{"left":"Strong smells","right":"Air a room or move spots"},{"left":"Busy visuals","right":"A plain, uncluttered corner"}],"relearn":"Glare, loud noise, scratchy fabric, strong smells and busy visuals each have a simple way to ease the overload.","persona":"any","source":"sense to relief"},
  {"id":"nd-918","cat":"accommodate","type":"branch","persona":"Meena","source":"party prepared","hook":"Your son's cousin is having a loud, crowded birthday party with balloons.","steps":[{"prompt":"The invitation says Saturday. How do you get ready?","options":[{"text":"Pack headphones, choose a quiet room and plan an early exit","then":"You show him a photo of the room. He picks his blue headphones and says okay.","best":true},{"text":"Bring nothing and see how he does once he is inside there","then":"He walks in smiling. Then the balloons start popping, and he cannot find a way out."},{"text":"Tell him it is a party so he must be happy and stay put","then":"He nods and looks at his feet. He gets quieter as Saturday gets closer."},{"text":"Skip it and send a gift instead, just to be on the safe side","then":"The gift is a hit. The cousin still asks why he did not come."}],"why":"Supports and an exit plan let him take part without being pushed past his limit."},{"prompt":"Two weeks later, the room at another gathering goes loud with singing and he edges to the door. What do you do?","options":[{"text":"Tell him to wait it out, as it is only a minute of singing","then":"He stays frozen at the edge with his hands over his ears until it ends."},{"text":"Ask everyone to stop singing for his sake, just this once","then":"The room goes awkward. He hides behind you, more embarrassed than before."},{"text":"Quietly walk him to a quiet room and let him settle","then":"In the quiet room his breathing slows. After ten minutes he asks to go back for cake.","best":true},{"text":"Hand him some cake to distract him from the noise","then":"He holds the plate without eating. The noise keeps coming and his eyes stay on the door."}],"why":"Calmly reducing the load helps him settle and often return on his own."},{"prompt":"As you head out early, an aunt says you are spoiling his fun. What do you say?","options":[{"text":"Kindly say leaving before he tires keeps the day good for him","then":"She frowns, then nods. \"Well, he did look happy.\" He waves goodbye at the door.","best":true},{"text":"Stay on another hour or so to avoid making a fuss","then":"The hour is long. He grows tense and you leave with a meltdown in the car."},{"text":"Apologise that he is being a little difficult tonight","then":"He hears it. In the car he asks quietly if he did something wrong."},{"text":"Snap that nobody in this family understands him at all","then":"The aunt goes stiff. Others stop talking, and you leave in an awkward silence."}],"why":"Leaving on your own plan protects his day and shows he is not the problem."}],"debrief":"Join overwhelming events with supports and an exit plan, not forced endurance.","relearn":"Bring supports and an exit plan to loud events; don't force a child to endure overload."},
  {"id":"nd-919","cat":"accommodate","type":"branch","persona":"Meena","source":"keep what works","hook":"Your son does his homework better in short chunks with breaks in between.","steps":[{"prompt":"At lunch, your uncle says the breaks are only excuses. What do you do?","options":[{"text":"Cut the breaks this week to prove he can sit through","then":"He fidgets at the desk for an hour and finishes less than usual."},{"text":"Keep the breaks and tell him calmly they help your son finish","then":"Uncle raises an eyebrow but says no more. Your son keeps his shoulders relaxed.","best":true},{"text":"Agree with Uncle to avoid an argument over the lunch table","then":"Uncle looks pleased. Your son hears it and stops eating."},{"text":"Tell Uncle loudly that he knows nothing about children today","then":"The table goes quiet. Your son studies his plate, and lunch ends early."}],"why":"Keeping what fits his attention helps him finish, whatever onlookers say."},{"prompt":"His teacher says his homework often comes back half done. What do you say?","options":[{"text":"Say you will make him sit until every page is done at home","then":"He sits, but writes little. The homework comes back messier than before."},{"text":"Ask her to give him no homework at all for the time being","then":"She says that is not possible. Both of you leave without a plan."},{"text":"Agree he needs more discipline and promise to be stricter","then":"She nods. At home he senses the change and goes quiet."},{"text":"Show how chunks and breaks help him and ask her to try them","then":"She listens and says she can split his class work into steps too.","best":true}],"why":"Sharing what works gives the teacher a plan she can use in class too."},{"prompt":"One evening he sighs and calls himself lazy. What do you tell him?","options":[{"text":"You are not lazy, but you have to try harder than you do","then":"His shoulders drop. He says nothing and stares at the page."},{"text":"You are not lazy. Your brain needs breaks to finish","then":"He looks up. \"Really?\" You nod, and he picks up his pencil again.","best":true},{"text":"Do not say that. Go and finish your homework right now","then":"He wipes his eyes and starts writing, without looking at you."},{"text":"Let us not talk about it. Just get on with the work please","then":"He nods, but the word \"lazy\" stays on his face for the evening."}],"why":"Naming his brain's needs, not laziness, protects how he sees himself."}],"debrief":"Keep the chunked steps and breaks that fit your child, whatever onlookers say.","relearn":"Keep the breaks and chunked steps that fit your child's attention, whatever relatives say."},
  {"id":"nd-920","cat":"accommodate","type":"branch","persona":"Divya","source":"steady bedtime","hook":"Bedtime is a nightly battle, and your son seems to need the same routine each night.","steps":[{"prompt":"Bedtime ends in tears again. What do you change?","options":[{"text":"Change the order of the steps each night to teach flexibility","then":"He asks, \"What now?\" at every step and gets more upset."},{"text":"Make a picture chart of the same steps for every night","then":"He points at each picture as you go. He still cries tonight, but less.","best":true},{"text":"Let him stay up until he drops off wherever he is","then":"He falls asleep on the sofa at midnight. The next morning is rough."},{"text":"Promise a treat if he goes to bed without any fuss","then":"He goes for the treat, then gets up twice, still unsettled."}],"why":"The same steps each night tell him what comes next, which lowers his worry."},{"prompt":"A week later, guests are visiting and bedtime falls in the middle of the noise. What do you do?","options":[{"text":"Skip the routine tonight and let him sleep when he tires","then":"He stays up wired among the guests and cries at midnight."},{"text":"Ask the guests to leave early so he can go to bed on time","then":"The guests leave puzzled. You spend the rest of the evening apologising."},{"text":"Let him decide tonight's steps for once","then":"He changes the order twice and cannot say what should come next."},{"text":"Keep the same steps, keep voices low and start a bit earlier","then":"He follows the steps and settles a little later than usual, but he settles.","best":true}],"why":"Keeping the steps steady, even in noise, gives him something familiar to hold."},{"prompt":"Your mother says his routine makes him fussy and he should just learn to sleep. What do you say?","options":[{"text":"You are right, and I will drop the routine","then":"He looks around for the steps the next night and cannot settle."},{"text":"It helps him feel safe, so let us keep the routine a month","then":"She sighs. \"A month, then.\" She watches him settle the next night.","best":true},{"text":"Times have changed, Amma, so please do not worry about it","then":"She purses her lips and says nothing more. Her doubt remains in the room."},{"text":"I know what is best for him, so please leave it to me","then":"She stiffens. The next few visits are quiet and cold."}],"why":"Explaining why the routine helps brings her along and keeps it steady."}],"debrief":"A steady, predictable bedtime routine lowers anxiety better than nightly change.","relearn":"A predictable bedtime routine lowers anxiety; nightly change just leaves your child unsettled."},
  {"id":"nd-921","cat":"accommodate","type":"branch","persona":"Meena","source":"mall meltdown","hook":"At the mall your son melts down from the lights, the noise and the crowd.","steps":[{"prompt":"He is on the floor with his hands over his ears. What do you do?","options":[{"text":"Move him to a quiet spot and stay close while he settles","then":"Near the fire exit, the noise drops. His breathing slows after a few minutes.","best":true},{"text":"Scold him to stop and pull him on to finish the shopping","then":"He cries harder and pulls away. People slow down to look at both of you."},{"text":"Hand him your phone to calm him down","then":"He holds it without looking. The lights and noise keep pressing on him."},{"text":"Ask him why he is doing this and wait for an answer","then":"He cannot answer and covers his face. Seconds stretch on."}],"why":"Less light and noise, and a calm adult close by, help him settle."},{"prompt":"Once he is calmer, you still need bread from the ground floor. What do you do?","options":[{"text":"Finish the shopping now since you are already here","then":"He trails behind you, tense, and starts to drop things."},{"text":"Promise a chocolate if he stays calm for the whole trip","then":"He tries hard, then cracks at the billing counter."},{"text":"Leave now and get the bread another day","then":"He walks out beside you, quiet. You order the bread online later.","best":true},{"text":"Tell him to hold your hand and not make another scene","then":"He holds on tight. His grip is trembling by the counter."}],"why":"Once he is recovering, cutting the trip short protects him from another overload."},{"prompt":"Your husband says the mall should be off the list for ever. What do you say?","options":[{"text":"Go again in quiet hours with headphones and a short list","then":"He thinks it over. \"Fine. Try it once and we will see.\"","best":true},{"text":"Agree that malls are off the list for ever","then":"It settles the argument. Family outings shrink to a few familiar places."},{"text":"Say he must go every week to get used to it","then":"He nods, unconvinced. Your son starts refusing to leave the house on Saturdays."},{"text":"Say you will try again when he is much older","then":"He shrugs and the subject drops. Nobody decides anything."}],"why":"Planning around his needs keeps outings possible without forcing him."}],"debrief":"Meet a sensory meltdown by reducing the load and helping him settle, not by scolding.","relearn":"Meet a sensory meltdown by moving to calm and easing the load; scolding only deepens overwhelm."},
  {"id":"nd-922","cat":"accommodate","type":"branch","persona":"Divya","source":"retune the kit","hook":"You set up a sensory kit for your son, but lately it is not helping much.","steps":[{"prompt":"He pushes the kit away and grows restless in the evenings. What do you do?","options":[{"text":"Insist the kit must work, as the article said","then":"He pushes it away again and paces the room."},{"text":"Add more items to the kit and hope one helps","then":"He ignores the new items. The kit is now a heap on the floor."},{"text":"Put the kit away for good since it has failed","then":"The evenings get harder. He has nothing to reach for when he is tense."},{"text":"Watch what he does now, ask him and try one change","then":"You see him wrap himself in the sofa throw. He says, \"Cosy.\"","best":true}],"why":"His cues today show what fits him now, so watch, ask and try one change."},{"prompt":"A few days later, he says the earmuffs itch but he likes his soft blanket. What do you do?","options":[{"text":"Keep both, since he should get used to the earmuffs","then":"He wears them stiffly and pulls them off within minutes."},{"text":"Try the blanket and leave the earmuffs out for a week","then":"He wraps up in the blanket and sits still through his story time.","best":true},{"text":"Buy a new, bigger kit instead of adjusting the old one","then":"The new kit arrives. He wants the blanket anyway."},{"text":"Tell him blankets are for bedtime only","then":"He gives it up, then starts pacing again at study time."}],"why":"Following what he tells you keeps the supports matched to him."},{"prompt":"A friend shares a video about the \"perfect kit for all autistic children\". What do you do?","options":[{"text":"Order the entire kit at once so he has everything","then":"It arrives in a big box. He opens two items and walks away."},{"text":"Ignore it, since kits never help anyone","then":"You miss one small idea that would have suited him."},{"text":"Ask his teacher to use the same kit at school right away","then":"She agrees to try, but he has not tested any of it yet."},{"text":"Note ideas that may suit him and test them one at a time","then":"You try the timer idea alone. He likes it, and the rest stays in a folder.","best":true}],"why":"Ideas from others are starting points. His response shows what fits."}],"debrief":"Keep tuning accommodations to your real, changing child by watching and asking.","relearn":"Tune accommodations to your real child by watching and asking; needs change, so a fixed kit drifts off."},
  {"id":"nd-923","cat":"accommodate","type":"branch","persona":"Meena","source":"preview new term","hook":"A new term begins with a new room, a new teacher and a new timetable for your son.","steps":[{"prompt":"School reopens on Monday. What do you do this week?","options":[{"text":"Let him face it on Monday and adapt on the spot, like others","then":"On Monday the noise and new faces hit at once. He clings to the gate."},{"text":"Tell him about the changes on Sunday night before bed","then":"He asks questions late into the night. He needed more time than that."},{"text":"Visit the school with him, meet his teacher and see the timetable","then":"He walks the corridor and finds his peg. \"My room,\" he says, and smiles.","best":true},{"text":"Buy him a new bag and shoes so he feels excited about it","then":"He loves the bag, but on Monday he still does not know where to go."}],"why":"A preview shows him what to expect, so the change feels safer."},{"prompt":"His teacher asks how she can help him settle in. What do you tell her?","options":[{"text":"Share what calms him and what overwhelms him in a short note","then":"She reads it and says she will seat him near the door with a quiet corner.","best":true},{"text":"That he is fine and she need not do anything special for him","then":"She treats him like the rest. By Wednesday he is holding his ears in class."},{"text":"Give her a long list of everything he cannot do yet at school","then":"She looks overwhelmed. His struggles are all she remembers about him."},{"text":"That you will explain everything in a month once he settles in","then":"She waits and guesses, and gets some things wrong in the meantime."}],"why":"A short note on what helps him gives his teacher a place to start."},{"prompt":"By Friday he is tired and says he does not want school. What do you do?","options":[{"text":"Say everyone finds a new term hard and he must get on","then":"He goes quiet. On Monday he drags his feet to the gate."},{"text":"Let him stay home until he feels like going back to school","then":"He is relieved. Each day away makes the return feel bigger."},{"text":"Ask what was hard, listen, and pass it on to his teacher","then":"He says the bell is too loud. She agrees to warn him before it rings.","best":true},{"text":"Promise a toy if he goes to school every day next week","then":"He goes for the toy. The bell still hurts, and nobody knows."}],"why":"Listening to what was hard lets you fix the cause together with his teacher."},{"prompt":"Next month the school changes his timetable for an annual day. What do you do?","options":[{"text":"Ask for the new plan early and show it to him with pictures","then":"He studies the pictures and asks, \"Which room?\" You point it out.","best":true},{"text":"Wait and let him find out about it on the day itself","then":"He arrives to a different room, and stands still at the door."},{"text":"Tell him it is only one day so he should stay calm","then":"He nods hard, but his hands are shaking by the second period."},{"text":"Ask the school to cancel the change for him alone","then":"The school says it cannot, and the plan is late by then."}],"why":"Early notice with pictures lets him prepare for a change, big or small."}],"debrief":"Ease a big transition by previewing the new place and routine in advance.","relearn":"Preview a new term's room, teacher and routine in advance to ease the transition."},
  {"id":"nd-924","cat":"accommodate","type":"reflect","hook":"Lensy: noise-cancelling headphones at the party aren't him 'avoiding' the family. They're how he stays in the room with you. Sit right?","prompt":"What do you think?","options":["Sits right","Lets him stay","Not avoidance"],"affirm":"A tool that lowers sensory overload keeps a child present and connected, instead of forcing a choice between coping and being there.","relearn":"An accommodation like headphones isn't withdrawal. It's what lets a child stay in the room and join in.","persona":"Meena","source":"headphones stay in room"},
  {"id":"nd-925","cat":"accommodate","type":"reflect","hook":"Lensy: accommodations are like glasses, they give fair access, not an unfair edge. Does that frame help you?","prompt":"What do you think?","options":["Like glasses","Fair access","Levels the ground"],"affirm":"Accommodations level the ground so your child gets the same fair chance as others; fair access isn't an unfair advantage.","relearn":"Accommodations are like glasses: they give fair access and level the ground, not an unfair edge.","persona":"Vikram","source":"glasses frame"},
  {"id":"nd-926","cat":"accommodate","type":"reflect","hook":"Lensy: you know your child best, so watching and asking them often beats any generic checklist. Ring true?","prompt":"What do you think?","options":["Rings true","Watch and ask","My real child"],"affirm":"Tuning support to your real child by watching their cues and asking them works better than any one-size checklist.","relearn":"Watching and asking your own child tailors support better than a generic checklist ever could.","persona":"Divya","source":"watch and ask reflect"},
  {"id":"nd-927","cat":"accommodate","type":"reflect","hook":"Lensy: a meltdown in an overwhelming place is overwhelm, not bad behaviour to punish. Does that sit right?","prompt":"What do you think?","options":["Sits right","It's overwhelm","Not misbehaviour"],"affirm":"A meltdown in an overloading setting is a nervous system flooded, not defiance; preventing overload helps far more than punishing it.","relearn":"A meltdown in an overwhelming place is overwhelm, not misbehaviour to punish.","persona":"Meena","source":"overwhelm not behaviour"},
  {"id":"nd-928","cat":"accommodate","type":"reflect","hook":"Lensy: adjusting the room, the plan and your expectations is gentler than asking a child to mask all day. Agree?","prompt":"What do you think?","options":["Agree","Flex the setting","Not the child"],"affirm":"It's kinder and it works better to flex the environment and your expectations than to demand a child mask who they are.","relearn":"Flex the room, the plan and your expectations rather than asking your child to mask all day.","persona":"Meena","source":"flex not mask reflect"},
  {"id":"nd-929","cat":"accommodate","type":"reflect","hook":"Lensy: respecting your child's food, clothing and noise needs honours a real sensory truth, not fussiness. Sit right?","prompt":"What do you think?","options":["Sits right","A real need","Not fussiness"],"affirm":"Sensory needs around food, fabric and sound are genuine; respecting them is accommodation, not giving in to fussiness.","relearn":"Respecting food, clothing and noise needs honours a real sensory truth, not fussiness.","persona":"any","source":"sensory needs reflect"},
  {"id":"nd-930","cat":"accommodate","type":"reflect","hook":"Lensy: the support you give now is the launchpad real coping grows from, not a crutch. Does that land?","prompt":"What do you think?","options":["It lands","A launchpad","Not a crutch"],"affirm":"Accommodation builds the security and skills from which real coping grows; forced distress teaches fear, not coping.","relearn":"Support is the launchpad real coping grows from, not a crutch.","persona":"Vikram","source":"launchpad reflect"},
  {"id":"nd-931","cat":"accommodate","type":"spot","hook":"Spot the two moves that force your child to mask, not accommodate them.","scene":[{"id":"a","text":"Offering headphones in a loud hall","trick":false},{"id":"b","text":"Punishing him for hand-flapping to self-soothe","trick":true},{"id":"c","text":"Giving a clear visual schedule","trick":false},{"id":"d","text":"Forcing him to hold eye contact","trick":true},{"id":"e","text":"A quiet break when overstimulated","trick":false}],"why":"Punishing stimming and forcing eye contact make a child mask; the other three adjust the setting to support him.","relearn":"Punishing stimming and forcing eye contact force masking; headphones, schedules and quiet breaks accommodate.","persona":"Meena","source":"spot the masking"},
  {"id":"nd-932","cat":"accommodate","type":"spot","hook":"Spot the two responses that overload your child instead of easing the moment.","scene":[{"id":"a","text":"Dimming the harsh lights when he winces","trick":false},{"id":"b","text":"Turning the loud TV up over his protest","trick":true},{"id":"c","text":"Warning him before the plan changes","trick":false},{"id":"d","text":"Springing a surprise crowd on him","trick":true},{"id":"e","text":"Offering a quiet corner to settle","trick":false}],"why":"Blasting the TV and a surprise crowd pile on overload; dimming lights, a warning and a quiet corner ease it.","relearn":"Loud TV and surprise crowds overload a child; dimming lights, warnings and a quiet corner ease the moment.","persona":"any","source":"spot the overload"},
  {"id":"nd-933","cat":"accommodate","type":"spot","hook":"Spot the two 'tough-love' moves that harm an overwhelmed child, not support them.","scene":[{"id":"a","text":"Letting him leave a function early when flooded","trick":false},{"id":"b","text":"Scolding him to stop a sensory meltdown","trick":true},{"id":"c","text":"Respecting his safe foods at dinner","trick":false},{"id":"d","text":"Making him sit perfectly still","trick":true},{"id":"e","text":"Breaking homework into short chunks","trick":false}],"why":"Scolding a meltdown and forcing stillness punish overwhelm; a quiet exit, safe foods and chunks support him.","relearn":"Scolding meltdowns and forcing stillness harm a child; quiet exits, safe foods and chunks support them.","persona":"Meena","source":"spot the tough-love harm"},
  {"id":"nd-934","cat":"accommodate","type":"role-play","persona":"Vikram","source":"not pampering","hook":"Your son eats only a few foods and wears headphones at busy family meals.","setup":"At lunch, your aunt looks from his plate to you.","steps":[{"prompt":"Your aunt says: \"You pamper him with those headphones and that special food.\"","options":[{"text":"\"Maybe you are right. I will make him manage like others.\"","then":"\"That is what I say,\" she nods. Your son stops eating."},{"text":"\"You have no idea what we deal with. Please stay out.\"","then":"Her lips tighten. \"I only care about him.\""},{"text":"\"They are like his glasses. They help him be his best.\"","then":"She pauses. \"Glasses? I never thought of it that way.\"","best":true},{"text":"\"The therapist told us to. I cannot explain any more.\"","then":"\"Hmm,\" she says, unconvinced, and passes the dal."}],"why":"Comparing supports to glasses defends them calmly, without blaming her."},{"prompt":"Your aunt taps his plate and asks: \"What is wrong with the food we all eat?\"","options":[{"text":"\"Some foods are too much for him. We add tastes slowly.\"","then":"\"Slowly,\" she repeats. \"I suppose forcing never worked for your uncle either.\"","best":true},{"text":"\"Nothing. From tonight he eats what is served.\"","then":"She nods. Your son pushes his plate away and stares at the table."},{"text":"\"Forcing him would be cruel. We will never try new foods.\"","then":"She frowns. \"Never? That seems a pity.\""},{"text":"\"It is easier for me to give him plain rice, so I do.\"","then":"\"Aha, so it is only your convenience,\" she says."}],"why":"Respecting his food needs while adding tastes slowly keeps mealtimes calm."},{"prompt":"Your aunt sighs: \"Will he ever be normal like the others?\"","options":[{"text":"\"Maybe he will grow out of it as he gets older.\"","then":"She smiles, relieved. \"See, that is what I hoped.\""},{"text":"\"Do not say that word about him. Ever.\"","then":"She stiffens. \"I did not mean any harm.\""},{"text":"\"He is himself already. We help him do well as he is.\"","then":"She softens. \"He does have a way with the neighbour's dog.\"","best":true},{"text":"\"I do not know. Let us wait and see what the doctor says.\"","then":"She shrugs. \"Then we wait.\" The worry stays in the room."}],"why":"Different is not less. Support helps him thrive as himself."}],"relearn":"Framing accommodations as fair access, like glasses, defends them calmly against the 'pampering' charge."},
  {"id":"nd-935","cat":"accommodate","type":"role-play","persona":"any","source":"defend fidget tool","hook":"At a family lunch, a cousin laughs at your daughter's fidget spinner.","setup":"Your daughter goes still and holds it tightly.","steps":[{"prompt":"Your cousin asks: \"Why is she playing with a toy at the table?\"","options":[{"text":"\"Sorry. She should not have it here. I will take it away.\"","then":"Your daughter's face crumples as it leaves her hand."},{"text":"\"Mind your own business and eat your food.\"","then":"He rolls his eyes. \"Touchy. Fine.\""},{"text":"\"She is just bored. Kids these days.\"","then":"He laughs. \"Ha, true.\" Her grip tightens on the spinner."},{"text":"\"It helps her focus and settle, like my reading glasses.\"","then":"He blinks. \"Oh. I thought it was just a toy.\"","best":true}],"why":"Naming it as a focus tool, calmly, keeps her support from being mocked away."},{"prompt":"Your cousin says: \"I read those spinners are a fad. Do they even help anyone?\"","options":[{"text":"\"I do not know. The therapist said to try it.\"","then":"\"So nobody really knows,\" he says, unconvinced."},{"text":"\"For her, yes. She listens better with busy hands.\"","then":"He thinks. \"My son doodles in class. Maybe it is the same.\"","best":true},{"text":"\"Maybe it is a fad. I will stop buying them for her.\"","then":"Your daughter looks down at her plate and goes quiet."},{"text":"\"Ask her yourself. I am tired of explaining this.\"","then":"He turns to her awkwardly. She looks down and says nothing."}],"why":"Saying plainly what it does for her answers his doubt without a fight."},{"prompt":"Grandma says: \"In my day, children sat still without toys.\"","options":[{"text":"\"You are right, Amma. No more toys at the table.\"","then":"\"Good,\" she says. Your daughter folds her hands in her lap."},{"text":"\"Times have changed, Amma. That is how it is now.\"","then":"\"Hmm,\" she says, and turns to her plate, unconvinced."},{"text":"\"Children in your day were just scared of grown-ups.\"","then":"Grandma's eyes narrow. \"Is that what you think of us?\""},{"text":"\"Every child is different, Amma. This helps her sit calmly.\"","then":"Grandma studies her granddaughter. \"She is sitting nicely. That is true.\"","best":true}],"why":"Explaining gently, with respect, keeps her support and the elders on side."}],"relearn":"Naming a fidget tool as a focus aid, calmly, protects your child's support from being mocked away."},
  {"id":"nd-936","cat":"accommodate","type":"role-play","persona":"Meena","source":"eye contact with elders","hook":"Eye contact is hard for your son, and today you are visiting his grandmother.","setup":"He stands at her door, waving with his eyes on the floor.","steps":[{"prompt":"Grandma says: \"Look at me when you greet me, beta.\"","options":[{"text":"\"He hears you, Amma. For him a wave is a warm hello.\"","then":"She peers at him. \"A wave, then. Hmm. He did wave.\"","best":true},{"text":"\"Look at your grandmother right now, or no greeting at all.\"","then":"He flinches and stares harder at his shoes. \"Now he is upset,\" she says."},{"text":"\"Sorry, Amma. He is shy and will learn when he is older.\"","then":"\"Shy children need firm handling,\" she says, and looks at him sternly."},{"text":"\"He does not have to. That is a silly rule anyway.\"","then":"She stiffens. \"Silly? In my own house?\""}],"why":"Explaining that a wave is a hello protects him from a stressful forced gaze."},{"prompt":"Grandma asks: \"If he will not look at me, how do I know he is listening?\"","options":[{"text":"\"You will just have to trust me on this one, Amma.\"","then":"\"Trust is fine, but I like to see it,\" she says, and sighs."},{"text":"\"We will train him to look at you, Amma. It will take time.\"","then":"\"Good. Practise every day,\" she says. Your son's shoulders rise."},{"text":"\"Ask him a small question. He answers even without looking.\"","then":"She asks about school. He answers in three words, watching the fan. \"Well. He heard me.\"","best":true},{"text":"\"Come now, Amma. Please do not ask so many questions.\"","then":"She purses her lips. \"I was only asking a simple thing.\""}],"why":"Showing he listens without a gaze answers her real worry."},{"prompt":"Grandma asks: \"Will he greet the Diwali guests properly this time?\"","options":[{"text":"\"He will wave and say namaste. That is his greeting.\"","then":"She nods slowly. \"Namaste and a wave. I can tell people that.\"","best":true},{"text":"\"I will make him look at each guest in the eye, Amma.\"","then":"\"Good,\" she says. At home your son practises staring, and hates it."},{"text":"\"He can stay in his room so no one notices him.\"","then":"She looks at you strangely. \"Then who will greet my guests?\""},{"text":"\"Please tell the guests he is shy so they do not mind.\"","then":"She agrees. Your son hears the word \"shy\" again and again."}],"why":"Letting him greet in his own way keeps him at ease and part of the day."}],"relearn":"Gently explaining that listening doesn't need eye contact protects your child from a stressful forced gaze."},
  {"id":"nd-937","cat":"accommodate","type":"role-play","persona":"any","source":"propose quiet exit","hook":"At a noisy wedding, your child is close to overload.","setup":"Your partner is chatting with an uncle nearby.","steps":[{"prompt":"Your partner says: \"He looks fine to me. Why do you look worried?\"","options":[{"text":"\"He has to sit through it all. It would look rude to leave.\"","then":"\"True, true,\" your partner says. Then your son presses his hands to his ears."},{"text":"\"He is getting overloaded. Let us step out to the courtyard.\"","then":"Your partner glances at him. \"His hands are at his ears. Yes, come.\"","best":true},{"text":"\"Nothing. Just tell him to sit straight and be quiet.\"","then":"Your partner does. Your son's hands drift back to his ears."},{"text":"\"Let us wait a bit more. Maybe he will settle by himself.\"","then":"\"Fine, a little longer,\" your partner says. The band gets louder."}],"why":"Naming the overload and a quiet exit acts before it tips into a meltdown."},{"prompt":"Your partner asks: \"If we step out, what do we tell everyone?\"","options":[{"text":"\"That he is being difficult. They will understand.\"","then":"\"Hmm,\" your partner says. \"Is that fair to him?\""},{"text":"\"Let us stay then. Leaving means too many explanations.\"","then":"Your partner sighs and stays. Your son starts rocking in his chair."},{"text":"\"Nothing. Let us just slip away without a word to anyone.\"","then":"\"Just vanish?\" your partner says. \"Your aunt will ring us all night.\""},{"text":"\"Just that we need some air. No long explanation needed.\"","then":"\"That is easy,\" your partner says, and picks up the water bottle.","best":true}],"why":"A simple, short reason lets you leave calmly without a long explanation."},{"prompt":"Your partner asks: \"There is another wedding next month. Should we even go?\"","options":[{"text":"\"No. Weddings are too much for him, so we will skip them all.\"","then":"\"All of them?\" your partner says. \"Even his cousin's?\""},{"text":"\"Yes, with headphones and a quiet spot planned. We will leave early.\"","then":"\"Good,\" your partner says. \"I will find out where the quiet room is.\"","best":true},{"text":"\"Yes, and he will just have to manage like everyone else.\"","then":"Your partner frowns. \"Like tonight? I do not think so.\""},{"text":"\"Let us decide once the invitation actually arrives.\"","then":"\"Alright,\" your partner says. The invitation comes, and there is no plan."}],"why":"Planning supports ahead lets him join events without being pushed too far."}],"relearn":"Calmly proposing a quiet exit prevents overload at a loud event instead of forcing a child to the breaking point."},
  {"id":"nd-938","cat":"accommodate","type":"role-play","persona":"Meena","source":"overwhelm not naughty stranger","hook":"Your son is melting down in a busy shop, and people have started to stare.","setup":"He is on the floor, and you crouch beside him, staying calm.","steps":[{"prompt":"A stranger snaps: \"That boy needs a good scolding!\"","options":[{"text":"\"You are right. Sorry. I will sort out his behaviour at once.\"","then":"She nods. Your son hears it and cries harder."},{"text":"\"Mind your own business, madam!\"","then":"\"Well!\" she says, and she turns to her friend, loudly offended."},{"text":"\"He is overwhelmed, not naughty. He needs a moment of calm.\"","then":"She steps back, frowning. \"Hmm. Take your time, then.\"","best":true},{"text":"\"Sorry, he is just tired. He will be fine soon.\"","then":"\"Then take him home. Children must not disturb others,\" she says."}],"why":"Naming it as overwhelm holds your ground and protects him."},{"prompt":"The stranger says: \"In my time, one slap and that was that.\"","options":[{"text":"\"A slap would only frighten him more. He needs quiet.\"","then":"She hesitates. \"Hmm. Quiet, then. Well, take care.\"","best":true},{"text":"\"You may be right. I will try that at home tonight.\"","then":"\"Good,\" she says. Your son's breathing quickens as he hears it."},{"text":"\"Hitting children is cruel! Shame on you, madam!\"","then":"Her voice rises. \"How dare you!\" A small crowd gathers around you."},{"text":"\"He is a special child, so please go easy on him.\"","then":"\"Oh, poor thing,\" she says. She pats him, and he flinches."}],"why":"Explaining calmly that a slap adds fear keeps the focus on what helps him."},{"prompt":"Your son whispers: \"Did I make the lady angry?\"","options":[{"text":"\"Do not worry about her. Just try not to do it again.\"","then":"He nods slowly. His face closes up, and he stops talking."},{"text":"\"Yes, but never mind. Let us buy some sweets.\"","then":"He takes the sweet without a word. The question stays unanswered."},{"text":"\"No. She did not understand. You did nothing wrong.\"","then":"He leans against you. \"Okay,\" he whispers, and his hands relax.","best":true},{"text":"\"That lady is horrible. Forget her. She is stupid.\"","then":"He giggles for a moment, then looks over his shoulder at her."}],"why":"Reassuring him that he did nothing wrong rebuilds his sense of safety."}],"relearn":"Naming a meltdown as overwhelm, not naughtiness, holds your ground against onlookers and protects your child."},
  {"id":"nd-990","cat":"advocate","type":"strike-rewrite","persona":"Meena","source":"partnership not interference","hook":"\"The teacher knows best; questioning her makes me an interfering parent.\"","myth":{"un":"The teacher knows best; questioning her makes me an interfering parent.","re":"You know your child best; teaming up with the teacher and sharing what works is partnership, not interference.","why":"You're both on the same side."},"relearn":"You know your child best; teaming up and sharing what works is partnership, not interference."},
  {"id":"nd-991","cat":"advocate","type":"strike-rewrite","persona":"Meena","source":"record opens doors","hook":"\"A diagnosis on the school record will only get my child labelled and held back.\"","myth":{"un":"A diagnosis on the record will only get my child labelled and held back.","re":"On record, a diagnosis unlocks the accommodations the law entitles your child to; it opens doors, not closes them.","why":"It's a key to support, not a brand."},"relearn":"On record, a diagnosis unlocks accommodations; it opens doors, it doesn't brand your child."},
  {"id":"nd-992","cat":"advocate","type":"strike-rewrite","persona":"Vikram","source":"concessions fair access","hook":"\"If I ask for exam concessions, people will say my child gets an unfair edge.\"","myth":{"un":"If I ask for exam concessions, people will say my child gets an unfair edge.","re":"Concessions like extra time or a scribe are fair access, like glasses; they let your child show what they know.","why":"Fair access isn't an advantage."},"relearn":"Exam concessions are fair access, like glasses; they let your child show what they truly know."},
  {"id":"nd-993","cat":"advocate","type":"strike-rewrite","persona":"Meena","source":"inclusion is a right","hook":"\"Special schools are the only option; a regular school can never include my child.\"","myth":{"un":"Special schools are the only option; a regular school can never include my child.","re":"The law backs inclusive education; many regular schools can include your child with the right support, if you ask.","why":"Inclusion is a right, not a favour."},"relearn":"The law backs inclusive education; many regular schools can include your child with support."},
  {"id":"nd-994","cat":"advocate","type":"strike-rewrite","persona":"Divya","source":"don't wait","hook":"\"I should wait until my child is older before raising this with the school.\"","myth":{"un":"I should wait until my child is older before raising this with the school.","re":"Earlier support helps more; raising it now, calmly, gets help in place sooner than losing years to waiting.","why":"Early support beats lost years."},"relearn":"Earlier support helps more; raising needs now gets help in place sooner than waiting."},
  {"id":"nd-995","cat":"advocate","type":"strike-rewrite","persona":"Vikram","source":"support not strictness","hook":"\"Elders say therapy is a waste of money; we should just be stricter at home.\"","myth":{"un":"Elders say therapy is a waste of money; we should just be stricter at home.","re":"You can't discipline neurodivergence away; the right professional support builds skills that strictness never will.","why":"Support teaches; strictness only frightens."},"relearn":"You can't discipline neurodivergence away; professional support builds skills strictness can't."},
  {"id":"nd-996","cat":"advocate","type":"strike-rewrite","persona":"Meena","source":"writing protects plan","hook":"\"A written request will make the teacher think I don't trust her.\"","myth":{"un":"A written request will make the teacher think I don't trust her.","re":"A calm written request isn't distrust; it gives the teacher a clear record to act on and protects your child's plan.","why":"In writing, support isn't forgotten."},"relearn":"A calm written request isn't distrust; it gives a clear record and protects your child's plan."},
  {"id":"nd-997","cat":"advocate","type":"strike-rewrite","persona":"Divya","source":"bright still needs support","hook":"\"My child is bright, so asking for learning support is just making excuses.\"","myth":{"un":"My child is bright, so asking for learning support is just making excuses.","re":"A bright child can still have dyslexia or ADHD; support isn't an excuse, it lets that brightness show in school.","why":"Support and ability aren't opposites."},"relearn":"A bright child can still have dyslexia or ADHD; support lets their brightness show, it's no excuse."},
  {"id":"nd-998","cat":"advocate","type":"strike-rewrite","persona":"Meena","source":"one no isn't final","hook":"\"If the principal says no once, that's final and there's nothing more I can do.\"","myth":{"un":"If the principal says no once, that's final and there's nothing I can do.","re":"One 'no' isn't the end; you can put it in writing, ask whom to approach next, or seek another school, calmly.","why":"A first 'no' is rarely the last word."},"relearn":"One 'no' isn't the end; put it in writing, ask whom to approach next, or seek another route."},
  {"id":"nd-999","cat":"advocate","type":"strike-rewrite","persona":"Divya","source":"calm not confrontational","hook":"\"Advocating means fighting everyone; I'm not confrontational, so I can't do it.\"","myth":{"un":"Advocating means fighting everyone; I'm not confrontational, so I can't do it.","re":"Advocacy is calm, clear partnership, not a fight; you needn't be loud, just steady and informed about your child's needs.","why":"Quiet and firm beats loud and angry."},"relearn":"Advocacy is calm, clear partnership, not a fight; you needn't be loud, just steady and informed."},
  {"id":"nd-1000","cat":"advocate","type":"strike-rewrite","persona":"Meena","source":"one-pager is a gift","hook":"\"It's pushy to give the teacher a one-page note on what helps my child.\"","myth":{"un":"It's pushy to give the teacher a one-page note on what helps my child.","re":"A short one-pager on your child's strengths and what helps is a gift to a busy teacher, not pushiness.","why":"You're saving the teacher guesswork."},"relearn":"A short note on your child's strengths and what helps is a gift to a busy teacher, not pushy."},
  {"id":"nd-1001","cat":"advocate","type":"sort","persona":"any","source":"build or burn bridge","hook":"Sort: builds partnership with the teacher, or burns the bridge?","items":[{"id":"a","text":"\"Here's what calms him, can we try it?\""},{"id":"b","text":"\"Your class is the problem, fix it.\""},{"id":"c","text":"Sharing a short note on his strengths"},{"id":"d","text":"Blaming her in front of others"},{"id":"e","text":"Asking what she's noticing too"},{"id":"f","text":"Threatening to complain on day one"}],"bins":[{"id":"build","label":"Builds partnership","valence":"pos"},{"id":"break","label":"Burns the bridge","valence":"neg"}],"key":{"a":"build","b":"break","c":"build","d":"break","e":"build","f":"break"},"relearn":"Offering what helps, sharing strengths and asking what she notices build partnership; blame and threats burn the bridge."},
  {"id":"nd-1002","cat":"advocate","type":"sort","persona":"any","source":"open or shut door","hook":"Sort: opens the door to support, or shuts it?","items":[{"id":"a","text":"Seeking a professional assessment"},{"id":"b","text":"Hiding the report from school"},{"id":"c","text":"Putting needs in writing"},{"id":"d","text":"Telling no one, to avoid gossip"},{"id":"e","text":"Following up after a 'we'll see'"},{"id":"f","text":"Dropping it after the first delay"}],"bins":[{"id":"open","label":"Opens the door","valence":"pos"},{"id":"shut","label":"Shuts the door","valence":"neg"}],"key":{"a":"open","b":"shut","c":"open","d":"shut","e":"open","f":"shut"},"relearn":"Assessment, written requests and following up open the door; hiding, silence and dropping it shut it."},
  {"id":"nd-1003","cat":"advocate","type":"sort","persona":"any","source":"right or myth","hook":"Sort: a real disability-rights protection, or a myth about it?","items":[{"id":"a","text":"Reasonable accommodation in school"},{"id":"b","text":"\"The law doesn't cover dyslexia\""},{"id":"c","text":"Inclusive-education backing"},{"id":"d","text":"\"Only special schools must take him\""},{"id":"e","text":"Exam concessions on assessment"},{"id":"f","text":"\"He has no legal standing at all\""}],"bins":[{"id":"right","label":"A real right","valence":"pos"},{"id":"myth","label":"A myth","valence":"neg"}],"key":{"a":"right","b":"myth","c":"right","d":"myth","e":"right","f":"myth"},"relearn":"Accommodation, inclusive education and exam concessions are real rights; 'no cover' or 'no standing' are myths."},
  {"id":"nd-1004","cat":"advocate","type":"sort","persona":"any","source":"school vs family","hook":"Sort: which is school advocacy, and which is family advocacy?","items":[{"id":"a","text":"Requesting a learning-support plan"},{"id":"b","text":"Asking for exam concessions"},{"id":"c","text":"Explaining the profile to grandparents"},{"id":"d","text":"Setting respectful limits with a relative"},{"id":"e","text":"A note to the class teacher"},{"id":"f","text":"Coaching an aunt on what calms him"}],"bins":[{"id":"school","label":"School advocacy","valence":"neutral"},{"id":"family","label":"Family advocacy","valence":"neutral"}],"key":{"a":"school","b":"school","c":"family","d":"family","e":"school","f":"family"},"relearn":"Support plans, concessions and teacher notes are school advocacy; explaining the profile and coaching relatives are family advocacy."},
  {"id":"nd-1005","cat":"advocate","type":"sort","persona":"any","source":"strong or thin over time","hook":"Sort: keeps advocacy strong over time, or wears it thin?","items":[{"id":"a","text":"Keeping a folder of reports and notes"},{"id":"b","text":"Re-explaining from scratch each year"},{"id":"c","text":"A short summary for each new teacher"},{"id":"d","text":"Relying only on memory in meetings"},{"id":"e","text":"Noting what worked last term"},{"id":"f","text":"Letting the plan lapse over holidays"}],"bins":[{"id":"strong","label":"Keeps it strong","valence":"pos"},{"id":"thin","label":"Wears it thin","valence":"neg"}],"key":{"a":"strong","b":"thin","c":"strong","d":"thin","e":"strong","f":"thin"},"relearn":"A folder, a summary per teacher and notes on what worked keep advocacy strong; starting from scratch wears it thin."},
  {"id":"nd-1006","cat":"advocate","type":"sort","persona":"any","source":"hold or give away","hook":"Sort: holds your ground calmly, or gives your child's needs away?","items":[{"id":"a","text":"\"What support can the school offer him?\""},{"id":"b","text":"\"Sorry to bother you, never mind.\""},{"id":"c","text":"\"Can we write down what we agreed?\""},{"id":"d","text":"\"Maybe I'm overreacting, ignore me.\""},{"id":"e","text":"\"Whom should I speak to next?\""},{"id":"f","text":"\"If you say he's fine, he's fine.\""}],"bins":[{"id":"hold","label":"Holds the ground","valence":"pos"},{"id":"give","label":"Gives it away","valence":"neg"}],"key":{"a":"hold","b":"give","c":"hold","d":"give","e":"hold","f":"give"},"relearn":"Asking what support exists, writing it down and asking whom to see next hold the ground; over-apologising gives it away."},
  {"id":"nd-1007","cat":"advocate","type":"sort","persona":"any","source":"forward or dead end","hook":"Sort: a wise next step when a service is slow, or a dead end?","items":[{"id":"a","text":"Politely following up in writing"},{"id":"b","text":"Assuming nothing's available, stopping"},{"id":"c","text":"Asking a parent group for another route"},{"id":"d","text":"Deciding the system just won't help"},{"id":"e","text":"Requesting a timeline for next steps"},{"id":"f","text":"Quietly giving up to dodge the hassle"}],"bins":[{"id":"forward","label":"Keeps it moving","valence":"pos"},{"id":"dead","label":"A dead end","valence":"neg"}],"key":{"a":"forward","b":"dead","c":"forward","d":"dead","e":"forward","f":"dead"},"relearn":"Following up, asking a parent group and requesting a timeline keep it moving; assuming nothing exists is a dead end."},
  {"id":"nd-1008","cat":"advocate","type":"sort","persona":"any","source":"team or alone","hook":"Sort: builds a team of champions, or leaves you carrying it alone?","items":[{"id":"a","text":"Briefing a willing uncle on what helps"},{"id":"b","text":"Doing every school meeting solo"},{"id":"c","text":"Bringing your partner into the plan"},{"id":"d","text":"Hiding the diagnosis from family"},{"id":"e","text":"Joining a parent support group"},{"id":"f","text":"Refusing all offers of help"}],"bins":[{"id":"team","label":"Builds the team","valence":"pos"},{"id":"alone","label":"Leaves you alone","valence":"neg"}],"key":{"a":"team","b":"alone","c":"team","d":"alone","e":"team","f":"alone"},"relearn":"Briefing relatives, bringing your partner in and joining a parent group build the team; going solo leaves you alone."},
  {"id":"nd-1009","cat":"advocate","type":"branch","persona":"Meena","source":"slow to a plan","hook":"The teacher seats your son at the back and calls him just slow and distracted.","steps":[{"prompt":"She repeats it at the parent meeting. What do you say?","options":[{"text":"Accept it and say he will just need to try a lot harder","then":"She nods. At home he tries harder and tires himself out."},{"text":"Tell her he is very bright and she is wrong about him","then":"She stiffens. \"I only meant he needs help to focus.\""},{"text":"Promise extra tuition to make him faster in class","then":"She agrees. He has one more long hour each day, and no fix."},{"text":"Share his profile and ask for a front seat and chunked work","then":"She listens, a little surprised. \"Let me think about how to do it.\"","best":true}],"why":"Sharing his profile and specific asks turns a label into a plan she can follow."},{"prompt":"The next week, she says a front seat would help him but other parents may object. What do you say?","options":[{"text":"Agree, and leave him at the back to avoid any fuss","then":"She looks relieved. He goes on missing what she says."},{"text":"It is fair access, like glasses, and I can help explain it","then":"She relaxes. \"Alright. I will tell them every child gets what helps them.\"","best":true},{"text":"Other parents can complain to me directly if they mind","then":"She frowns. \"I do not want a fuss with parents.\""},{"text":"Then I will find a school that understands him better","then":"She shrugs. \"That is up to you.\" The seat stays at the back."}],"why":"Naming it as fair access, like glasses, answers her worry without a fight."},{"prompt":"A month later, his classwork is still not broken into chunks, and he is falling behind. What do you do?","options":[{"text":"Tell him to remind her about the chunked work every day","then":"He nods. He stops trying after two days, and feels bad about it."},{"text":"Complain to the principal without speaking to her first","then":"She hears it from the principal. Her replies to you turn short."},{"text":"Let it slide, since the teacher is clearly very busy","then":"The work stays too long for him, and his homework piles up."},{"text":"Share examples of chunked work and ask for a quick check-in","then":"She looks them over. \"That would help. Let us meet at the end of the month.\"","best":true}],"why":"Examples and a check-in keep the plan going without blaming her."},{"prompt":"Six months on, a new teacher takes his class and seats him at the back again. What do you do?","options":[{"text":"Assume the school passed it on and say nothing","then":"She has no idea what helps him. He stays in the last row."},{"text":"Meet her early with a one-page summary of what works for him","then":"She reads it at once. \"This helps. I will move him tomorrow.\"","best":true},{"text":"Ask the old teacher to tell the new one about it","then":"The old teacher agrees, but the message is lost in the corridor."},{"text":"Wait a few weeks to see how the term begins","then":"The weeks pass. He is quiet and lost again in the last row."}],"why":"Carrying his plan across to each new teacher yourself keeps his support going."}],"debrief":"Turn a vague 'slow' label into specific accommodations you and the teacher can both act on.","relearn":"When a teacher calls your child 'slow', share his profile and request concrete accommodations."},
  {"id":"nd-1010","cat":"advocate","type":"branch","persona":"Meena","source":"shield at the wedding","hook":"At a wedding, your daughter flaps her hands with joy when the music starts.","steps":[{"prompt":"An uncle says loudly it is bad manners and should be beaten out of her. What do you do?","options":[{"text":"Scold her in front of everyone to satisfy Uncle","then":"She freezes and drops her hands. Her eyes fill up."},{"text":"Say calmly it helps her settle, and move her somewhere quiet","then":"Uncle grunts. She flaps quietly by the window, calm again in a minute.","best":true},{"text":"Pretend not to hear him and look away from the whole thing","then":"She heard him. Her hands go still, and she looks at you."},{"text":"Snap at him that he is a cruel old man, in front of guests","then":"The hall falls quiet. Your daughter shrinks against your leg."}],"why":"A calm word and a quiet place protect her from blame she does not deserve."},{"prompt":"Later that evening, she asks if Uncle was angry because of her. What do you say?","options":[{"text":"He was a bit angry. Try not to flap in front of people","then":"She tucks her hands under her arms and goes quiet."},{"text":"Do not think about it. Go and eat something now","then":"She goes, but she keeps checking his face across the hall."},{"text":"He is a bad man. We are not going to talk to him again","then":"She nods, wide-eyed. Then she hides behind you whenever he passes."},{"text":"No. He did not understand. Your hands show you are happy","then":"She looks at her hands, then at you. \"Happy hands,\" she says.","best":true}],"why":"Telling her plainly that it is not her fault keeps her feeling safe and whole."},{"prompt":"Later, Uncle says you should have raised her more strictly. What do you say?","options":[{"text":"You are right. I will be stricter with her from now on","then":"He nods, pleased. At home she watches your face before she moves."},{"text":"It is how her mind works, Uncle. No one is to blame","then":"He is silent. \"Hmm. Well. She is a sweet girl, at least.\"","best":true},{"text":"Please take it up with her father, Uncle","then":"Uncle shrugs. \"He will agree with me.\" Nobody corrects him."},{"text":"Your own children were a lot worse, if I remember well","then":"His face darkens. The conversation ends, and a family row begins to brew."}],"why":"Correcting blame calmly shields her, and no one caused this."}],"debrief":"Shield your child from undeserved blame by calmly correcting it, not passing it on.","relearn":"When a relative shames stimming, calmly explain it's self-soothing and protect your child."},
  {"id":"nd-1011","cat":"advocate","type":"branch","persona":"Divya","source":"report unlocks concession","hook":"The school will only allow exam extra time if you produce a formal assessment report.","steps":[{"prompt":"His final exams at school are a few months away, and you have no report yet. What do you do?","options":[{"text":"Book a qualified professional assessment to get the report","then":"The psychologist has a slot next month. You mark the school deadline on the calendar.","best":true},{"text":"Argue that extra time should be granted on your word alone","then":"The principal says the school needs paper, not promises. The meeting ends stiffly."},{"text":"Ask his teacher to quietly give him extra time in class tests","then":"She does, once or twice. The final exams still have no record of his need."},{"text":"Wait for the school to arrange an assessment on its own","then":"Weeks pass. Nobody at school has started anything, and the exams draw closer."}],"why":"A qualified report is the evidence the school needs to grant fair extra time."},{"prompt":"Before the mock tests, he says he will fail because he is stupid. What do you say?","options":[{"text":"Do not say that. Just study more at night and you will pass","then":"He nods, and studies until midnight. His eyes are red in the morning."},{"text":"Maybe the tests do not matter. Let us forget about them","then":"He relaxes, but a knot of shame stays. He avoids his books."},{"text":"You are not stupid. Your brain just reads differently","then":"He looks up, unsure, but his shoulders come down a little.","best":true},{"text":"We will fix your reading by drilling every evening from now","then":"He groans. The evenings become long, tense sessions for both of you."}],"why":"Telling him his brain works differently protects how he sees himself."},{"prompt":"The school sets a date for the extra-time form: a report plus your signed request. What do you do?","options":[{"text":"Get the report and request in before the date, with copies","then":"The clerk stamps your copies. You keep your set in a folder at home.","best":true},{"text":"Send only your request and assume the school will chase the rest","then":"A week later, the form is still missing the report. The deadline slips closer."},{"text":"Tell his class teacher verbally and trust her to pass it on","then":"She nods kindly. The office never hears about it."},{"text":"Submit it later, once the mock results come out","then":"The mock results are poor, and now the deadline has also passed."}],"why":"Submitting on time with copies keeps the concession safe."},{"prompt":"The day before the exam, you learn the invigilator's list has no extra time for him. What do you do?","options":[{"text":"Trust the school to fix it on the day itself","then":"On the day, the invigilator has no record. He starts the paper without the time."},{"text":"Tell him to ask the invigilator himself when he arrives","then":"He is too nervous to speak up. The bell rings, and the time is gone."},{"text":"Go to the office today and ask them to add him","then":"The clerk checks the file and calls the exam in-charge. Together you sort out how to add his name.","best":true},{"text":"Argue with the invigilator in the hall tomorrow morning","then":"Other students look on. The argument only makes him more anxious before the paper."}],"why":"Going in person the day before fixes a missing record while there is still time."},{"prompt":"After the exams, he asks if he will always need extra time. What do you say?","options":[{"text":"Let us hope not. Try to manage without it next year","then":"He looks down. \"But I need it to finish,\" he says softly."},{"text":"If it helps you show what you know, yes. That is fair","then":"He smiles. \"So I can read each question twice.\"","best":true},{"text":"Yes, but do not tell your friends that you get it","then":"He nods, and keeps a small secret that weighs on him."},{"text":"Only until you learn to read as fast as the others","then":"He goes quiet, then asks, \"What if I never do?\""}],"why":"Extra time is fair access for as long as it helps, and nothing to hide."}],"debrief":"A professional assessment is the evidence that unlocks fair exam concessions; pursue it.","relearn":"Seek a qualified assessment to get the report the school needs for fair exam concessions."},
  {"id":"nd-1012","cat":"advocate","type":"branch","persona":"Meena","source":"carry the plan over","hook":"Your son's support plan was agreed last year, but his new teacher has not seen it.","steps":[{"prompt":"Term starts and he is already covering his ears in class. What do you do?","options":[{"text":"Assume the school passed it on and say nothing so far","then":"Days pass. He keeps covering his ears, and nobody knows what to try."},{"text":"Ask him to explain his needs to the new teacher himself","then":"He tries. He is too anxious to say more than \"Loud\", and she is puzzled."},{"text":"Wait a month to see if the teacher notices by herself","then":"The month passes. He comes home tired and snappish every day."},{"text":"Share the plan and a short summary and ask to review it","then":"The teacher takes the pages with thanks. \"I did not know about this,\" she says.","best":true}],"why":"Sharing the plan and a summary yourself keeps his support from lapsing."},{"prompt":"Soon after, the teacher calls you in and asks what matters most for him. What do you say?","options":[{"text":"Hand her the whole plan and say every part matters equally","then":"She looks daunted. The plan stays unread on her desk."},{"text":"Name the top two supports: his seat and warnings before changes","then":"She writes both on a sticky note. \"That I can do from tomorrow,\" she says.","best":true},{"text":"Say you will send the plan next month, when she is less busy","then":"She nods, relieved. The month is a long one for him."},{"text":"Say the school should have told her already. It is their job","then":"She stiffens. The rest of the meeting is polite and cold."}],"why":"Two clear priorities give a busy teacher something she can start today."},{"prompt":"The teacher asks how she will know if the supports are working. What do you propose?","options":[{"text":"Waiting for the annual review to see how things went","then":"The annual review is months away, and small problems grow in between."},{"text":"Saying he will tell her himself if something is not working","then":"He is not able to explain. Things slip before anyone notices."},{"text":"Saying you will let her know only if you are unhappy","then":"She waits for your call. Small problems grow quietly in the meantime."},{"text":"A short check-in every month and a shared note of what helps","then":"She smiles. \"Yes, let us do that. I will put the first date in my diary.\"","best":true}],"why":"A regular check-in keeps the plan alive and fitted to how he is doing."}],"debrief":"Carry your child's plan across each teacher handover yourself; don't assume it travelled.","relearn":"At a handover, share the plan and a summary yourself so accommodations carry over."},
  {"id":"nd-1013","cat":"advocate","type":"branch","persona":"Vikram","source":"refuse the cure seller","hook":"A miracle therapist guarantees to cure your child's autism in three months for a big fee.","steps":[{"prompt":"A relative arranged the visit, and the fee is due today. What do you do?","options":[{"text":"Pay up, since this may be the cure you have prayed for so long","then":"You hand over the fee. The therapist smiles and promises results by the third month."},{"text":"Pay half now as a trial and see whether he improves in time","then":"You hand over half. The therapist asks for the rest before week two."},{"text":"Decline and ask a qualified professional what would help him","then":"The relative sighs. You book a session with the psychologist you trust.","best":true},{"text":"Ask for a written guarantee first and then decide about it","then":"The therapist writes one quickly. It says a lot and proves nothing."}],"why":"There is no cure for neurodivergence, so real support beats a guarantee."},{"prompt":"That evening, the relative calls. She says the whole family is counting on this cure. What do you say?","options":[{"text":"Thank her, and say there is no cure, only support that helps","then":"She sighs. \"I only wanted the best for him.\" She does not press again.","best":true},{"text":"Agree to give it a try, just to keep the family peace","then":"The sessions begin. The fees mount, and he dreads each visit."},{"text":"Say she is wasting the family's time and money on nonsense","then":"She goes quiet, hurt. The next family gathering is stiff."},{"text":"Say she should not mention your son's diagnosis to anyone","then":"\"You are hiding it?\" she asks, and the talk turns into a fight."}],"why":"Thanking her while naming the truth declines the cure without a fight."},{"prompt":"Later, an online ad promises a natural cure with a special diet pack. What do you do?","options":[{"text":"Try it for a month and watch him closely to see","then":"His meals become stressful as you weigh every bite, and nothing changes."},{"text":"Order the pack because the cost is small, just to be sure","then":"It arrives. He refuses it, and the leftover packets sit in a cupboard."},{"text":"Skip it and ask his doctor only if he has real food needs","then":"You close the ad. Your son eats his usual dinner and asks for more rice.","best":true},{"text":"Share the ad in the parents' group in case it helps others","then":"A few parents ask for the link. Some of them start ordering the pack."}],"why":"No pack or diet cures neurodivergence, so trust qualified support."},{"prompt":"A month later, a parent in your group asks how you decided about the clinic. What do you say?","options":[{"text":"Share what helped and that there is no cure, only support","then":"She nods. \"I was tempted too. Thank you for telling me.\"","best":true},{"text":"Recommend the therapist anyway, since a visit cannot hurt","then":"She books it. Your advice now rests on someone else's money."},{"text":"Say every child is different, so she should just try it","then":"She books a visit. Nobody has told her about the fee or the guarantee."},{"text":"Say you did nothing and he improved on his own","then":"She looks puzzled. \"So nothing helps?\" she asks."}],"why":"Sharing what you learned helps other parents avoid the same trap."}],"debrief":"There is no 'cure' for neurodivergence; trust qualified, evidence-based support.","relearn":"Decline 'cure' sellers; neurodivergence isn't a disease to cure, so seek evidence-based support."},
  {"id":"nd-1014","cat":"advocate","type":"branch","persona":"Meena","source":"reframe meltdown plan","hook":"The school sends your daughter home after a meltdown, calling it violent misconduct.","steps":[{"prompt":"The principal's note says she may not return until she is more disciplined. What do you do?","options":[{"text":"Accept the punishment and keep her at home for now","then":"She stays home. For now, nobody at school has asked what set her off."},{"text":"Ask to meet, explain overwhelm and request a sensory plan","then":"The principal agrees to meet on Monday and asks you to bring notes.","best":true},{"text":"Promise the principal it will never happen again at school","then":"The principal accepts. You cannot keep that promise, and you know it."},{"text":"Punish her at home so the school sees that you are serious","then":"She cries at home. The next meltdown comes the first time the noise builds."}],"why":"Reframing it as overwhelm and asking for a plan moves the school from punishing to preventing."},{"prompt":"Later, the principal asks you what set her off. What do you say?","options":[{"text":"Say you are not sure and leave it to the school to decide","then":"She looks puzzled. \"Then how can we prevent it happening again?\""},{"text":"Say another child provoked her and should be punished too","then":"She frowns. The meeting turns into a hunt for blame."},{"text":"Say she is too sensitive to cope with a regular school","then":"She nods slowly. \"Then we will need to decide whether we can keep her here.\""},{"text":"Name the noise and crowd, and suggest a quiet space","then":"She listens. \"A signal card and a quiet room. We can try that.\"","best":true}],"why":"Naming the trigger and a specific plan gives the school something to act on."},{"prompt":"Your daughter says everyone thinks she is dangerous now. What do you tell her?","options":[{"text":"Just say sorry to your class and it will all be forgotten","then":"She practises her sorry in the mirror, and feels sick at the thought."},{"text":"You are not dangerous. It got too much. We will plan for it","then":"She wipes her eyes. \"Can I have a quiet place?\" You nod, and she relaxes.","best":true},{"text":"Do not care what they think. Go back with your head held high","then":"She nods, but she keeps her eyes on the floor at the school gate."},{"text":"You can stay home until they forget about it, beta","then":"She is relieved. The gate feels harder each day she stays away."}],"why":"Reassuring her and having a plan rebuilds her sense of safety at school."}],"debrief":"Reframe a meltdown as overwhelm and ask for prevention, not punishment.","relearn":"When a meltdown is called misconduct, reframe it as overwhelm and request a sensory plan."},
  {"id":"nd-1015","cat":"advocate","type":"branch","persona":"Vikram","source":"hold to inclusion duty","hook":"A school says it cannot accommodate your son and tells you to look elsewhere.","steps":[{"prompt":"The admissions head hands you a list of other schools. What do you do?","options":[{"text":"Ask in writing about its inclusion duty and whom to approach","then":"He looks uneasy. \"The trustee handles this,\" he says. You note the name.","best":true},{"text":"Quietly accept that no school will take him at all","then":"You take the list home. The search feels heavier every evening."},{"text":"Argue loudly at the desk until someone changes the decision","then":"Security is called to the lobby. The head closes the file."},{"text":"Leave and ask relatives which schools are friendliest instead","then":"Aunties give you three names. Nobody says why the first school refused."}],"why":"Asking in writing keeps the door open and shows the school you know its duty."},{"prompt":"A week later, the school emails two lines saying it lacks resources. What do you do?","options":[{"text":"Accept the reply, since it is now official from the school","then":"You file the letter. The refusal now looks final to everyone."},{"text":"Post an angry review of the school online tonight","then":"The review gets attention. The school stops replying to your emails."},{"text":"Reply politely and ask what support it would need","then":"A trustee replies within days and asks to meet. The door stays ajar.","best":true},{"text":"Ask them to take him for a trial month, off the record","then":"The head hesitates and says nothing can be put on paper."}],"why":"A polite reply asking what support it needs keeps the talk alive and on record."},{"prompt":"Your son asks why he is not going to school like his cousin. What do you say?","options":[{"text":"We are finding a school that fits you. You did nothing wrong","then":"He thinks. \"A school with a quiet room?\" \"We will look for one,\" you say.","best":true},{"text":"Some schools do not want children like you, so we will wait","then":"He looks at his hands. The word \"wait\" makes him uneasy."},{"text":"Do not worry. You will be in a school by next month","then":"He cheers. When next month comes with no place, he asks again."},{"text":"Do not ask about that now. Eat your food first","then":"He pushes the plate away. The question stays with him."}],"why":"Telling him it is not his fault and you are looking keeps him secure."},{"prompt":"A month on, the first school's new brochure says it welcomes every child. What do you do?","options":[{"text":"Let it go, since the school has already said no once","then":"You set the brochure aside. The search goes on elsewhere."},{"text":"Confront the head at the school gate in front of parents","then":"The head refuses to talk, and other parents stare."},{"text":"Write again, quoting the brochure, and ask to meet","then":"The school replies with a date to discuss the support he needs.","best":true},{"text":"Ask a relative who knows the head to put in a word","then":"The relative calls once. The head is polite, and nothing is on record."}],"why":"One no is not final. A calm written request holds the school to its word."}],"debrief":"Hold a school to its inclusion duty calmly and in writing; one 'no' isn't final.","relearn":"If a school 'can't accommodate', ask in writing about its inclusion duty and the next step."},
  {"id":"nd-1016","cat":"advocate","type":"branch","persona":"Divya","source":"don't advocate alone","hook":"You feel too drained and ashamed to attend yet another meeting about your child's needs.","steps":[{"prompt":"The school meeting is tomorrow. What do you do tonight?","options":[{"text":"Skip it and say nothing to the school","then":"The meeting goes ahead without you, and his plan stalls again."},{"text":"Go alone and say nothing so that it is over quickly","then":"You sit, nod and leave. The plan does not move, and you feel worse."},{"text":"Stay up all night writing every complaint you have ever had","then":"You arrive exhausted with six pages. The meeting cannot cover them."},{"text":"Ask your partner or a parent-group friend to come with you","then":"Your friend says, \"Of course.\" She offers to take notes so you can listen.","best":true}],"why":"Bringing someone shares the load, so the meeting can actually move things forward."},{"prompt":"A fortnight later, the school calls you in again. As the teacher lists his problems, your chest tightens. What do you do?","options":[{"text":"Agree with everything so that the meeting ends sooner","then":"She nods, relieved. You leave with a list of his faults and no plan."},{"text":"Ask for a short pause, then ask what the school can do","then":"She waits. Then she says, \"A break card and a seat near me.\"","best":true},{"text":"Say you are fine and push through in silence","then":"You hold your breath until the end. Nothing is asked of the school."},{"text":"Tell her the school is just making excuses again","then":"She stiffens. \"I am only trying to help him,\" she says."}],"why":"A pause steadies you, and asking what the school can do turns problems into a plan."},{"prompt":"Your tiredness lingers. A parent group meets on Sunday. What do you do?","options":[{"text":"Skip it, since the others have enough troubles of their own","then":"Sunday passes quietly. You feel more alone than before."},{"text":"Go, but only to give advice to the other parents","then":"You speak for an hour. You leave with your own tiredness untouched."},{"text":"Go, but tell everyone you are coping fine","then":"They nod and move on. You leave as heavy as you came."},{"text":"Go, and share how heavy it has felt lately","then":"Two mothers nod. \"Same here,\" one says, and hands you a cup of tea.","best":true}],"why":"Sharing with other parents sustains you, so advocacy does not rest on you alone."}],"debrief":"You don't have to advocate alone; bring someone so advocacy survives your tiredness.","relearn":"When you're drained, bring your partner or a parent-friend so advocacy doesn't rest on you alone."},
  {"id":"nd-1017","cat":"advocate","type":"branch","persona":"Divya","source":"right method not drills","hook":"After his dyslexia assessment, a tutor offers to help your son with his slow reading before exams.","steps":[{"prompt":"The tutor proposes two hours of drills every day. What do you say?","options":[{"text":"Agree, since at least someone is trying to help him","then":"The drills start. By the second week he cries at the sight of the book."},{"text":"Say no tutor is needed and stop all outside help","then":"Reading gets no extra help at all. The exam date does not move."},{"text":"Explain that dyslexia needs the right method and concessions","then":"He listens. \"I have only ever done drills,\" he says. \"What method?\"","best":true},{"text":"Ask the tutor to shorten the drills but keep them daily","then":"The drills are shorter, but the same pages still come back each day."}],"why":"Naming the right method and concessions steers help toward what works for him."},{"prompt":"A week later, the tutor calls and asks what would work better for your son. What do you suggest?","options":[{"text":"A structured sound-based method, checked with a specialist","then":"He nods and takes notes. \"I will read up on it,\" he says.","best":true},{"text":"Double the drills so he catches up before the exams","then":"He works twice as long. His eyes hurt, and his reading is unchanged."},{"text":"Let him pick whatever seems easiest to him each day","then":"He picks pictures every time. The reading does not grow."},{"text":"Use flashcards, since they worked for your cousin's child","then":"The flashcards go well one week. Then he stops looking at them."}],"why":"A structured method matched to how he learns beats more hours of the same thing."},{"prompt":"Your mother-in-law says more drills would fix it faster. What do you say?","options":[{"text":"Agree to more drills on Sundays to keep her happy","then":"Sundays turn into a battle. He hides his book under the sofa."},{"text":"Tell her it is not her decision and to stay out of it","then":"She says nothing. Her silence hangs at every meal."},{"text":"Effort is not the gap. The right help is what he needs","then":"She sighs. \"He does try hard,\" she says. \"I have seen it.\"","best":true},{"text":"Say the tutor knows best, so nobody should worry about it","then":"She nods, and the worry about his reading stays where it was."}],"why":"Explaining that effort is not the gap brings the family along."}],"debrief":"Advocate for the right method and concessions, not just more hours; effort isn't the gap.","relearn":"For dyslexia, advocate for the right method and exam concessions, not endless drilling."},
  {"id":"nd-1018","cat":"advocate","type":"branch","persona":"Meena","source":"openness over secrecy","hook":"Grandparents insist the diagnosis stays secret to protect the child's marriage prospects.","steps":[{"prompt":"Grandpa says nobody outside the house must ever know. What do you say?","options":[{"text":"Agree to hide it completely to keep the peace at home","then":"He nods, satisfied. At the next function your son is left alone, unexplained."},{"text":"Say gently that openness on your terms lets support in","then":"He grunts. \"Support? From whom?\" Grandma glances at you, listening.","best":true},{"text":"Announce it to everyone at the next function, so it is out","then":"The room stirs. Grandma is upset, and the talk turns to family honour."},{"text":"Say nothing now and decide later, when things are calmer","then":"He takes your silence for a yes. Nothing is settled."}],"why":"Openness on your own terms lets support and understanding in."},{"prompt":"A neighbour asks why your son wears headphones. Grandma glances at you anxiously. What do you say?","options":[{"text":"A new gadget he loves, and that is all it is","then":"She nods and moves on. Your son hears the story and looks away."},{"text":"Mind your own business, please. It is our family matter","then":"Her face falls. She leaves quickly and does not visit for weeks."},{"text":"He has a problem and we prefer not to talk about it","then":"She looks at your son with pity. Grandma looks away."},{"text":"He finds noise hard, and the headphones help him","then":"She nods. \"My grandson is like that with fireworks.\"","best":true}],"why":"A simple, honest answer lets understanding in without a long explanation."},{"prompt":"Grandpa asks what will happen to his marriage prospects. What do you say?","options":[{"text":"You are right. We must not risk it. We will hide it","then":"He looks satisfied. The secret sits at every family meal."},{"text":"His happiness and confidence come first. He can decide later","then":"Grandpa is quiet. \"He is only five,\" he says. \"Let us see.\"","best":true},{"text":"Times have changed, Papa. Nobody cares about such things now","then":"He bristles. \"You young people think you know everything.\""},{"text":"We will find out when the time comes, so no point now","then":"He shrugs. The worry stays where it was."}],"why":"A child who feels accepted has the best base for his whole life."},{"prompt":"The school asks if it may share his needs with all his teachers. Grandma looks worried. What do you do?","options":[{"text":"Say no and keep it hidden from his teachers","then":"The teachers do not know. He gets scolded for what he cannot help."},{"text":"Say yes and let the school tell anyone it likes","then":"Details reach the canteen staff and other parents in the corridor."},{"text":"Ask Grandma to decide, since she is so worried","then":"She says no, and it stays that way for the whole year."},{"text":"Say yes, choose what is shared and tell Grandma why","then":"Grandma listens. \"Only what helps him,\" she says quietly.","best":true}],"why":"Sharing with the people who need to know, on your terms, keeps him supported."}],"debrief":"Openness on your own terms lets support in; secrecy feeds the stigma it fears.","relearn":"Openness about a diagnosis, on your own terms, lets support in; secrecy isolates the family."},
  {"id":"nd-1019","cat":"advocate","type":"branch","persona":"Meena","source":"verbal yes in writing","hook":"The school agreed out loud to a front seat and short breaks for your son.","steps":[{"prompt":"A week on, neither is in place. What do you do?","options":[{"text":"Send a polite written summary with a review date","then":"The class teacher replies within the day. \"Thanks. Yes, I have it here.\"","best":true},{"text":"Assume good intentions and wait for months","then":"Weeks pass. He is still at the back with no breaks."},{"text":"Ask him to remind the teacher himself every single day","then":"He tries twice, then stops. He feels he has failed."},{"text":"Call the principal and say the school has lied to you","then":"She defends the teacher. Now everyone is defensive."}],"why":"A written summary with a review date turns a vague yes into something trackable."},{"prompt":"At pick-up one day, the teacher tells you she has a full class and a busy week. What do you say?","options":[{"text":"Say it is fine, and she can take all the time she needs","then":"She thanks you. Weeks pass without anything changing."},{"text":"Say the agreement is overdue and you will escalate at once","then":"She goes quiet. The school starts to act stiff around you."},{"text":"Thank her and ask which one thing she can start first","then":"She thinks. \"The seat, from Monday. The breaks after that.\"","best":true},{"text":"Say you will drop the breaks and settle for the seat alone","then":"She looks relieved. He loses the breaks he was promised."}],"why":"Asking for one thing first makes it doable for a busy teacher."},{"prompt":"Later in the term, the seat is in place, but without breaks he fades by noon. What do you do?","options":[{"text":"Thank her for the seat and set a date for the breaks","then":"She smiles, and adds the date to her diary. \"Breaks by then,\" she says.","best":true},{"text":"Write to the principal that the school has failed him","then":"The principal calls you both in, and she feels ambushed."},{"text":"Assume breaks are not possible and drop them for good","then":"The seat helps, but his afternoons stay a struggle."},{"text":"Wait for the next term to raise it again","then":"The term drags on. He sits in the front but without any breaks."}],"why":"Thanking her and setting a date for the rest keeps every step moving."}],"debrief":"Follow a verbal yes with a calm written summary and a review date so agreements happen.","relearn":"After a verbal yes, send a written summary and a review date so accommodations actually happen."},
  {"id":"nd-1020","cat":"advocate","type":"match","persona":"Meena","source":"blocker to reply","hook":"Match each blocker you might hear to a calm advocacy reply.","pairs":[{"left":"\"He's just lazy and won't try.\"","right":"\"His brain works differently; here's what helps him.\""},{"left":"\"We can't accommodate him.\"","right":"\"What's our duty to include him here?\""},{"left":"\"Extra time is unfair to others.\"","right":"\"It's fair access, like glasses.\""},{"left":"\"Let's just wait and see.\"","right":"\"Can we set a date to review?\""},{"left":"\"Keep the diagnosis quiet.\"","right":"\"Openness, on our terms, lets help in.\""}],"relearn":"Each blocker has a calm reply: reframe 'lazy', name the duty to include, name fair access, set a review."},
  {"id":"nd-1021","cat":"advocate","type":"match","persona":"any","source":"arena to first move","hook":"Match each arena to the right first advocacy move there.","pairs":[{"left":"School","right":"Request a written learning-support plan"},{"left":"Exam board","right":"Apply for concessions with an assessment"},{"left":"Grandparents","right":"Explain the profile and set respectful limits"},{"left":"A slow service","right":"Follow up politely and ask the next step"},{"left":"Your co-parent","right":"Agree the plan and share the load"}],"relearn":"School needs a written plan, the exam board concessions, grandparents understanding, a slow service follow-up, a co-parent shared load."},
  {"id":"nd-1022","cat":"advocate","type":"match","persona":"any","source":"right to example","hook":"Match each disability right to a plain example for a parent.","pairs":[{"left":"Reasonable accommodation","right":"Noise headphones and a quiet exam room"},{"left":"Inclusive education","right":"A place in a regular school with support"},{"left":"Non-discrimination","right":"Not refused only for being autistic"},{"left":"Exam adjustments","right":"Extra time or a scribe on assessment"},{"left":"Accessible learning","right":"Materials in a form he can use"}],"relearn":"These rights mean accommodation, a regular-school place, exam adjustments, accessible materials."},
  {"id":"nd-1023","cat":"advocate","type":"match","persona":"any","source":"habit to problem","hook":"Match each advocacy habit to the problem it prevents.","pairs":[{"left":"Keeping a report folder","right":"Re-proving the diagnosis every year"},{"left":"A one-page profile note","right":"Each new teacher starting from zero"},{"left":"Written agreements","right":"A verbal yes going nowhere"},{"left":"A review date","right":"A plan that lapses and is forgotten"},{"left":"A parent-group contact","right":"Hitting a dead end with no other route"}],"relearn":"A folder, a profile note, written agreements, review dates and parent contacts each prevent a way advocacy quietly fails."},
  {"id":"nd-1024","cat":"advocate","type":"match","persona":"any","source":"who gives what","hook":"Match each person on your child's team to what they best give.","pairs":[{"left":"Class teacher","right":"Day-to-day accommodations in the room"},{"left":"Qualified professional","right":"Assessment and tailored strategies"},{"left":"Co-parent","right":"Sharing meetings and the daily load"},{"left":"Parent support group","right":"Practical tips and another route to try"},{"left":"Willing grandparent","right":"A calm, understanding extra champion"}],"relearn":"A teacher gives daily accommodations, a professional assessment, a co-parent shared load, a group tips, a grandparent support."},
  {"id":"nd-1025","cat":"advocate","type":"match","persona":"any","source":"weak to strong move","hook":"Match each weak advocacy move to its stronger version.","pairs":[{"left":"\"Sorry to bother you.\"","right":"\"I'd like to discuss the support he needs.\""},{"left":"Relying on memory","right":"Bringing a folder of reports and notes"},{"left":"Dropping it after a 'no'","right":"Asking, in writing, whom to approach next"},{"left":"Blaming the teacher","right":"Asking what she notices, then offering help"},{"left":"Hiding the diagnosis","right":"Sharing it, on your terms, with helpers"}],"relearn":"Swap apology for a clear ask, memory for a folder, giving up for a next step, blame for partnership, hiding for openness."},
  {"id":"nd-1026","cat":"advocate","type":"match","persona":"any","source":"line to effect","hook":"Match each calm parent line to what it achieves in a meeting.","pairs":[{"left":"\"Can we write down what we agreed?\"","right":"Turns a vague yes into a commitment"},{"left":"\"What's worked for others here?\"","right":"Invites the school's experience"},{"left":"\"Here are his strengths and triggers.\"","right":"Gives the teacher a starting point"},{"left":"\"Whom should I speak to next?\"","right":"Keeps the path open after a 'no'"},{"left":"\"Can we set a date to review?\"","right":"Stops the plan quietly lapsing"}],"relearn":"Calm lines do work: writing tracks it, asking experience builds partnership, review dates hold the plan."},
  {"id":"nd-1027","cat":"advocate","type":"match","persona":"any","source":"quackery to truth","hook":"Match each 'cure' claim to the truth that debunks it.","pairs":[{"left":"\"This diet will cure his autism.\"","right":"Neurodivergence isn't a disease to cure"},{"left":"\"Strict discipline fixes ADHD.\"","right":"You can't punish a wiring difference away"},{"left":"\"He'll grow out of dyslexia.\"","right":"It's lifelong; the right method helps"},{"left":"\"A label will ruin his future.\"","right":"A diagnosis is a key, not a verdict"},{"left":"\"Just try harder, he'll be normal.\"","right":"Support lets him show his best"}],"relearn":"No diet cures autism, discipline can't fix ADHD, dyslexia is lifelong, a label is a key not a verdict."},
  {"id":"nd-1028","cat":"advocate","type":"role-play","persona":"Meena","source":"open as partner","hook":"You are meeting the principal to request a support plan for your son.","setup":"She waves you to a chair and folds her hands.","steps":[{"prompt":"The principal says: \"I have ten minutes. What can I do for you?\"","options":[{"text":"\"Thank you for your time. I'd love to work with you. Here are his strengths.\"","then":"She unfolds her hands. \"Strengths first. That is a nice change. Go on.\"","best":true},{"text":"\"I suppose you will say there is nothing the school can do, as usual.\"","then":"Her jaw tightens. \"I have not said anything yet.\""},{"text":"\"I know he is difficult. I am sorry to take your time.\"","then":"\"Well, he is not the only one,\" she says, and glances at the clock."},{"text":"\"I need a plan today, or I will go higher up.\"","then":"She stiffens. \"Let us not start with threats.\""}],"why":"Opening with thanks, strengths and a wish to work together sets the tone."},{"prompt":"She says: \"Support plans are a lot of work for the staff.\"","options":[{"text":"\"That is what all schools say. It is your duty, madam.\"","then":"Her voice cools. \"I will hear you out, but I will not be lectured.\""},{"text":"\"Then he can go to a school that has time for him.\"","then":"She reaches for his file, then stops. \"Before you decide that, tell me more.\""},{"text":"\"I understand. Could we start with two small steps?\"","then":"She softens. \"Two steps sound manageable,\" she says, and picks up a pen.","best":true},{"text":"\"Then never mind. I will manage without the school.\"","then":"She looks relieved, then hesitates. \"Wait. Let us not give up so fast.\""}],"why":"Offering two small steps makes yes an easy answer for a busy principal."},{"prompt":"She asks: \"If we tried one or two things for him, what would they be?\"","options":[{"text":"\"A front seat and a short break every half hour.\"","then":"She writes both down. \"I can bring these to the staff.\"","best":true},{"text":"\"Everything on the list I brought, all at once.\"","then":"She flips through six pages and sighs. \"That is a lot to start with.\""},{"text":"\"Whatever you think is best. I do not really know.\"","then":"\"Then I will decide,\" she says. Her choices do not match his needs."},{"text":"\"That he is never punished for anything again.\"","then":"\"That I cannot promise,\" she says. \"Not for any child.\""}],"why":"Two clear requests give her something she can start on this week."}],"relearn":"Opening with thanks, strengths and a wish to work together sets advocacy up as partnership, not a battle."},
  {"id":"nd-1029","cat":"advocate","type":"role-play","persona":"Vikram","source":"fair access reply","hook":"Your son's teacher will not give him extra time in tests.","setup":"You catch her in the corridor after the class test.","steps":[{"prompt":"The teacher says: \"Extra time would not be fair to the others.\"","options":[{"text":"\"Fine. Forget it. I do not want him to be the odd one out.\"","then":"She looks relieved. He goes back to timed tests with the rest."},{"text":"\"It is fair access, like glasses. It lets him show what he knows.\"","then":"She hesitates. \"Like glasses. Hmm. I had not thought of it that way.\"","best":true},{"text":"\"So you want him to fail? That is very unfair of you.\"","then":"Her face hardens. \"I said nothing of the sort.\""},{"text":"\"Could you at least tell him he is doing well in class?\"","then":"She smiles and says she will. The test timing stays the same."}],"why":"Naming extra time as fair access answers the fairness worry without backing down."},{"prompt":"She adds: \"If one child got extra time, the others would ask why.\"","options":[{"text":"\"Tell them he is special and needs help.\"","then":"\"Poor thing,\" a child mutters. Your son hears it and goes quiet."},{"text":"\"Then let us make the whole class take extra time.\"","then":"She laughs, but not kindly. \"The timetable will not allow it.\""},{"text":"\"Do not tell them anything. Just do it quietly, please.\"","then":"She agrees. The children still notice, and make up their own reasons."},{"text":"\"Every child gets what helps them, and this is his.\"","then":"She thinks. \"That I can say. It is true, at least.\"","best":true}],"why":"A simple, true answer keeps his support fair and free of pity."},{"prompt":"She says: \"I would need something in writing for the school.\"","options":[{"text":"\"Just trust me. I would never lie about my own son.\"","then":"\"I do trust you,\" she says. \"But the office needs paper.\""},{"text":"\"Of course. I will bring the professional's report by Friday.\"","then":"\"Thank you. I will pass it to the principal that day.\"","best":true},{"text":"\"You should not need that. It is only common sense, madam.\"","then":"\"Perhaps. But rules are rules,\" she says."},{"text":"\"Please ask the principal to sort it out for you, madam.\"","then":"\"I will try,\" she says. The request goes to the bottom of a pile."}],"why":"Bringing the report and a date makes it easy for her to say yes."}],"relearn":"Naming concessions as fair access, like glasses, answers the 'unfairness' worry without backing down."},
  {"id":"nd-1030","cat":"advocate","type":"role-play","persona":"Meena","source":"answer the hide-it elder","hook":"Your mother-in-law wants your son's autism diagnosis kept hidden.","setup":"She lowers her voice as the tea is served.","steps":[{"prompt":"Your mother-in-law whispers: \"Tell no one. People will talk about our family.\"","options":[{"text":"\"You are right. We will never mention it to anyone again.\"","then":"She nods, relieved. Your son is left unexplained at the next function."},{"text":"\"I do not care what people say. I will tell everyone.\"","then":"She goes pale. \"Not in front of me. Not like this.\""},{"text":"\"Let us not talk about it now. Please drink your tea.\"","then":"She sips, unsatisfied. The worry sits between you."},{"text":"\"I understand. Openness on our terms lets people help him.\"","then":"She frowns. \"Help? From whom? People only gossip.\"","best":true}],"why":"Acknowledging her fear while choosing openness keeps help flowing to him."},{"prompt":"She frets: \"What if the neighbours find out and look down on him?\"","options":[{"text":"\"Then it is my fault. I will take all the blame myself.\"","then":"She says, \"Do not say that. Nobody did this to him.\" Her voice is unsteady."},{"text":"\"Some may. But he will have people around who understand him.\"","then":"She is quiet. \"People who understand. That would be something.\"","best":true},{"text":"\"Then we will stop speaking to those neighbours for good.\"","then":"She looks alarmed. \"Over gossip? That is extreme.\""},{"text":"\"Then we will move somewhere no one knows our family.\"","then":"She stares. \"Move? For this? What would people say?\""}],"why":"No one caused this. A circle of people who understand him is stronger than avoiding gossip."},{"prompt":"A few days later, she asks: \"Tell me plainly. Who should know about his diagnosis?\"","options":[{"text":"\"Only the doctor. Nobody else, so it stays private forever.\"","then":"She agrees warmly. Help stays limited to one clinic room."},{"text":"\"The whole family WhatsApp group, tonight, so it is out.\"","then":"She gasps. \"Tonight? Without asking anyone?\""},{"text":"\"Whoever the elders decide. It is their family matter.\"","then":"She brightens. \"Then I will tell my sisters first.\""},{"text":"\"His teacher, our doctor and a parent group for support.\"","then":"She nods slowly. \"Teacher and doctor. That I can accept.\"","best":true}],"why":"Telling the people who can help, on your terms, keeps him supported and you in charge."},{"prompt":"She asks: \"And what should I say if someone asks me about him?\"","options":[{"text":"\"Say he is just shy. That is what we always say.\"","then":"She nods. Your son hears it again at the next function."},{"text":"\"Say he is autistic, and wonderful, and needs some quiet.\"","then":"She nods slowly. \"Autistic. Wonderful. I can say that.\"","best":true},{"text":"\"Say nothing, and change the subject if anyone asks.\"","then":"She agrees. The neighbours gossip louder for being left guessing."},{"text":"\"Say it is my fault, and please do not blame him.\"","then":"She looks pained. \"Do not say that about yourself.\""}],"why":"A plain, warm line names it on your terms and keeps the blame away."}],"relearn":"Acknowledging the fear while choosing openness keeps support flowing and protects the child from isolating secrecy."},
  {"id":"nd-1031","cat":"advocate","type":"role-play","persona":"Divya","source":"polite follow-up call","hook":"A slow service has ignored your assessment request for weeks.","setup":"You are on the phone with its front desk.","steps":[{"prompt":"The receptionist says: \"Hello, how may I help you?\"","options":[{"text":"\"I assume nothing is happening, so I will stop bothering you.\"","then":"\"Alright,\" she says, then pauses. \"Hold on. Let me look it up first.\""},{"text":"\"Why has nobody called me? This is absolutely unacceptable!\"","then":"\"Madam, I am only the front desk,\" she says coolly. \"Let me look it up.\""},{"text":"\"I am following up on last month's request. What happens next?\"","then":"\"Let me see,\" she says, and you hear her typing.","best":true},{"text":"\"Is the doctor there? I want to speak only to the doctor.\"","then":"\"The doctor is with a patient,\" she says flatly. \"I can look up your request.\""}],"why":"A polite, specific follow-up keeps a slow service moving."},{"prompt":"She says: \"I cannot find your request. Can you give me the details?\"","options":[{"text":"\"Of course. His name, date of birth and the date I applied.\"","then":"She types. \"Found it. It was filed under his father's name.\"","best":true},{"text":"\"You should have it. Please look properly this time.\"","then":"She sighs. \"I am looking, madam. Please give me a moment.\""},{"text":"\"I do not remember exactly. I will call again another day.\"","then":"\"Alright,\" she says. \"I will keep looking and call you back.\""},{"text":"\"It is all in the email. Can you check that yourself?\"","then":"\"I can try, but I do not have access,\" she says."}],"why":"Clear details make it easy for her to find his file and help you."},{"prompt":"A week later, she calls back and says: \"The soonest slot is in two months. Shall I book it?\"","options":[{"text":"\"Then never mind. We will manage on our own somehow, madam.\"","then":"\"As you wish,\" she says. Nothing moves for him."},{"text":"\"Book it, but I will not call again until that day comes.\"","then":"\"Fine,\" she says. Two months later there is a mix-up with the date."},{"text":"\"Yes, please book it. And add me to the cancellation list.\"","then":"\"Done,\" she says. \"If a slot opens, I will call you.\"","best":true},{"text":"\"Can you skip the queue for us if I pay something extra?\"","then":"\"That is not possible,\" she says. The call ends on a stiff note."}],"why":"Booking the slot and joining the cancellation list gets him seen as soon as possible."}],"relearn":"A polite, specific follow-up asking the next step and a timeline keeps a slow service moving, not stalling."},
  {"id":"nd-1032","cat":"advocate","type":"role-play","persona":"Meena","source":"reframe naughty","hook":"At the parent-teacher meeting, your son's teacher has a complaint.","setup":"She slides his notebook across the table.","steps":[{"prompt":"The teacher says: \"He is naughty and disruptive in class.\"","options":[{"text":"\"He is just badly behaved, I know. I will tell him off at home.\"","then":"She nods. At home he hears it and goes quiet."},{"text":"\"When he is overwhelmed he cannot sit still. Breaks help him.\"","then":"She looks at the notebook. \"Breaks. I can try that.\"","best":true},{"text":"\"Nonsense. My son is a very good boy, and you are wrong.\"","then":"She stiffens. \"I am only telling you what I see.\""},{"text":"\"He behaves at home. Maybe the problem is your classroom.\"","then":"Her face tightens. \"The other children manage fine.\""}],"why":"Reframing naughty as overwhelm, with concrete supports, gives her a plan."},{"prompt":"She says: \"Other children get distracted when he gets up.\"","options":[{"text":"\"Then keep him out of the class activities for now.\"","then":"She agrees. He spends the lesson at the back, alone."},{"text":"\"Then the others must learn to ignore it, madam.\"","then":"She frowns. \"That is not how a classroom works.\""},{"text":"\"I will ask him to sit still and try harder for you.\"","then":"She nods. He tries, and he is worn out by noon."},{"text":"\"Could he have a movement job, like handing out books?\"","then":"She considers. \"That could work. He could hand out notebooks.\"","best":true}],"why":"Giving his movement a purpose turns a disruption into a job."},{"prompt":"She asks: \"What should I do when he melts down?\"","options":[{"text":"\"Send him to the principal's room. That is the school rule.\"","then":"She nods. He sits in the principal's room, shaking."},{"text":"\"Give him a quiet spot and a moment. Talk after he is calm.\"","then":"She writes it down. \"A quiet spot first. Then talk. Alright.\"","best":true},{"text":"\"Ignore it until it stops. He only wants attention from you.\"","then":"She looks unsure. \"For a whole meltdown? In front of the class?\""},{"text":"\"Call me at once, and I will collect him each time.\"","then":"\"Every time?\" she says. \"It could be daily.\""}],"why":"A quiet place and a moment to calm keeps him safe and lets you talk later."}],"relearn":"Reframing 'naughty' as overwhelm plus concrete supports turns blame into a plan the teacher can use."},
  {"id":"nd-1033","cat":"advocate","type":"role-play","persona":"Priya","source":"brief the willing relative","hook":"Your brother offers to look after your son for an afternoon.","setup":"He waits by the door with his keys in his hand.","steps":[{"prompt":"Your brother says: \"Just tell me what to do with him.\"","options":[{"text":"\"He loves trains. Noise overwhelms him, so go somewhere quiet.\"","then":"He nods. \"Trains. Quiet. Got it.\" He makes a small note on his phone.","best":true},{"text":"\"You will not manage him. Maybe I should cancel my plans.\"","then":"His face falls. \"I offered because I want to help.\""},{"text":"\"Nothing special. Treat him like any other boy his age.\"","then":"\"Okay,\" he says. He puts on loud music in the car."},{"text":"\"Here is a long list of everything that upsets him.\"","then":"He scans it. \"That is a lot. Maybe I am not the right one.\""}],"why":"A short brief on his strengths and what calms him turns a willing relative into a helper."},{"prompt":"Your brother asks: \"What if he will not stop crying?\"","options":[{"text":"\"Then just call me straight away. I will come and collect him.\"","then":"\"Every time?\" he says. \"Then I have not really helped.\""},{"text":"\"Then tell him firmly to stop, and take his toy away if not.\"","then":"\"Alright.\" He tries it, and the crying gets louder."},{"text":"\"He may be overwhelmed. Take him somewhere quiet and stay near.\"","then":"He nods slowly. \"Quiet and near. I can do that.\"","best":true},{"text":"\"Give him some sweets or chocolate. That always works.\"","then":"He grins. \"Easy.\" Your son eats and keeps crying."}],"why":"A calm place and steady company help an overwhelmed child recover."},{"prompt":"Your brother asks: \"Can I take him to the temple fair?\"","options":[{"text":"\"Maybe a short visit at a quiet hour, with his headphones.\"","then":"He smiles. \"A short visit. I will go early, then.\"","best":true},{"text":"\"No. Nowhere with people. Keep him at home with you always.\"","then":"He looks disappointed. \"Then what are we going to do?\""},{"text":"\"Yes, of course. He will get used to it if he goes.\"","then":"\"Great!\" he says. He takes him at noon, at the height of the crowd."},{"text":"\"Ask his father. I am not sure what to say to you.\"","then":"\"Alright,\" he says, and the afternoon passes with no plan."}],"why":"A small plan with supports lets him try something new without being overwhelmed."},{"prompt":"Your brother says: \"He asked me to come again next week. Should I?\"","options":[{"text":"\"No, once was enough. He gets too excited with you.\"","then":"His face falls. \"I thought it went well.\""},{"text":"\"Yes, but only if you keep his toy trains away.\"","then":"He looks puzzled. \"But he loves them. Why hide them?\""},{"text":"\"Yes, please. Next time, let us plan the afternoon together.\"","then":"He grins. \"Deal. I will bring the train book he liked.\"","best":true},{"text":"\"Let us wait a month. I want to see how he handles it.\"","then":"He nods, a little hurt. The month drags by without a visit."}],"why":"Planning together makes him a regular helper, not a one-time visitor."}],"relearn":"A simple brief on strengths and what calms your child turns a willing relative into a real champion."},
  {"id":"nd-1034","cat":"advocate","type":"role-play","persona":"Meena","source":"hold the inclusion line","hook":"Your daughter's school would rather not adapt anything for her, and asks to meet.","setup":"The coordinator leans back with a polite smile.","steps":[{"prompt":"The coordinator says: \"She would be happier in a special school.\"","options":[{"text":"\"If you do not want her, we will take her away quietly.\"","then":"She nods. \"That might be easier for everyone.\""},{"text":"\"I will think it over and let you know next month.\"","then":"She nods. \"Of course.\" She pulls a transfer form from the file anyway."},{"text":"\"You cannot say that. I will go to the newspapers about this.\"","then":"Her smile vanishes. \"There is no need for threats.\""},{"text":"\"She is doing well here with friends. What would help her stay?\"","then":"Her smile fades. \"Hmm. She does have friends here. Let me think.\"","best":true}],"why":"Naming what is working and asking for support keeps a regular-school place open."},{"prompt":"She says: \"We do not have trained staff for this.\"","options":[{"text":"\"Then I will pay for a private teacher and say no more.\"","then":"She relaxes. The school keeps its distance and your daughter has one adult."},{"text":"\"What help would you need? I can bring her therapist's ideas.\"","then":"She pauses. \"Suggestions would help. Yes, bring them.\"","best":true},{"text":"\"That is the school's problem, not mine, madam.\"","then":"She stiffens. \"Then we are stuck,\" she says, and taps the file."},{"text":"\"I see. Then there is nothing more to discuss.\"","then":"She nods, then pauses. \"Perhaps we should not decide today.\""}],"why":"Asking what help the school needs, and offering some, turns a refusal into a plan."},{"prompt":"She says: \"Let us review after a term and see.\"","options":[{"text":"\"Fine. Whatever you decide after a term, I will accept.\"","then":"She smiles. \"Good. I will let you know.\" She writes nothing down."},{"text":"\"A term is too long. I want answers by next week.\"","then":"She frowns. \"Next week is not possible, madam.\""},{"text":"\"Let us see. I will not bring it up unless you do.\"","then":"She agrees and closes the file with no date set."},{"text":"\"Yes, and let us write down the supports and the date now.\"","then":"She takes out a page. \"Alright. Let us write it down.\"","best":true}],"why":"Writing supports and a date makes the review real and keeps her place."},{"prompt":"She adds: \"If we bring in a helper for her, other parents may object.\"","options":[{"text":"\"Then let us keep it secret from the other parents.\"","then":"She agrees. Parents guess, and the rumours are unkind."},{"text":"\"Let us explain it as help for the class. I can join a parent meeting.\"","then":"She thinks. \"A short meeting might ease things. Let us plan it.\"","best":true},{"text":"\"Then let them find another school for their children.\"","then":"She stiffens. \"That will not help anyone, madam.\""},{"text":"\"Then I will take her out before there is any fuss.\"","then":"She looks relieved. Your daughter loses her friends and her place."}],"why":"Helping other parents understand keeps her place and grows goodwill for all."}],"relearn":"Naming what's working and asking for inclusive support keeps a regular-school place on the table."},
  {"id":"nd-1035","cat":"advocate","type":"role-play","persona":"Vikram","source":"decline the cure clinic","hook":"Your cousin arrives excited about a clinic he saw advertised.","setup":"He holds out a glossy brochure at the door.","steps":[{"prompt":"Your cousin says: \"This clinic guarantees a cure. Book it today.\"","options":[{"text":"\"Maybe you are right. What is the harm? I will book it to be safe.\"","then":"He beams. \"Good. I will call them tonight.\""},{"text":"\"Stop pushing this rubbish. I am tired of your advice.\"","then":"His smile disappears. \"I only wanted to help.\""},{"text":"\"Thanks for caring. There is no cure, so we focus on real support.\"","then":"He looks surprised. \"No cure? They say otherwise, though.\"","best":true},{"text":"\"Leave the brochure. I will think about it later.\"","then":"He leaves it. It sits on the table, and the pressure stays."}],"why":"Thanking him while naming that there is no cure declines the clinic without a fight."},{"prompt":"He adds: \"They even showed videos of children who were cured.\"","options":[{"text":"\"Videos are not evidence. I will ask his doctor what helps.\"","then":"\"Hmm. His doctor,\" he says. \"I did not think to ask.\"","best":true},{"text":"\"Maybe some of them worked. I will try it for one month.\"","then":"\"That is the spirit,\" he says. You pay the first fee that day."},{"text":"\"Videos can be faked. You are a fool to believe them.\"","then":"His face flushes. \"I was only trying to help,\" he mutters."},{"text":"\"I cannot judge this. Please stop showing me things.\"","then":"\"Fine,\" he says. He puts his phone away, and the doubt stays."}],"why":"Asking a qualified professional beats videos, and it keeps the family kind."},{"prompt":"He asks: \"Apart from clinics, what are you doing for him?\"","options":[{"text":"\"Waiting to see if he grows out of it. Time will tell.\"","then":"He sighs. \"That is not much of a plan.\""},{"text":"\"That is private. I owe you no explanation, cousin.\"","then":"He shrugs, hurt, and leaves without another word."},{"text":"\"A therapist, a school plan and celebrating what he does well.\"","then":"He nods slowly. \"That sounds real. He does light up about trains.\"","best":true},{"text":"\"Trying diets and supplements we read about online.\"","then":"\"Ah, good, I have a list of those too,\" he says eagerly."}],"why":"Real support and celebrating his strengths is what helps him flourish."}],"relearn":"Thanking the relative while naming that there's no cure, only evidence-based support, declines quackery without conflict."},
  {"id":"nd-1036","cat":"advocate","type":"reflect","persona":"Meena","source":"a time you spoke up","hook":"Lensy: think of a time you spoke up for your child and it shifted something, even a little.","prompt":"What comes to mind?","options":["A meeting that went better","A teacher who finally understood","Just feeling braver next time"],"affirm":"Every time you speak up, you build the muscle, and you show your child they're worth standing up for.","relearn":"Each act of advocacy, however small, builds your confidence and shows your child they matter."},
  {"id":"nd-1037","cat":"advocate","type":"reflect","persona":"Divya","source":"make the meeting doable","hook":"Lensy: what would make the next school meeting feel a little more doable for you?","prompt":"What would help?","options":["Bringing my notes in a folder","Taking my partner along","Writing my main ask first"],"affirm":"There's no single right way; whatever steadies you, a folder, a person, a written ask, makes you a stronger advocate.","relearn":"Small preparations, notes, a companion or a written ask, make advocacy more doable and effective."},
  {"id":"nd-1038","cat":"advocate","type":"reflect","persona":"any","source":"who could champion too","hook":"Lensy: who could become another champion for your child if you let them in a little?","prompt":"Who comes to mind?","options":["My partner","A grandparent or aunt","A parent who gets it"],"affirm":"You needn't be the only one; every champion you let in doubles the people standing up for your child.","relearn":"Letting trusted people in builds a team of champions, so advocacy isn't yours to carry alone."},
  {"id":"nd-1039","cat":"advocate","type":"reflect","persona":"Meena","source":"name the worry","hook":"Lensy: when you imagine asking the school for support, what worry shows up first?","prompt":"What's the worry?","options":["Being seen as 'that parent'","Not knowing the right words","Hearing 'no' again"],"affirm":"That worry is normal and it doesn't make you wrong; even with it, asking for your child is worth it.","relearn":"Worries about advocating are normal; naming them helps you ask anyway, which is what your child needs."},
  {"id":"nd-1040","cat":"advocate","type":"reflect","persona":"Divya","source":"picture the good year","hook":"Lensy: picture the school year going well for your child. What support is in place?","prompt":"What do you see?","options":["A teacher who knows what helps","A few simple accommodations","Him feeling understood"],"affirm":"Whatever you pictured, that's the goal worth advocating toward, and naming it helps you ask for it.","relearn":"Picturing the support you want for your child clarifies exactly what to advocate for."},
  {"id":"nd-1041","cat":"advocate","type":"reflect","persona":"Divya","source":"refill between rounds","hook":"Lensy: after a hard meeting, how do you usually refill before the next round?","prompt":"What refills you?","options":["A friend who listens","A break for myself","Remembering why I do this"],"affirm":"Advocacy is a long road; refilling however works for you is part of staying able to keep championing your child.","relearn":"Looking after yourself between hard meetings is part of being able to keep advocating for your child."},
  {"id":"nd-1042","cat":"advocate","type":"reflect","persona":"Meena","source":"strength to lead with","hook":"Lensy: what's one strength of your child you'd want every new teacher to know first?","prompt":"What would you tell them?","options":["How focused he is on what he loves","How honest and kind he is","How he notices what others miss"],"affirm":"Leading with a strength changes how a teacher sees your child, and you're the one who can make sure they hear it.","relearn":"Leading your child's story with a strength shapes how teachers see and support them."},
  {"id":"nd-1043","cat":"advocate","type":"spot","persona":"any","source":"spot the giving-up lines","hook":"Spot the two red flags: lines that quietly give up your child's support.","scene":[{"id":"a","text":"\"Could we put the agreed plan in writing?\"","trick":false},{"id":"b","text":"\"Sorry to be a nuisance, forget I asked.\"","trick":true},{"id":"c","text":"\"What's our duty to include him here?\"","trick":false},{"id":"d","text":"\"If you say he's fine, I'll trust that.\"","trick":true},{"id":"e","text":"\"Whom should I speak to next?\"","trick":false}],"why":"Over-apologising and accepting 'he's fine' both surrender support; the other lines hold the ground calmly.","relearn":"Apologising your way out or accepting 'he's fine' give up support; writing it down and asking next steps hold the ground."},
  {"id":"nd-1044","cat":"advocate","type":"spot","persona":"any","source":"spot the quackery","hook":"Spot the two red flags: 'support' offers that are quackery or harm.","scene":[{"id":"a","text":"A qualified professional assessment","trick":false},{"id":"b","text":"A clinic 'guaranteeing a full autism cure'","trick":true},{"id":"c","text":"A visual schedule and movement breaks","trick":false},{"id":"d","text":"\"Strict beatings will fix his ADHD\"","trick":true},{"id":"e","text":"Exam concessions with a report","trick":false}],"why":"A guaranteed 'cure' and 'beatings fix ADHD' are quackery and harm; the rest are real, evidence-based support.","relearn":"Guaranteed 'cures' and punishment are quackery; assessment, visual schedules and exam concessions are real support."},
  {"id":"nd-1045","cat":"advocate","type":"spot","persona":"any","source":"spot the shaming responses","hook":"Spot the two red flags: family responses that shame your child.","scene":[{"id":"a","text":"\"Let's learn what calms him together.\"","trick":false},{"id":"b","text":"\"Beat the stimming out of her, it's rude.\"","trick":true},{"id":"c","text":"\"I'll take him somewhere quiet when it's loud.\"","trick":false},{"id":"d","text":"\"Hide it or no one will marry him.\"","trick":true},{"id":"e","text":"\"Tell me his strengths so I can cheer him.\"","trick":false}],"why":"Punishing stimming and hiding the diagnosis both shame the child; the others offer real understanding.","relearn":"Beating out stimming or hiding the diagnosis shame your child; learning what calms them and naming strengths support them."},
  {"id":"nd-1046","cat":"advocate","type":"spot","persona":"any","source":"spot the handover gaps","hook":"Spot the two red flags: things that make a teacher handover lose support.","scene":[{"id":"a","text":"Sharing the plan with the new teacher","trick":false},{"id":"b","text":"Assuming the school passed it on","trick":true},{"id":"c","text":"Giving a one-page strengths note","trick":false},{"id":"d","text":"Waiting to see if she struggles first","trick":true},{"id":"e","text":"Asking to review the plan together","trick":false}],"why":"Assuming a handover happened and waiting for problems both let the plan lapse; the rest keep support continuous.","relearn":"Assuming the plan was passed on or waiting for struggles loses support; share it and review it together to keep it."},
  {"id":"nd-1047","cat":"advocate","type":"spot","persona":"any","source":"spot the door-closing replies","hook":"Spot the two red flags: replies to a 'no' that end your child's chances.","scene":[{"id":"a","text":"\"Could we revisit this in writing?\"","trick":false},{"id":"b","text":"\"Then there's nothing to be done.\"","trick":true},{"id":"c","text":"\"Whom can I approach next?\"","trick":false},{"id":"d","text":"\"You're right, I'll stop pushing.\"","trick":true},{"id":"e","text":"\"What would change your answer?\"","trick":false}],"why":"\"Nothing to be done\" and \"I'll stop pushing\" treat one 'no' as final; the rest keep the door open.","relearn":"Treating a 'no' as final ends your child's chances; revisiting in writing and asking whom to see next keep the door open."},
  {"id":"nd-1048","cat":"advocate","type":"spot","persona":"any","source":"spot the spoiling framing","hook":"Spot the two red flags: framings of accommodations to push back on.","scene":[{"id":"a","text":"\"It's fair access, like glasses.\"","trick":false},{"id":"b","text":"\"Extra time just spoils him.\"","trick":true},{"id":"c","text":"\"It lets him show what he knows.\"","trick":false},{"id":"d","text":"\"Headphones are pandering, toughen up.\"","trick":true},{"id":"e","text":"\"It levels the ground, it's no edge.\"","trick":false}],"why":"\"Spoils him\" and \"pandering, toughen up\" wrongly cast fair access as indulgence; the rest frame it as leveling the ground.","relearn":"Calling accommodations 'spoiling' or 'pandering' is wrong; they're fair access that levels the ground, like glasses."},
  {"id":"nd-1049","cat":"advocate","type":"spot","persona":"any","source":"spot the burnout patterns","hook":"Spot the two red flags: ways of carrying advocacy that burn you out.","scene":[{"id":"a","text":"Bringing your partner to the meeting","trick":false},{"id":"b","text":"Doing every meeting alone, every time","trick":true},{"id":"c","text":"Leaning on a parent group for tips","trick":false},{"id":"d","text":"Refusing all offers of help on principle","trick":true},{"id":"e","text":"Sharing the load with a co-parent","trick":false}],"why":"Always going solo and refusing help drain you until advocacy stalls; the rest sustain it.","relearn":"Doing it all alone and refusing help burn you out; sharing meetings and leaning on others sustain your advocacy."},
  {"id":"nd-1080","cat":"drop-the-shame","type":"strike-rewrite","hook":"\"Too much mobile and TV gave my child autism.\"","myth":{"un":"Too much mobile and TV gave my child autism.","re":"Screen time doesn't cause autism or ADHD; your child was born wired this way, screens or no screens.","why":"Correlation in tired homes isn't a cause."},"relearn":"Screens didn't cause your child's neurodivergence; it's how they were wired from the start.","persona":"Meena","source":"not screens"},
  {"id":"nd-1081","cat":"drop-the-shame","type":"strike-rewrite","hook":"\"It's my karma, or some past-life sin, coming back through my child.\"","myth":{"un":"It's my karma, or some past-life sin, coming back through my child.","re":"Neurodivergence is not punishment, karma or a curse; it's simply a different way a brain is wired.","why":"A wiring difference carries no blame or sin."},"relearn":"Your child's neurodivergence is no curse or karma; it's just how their brain is wired.","persona":"Meena","source":"not karma"},
  {"id":"nd-1082","cat":"drop-the-shame","type":"strike-rewrite","hook":"\"A working mother who isn't home enough makes children like this.\"","myth":{"un":"A working mother who isn't home enough makes children like this.","re":"No mother's job, absence or 'cold' parenting causes neurodivergence; that old blame has been thoroughly debunked.","why":"Wiring isn't set by a mother's schedule."},"relearn":"Working or being away didn't cause your child's neurodivergence; that mother-blaming idea is a debunked myth.","persona":"Meena","source":"not working mother"},
  {"id":"nd-1083","cat":"drop-the-shame","type":"strike-rewrite","hook":"\"Vaccines must have triggered my child's condition.\"","myth":{"un":"Vaccines must have triggered my child's condition.","re":"Vaccines do not cause autism; that claim came from fraud and has been disproven again and again.","why":"The original study was retracted as fraudulent."},"relearn":"Vaccines didn't cause your child's neurodivergence; that link was a fraud and has been disproven.","persona":"any","source":"not vaccines"},
  {"id":"nd-1084","cat":"drop-the-shame","type":"strike-rewrite","hook":"\"My diet in pregnancy, or eating the wrong things, caused this.\"","myth":{"un":"My diet in pregnancy, or eating the wrong things, caused this.","re":"What you ate in pregnancy didn't cause your child's neurodivergence; you did nothing wrong to bring it about.","why":"Self-blame over food is misplaced guilt."},"relearn":"Your pregnancy diet didn't cause this; there's no food choice you could have made to prevent your child's wiring.","persona":"Divya","source":"not diet"},
  {"id":"nd-1085","cat":"drop-the-shame","type":"strike-rewrite","hook":"\"A special diet or supplement will cure the autism.\"","myth":{"un":"A special diet or supplement will cure the autism.","re":"No diet, supplement or detox cures neurodivergence; people selling 'cures' are selling false hope, not help.","why":"There's no cure to buy, only support that helps."},"relearn":"No diet or supplement cures neurodivergence; beware anyone selling a 'cure'. Support, not a cure, helps your child.","persona":"any","source":"no cure to buy"},
  {"id":"nd-1086","cat":"drop-the-shame","type":"strike-rewrite","hook":"\"If I'd been stricter, my child would behave like the others.\"","myth":{"un":"If I'd been stricter, my child would behave like the others.","re":"Stricter discipline doesn't fix neurodivergence; meltdowns are overwhelm, and punishment only adds fear.","why":"You can't discipline a wiring difference away."},"relearn":"Being stricter wouldn't have changed your child's wiring; meltdowns are overwhelm, not a discipline failure.","persona":"Vikram","source":"not strictness"},
  {"id":"nd-1087","cat":"drop-the-shame","type":"strike-rewrite","hook":"\"My child stims and rocks because we failed to train it out of him.\"","myth":{"un":"My child stims and rocks because we failed to train it out of him.","re":"Stimming is self-soothing, not a failure to train; it calms your child and isn't something to shame out of them.","why":"Self-soothing is a need, not bad behaviour."},"relearn":"Stimming is your child soothing themselves, not your failure; it's not shameful and needn't be trained away.","persona":"Meena","source":"stimming not failure"},
  {"id":"nd-1088","cat":"drop-the-shame","type":"strike-rewrite","hook":"\"A diagnosis is a tragedy that ruins a child's whole future.\"","myth":{"un":"A diagnosis is a tragedy that ruins a child's whole future.","re":"A diagnosis is a key to the right support, not a tragedy or a verdict; your child is the same child the day after.","why":"A name opens doors; it doesn't close them."},"relearn":"A diagnosis is a key to support, not a tragedy; your child is unchanged by the label and their future is open.","persona":"Meena","source":"key not tragedy"},
  {"id":"nd-1090","cat":"drop-the-shame","type":"strike-rewrite","hook":"\"My child is a burden I'm being punished with.\"","myth":{"un":"My child is a burden I'm being punished with.","re":"Your child is a whole, wonderful person, not a punishment or a burden; the heavy part is the stigma, not the child.","why":"The weight is society's judgement, not your child."},"relearn":"Your child isn't a burden or a punishment; they're a whole person, and the weight you feel is stigma, not them.","persona":"Meena","source":"not a burden"},
  {"id":"nd-1091","cat":"drop-the-shame","type":"strike-rewrite","hook":"\"I should have caught this sooner; the late diagnosis is my failure.\"","myth":{"un":"I should have caught this sooner; the late diagnosis is my failure.","re":"A late diagnosis is common and isn't your failure; you acted the moment you understood, and that's what counts.","why":"You can only act on what you've come to know."},"relearn":"A late diagnosis isn't a failure; signs are easy to miss, and acting once you understood is exactly the right thing.","persona":"Divya","source":"late not failure"},
  {"id":"nd-1092","cat":"drop-the-shame","type":"strike-rewrite","hook":"\"My child's meltdown in public showed everyone I can't control him.\"","myth":{"un":"My child's meltdown in public showed everyone I can't control him.","re":"A public meltdown is overwhelm spilling over, not proof of bad parenting; you're supporting a child, not failing to control one.","why":"Strangers' stares aren't evidence of anything."},"relearn":"A public meltdown is overwhelm, not proof you can't parent; you're helping an overloaded child, not failing.","persona":"Meena","source":"public meltdown"},
  {"id":"nd-1094","cat":"drop-the-shame","type":"strike-rewrite","hook":"\"Sharing his diagnosis with the school will mark him for life.\"","myth":{"un":"Sharing his diagnosis with the school will mark him for life.","re":"Sharing on your terms unlocks support and understanding; secrecy is what isolates a child and feeds the stigma.","why":"Hiding protects the shame, not the child."},"relearn":"Telling school on your own terms opens support; hiding the diagnosis isolates your child and feeds stigma.","persona":"Vikram","source":"openness unlocks support"},
  {"id":"nd-1095","cat":"drop-the-shame","type":"sort","hook":"Sort each line: a fact that lifts the shame, or a blame myth that piles it on.","items":[{"id":"a","text":"\"It's no one's fault, least of all yours\""},{"id":"b","text":"\"Screen time gave him autism\""},{"id":"c","text":"\"With support, your child can flourish\""},{"id":"d","text":"\"A good family hides such things\""},{"id":"e","text":"\"A diagnosis is a key to support\""},{"id":"f","text":"\"It's your karma coming back\""}],"bins":[{"id":"lifts","label":"Lifts shame","valence":"pos"},{"id":"piles","label":"Piles on blame","valence":"neg"}],"key":{"a":"lifts","b":"piles","c":"lifts","d":"piles","e":"lifts","f":"piles"},"relearn":"'No one's fault', 'can flourish' and 'a key to support' lift shame; screens, karma and 'hide it' are blame myths.","persona":"any","source":"lifts vs piles"},
  {"id":"nd-1096","cat":"drop-the-shame","type":"sort","hook":"Sort: which of these is true and steadying, and which is a debunked cause-myth?","items":[{"id":"a","text":"Neurodivergence is lifelong, not a phase"},{"id":"b","text":"Vaccines triggered it"},{"id":"c","text":"It's how the brain is wired"},{"id":"d","text":"Bad parenting caused it"},{"id":"e","text":"Support helps a child thrive"},{"id":"f","text":"A special detox can cure it"}],"bins":[{"id":"true","label":"True","valence":"pos"},{"id":"myth","label":"Debunked myth","valence":"neg"}],"key":{"a":"true","b":"myth","c":"true","d":"myth","e":"true","f":"myth"},"relearn":"Lifelong wiring and support that helps are true; vaccines, bad parenting and 'detox cures' are debunked myths.","persona":"any","source":"true vs debunked"},
  {"id":"nd-1097","cat":"drop-the-shame","type":"sort","hook":"A meltdown happens. Sort each thought: shame-talk that traps you, or a kind truth that frees you.","items":[{"id":"a","text":"\"Everyone's judging my parenting\""},{"id":"b","text":"\"He's overwhelmed and needs me calm\""},{"id":"c","text":"\"This proves I've failed\""},{"id":"d","text":"\"Strangers' stares aren't the truth\""},{"id":"e","text":"\"I should be ashamed in public\""},{"id":"f","text":"\"My job is to help him feel safe\""}],"bins":[{"id":"shame","label":"Shame-talk","valence":"neg"},{"id":"kind","label":"Kind truth","valence":"pos"}],"key":{"a":"shame","b":"kind","c":"shame","d":"kind","e":"shame","f":"kind"},"relearn":"'Everyone's judging' and 'I've failed' are shame-talk; 'he's overwhelmed' and 'help him feel safe' are kind truths.","persona":"Meena","source":"shame-talk vs truth"},
  {"id":"nd-1098","cat":"drop-the-shame","type":"sort","hook":"Sort: which words shield your child from blame, and which quietly hand them shame?","items":[{"id":"a","text":"\"It's no one's fault, you're wonderful\""},{"id":"b","text":"\"See, you've embarrassed us again\""},{"id":"c","text":"\"Your brain just works differently\""},{"id":"d","text":"\"Why can't you be normal?\""},{"id":"e","text":"\"I'm proud of how you tried\""},{"id":"f","text":"\"Don't tell anyone about this\""}],"bins":[{"id":"shield","label":"Shields the child","valence":"pos"},{"id":"hands","label":"Hands them shame","valence":"neg"}],"key":{"a":"shield","b":"hands","c":"shield","d":"hands","e":"shield","f":"hands"},"relearn":"'No one's fault' and 'I'm proud you tried' shield your child; 'be normal' and 'don't tell anyone' hand them shame.","persona":"Meena","source":"shield vs hand shame"},
  {"id":"nd-1099","cat":"drop-the-shame","type":"sort","hook":"A relative offers 'cures'. Sort: a quack promise to refuse, or a real support to lean on.","items":[{"id":"a","text":"A miracle detox to 'fix' him"},{"id":"b","text":"A qualified professional assessment"},{"id":"c","text":"A faith-healer's 'cure'"},{"id":"d","text":"A peer parent support group"},{"id":"e","text":"Drops that 'remove' autism"},{"id":"f","text":"Tele-MANAS 14416 for guidance"}],"bins":[{"id":"quack","label":"Quack promise","valence":"neg"},{"id":"real","label":"Real support","valence":"pos"}],"key":{"a":"quack","b":"real","c":"quack","d":"real","e":"quack","f":"real"},"relearn":"Detoxes, faith-cures and 'autism-removing drops' are quackery; a professional, a peer group and Tele-MANAS are real support.","persona":"any","source":"quack vs real"},
  {"id":"nd-1100","cat":"drop-the-shame","type":"sort","hook":"Lensy: sort the grief work. Which moves you forward, and which keeps you stuck in guilt?","items":[{"id":"a","text":"Letting yourself feel the sadness"},{"id":"b","text":"Replaying 'what did I do wrong?'"},{"id":"c","text":"Refocusing on the child here now"},{"id":"d","text":"Punishing yourself with what-ifs"},{"id":"e","text":"Naming that it's no one's fault"},{"id":"f","text":"Carrying guilt silently for years"}],"bins":[{"id":"forward","label":"Moves forward","valence":"pos"},{"id":"stuck","label":"Keeps you stuck","valence":"neg"}],"key":{"a":"forward","b":"stuck","c":"forward","d":"stuck","e":"forward","f":"stuck"},"relearn":"Feeling the grief, refocusing on your child and 'no one's fault' move you forward; what-ifs and silent guilt keep you stuck.","persona":"Divya","source":"grief forward vs stuck"},
  {"id":"nd-1101","cat":"drop-the-shame","type":"reflect","hook":"Lensy: a diagnosis is a key to support, not a verdict on your child. Does that land?","prompt":"What do you feel?","options":["It lands","A key, not a verdict","Same child tomorrow"],"affirm":"A diagnosis is information and a key to the right support, not a tragedy or a verdict; your child is unchanged by it.","relearn":"A diagnosis is a key to support, not a verdict; your child is the same wonderful child the day after.","persona":"Meena","source":"key not verdict"},
  {"id":"nd-1102","cat":"drop-the-shame","type":"reflect","hook":"Lensy: you can grieve the path you imagined and still love the child in front of you. True for you?","prompt":"Sit with that.","options":["True for me","Grief is allowed","Love them as they are"],"affirm":"Allowing the grief and dropping the guilt are both okay; you can mourn your expectations and fully love your real child.","relearn":"You're allowed the grief and free of the guilt; love the child you have, exactly as they are.","persona":"Divya","source":"grief and love"},
  {"id":"nd-1103","cat":"drop-the-shame","type":"reflect","hook":"Lensy: the stares of strangers in a market are not the truth about your child. Agree?","prompt":"What's your take?","options":["Agree","Stares aren't truth","I know my child"],"affirm":"A stranger's judgement during a meltdown is their misunderstanding, not a verdict on you or your wonderful child.","relearn":"Strangers' stares aren't the truth; a meltdown is overwhelm, and you know your child far better than they do.","persona":"Meena","source":"stares not truth"},
  {"id":"nd-1104","cat":"drop-the-shame","type":"reflect","hook":"Lensy: you didn't cause this, and you don't owe anyone an apology for your child. Feel right?","prompt":"How does that sit?","options":["Feels right","No apology owed","Not my fault"],"affirm":"You caused nothing and owe no apology; over-saying sorry for your child quietly accepts a blame that was never yours.","relearn":"You didn't cause it and owe no apology; constant sorrys hand you a blame that was never yours to carry.","persona":"Meena","source":"no apology owed"},
  {"id":"nd-1105","cat":"drop-the-shame","type":"reflect","hook":"Lensy: the energy you spend on shame could go to understanding your child instead. Worth a try?","prompt":"What do you think?","options":["Worth a try","Redirect the energy","Understand, not blame"],"affirm":"Shame and blame help no one; the same energy, turned toward understanding and championing your child, changes everything.","relearn":"Shame helps no one; spend that energy on understanding your child instead, and it goes much further.","persona":"Meena","source":"redirect energy"},
  {"id":"nd-1106","cat":"drop-the-shame","type":"reflect","hook":"Lensy: you don't have to be a perfect parent, just a loving, learning one. Does that ease it?","prompt":"Take a breath.","options":["It eases it","Learning is enough","Loving, not perfect"],"affirm":"You don't have to be perfect or all-knowing; a learning, loving parent is exactly what your child needs.","relearn":"You needn't be perfect; a loving, learning parent is exactly what your child needs, and that's enough.","persona":"Divya","source":"loving not perfect"},
  {"id":"nd-1107","cat":"drop-the-shame","type":"reflect","hook":"Lensy: when a relative says 'fix him', remember there's nothing broken to fix. Hold that?","prompt":"What's your feeling?","options":["I'll hold it","Nothing's broken","Difference, not defect"],"affirm":"There is nothing broken in your child to fix; they're wired differently, not wrongly, and they're whole exactly as they are.","relearn":"There's nothing broken to fix; your child is different, not defective, and whole as they are.","persona":"Meena","source":"nothing to fix"},
  {"id":"nd-1108","cat":"drop-the-shame","type":"reflect","hook":"Lensy: telling one trusted person can lift a weight you've carried alone. Ready to consider it?","prompt":"Sit with it.","options":["I'll consider it","Sharing lifts weight","Not alone"],"affirm":"Openness on your own terms, even with just one trusted person, lets support in and lightens the shame you've carried alone.","relearn":"Sharing on your terms, even with one trusted person, lets support in and lifts the weight of carrying it alone.","persona":"Vikram","source":"sharing lifts weight"},
  {"id":"nd-1109","cat":"drop-the-shame","type":"branch","persona":"Meena","source":"correct the slur","hook":"At a family function, an uncle loudly calls your son 'mad' in front of everyone.","steps":[{"prompt":"Heads turn and your son freezes beside you. What do you do?","options":[{"text":"Say calmly that his brain works differently","then":"The uncle blinks. Your son's shoulders drop a little as you take his hand.","best":true},{"text":"Say nothing and hope no one noticed","then":"The moment passes. Your son stares at the floor, having heard every word."},{"text":"Laugh it off as Uncle's usual joke","then":"A few people laugh along. Your son doesn't."},{"text":"Tell the uncle loudly that he should be ashamed","then":"The hall goes quiet. Your son covers his ears, now at the centre of a bigger scene."}],"why":"A calm correction shows your son the label is not his, without a scene."},{"prompt":"Later, your son asks quietly if he is mad. What do you say?","options":[{"text":"Tell him he is not mad and his brain works differently","then":"He leans into you and asks what different means. You begin to explain.","best":true},{"text":"Say Uncle didn't mean it and change the subject","then":"He nods slowly. The question stays with him."},{"text":"Tell him to ignore Uncle and promise to explain another day","then":"He nods. Days pass and the word still sits with him."},{"text":"Say it's only a word and he is too sensitive","then":"He goes quiet and stops asking."}],"why":"A child needs to hear that he is whole, and why his brain works differently."},{"prompt":"At the next gathering, the uncle asks what is 'wrong' with your son. What do you do?","options":[{"text":"Explain briefly and invite him to spend time with your son","then":"The uncle listens, looking awkward. \"I didn't know,\" he says.","best":true},{"text":"Say \"nothing\" and walk away","then":"The uncle shrugs, then tells others it must be something serious."},{"text":"Ask your husband to deal with the uncle","then":"Your husband mumbles something vague. The uncle leaves no wiser."},{"text":"Give him a long lecture on everything he has got wrong","then":"The uncle goes red and stops listening. Others overhear and look away."}],"why":"A short, calm explanation turns a critic into someone who understands."}],"debrief":"Correct cruel labels calmly and protect your child; the blame was never theirs to wear.","relearn":"When someone shames your child, correct it calmly and shield them; it's no one's fault."},
  {"id":"nd-1110","cat":"drop-the-shame","type":"branch","persona":"any","source":"refuse cure seller","hook":"A relative forwards you an advert from a man calling himself a 'doctor', selling a costly autism 'cure'.","steps":[{"prompt":"The message has a payment link and many forwards. What do you do?","options":[{"text":"Politely decline and stay with your professional","then":"He sends a thumbs up and a second forward. You archive both.","best":true},{"text":"Pay the advance, just in case it works","then":"The payment goes through. Then the clinic asks for a much bigger sum before it will start."},{"text":"Send your partner the link and ask whether to pay","then":"Your partner is as unsure as you are. Nobody with training has seen it yet."},{"text":"Reply in the family group with an angry lecture","then":"The group goes quiet. Your relative replies, stung, that he was only trying to help."}],"why":"There is no cure to buy, and a polite no protects your money and your child."},{"prompt":"Days later, your relative calls. \"My friend's son improved on it,\" he says. What do you say?","options":[{"text":"Thank him and say you rely on your professional","then":"He sighs. \"I only wanted to help,\" he says, and lets it go.","best":true},{"text":"Say you'll think about it, to avoid an argument","then":"He takes it as a yes and forwards the next payment link."},{"text":"Ask for the clinic's number to look into it yourself","then":"He sends it gladly. The clinic's assistant phones you within the hour with an offer."},{"text":"Tell him he thinks your child is broken","then":"He is stung and denies it. The call ends stiffly."}],"why":"Thanking him keeps the bond, and naming your professional closes the door on false hope."},{"prompt":"Weeks on, another 'miracle therapy' ad appears in the group with your name tagged. What do you do?","options":[{"text":"Say you follow your professional, then mute the thread","then":"A few people react with hearts. The forwards begin to slow.","best":true},{"text":"Buy a small trial pack, just to be on the safe side","then":"The parcel arrives with no ingredients listed. It sits unopened on a shelf."},{"text":"Say you'll consider it after the next appointment","then":"Someone replies with a discount code. The offer keeps coming back."},{"text":"Post a long reply disproving every claim in the ad","then":"Replies pile up overnight. You spend your evening defending your child."}],"why":"Trusting your professional over a sales pitch keeps your child's care steady."}],"debrief":"There's no cure to buy; refuse the sellers and lean on real support and a professional.","relearn":"You can't 'cure' neurodivergence; refuse the sellers and trust real support, not false hope."},
  {"id":"nd-1111","cat":"drop-the-shame","type":"branch","persona":"Meena","source":"not nazar","hook":"Your mother-in-law believes your son's diagnosis comes from 'nazar', the evil eye.","steps":[{"prompt":"She asks you to keep it quiet so no one's nazar falls on him. What do you say?","options":[{"text":"Say gently it isn't nazar and you won't hide him","then":"She is silent, then says she only fears for him.","best":true},{"text":"Agree to hide it, to keep the peace","then":"She relaxes. You feel a small weight settle on your chest."},{"text":"Say she is being old-fashioned and superstitious","then":"Her face closes. She leaves the room and stays quiet for days."},{"text":"Nod, and plan to tell people without her knowing","then":"She thinks you agree. The secret now sits between you."}],"why":"Naming it kindly keeps the peace and the truth together."},{"prompt":"At the next family dinner, she asks what you will tell the neighbours. What do you say?","options":[{"text":"Say you'll tell those who help, and invite her in","then":"She thinks it over. \"I only worry what they'll say to him,\" she says.","best":true},{"text":"Say he is just shy, and change the subject fast","then":"She approves. Your son hears you explain him away."},{"text":"Ask your husband to sort it out with her later","then":"He changes the subject. Nothing is settled, and she watches you."},{"text":"Say nothing and leave the table without a word","then":"The room falls quiet. She is left with her worry and no answer."}],"why":"Sharing with people who help, and asking her in, gives her a role beyond fear."},{"prompt":"Her friend visits and calls your son's behaviour strange, and your mother-in-law looks at you. What do you do?","options":[{"text":"Answer calmly, naming his strengths and needs","then":"Her friend nods. Your mother-in-law pours the tea and says nothing against you.","best":true},{"text":"Wait for your mother-in-law to speak for him","then":"She says he has had nazar. Her friend offers a remedy while he listens."},{"text":"Say he has had a little nazar, to end the talk","then":"Her friend nods wisely. Your son sits on the floor, having heard it all."},{"text":"Take your son out of the room without a word","then":"The room stays tense. Nobody learns anything about him."}],"why":"Speaking for your son yourself shows your family what he needs, and what he is good at."}],"debrief":"It's not nazar and nothing to hide; refuse secrecy kindly and keep his life in the open.","relearn":"Neurodivergence isn't an evil eye to hide; secrecy feeds shame, openness lets support in."},
  {"id":"nd-1112","cat":"drop-the-shame","type":"branch","persona":"Divya","source":"repair and forgive","hook":"You snapped at your son mid-meltdown, and now the guilt is sinking in.","steps":[{"prompt":"The meltdown has passed and he sits quietly on his bed. What do you do?","options":[{"text":"Breathe, sit beside him, and tell him you're sorry","then":"He leans against you and says okay in a small voice.","best":true},{"text":"Act as if nothing happened and offer a snack","then":"He eats quietly. The shout hangs in the room."},{"text":"Tell him how his screaming made you shout","then":"He looks down and says sorry, though he isn't sure what for."},{"text":"Ask his father to go in and comfort him instead","then":"His father sits with him. You stay in the kitchen while the guilt grows."}],"why":"A quick repair tells him the shout was yours to own, not his fault."},{"prompt":"That night, you lie awake as the guilt returns. What do you do?","options":[{"text":"Remind yourself one snap isn't the whole of you","then":"The thoughts slow. Sleep comes late, but it comes.","best":true},{"text":"Replay every hard moment of the past month","then":"By 3 am you have a long list and no plan."},{"text":"Text a friend to ask her to say you're a good mother","then":"She replies with hearts. It feels warm for a minute, then doubt returns."},{"text":"Vow never to lose your patience again","then":"The vow feels firm at midnight. By breakfast it already feels heavy."}],"why":"One hard moment doesn't define you, and rest gives you patience for tomorrow."},{"prompt":"A week later, another meltdown starts and your voice begins to rise. What do you do?","options":[{"text":"Breathe, lower your voice, and stay close","then":"The storm is loud, but it fades sooner, and he ends up against your shoulder.","best":true},{"text":"Walk out of the room until he has stopped crying","then":"He cries louder alone. The wave lasts longer."},{"text":"Raise your voice to match his and get through","then":"His screaming climbs. He covers his ears and backs into a corner."},{"text":"Warn him calmly that he will lose screen time","then":"He can't seem to take it in. The screaming goes on."}],"why":"Staying calm and close helps his wave pass, and keeps you both safe."}],"debrief":"Repair after a hard moment and drop the guilt; a loving, learning parent is what your child needs.","relearn":"Snapping once doesn't make you a bad parent; reconnect, forgive yourself, keep learning."},
  {"id":"nd-1113","cat":"drop-the-shame","type":"branch","persona":"Meena","source":"screens dont cause it","hook":"On the stairs, neighbours whisper that 'screen time' made your daughter this way.","steps":[{"prompt":"Your daughter hears them and looks up at you. What do you do?","options":[{"text":"Tell them plainly screens don't cause it, then reassure her","then":"The neighbours look away, embarrassed. Your daughter's grip on your hand loosens.","best":true},{"text":"Take her phone away, to look like a good parent","then":"The neighbours nod approvingly. Your daughter decides it must have been her fault."},{"text":"Pretend you didn't hear and walk on","then":"The whispers follow you down the stairs. Your daughter grips your hand tighter."},{"text":"Correct them firmly, then walk on without a word to her","then":"The neighbours fall silent. Your daughter wonders if they were right anyway."}],"why":"Correcting the myth and reassuring her shows her it was never her fault."},{"prompt":"That evening she asks if her screen time made her different. What do you say?","options":[{"text":"Tell her it isn't screens and it's no one's fault","then":"Her shoulders loosen. \"Then why am I like this?\" she asks, and you begin to explain.","best":true},{"text":"Say a little less screen time can't hurt","then":"She nods and hands over her tablet, looking smaller."},{"text":"Tell her not to worry about what people say","then":"She says okay but keeps looking at her hands."},{"text":"Say you'll ask the doctor whether screens caused it","then":"She waits days for the answer, wondering all the while if she caused it."}],"why":"A child needs the plain truth that this is not her doing."},{"prompt":"Her cousin visits and repeats the screen story to her face. What do you do?","options":[{"text":"Say calmly it isn't screens, then put an arm around her","then":"The cousin mumbles a sorry. Your daughter leans into you.","best":true},{"text":"Change the subject and offer the cousin tea","then":"The tea comes. Your daughter hears the story go unchallenged."},{"text":"Ask your daughter to tell her cousin what she thinks","then":"Your daughter goes red and can't find words. The cousin shrugs."},{"text":"Tell the cousin off sharply and send her home","then":"The cousin leaves in a huff. Your daughter feels she caused the fight."}],"why":"Correcting the myth yourself keeps the burden off your daughter."}],"debrief":"Screens don't cause neurodivergence; correct the myth and shield your child from it.","relearn":"Screens didn't cause it; correct that blame so your child never wears a fault not theirs."},
  {"id":"nd-1114","cat":"drop-the-shame","type":"branch","persona":"Meena","source":"blame to plan","hook":"At a school meeting, a teacher asks what you did at home to make your son like this.","steps":[{"prompt":"The other staff wait for your answer. What do you say?","options":[{"text":"Say it's no one's fault and ask what he needs","then":"The room shifts. The teacher opens her notebook and asks what usually helps him.","best":true},{"text":"Apologise and promise to try harder at home","then":"Heads nod. You leave with a long list of promises and no help for him."},{"text":"Ask the teacher to be careful with her words","then":"She looks embarrassed. The meeting stalls without a plan for him."},{"text":"Say you did nothing and walk out of the meeting","then":"You leave shaking. The school phones again the following week."}],"why":"Saying it's no one's fault moves the room from blame to a plan."},{"prompt":"The school offers a second meeting to plan for your son. What do you bring?","options":[{"text":"Notes on what helps him and two clear requests","then":"The teacher writes both down and agrees to try a quiet corner and warnings before changes.","best":true},{"text":"A list of everything the school has done wrong","then":"The staff grow defensive and the hour goes on arguing about the past."},{"text":"Nothing, and hope they suggest something","then":"The teacher suggests general rules that don't fit him. You nod and leave."},{"text":"A doctor's report only, with no requests","then":"They read it politely and say they will keep it in mind."}],"why":"Clear notes and specific requests give the school something to act on."},{"prompt":"A month on, a teacher still scolds him for getting upset when plans change. What do you do?","options":[{"text":"Email the teacher a specific example and a request","then":"She replies within a day, and you agree on a signal he can use.","best":true},{"text":"Give up, since they clearly won't listen","then":"The scolding continues. Your son starts saying he hates school."},{"text":"Wait until the next term's meeting to raise it","then":"Weeks pass and he is scolded again, more than once."},{"text":"Scold your son at home to avoid more trouble","then":"He grows quiet at home and dreads the school gate."}],"why":"Specific, written examples keep you working with the teacher, not against her."}],"debrief":"You didn't cause it; deflect the blame and steer toward the accommodations he needs.","relearn":"When blamed for your child's wiring, say it's no one's fault and refocus on support."},
  {"id":"nd-1115","cat":"drop-the-shame","type":"branch","persona":"Vikram","source":"share on your terms","hook":"Since your child's diagnosis, your partner Sneha has been anxious about what relatives will say.","steps":[{"prompt":"Sneha says it will be easier if no one knows. What do you say?","options":[{"text":"Ask what worries her, then suggest safe people","then":"Sneha admits she fears the whispers. She agrees to think about a few names.","best":true},{"text":"Agree to total secrecy, to avoid a fight","then":"Sneha relaxes. You both start watching what you say in front of others."},{"text":"Tell her hiding it means she is ashamed of your child","then":"Sneha's eyes fill. \"That's not fair,\" she says, and leaves the room."},{"text":"Tell your parents anyway without asking her","then":"Your mother is glad to know. When Sneha finds out, she says nothing for two days."}],"why":"Listening to her fear first makes it easier to choose together who to tell."},{"prompt":"At a family dinner, your aunt asks why your child sees a therapist. What do you say?","options":[{"text":"Say your child gets support that helps, and leave it there","then":"Aunty nods. \"Whatever helps,\" she says, and passes the rice.","best":true},{"text":"Say it is only extra tuition and quickly change the topic","then":"Aunty seems satisfied. Your child, listening, learns that support is something to hide."},{"text":"Tell the whole table the full diagnosis and history","then":"The table goes quiet. Sneha stares at her plate, and your child stares at you."},{"text":"Look at Sneha to answer while you stay silent","then":"Sneha stammers something vague. Aunty's eyebrows rise."}],"why":"Sharing what helps, and no more, is telling on your own terms."},{"prompt":"Weeks later, Sneha admits she feels alone with all of it. What do you say?","options":[{"text":"Say you feel it too, and suggest a parent group together","then":"She lets out a breath. \"Yes. I'd like to meet other parents,\" she says.","best":true},{"text":"Tell her she's overthinking and just needs a break","then":"She flinches and stops talking. The loneliness stays between you."},{"text":"Say you'll manage and she should not worry","then":"She nods and goes quiet. You both carry it separately."},{"text":"Suggest she tell all her friends the full story tonight","then":"She panics at the idea. You drop it, and the distance stays."}],"why":"Admitting you feel it too, and finding other parents, turns isolation into support you choose."}],"debrief":"Openness on your terms, with people who can support you, beats hiding it in secrecy.","relearn":"Choose openness with safe people; secrecy isolates, and there's nothing shameful to hide."},
  {"id":"nd-1116","cat":"drop-the-shame","type":"branch","persona":"Meena","source":"comfort over scene","hook":"At a wedding, your son melts down from the noise and lights while aunties tut.","steps":[{"prompt":"He is crying with his hands over his ears as the band starts. What do you do?","options":[{"text":"Take him to a quiet room and comfort him","then":"In the quiet room his breathing slows. The tutting outside fades.","best":true},{"text":"Hiss at him to stop embarrassing the family","then":"He flinches and cries harder, now afraid as well as overwhelmed."},{"text":"Tell him to hold on until the food is served","then":"He grips your sleeve and shakes. The band gets louder."},{"text":"Apologise to the aunties while he cries beside you","then":"The aunties wave it off. His crying grows louder."}],"why":"Comfort in a quiet place answers his overwhelm, and shame only adds fear."},{"prompt":"Later, an aunty tells you that you should not have brought him. What do you say?","options":[{"text":"Say he is overwhelmed, not naughty","then":"She looks surprised, then hands you a bottle of water.","best":true},{"text":"Apologise and say it won't happen again","then":"She nods with satisfaction. Your son hears you say sorry for him."},{"text":"Snap that she should mind her own family","then":"The row goes quiet. Your voice carries and other guests look over."},{"text":"Explain his diagnosis to the whole row of aunties","then":"They listen politely. Then two of them start giving advice you didn't ask for."}],"why":"Naming overwhelm calmly replaces blame with understanding, without a fight."},{"prompt":"On the drive home, your son asks if he ruined the wedding. What do you say?","options":[{"text":"Tell him he ruined nothing and loud places are hard","then":"He rests his head on the window. \"Can we bring my headphones next time?\" he says.","best":true},{"text":"Tell him to try harder to behave at the next wedding","then":"He goes still and keeps his hands in his lap."},{"text":"Say the aunties will forget all about it by tomorrow","then":"He nods, but asks again the next morning."},{"text":"Turn on the radio and let the question pass","then":"The music fills the car. He stays quiet, still holding the question."}],"why":"Telling him plainly it wasn't his fault, and what helps, rebuilds his safety."}],"debrief":"A meltdown is overwhelm, not misbehaviour; meet it with calm, not shame for onlookers.","relearn":"A meltdown is overwhelm, not embarrassment to punish; comfort your child, let the tutting go."},
  {"id":"nd-1117","cat":"drop-the-shame","type":"branch","persona":"Divya","source":"break the spiral","hook":"It is 1 am and you are scrolling, drowning in guilt about not noticing sooner.","steps":[{"prompt":"Your thumb hovers over another post on signs you missed. What do you do?","options":[{"text":"Close the phone and name that late is not failure","then":"The room goes dark and quiet. Your shoulders drop, and you sleep.","best":true},{"text":"Keep reading 'early signs I missed' posts till dawn","then":"Dawn arrives with a heavy head and a longer list of what-ifs."},{"text":"Make a list of every moment you should have noticed","then":"The list fills a page. It proves nothing except how tired you are."},{"text":"Save the posts to read properly tomorrow","then":"You put the phone down, but the posts wait in your feed like a task."}],"why":"Late diagnoses are common, and rest gives you energy to support your child tomorrow."},{"prompt":"The next morning, your mother-in-law asks why you didn't notice earlier. What do you say?","options":[{"text":"Say the diagnosis is a start and you are learning","then":"She is quiet, then says, \"Then we should learn along with you.\"","best":true},{"text":"Apologise and say you should have noticed much sooner","then":"She sighs. Your guilt sits heavier, and your son hears from the doorway."},{"text":"Say that she never noticed anything about it either","then":"She bristles. The kitchen turns cold and you both go quiet."},{"text":"Change the subject and avoid her all day","then":"She lets it go for now. The question waits for another day."}],"why":"Saying late isn't failure ends the blame and points everyone toward support."},{"prompt":"A friend says she is drowning in the same what-ifs. What do you say?","options":[{"text":"Tell her it isn't failure, and swap what has helped","then":"She exhales. \"I needed someone to say that,\" she says, and asks what worked for you.","best":true},{"text":"Agree that you both missed things you should have caught","then":"She nods, teary. You both leave feeling worse than when you sat down."},{"text":"Tell her to stop thinking about it","then":"She says okay, but her eyes say she can't."},{"text":"Say you're sure she did everything right","then":"She manages a smile. The what-ifs are still there when she gets home."}],"why":"Saying it isn't failure, and sharing what helps, passes on relief and not guilt."}],"debrief":"Late diagnoses are common, not your failure; rest, and put tomorrow's energy into support.","relearn":"A late diagnosis isn't failure; drop the 2am what-ifs and save your energy for your child."},
  {"id":"nd-1118","cat":"drop-the-shame","type":"spot","hook":"Spot the two shaming lines an aunt drops at tea (the ones that pin blame).","scene":[{"id":"a","text":"\"You must have spoiled him rotten\"","trick":true},{"id":"b","text":"\"He has such a sharp memory\"","trick":false},{"id":"c","text":"\"Hide it or no one will marry your daughter\"","trick":true},{"id":"d","text":"\"Tell me how I can help out\"","trick":false},{"id":"e","text":"\"He drew that whole train from memory\"","trick":false}],"why":"'You spoiled him' and 'hide it or no one will marry her' pin blame and shame; the rest are kind or neutral.","relearn":"Blame myths like 'you spoiled him' and 'hide it' are the shaming lines to catch and let go.","persona":"any","source":"catch the shaming lines"},
  {"id":"nd-1119","cat":"drop-the-shame","type":"spot","hook":"Spot the two false 'cause or cure' claims in this forwarded message.","scene":[{"id":"a","text":"\"Vaccines secretly cause autism\"","trick":true},{"id":"b","text":"\"Support helps children thrive\"","trick":false},{"id":"c","text":"\"₹50,000 detox removes it in weeks\"","trick":true},{"id":"d","text":"\"A qualified professional can assess your child\"","trick":false},{"id":"e","text":"\"Neurodivergence is lifelong\"","trick":false}],"why":"'Vaccines cause autism' and a 'detox that removes it' are the false cause-and-cure claims; the rest are true.","relearn":"Catch debunked claims like 'vaccines cause autism' and 'a detox cures it'; there's no cause to blame or cure to buy.","persona":"any","source":"catch cause-cure claims"},
  {"id":"nd-1120","cat":"drop-the-shame","type":"spot","hook":"Spot the two thoughts in this 1am spiral that are shame, not truth.","scene":[{"id":"a","text":"\"I broke my child somehow\"","trick":true},{"id":"b","text":"\"He's overwhelmed, not naughty\"","trick":false},{"id":"c","text":"\"A better mother would have prevented this\"","trick":true},{"id":"d","text":"\"It's no one's fault\"","trick":false},{"id":"e","text":"\"Support can help him flourish\"","trick":false}],"why":"'I broke my child' and 'a better mother would have prevented this' are shame talking, not truth; the rest are true.","relearn":"Catch shame-thoughts like 'I broke my child' and 'a better mother would have prevented it'; they're false.","persona":"Meena","source":"catch the shame-thoughts"},
  {"id":"nd-1121","cat":"drop-the-shame","type":"spot","hook":"At a clinic waiting room, spot the two myths other parents repeat.","scene":[{"id":"a","text":"\"Strict discipline fixes this behaviour\"","trick":true},{"id":"b","text":"\"Meltdowns are overwhelm, not defiance\"","trick":false},{"id":"c","text":"\"Good families keep it a secret\"","trick":true},{"id":"d","text":"\"Stimming is just him self-soothing\"","trick":false},{"id":"e","text":"\"A diagnosis opens the door to support\"","trick":false}],"why":"'Strict discipline fixes it' and 'good families keep it secret' are myths; the rest are accurate.","relearn":"Catch myths like 'discipline fixes it' and 'hide it'; you can't punish wiring away and secrecy only isolates.","persona":"any","source":"catch waiting-room myths"},
  {"id":"nd-1122","cat":"drop-the-shame","type":"spot","hook":"Spot the two cruel labels in this relative's voice note (the ones that shame your child).","scene":[{"id":"a","text":"\"He's just a stubborn, badly-raised boy\"","trick":true},{"id":"b","text":"\"He notices details nobody else does\"","trick":false},{"id":"c","text":"\"This is a curse on your house\"","trick":true},{"id":"d","text":"\"Bring him over, we'd love to see him\"","trick":false},{"id":"e","text":"\"He learns differently, and that's okay\"","trick":false}],"why":"'Badly-raised, stubborn boy' and 'a curse on your house' are cruel, false labels; the rest are warm or true.","relearn":"Catch cruel labels like 'badly-raised' and 'a curse'; they're untrue blame your child should never wear.","persona":"Meena","source":"catch cruel labels"},
  {"id":"nd-1123","cat":"drop-the-shame","type":"role-play","persona":"Meena","source":"wont hide him","hook":"You're thinking of sharing your son's diagnosis online, and your sister has heard.","setup":"She is on the phone after dinner.","steps":[{"prompt":"Your sister says: \"Please don't post about his diagnosis. People will talk.\"","options":[{"text":"\"I won't hide him for gossips. I'll share on my terms.\"","then":"She is quiet. \"I just don't want you hurt,\" she says.","best":true},{"text":"\"You're right. Maybe it's better people don't know.\"","then":"She sounds relieved. \"Good. It's safer that way,\" she says."},{"text":"\"I'll ask the family group what they think first.\"","then":"She groans. \"Now everyone will have an opinion,\" she says."},{"text":"\"Who cares what people say? I'll post it tonight.\"","then":"She sighs. \"You're not listening. Do what you want,\" she says, and hangs up."}],"why":"Sharing on your terms keeps support open without letting gossip decide."},{"prompt":"A few days later, your sister says: \"Whenever you share anything about him, please don't tag me. I don't want questions.\"","options":[{"text":"\"That's fair. I'll leave you out. Can I count on you?\"","then":"She relaxes. \"Of course you can. I love him too,\" she says.","best":true},{"text":"\"Fine. But I'm hurt that you're embarrassed by him.\"","then":"She goes silent. \"I'm not embarrassed. I'm scared,\" she says at last."},{"text":"\"You're being a coward.\"","then":"Her voice cracks. \"That's harsh. I'm scared for him too,\" she says."},{"text":"\"You're right. It isn't worth it. I'll drop the idea.\"","then":"She says thanks and you both talk about something else. The post is never written."}],"why":"Respecting her limits while asking for her support keeps your sister on your side."},{"prompt":"A week later, your sister says: \"Someone at my office asked about your son. What do I say?\"","options":[{"text":"\"Say we're proud of him and he's getting support.\"","then":"She smiles. \"I can say that,\" she says, and sounds proud too.","best":true},{"text":"\"Say you don't know anything about it.\"","then":"She fumbles, and the colleague looks puzzled at her awkwardness."},{"text":"\"Tell them everything about his diagnosis and history.\"","then":"She tells the full story to three people. You hear it back from an aunt."},{"text":"\"Say sorry that it all happened.\"","then":"Her face falls. \"Why would I say sorry for him?\" she asks."}],"why":"Simple, proud words let her answer without hiding or oversharing."}],"relearn":"Refusing to hide your child, on your own terms, keeps support flowing and tells him there's nothing to be ashamed of."},
  {"id":"nd-1124","cat":"drop-the-shame","type":"role-play","persona":"Meena","source":"not unlucky","hook":"Another parent at school pickup pities you about your son's diagnosis.","setup":"You wait by the gate, and he hasn't come out yet.","steps":[{"prompt":"Another parent says: \"You must feel so unlucky. I could never cope.\"","options":[{"text":"\"Not unlucky. He's wonderful, and we understand him better.\"","then":"She blinks. \"Oh. I didn't mean it that way,\" she says, and smiles.","best":true},{"text":"\"Yes, we've had such terrible luck. It's been a real tragedy.\"","then":"She squeezes your arm. \"Poor you,\" she says, and you feel smaller."},{"text":"\"It's not bad luck, just a great deal of extra hard work.\"","then":"She nods. \"Extra work, of course,\" she says, as though that settles it."},{"text":"\"Please don't pity us. My family is none of your business.\"","then":"She stiffens and steps away. The gate feels colder."}],"why":"Reframing pity as understanding tells everyone he is a whole person, not a tragedy."},{"prompt":"The next week she asks: \"Does he even understand things? Will he ever manage?\"","options":[{"text":"\"He understands plenty. He's wired differently, and he has strengths.\"","then":"She listens, surprised. \"I didn't think of it like that,\" she says.","best":true},{"text":"\"Everyone learns at their own pace. We'll wait and see how he does.\"","then":"She nods vaguely. Nothing about her view has changed."},{"text":"\"Maybe not. We can only pray and hope for the best.\"","then":"She sighs sadly. \"Poor boy,\" she says."},{"text":"\"He's actually very bright. Much smarter than most kids.\"","then":"She raises an eyebrow. \"Smarter than mine?\" she asks, and the talk turns prickly."}],"why":"Naming his understanding and strengths replaces pity with a fuller picture."},{"prompt":"Later she asks: \"Would it be all right if my son invited him to play?\"","options":[{"text":"\"He'd love that. A short, quiet play works best for him.\"","then":"She beams. \"Saturday at four, then? I'll keep the toys few,\" she says.","best":true},{"text":"\"Better not. He might upset your son or spoil the play.\"","then":"She looks hurt. \"Oh. Okay,\" she says, and the invitation fades."},{"text":"\"Yes, but only if I stay and run the whole play.\"","then":"She agrees stiffly. The visit is awkward with two grown-ups hovering."},{"text":"\"Let's wait a few months and see how he is feeling.\"","then":"She nods, and the months pass without another invitation."}],"why":"Saying yes, with a note on what helps him, opens a real friendship."}],"relearn":"Reframing pity as understanding tells everyone, and yourself, that your child is not a tragedy but a whole person."},
  {"id":"nd-1125","cat":"drop-the-shame","type":"role-play","persona":"Meena","source":"job didnt cause it","hook":"Your mother has been searching for a reason behind your son's diagnosis.","setup":"She raises it over chai, while he plays in the next room.","steps":[{"prompt":"Your mother says: \"You brought this on by working so much.\"","options":[{"text":"\"My job didn't cause this, Ma. Nothing anyone did caused it.\"","then":"She is silent. \"I only worry,\" she says, and looks toward the next room.","best":true},{"text":"\"Maybe you're right. I should have stayed home.\"","then":"She nods slowly. \"These things happen,\" she says, and you feel it settle into you."},{"text":"\"Maybe it was the school. They pushed him far too hard.\"","then":"She nods eagerly. \"I always said that school was too strict,\" she says."},{"text":"\"You always blame me. You were never around when I was young.\"","then":"She gasps. \"I raised you,\" she says, and leaves the table."}],"why":"Saying no one caused it stops the blame from settling in you or being passed to him."},{"prompt":"A few days later, your mother asks: \"What can I do for him? I only want to help.\"","options":[{"text":"\"Spend time with him, and learn what calms him.\"","then":"Her face lights up. \"I'll come Saturday,\" she says, and asks what he likes.","best":true},{"text":"\"Cook his meals and leave everything else to me.\"","then":"She agrees with a small smile, and keeps her worries to herself."},{"text":"\"Pray that he gets better and becomes more like others.\"","then":"She nods and folds her hands, still waiting for him to become different."},{"text":"\"Just don't say anything to him about any of it.\"","then":"She frowns. \"So I just watch?\" she says, and goes quiet."}],"why":"Giving her a concrete way to help turns her worry into something useful."},{"prompt":"Weeks later, your mother asks: \"But why did it happen? There must be a reason.\"","options":[{"text":"\"It's how his brain is wired, Ma. It's not a fault.\"","then":"She nods slowly. \"Wired differently,\" she repeats, as if testing the words.","best":true},{"text":"\"Maybe it's the vaccines or his food. Let's check.\"","then":"She grabs the idea. Now she blames the clinic, and the blame only moves."},{"text":"\"I'll find a specialist who can tell us the cause.\"","then":"She agrees. You spend evenings reading about causes, and the hunt has no end."},{"text":"\"Maybe it is my job. Let's not think about it.\"","then":"She says nothing, and you carry the guilt out of the room."}],"why":"Saying it's simply how he is wired lets her stop searching for someone to blame."}],"relearn":"Naming that no one's choices caused it stops a false blame from taking root in you or being passed to your child."},
  {"id":"nd-1126","cat":"drop-the-shame","type":"role-play","persona":"Vikram","source":"no cure to buy","hook":"A salesman with a costly autism 'programme' has been working the school gate.","setup":"Today he corners you after pickup.","steps":[{"prompt":"The salesman says: \"A few sessions and your son will be completely normal.\"","options":[{"text":"\"There's no cure to buy. He doesn't need to be normal. Thank you.\"","then":"He shrugs. \"Your loss,\" he says, and turns to the next parent.","best":true},{"text":"\"Okay, maybe we should try it, just in case it works.\"","then":"His smile widens. \"I'll send the payment link tonight,\" he says."},{"text":"\"Send me the brochure. I'll show my wife and think about it.\"","then":"He hands you a glossy brochure and takes your number."},{"text":"\"How dare you sell this to worried parents? I'll report you.\"","then":"He backs off, muttering. A few parents nearby stare at you."}],"why":"There is no cure to buy, and a clear no protects your family from false hope."},{"prompt":"Next day at the gate, the salesman tries again: \"Offer ends tomorrow. Half price for the first ten families.\"","options":[{"text":"\"Not interested. Please don't approach me again.\"","then":"He shrugs and moves to another parent. He doesn't stop you again.","best":true},{"text":"\"Let me ask my wife to decide about the offer.\"","then":"Your wife says she is unsure too. Neither of you has asked a professional."},{"text":"\"What guarantees do you give for the results?\"","then":"He pulls up testimonials on his phone and a refund policy full of conditions."},{"text":"\"Okay, I'll pay half now and see what happens.\"","then":"You pay on your phone. His next text asks for the other half."}],"why":"A short, firm no ends the pressure without a debate you don't owe him."},{"prompt":"Your father says: \"If it helps him, what is a little money? Don't hold back.\"","options":[{"text":"\"It's not about the money. He needs support, not fixing.\"","then":"Your father is silent. \"I only want him to be well,\" he says gently.","best":true},{"text":"\"You're right. A little money is nothing, after all.\"","then":"He nods, pleased. The payment link arrives on your phone again."},{"text":"\"Let me think about it and tell you later.\"","then":"He nods. The question returns at every meal for a week."},{"text":"\"Don't interfere in how I raise my son.\"","then":"He stiffens. \"I only want to help,\" he says, and leaves the room."}],"why":"Saying what he needs, in a calm voice, lets your father hear your care."},{"prompt":"A week later, a friend asks: \"What support is your son getting now?\"","options":[{"text":"\"We spoke to a professional and joined a parent group.\"","then":"Your friend writes down the group's name. \"Can I come along?\" she asks.","best":true},{"text":"\"We ask other parents which programmes have worked.\"","then":"Your friend sighs. \"Every parent I ask swears by a different programme.\""},{"text":"\"We're trying a special diet for now.\"","then":"She raises an eyebrow and asks whether a professional agreed."},{"text":"\"Nothing yet. We're still deciding what to do.\"","then":"She nods. \"Don't wait too long,\" she says, and looks uneasy."}],"why":"A professional and other parents give steady support that a sales pitch never could."}],"relearn":"Refusing a 'cure' protects your family from false hope; your child needs support and acceptance, not fixing."},
  {"id":"nd-1127","cat":"drop-the-shame","type":"role-play","persona":"Meena","source":"overwhelmed not misbehaving","hook":"Your son has a meltdown in a busy market, and people start to stare.","setup":"You are still kneeling beside your son on the pavement.","steps":[{"prompt":"A passing man mutters: \"Control your child. This is a public place.\"","options":[{"text":"\"He's overwhelmed, not misbehaving. I'm helping him.\"","then":"The stranger blinks and steps back. \"Oh,\" he says, and walks on.","best":true},{"text":"\"Sorry, sorry, I know. He's just impossible.\"","then":"The stranger nods, satisfied. Your son hears himself called impossible."},{"text":"\"Sorry, we'll go. I'll take him home right now.\"","then":"You try to hurry him away, but he is crying too hard to walk."},{"text":"\"Mind your own business! Mind your own children!\"","then":"He snorts. \"Some people,\" he says loudly, and passers-by look over."}],"why":"Naming overwhelm calmly, without apology, refuses the shame and models calm for him."},{"prompt":"A shopkeeper steps out and says: \"Do you need a chair? Or water?\"","options":[{"text":"\"Yes, water and a quiet corner would help. Thank you.\"","then":"She brings water and a stool for the back corner, away from the noise.","best":true},{"text":"\"No, we're fine. We don't want to be a bother.\"","then":"She nods and goes back in. You stay on the hot pavement with him."},{"text":"\"Just a chair. Please make sure nobody stares at him.\"","then":"She brings a chair. The stares stay right where they were."},{"text":"\"Can you tell everyone to move away and stop looking?\"","then":"She waves at the crowd, and the stares become louder mutters."}],"why":"Accepting practical help gets him somewhere calm faster, with no shame attached."},{"prompt":"When he is calmer, your son asks: \"Did I do something wrong?\"","options":[{"text":"\"No. You were overwhelmed, and that's okay. I'm here.\"","then":"He nods and lets out a long breath. \"Loud,\" he whispers. \"Too loud.\"","best":true},{"text":"\"Not wrong, but try to be quieter in shops.\"","then":"He nods, shoulders creeping up. He tries very hard not to make a sound."},{"text":"\"It's all right. Let's just forget it.\"","then":"He nods, but at bedtime he asks if the man was angry."},{"text":"\"The man was silly. Let's never come here again.\"","then":"He agrees. Next weekend he refuses to go into any shop."}],"why":"Telling him he did nothing wrong, and naming overwhelm, gives him words for next time."},{"prompt":"Later, your husband asks: \"Should we just stop taking him out?\"","options":[{"text":"\"No. We'll go with headphones and a plan for breaks.\"","then":"Your husband nods. \"Then let's try the market on Sunday, briefly,\" he says.","best":true},{"text":"\"Yes, let's stay home until he's older and steadier.\"","then":"Your husband agrees. The outings stop, and your son's world shrinks."},{"text":"\"Only when it's empty, and never in the daytime.\"","then":"You try it for a month. He is calmer, but never sees the daytime market."},{"text":"\"Take him everywhere as usual so he learns to cope.\"","then":"You do. He goes rigid in the crowd and the afternoon ends badly."}],"why":"Planning supports, not staying home, keeps his world open with less overwhelm."}],"relearn":"Calmly naming overwhelm, instead of over-apologising, refuses the shame and models for your child that he's okay."},
  {"id":"nd-1128","cat":"drop-the-shame","type":"role-play","persona":"Priya","source":"reassure a friend","hook":"Your friend Rekha has seemed withdrawn since her son's diagnosis months ago.","setup":"You are on a park bench with her.","steps":[{"prompt":"Rekha says: \"I haven't told anyone about his diagnosis. I'm so ashamed.\"","options":[{"text":"\"It's no one's fault. You've nothing to hide, and I'm here.\"","then":"Rekha's eyes fill. \"Thank you. I've wanted someone to say that,\" she says.","best":true},{"text":"\"Yes, best to keep it quiet. People are so judgemental.\"","then":"She nods, relieved for a moment. \"It's so lonely, though,\" she says."},{"text":"\"Don't feel ashamed. Others have it much worse than you.\"","then":"She nods, though her face closes. \"I suppose,\" she says quietly."},{"text":"\"You must tell everyone tonight. Hiding will only hurt him.\"","then":"She stiffens. \"I'm not ready,\" she says, and shifts away."}],"why":"Saying it's no one's fault, and staying beside her, lets her feel less alone."},{"prompt":"Rekha says: \"But what if people think I did something wrong as a mother?\"","options":[{"text":"\"Some may say things, but it isn't true. I'll be beside you.\"","then":"She wipes her eyes. \"That helps. Just knowing I won't be alone,\" she says.","best":true},{"text":"\"Then let's prepare a script to prove you didn't cause it.\"","then":"She writes points in her phone. She practises them and grows more anxious."},{"text":"\"Some might. Mothers get blamed for everything, sadly.\"","then":"She sighs. \"Yes. It's always us,\" she says, and looks defeated."},{"text":"\"Then tell them nothing, ever. It's private.\"","then":"She nods. The secret feels heavier as the words settle."}],"why":"Saying it isn't true, and staying with her, shifts the blame off her shoulders."},{"prompt":"Rekha asks: \"Who could I even tell first? I'm scared.\"","options":[{"text":"\"Start with one safe person. You choose who and when.\"","then":"She thinks. \"My sister, maybe,\" she says slowly. \"She never judges.\"","best":true},{"text":"\"Tell your in-laws first, since they'll find out anyway.\"","then":"She goes pale. \"They'll blame me,\" she whispers."},{"text":"\"Just post it online and get it over with.\"","then":"She looks alarmed. \"Everyone at once? I couldn't,\" she says."},{"text":"\"Tell nobody until he is a bit older.\"","then":"She nods. The loneliness stays right where it was."}],"why":"Starting with one safe person, at her pace, makes sharing feel possible."},{"prompt":"A month later, Rekha says: \"I told my sister. She wants to know how to help.\"","options":[{"text":"\"Tell her one thing about him and one way to help.\"","then":"Rekha smiles. \"She can pick him up on Tuesdays,\" she says. Her voice sounds lighter.","best":true},{"text":"\"Ask her to keep it a secret from everyone else too.\"","then":"Rekha nods. Her sister feels trusted, and a little trapped."},{"text":"\"Tell her to read up about it online first, on her own.\"","then":"Her sister reads for hours. She calls back, more confused than before."},{"text":"\"Say there's nothing much she can do, but thank her warmly.\"","then":"Her sister is left wanting to help and not knowing how."}],"why":"One clear fact and one small task turn a willing relative into steady help."}],"relearn":"Telling another parent it's no one's fault, and that openness helps, passes on relief instead of shame."},
  {"id":"nd-1129","cat":"drop-the-shame","type":"role-play","persona":"Meena","source":"nothing wrong with him","hook":"Your son overhears someone ask what is wrong with him and looks up at you, worried.","setup":"You are in a bank queue, and his hand tightens in yours.","steps":[{"prompt":"Your son whispers: \"Mummy, is something wrong with me?\"","options":[{"text":"\"Nothing's wrong, jaan. Your brain works differently.\"","then":"He looks up at you. \"Different how?\" he asks, and you begin to answer.","best":true},{"text":"\"Nothing, nothing. Ignore them. They don't matter.\"","then":"He nods, but keeps glancing at the woman behind you."},{"text":"\"You're perfect. Nothing at all is different about you.\"","then":"He frowns. \"But I'm not like other kids,\" he says quietly."},{"text":"\"Yes, but the doctor is working to fix it for you.\"","then":"He looks down at his shoes, wondering what needs fixing."}],"why":"Telling him nothing is wrong, and that his brain works differently, is honest and loving."},{"prompt":"On the way home, he asks: \"Why did that lady think something's wrong with me?\"","options":[{"text":"\"She didn't understand. Your brain notices things others miss.\"","then":"He grins. \"Like the pattern on the bus seat,\" he says, and points it out.","best":true},{"text":"\"Because you're special, jaan. Don't worry about it at all.\"","then":"He nods slowly. He still doesn't know what he is meant to be special at."},{"text":"\"Because you need a lot of extra help to be normal.\"","then":"He looks down. \"Am I not normal?\" he asks, and your stomach drops."},{"text":"\"Ask your father about it when we get home.\"","then":"He asks his father, who points him back to you."}],"why":"A simple, honest word with a strength in it gives him a picture he can hold."},{"prompt":"At home, his cousin says loudly: \"My mum says he has a problem.\"","options":[{"text":"\"He has no problem. His brain just works differently.\"","then":"The cousin thinks. \"Oh. Can he show me his drawings?\" she asks.","best":true},{"text":"\"He has a condition, and the doctors are helping him.\"","then":"The cousin nods, bored. Your son hears himself called a condition."},{"text":"\"Shh. Go and play now, both of you, quickly.\"","then":"They scatter. Your son stays quiet for the rest of the afternoon."},{"text":"\"Tell your mum she is wrong and very rude.\"","then":"The cousin repeats it word for word to her mother. Voices rise in the kitchen."}],"why":"A calm, simple answer protects him and teaches the cousin something true."},{"prompt":"That night he asks: \"Will I always be different?\"","options":[{"text":"\"Yes, and that's okay. You'll always be you.\"","then":"He sighs and snuggles down. \"Okay,\" he says. \"I like being me.\"","best":true},{"text":"\"No, you'll grow out of it as you get older.\"","then":"He smiles and falls asleep. Months later, he feels let down when it hasn't gone."},{"text":"\"Different can change if you try hard enough.\"","then":"He nods and resolves to try harder. He looks worried."},{"text":"\"Let's not talk about it now. Go to sleep.\"","then":"He turns to the wall. The question stays with him."}],"why":"Honest, loving words let him know he will always be himself, and always loved."}],"relearn":"Answering 'nothing's wrong, his brain works differently' shields your child and tells him he's whole and loved."},
  {"id":"nd-1130","cat":"drop-the-shame","type":"match","hook":"Match each blame myth to the calm, true reply that lifts the shame.","pairs":[{"left":"\"Screens caused it\"","right":"He was wired this way from birth"},{"left":"\"You spoiled him\"","right":"Meltdowns are overwhelm, not spoiling"},{"left":"\"It's a curse\"","right":"It's wiring, not karma or a curse"},{"left":"\"Just buy a cure\"","right":"There's no cure to buy, only support"},{"left":"\"Hide the diagnosis\"","right":"Openness on my terms lets help in"}],"relearn":"Every blame myth, screens, spoiling, curses, cures, hiding, has a calm true reply that lifts the shame.","persona":"any","source":"myth to reply"},
  {"id":"nd-1131","cat":"drop-the-shame","type":"match","hook":"Match each false belief to the fact that debunks it.","pairs":[{"left":"Vaccines trigger autism","right":"Disproven; that study was fraud"},{"left":"They'll grow out of it","right":"Neurodivergence is lifelong"},{"left":"Bad parenting causes it","right":"It's how the brain is wired"},{"left":"A detox can cure it","right":"No diet or detox cures it"},{"left":"It's nobody's nazar","right":"It's not an evil eye or a sin"}],"relearn":"Vaccines, 'growing out of it', bad parenting, detoxes and nazar are myths; each has a plain fact that debunks it.","persona":"any","source":"belief to fact"},
  {"id":"nd-1132","cat":"drop-the-shame","type":"match","hook":"Match each shame-trap to the kinder move that frees the family.","pairs":[{"left":"Hiding the child away","right":"Sharing openly, on your terms"},{"left":"Endless self-blame","right":"Refocusing on support"},{"left":"Chasing a miracle cure","right":"Leaning on real, proven support"},{"left":"Over-apologising for him","right":"Calmly naming it's no one's fault"},{"left":"Carrying it all in silence","right":"Telling one trusted person"}],"relearn":"Each shame-trap, hiding, self-blame, chasing cures, apologising, silence, has a kinder move that frees the family.","persona":"any","source":"trap to free move"},
  {"id":"nd-1133","cat":"drop-the-shame","type":"match","hook":"Match each cutting comment to the calm boundary that ends the blame.","pairs":[{"left":"\"Control your child\"","right":"\"He's overwhelmed; I'm helping him\""},{"left":"\"You're so unlucky\"","right":"\"Not unlucky, he's wonderful\""},{"left":"\"What did you do wrong?\"","right":"\"No one did anything; let's help him\""},{"left":"\"Just discipline him harder\"","right":"\"You can't punish wiring away\""},{"left":"\"Keep it a family secret\"","right":"\"Secrecy only feeds the stigma\""}],"relearn":"Cutting comments, 'control him', 'unlucky', 'what did you do', 'discipline him', 'keep it secret', each meet a calm boundary.","persona":"any","source":"comment to boundary"},
  {"id":"nd-1134","cat":"drop-the-shame","type":"match","hook":"Match each parent's feeling to the steadying truth that meets it.","pairs":[{"left":"Grief for the path you imagined","right":"You can grieve and still love him"},{"left":"Guilt that you caused it","right":"You caused nothing; no one's fault"},{"left":"Fear of others' judgement","right":"Their misunderstanding isn't your shame"},{"left":"Exhaustion from coping alone","right":"You're allowed to ask for support"},{"left":"Shame after a public meltdown","right":"Overwhelm isn't yours to be ashamed of"}],"relearn":"Grief, guilt, fear, exhaustion and shame each meet a steadying truth; the feeling is real, the blame is not.","persona":"any","source":"feeling truth"},
  {"id":"nd-1135","cat":"drop-the-shame","type":"strike-rewrite","hook":"\"If I just pray hard enough, the autism will go away.\"","myth":{"un":"If I just pray hard enough, the autism will go away.","re":"Faith can comfort you, but no amount of prayer removes neurodivergence; your child isn't broken and needs support, not a cure.","why":"There's nothing to undo, only a child to support."},"relearn":"Prayer may comfort you, but it won't 'remove' your child's wiring; they need understanding and support, not curing.","persona":"any","source":"prayer not cure"},
  {"id":"nd-1136","cat":"drop-the-shame","type":"strike-rewrite","hook":"\"My child won't get married or work, so why even tell people?\"","myth":{"un":"My child won't get married or work, so why even tell people?","re":"Neurodiverse people build full lives, relationships and careers; writing off your child's future only limits the support they get now.","why":"A diagnosis predicts support needs, not a ceiling."},"relearn":"A diagnosis isn't a ceiling on your child's future; with support, neurodiverse people build full, rich lives.","persona":"Meena","source":"not a ceiling"},
  {"id":"nd-1170","cat":"strengths-and-wellbeing","type":"strike-rewrite","hook":"\"Praising my child will just make them lazy and big-headed.\"","myth":{"un":"Praising my child will just make them lazy and big-headed.","re":"Praising real effort and strengths builds a neurodiverse child's confidence and motivation, not laziness.","why":"Felt confidence fuels effort, not complacency."},"relearn":"Praising genuine effort and strengths grows a neurodiverse child's confidence and drive; it doesn't spoil them.","persona":"Meena","source":"praise builds confidence"},
  {"id":"nd-1171","cat":"strengths-and-wellbeing","type":"strike-rewrite","hook":"\"My child should toughen up and learn to handle a meltdown alone.\"","myth":{"un":"My child should toughen up and learn to handle a meltdown alone.","re":"A child in a meltdown is overwhelmed, not weak; calm co-regulation now is how they slowly learn to self-soothe.","why":"Coping grows from borrowed calm, not isolation."},"relearn":"A child can't 'toughen up' out of a meltdown alone; calm co-regulation is how self-soothing skills are built.","persona":"Meena","source":"co-regulation builds coping"},
  {"id":"nd-1172","cat":"strengths-and-wellbeing","type":"strike-rewrite","hook":"\"If I let my child draw all day, that 'obsession' will hold them back in life.\"","myth":{"un":"If I let my child draw all day, that 'obsession' will hold them back in life.","re":"An intense interest is a strength to feed; deep passions often grow into real skills, focus and even a future path.","why":"Today's obsession can be tomorrow's expertise."},"relearn":"An intense interest is a strength to feed, not an 'obsession' to shut down; it can become something amazing.","persona":"Meena","source":"feed the passion"},
  {"id":"nd-1173","cat":"strengths-and-wellbeing","type":"strike-rewrite","hook":"\"My child seems anxious all the time. That's just part of autism, nothing to do.\"","myth":{"un":"My child seems anxious all the time. That's just part of autism, nothing to do.","re":"Anxiety often rides alongside autism but is a real, treatable need on its own, worth taking seriously, not shrugging off.","why":"A co-occurring need can be eased, not endured."},"relearn":"Don't dismiss steady anxiety as 'just autism'; it's often a treatable co-occurring need worth support.","persona":"Divya","source":"anxiety is treatable"},
  {"id":"nd-1174","cat":"strengths-and-wellbeing","type":"strike-rewrite","hook":"\"After a meltdown I should explain how much trouble they caused, so it won't happen again.\"","myth":{"un":"After a meltdown I should explain how much trouble they caused, so it won't happen again.","re":"After a meltdown a child needs reconnection and reassurance, not a lecture; reproach adds shame and fear, not control.","why":"Safety, not shame, rebuilds a flooded child."},"relearn":"Reconnect after a meltdown with reassurance, not reproach; a lecture adds shame, it doesn't prevent the next wave.","persona":"Meena","source":"reconnect not reproach"},
  {"id":"nd-1175","cat":"strengths-and-wellbeing","type":"strike-rewrite","hook":"\"My child is a bundle of problems I have to manage every single day.\"","myth":{"un":"My child is a bundle of problems I have to manage every single day.","re":"Your child is a whole, wonderful person, far more than a list of challenges; their gifts and joy are just as real.","why":"A child is a person to know, not a problem to fix."},"relearn":"Your neurodiverse child is a whole, wonderful person, not a bundle of problems; their strengths are as real as their struggles.","persona":"Meena","source":"whole person not problem"},
  {"id":"nd-1176","cat":"strengths-and-wellbeing","type":"strike-rewrite","hook":"\"Celebrating small wins is silly. They're things every other child just does.\"","myth":{"un":"Celebrating small wins is silly. They're things every other child just does.","re":"For your child a 'small' win can be hard-won; celebrating it, not comparing it to others, builds real self-worth.","why":"Progress is measured against their own path."},"relearn":"Celebrate your child's small wins against their own path; comparing them to other kids chips at self-worth.","persona":"any","source":"celebrate small wins"},
  {"id":"nd-1177","cat":"strengths-and-wellbeing","type":"sort","hook":"Sort: a calm response to a meltdown, or one that escalates it?","items":[{"id":"a","text":"Lowering your voice and your body"},{"id":"b","text":"Shouting back to 'snap them out of it'"},{"id":"c","text":"Reducing noise and bright light"},{"id":"d","text":"Threatening to take their tablet away"},{"id":"e","text":"Offering a familiar comfort item"},{"id":"f","text":"Grabbing and forcing them to be still"}],"bins":[{"id":"calm","label":"Calms it","valence":"pos"},{"id":"escalate","label":"Escalates it","valence":"neg"}],"key":{"a":"calm","b":"escalate","c":"calm","d":"escalate","e":"calm","f":"escalate"},"relearn":"A meltdown calms when you lower your voice, dim the input and offer comfort; shouting, threats and force only escalate it.","persona":"Meena","source":"calm vs escalate meltdown"},
  {"id":"nd-1178","cat":"strengths-and-wellbeing","type":"sort","hook":"Sort: a strength worth feeding, or a behaviour to handle with care?","items":[{"id":"a","text":"Deep focus on a favourite topic"},{"id":"b","text":"Melting down in a loud bazaar"},{"id":"c","text":"Spotting patterns others miss"},{"id":"d","text":"Refusing a sudden change of plan"},{"id":"e","text":"Honest, fair-minded comments"},{"id":"f","text":"Shutting down when overwhelmed"}],"bins":[{"id":"strength","label":"Strength to feed","valence":"pos"},{"id":"care","label":"Needs care, not blame","valence":"uhoh"}],"key":{"a":"strength","b":"care","c":"strength","d":"care","e":"strength","f":"care"},"relearn":"Deep focus, pattern-spotting and honesty are strengths to feed; meltdowns, rigidity and shutdowns are overwhelm to meet with care, not blame.","persona":"any","source":"strength vs needs care"},
  {"id":"nd-1179","cat":"strengths-and-wellbeing","type":"sort","hook":"Sort: this builds self-worth, or this corrects-only and wears it down?","items":[{"id":"a","text":"'I love how your mind works'"},{"id":"b","text":"'Why can't you be like your cousin'"},{"id":"c","text":"'You worked so hard on that'"},{"id":"d","text":"'Everyone's staring, behave'"},{"id":"e","text":"'Tell me more about your project'"},{"id":"f","text":"'You always ruin family outings'"}],"bins":[{"id":"worth","label":"Builds self-worth","valence":"pos"},{"id":"wears","label":"Wears it down","valence":"neg"}],"key":{"a":"worth","b":"wears","c":"worth","d":"wears","e":"worth","f":"wears"},"relearn":"Warmth, effort-praise and curiosity build self-worth; comparison, public shaming and 'you always' wear it down.","persona":"Meena","source":"worth vs wears down"},
  {"id":"nd-1180","cat":"strengths-and-wellbeing","type":"branch","persona":"Meena","source":"wedding meltdown","hook":"At a family wedding, your son starts melting down from the noise and crowd.","steps":[{"prompt":"He is pacing fast and shouting as the crowd presses in. What do you do?","options":[{"text":"Take him to a quiet room and stay calm until it passes","then":"He settles slowly on a sofa, and the noise drops to a hum behind the door.","best":true},{"text":"Hiss at him to stop embarrassing you in front of guests","then":"He goes rigid, then screams louder. The nearby guests turn to stare."},{"text":"Offer him sweets to distract him and keep him in the hall","then":"He pushes the sweet away. The music and crowd keep pressing in."},{"text":"Ask an uncle to talk some sense into him in the hall","then":"The uncle lectures him in a loud voice. His pacing gets faster."}],"why":"A quiet room and a calm parent ease the overload, and shame only deepens it."},{"prompt":"Ten minutes on, he is calmer but says he wants to leave. What do you do?","options":[{"text":"Ask him what he needs and offer a break or going home","then":"He thinks, then asks for ten more minutes here and his headphones after.","best":true},{"text":"Insist he stay for the ceremony, since everyone is waiting","then":"He stays stiffly, hands over ears, and the meltdown restarts by the first song."},{"text":"Send him home with a relative and stay on yourself","then":"He leaves in an auto with a cousin, wondering why you stayed."},{"text":"Promise him a big treat if he stays till dinner","then":"He agrees, but he can't hold out. The overload builds under the treat."}],"why":"Asking him what he needs gives him a say and keeps the day within his limits."},{"prompt":"Weeks later, another big family event is coming up. What do you do?","options":[{"text":"Plan a quiet room, headphones, and an exit signal","then":"The host sets aside a study room. He uses it twice and rejoins each time.","best":true},{"text":"Decline every invitation so it never happens again","then":"The invitations dry up. You feel safe and a little lonely, and so does he."},{"text":"Pack his headphones and hope for the best","then":"The headphones help for an hour. Without a quiet room, the meltdown arrives after cake."},{"text":"Tell him he must behave or he'll be left at home","then":"He spends the week dreading it. On the day he shakes at the door."}],"why":"Planning supports before the event lets him take part without being overwhelmed."}],"debrief":"A meltdown in a crowd is overwhelm; ease the overload and co-regulate, don't shame.","relearn":"Meet a meltdown by easing the overload and staying calm; shaming only escalates it."},
  {"id":"nd-1181","cat":"strengths-and-wellbeing","type":"branch","persona":"Divya","source":"withdrawn for weeks","hook":"Your daughter has seemed flat and withdrawn for weeks since starting a new school.","steps":[{"prompt":"She eats little and stays in her room after school. What do you do?","options":[{"text":"Sit with her and gently ask how school is going","then":"She shrugs, then whispers that the canteen is too loud and lunch is scary.","best":true},{"text":"Decide it's just her autism and leave it be","then":"She stays in her room. A week later, the plate is still untouched."},{"text":"Tell her to go out and play to cheer herself up","then":"She goes out, returns sooner than expected, and closes her door."},{"text":"Ask the class teacher to keep an eye on her","then":"The teacher says she seems quiet. Your daughter never knew you asked."}],"why":"Sitting with her, without pressure, is how you learn what has changed."},{"prompt":"Two more weeks pass and her mood is still low. What do you do?","options":[{"text":"Take it seriously and book a visit with a professional","then":"The professional listens to you both and makes a gentle plan.","best":true},{"text":"Wait for her to settle, since new schools are hard","then":"The weeks stretch. She talks less and sleeps more."},{"text":"Look for tips online and try them at home first","then":"You try three tips. She goes along politely, and nothing lifts."},{"text":"Tell her that others cope with change, so she can too","then":"She nods and tucks her chin in. She says she is fine."}],"why":"A low mood that lingers deserves a professional's eyes, not wait-and-see."},{"prompt":"Weeks later, you ask her teacher for changes, but the teacher hesitates. What do you do?","options":[{"text":"Share what helps her and ask kindly for two small changes","then":"The teacher agrees to a quiet lunch spot and a warning before changes.","best":true},{"text":"Go over the teacher's head and complain to the principal","then":"The principal is polite, but the teacher now feels accused."},{"text":"Wait a while to see if the teacher comes around","then":"Weeks pass with nothing changed, and she withdraws further."},{"text":"Drop it since the teacher seems so unwilling to change","then":"Her low mood continues and the school stays as loud as ever."}],"why":"Small, specific requests keep the teacher on your team and help her feel safe."}],"debrief":"Persistent low mood is worth taking seriously, not dismissing as 'just the diagnosis'.","relearn":"Don't dismiss lasting low mood as 'just autism'; take it seriously and seek support."},
  {"id":"nd-1182","cat":"strengths-and-wellbeing","type":"branch","persona":"Vikram","source":"sorting cars strength","hook":"Your son spends hours arranging his toy cars by colour, and a relative calls it 'weird'.","steps":[{"prompt":"He lines up the last car as the relative watches. What do you do?","options":[{"text":"Sit with him and ask about his system","then":"He lights up and explains why red goes before orange.","best":true},{"text":"Sweep the cars away and tell him to play normally","then":"The cars scatter. He stands still, then goes quiet for the evening."},{"text":"Laugh along with the relative to avoid awkwardness","then":"The relative chuckles. Your son notices, and slides the cars into his lap."},{"text":"Suggest he play with his cousins for a while instead","then":"He follows you reluctantly. The cars stay lined up in the corner, ignored."}],"why":"Joining his world shows him his deep focus is worth your time."},{"prompt":"The next week, he wants to bring the cars to school. What do you do?","options":[{"text":"Let him bring a few, and tell his teacher why","then":"The teacher says he can show the class at circle time.","best":true},{"text":"Tell him no, since other kids will tease him","then":"He nods, eyes down, and puts the cars back in the box."},{"text":"Let him bring them all and see what happens","then":"The bag is heavy and the cars spill in class. He panics as they roll away."},{"text":"Suggest he bring something normal instead","then":"He picks a ball, and leaves school flat and unlike himself."}],"why":"A few cars and a word with the teacher let his interest travel safely."},{"prompt":"At the next gathering, the relative tells him to stop playing like a baby. What do you do?","options":[{"text":"Say calmly it's how he focuses, and let him play on","then":"The relative grunts. Your son keeps lining up cars, humming to himself.","best":true},{"text":"Quietly ask your son to put the cars away","then":"He tucks them into the bag and his humming stops."},{"text":"Tell the relative to stay out of your family's business","then":"The relative goes red. Two cousins leave the room, and your son hears the fight."},{"text":"Take your son outside to play with him there","then":"You play outside. The comment hangs unanswered in the room."}],"why":"Standing up for how he plays shows him his interest needs no apology."}],"debrief":"An intense, ordered interest is deep focus to honour, not a 'weird' habit to stop.","relearn":"Honour an intense interest as a strength to feed; don't shut it down."},
  {"id":"nd-1183","cat":"strengths-and-wellbeing","type":"branch","persona":"Meena","source":"reconnect after meltdown","hook":"After a hard meltdown, your son curls up, ashamed, and won't meet your eye.","steps":[{"prompt":"The house is quiet and he is pressed against the sofa. What do you do?","options":[{"text":"Sit close and say it's over and he's not in trouble","then":"His body loosens a little. He leans against your arm without looking up.","best":true},{"text":"List what he did wrong so he learns from it","then":"He curls tighter and says he is always in trouble."},{"text":"Say you're disappointed and leave him alone to think","then":"You go. He stays where he was, staring at the cushion."},{"text":"Bring his favourite snack and say nothing about it","then":"He eats it slowly. He still can't meet your eyes."}],"why":"Reassurance tells him he is safe and loved, and the storm was not his fault."},{"prompt":"Later, he asks in a small voice if you are angry. What do you say?","options":[{"text":"Tell him you're not angry and you love him always","then":"He looks up for the first time. \"Even when I scream?\" he asks, and you nod.","best":true},{"text":"Say you were just tired and it's forgotten","then":"He nods. He isn't sure what to make of it, and asks again at bedtime."},{"text":"Say you're not angry, but he must never do it again","then":"He nods solemnly, then checks your face all evening."},{"text":"Tell him to go wash his face and stop worrying","then":"He pads off to the bathroom, still unsure whether he is in trouble."}],"why":"He needs to hear he is loved without conditions, not only that the storm has passed."},{"prompt":"The next morning, he says he is scared it will happen again. What do you do?","options":[{"text":"Make a plan with him for calm signals and a quiet spot","then":"You draw a picture card together. He picks a blue cushion for his quiet spot.","best":true},{"text":"Tell him it won't, if he just tries harder","then":"He nods, but his hands twist in his lap. He looks even more worried."},{"text":"Say there is nothing to worry about and change the topic","then":"He nods, though the worry stays in his face."},{"text":"Promise him it will never ever happen again","then":"He smiles. The next time the noise builds, he remembers your promise and panics."}],"why":"A shared plan shows him meltdowns can be met with support, not fear."}],"debrief":"After a meltdown, reconnect with reassurance, not reproach, to rebuild safety.","relearn":"Reconnect after a meltdown with warmth; reproach only deepens a child's shame."},
  {"id":"nd-1184","cat":"strengths-and-wellbeing","type":"match","hook":"Match each neurodiverse strength to where it can shine.","pairs":[{"left":"Deep focus (autism)","right":"Mastering one subject in real depth"},{"left":"High energy (ADHD)","right":"Sport, dance and hands-on play"},{"left":"Pattern recognition","right":"Puzzles, coding and music"},{"left":"Big-picture thinking (dyslexia)","right":"Storytelling and inventing ideas"},{"left":"Strong sense of fairness","right":"Standing up for a friend"}],"relearn":"Deep focus, high energy, pattern recognition, big-picture thinking and fairness each have real places to shine.","persona":"any","source":"strength to where it shines"},
  {"id":"nd-1185","cat":"strengths-and-wellbeing","type":"match","hook":"Match each warm parent line to what it protects in your child.","pairs":[{"left":"'I love how your brain works'","right":"Their self-worth"},{"left":"'It's over, you're not in trouble'","right":"Safety after a meltdown"},{"left":"'Tell me everything about it'","right":"A treasured interest"},{"left":"'You tried so hard at that'","right":"Their effort and courage"},{"left":"'I'm here, take your time'","right":"Calm during overwhelm"}],"relearn":"Warm, specific words protect a child's self-worth, safety, interests, effort and calm far more than correction does.","persona":"Meena","source":"line to what it protects"},
  {"id":"nd-1186","cat":"strengths-and-wellbeing","type":"reflect","hook":"Lensy: a child who hears 'I love the way your mind works' carries that voice for life. Worth saying often?","prompt":"What do you think?","options":["Worth it","I'll say it more","They deserve to hear it"],"affirm":"A neurodiverse child who often hears their mind is loved, not just corrected, grows up liking who they are.","relearn":"Telling your child you love how their mind works builds a self-worth that lasts long after the moment.","persona":"Meena","source":"love your mind"},
  {"id":"nd-1187","cat":"strengths-and-wellbeing","type":"reflect","hook":"Lensy: under every meltdown is a child who is overwhelmed, not bad. Does holding that change how you meet it?","prompt":"Sit with that.","options":["It changes a lot","Overwhelmed, not bad","I can stay calmer"],"affirm":"Seeing a meltdown as overwhelm, not badness, lets you meet it with calm co-regulation instead of anger.","relearn":"Holding 'overwhelmed, not bad' under a meltdown helps you respond with calm, not punishment.","persona":"Meena","source":"overwhelmed not bad"},
  {"id":"nd-1188","cat":"strengths-and-wellbeing","type":"reflect","hook":"Lensy: your child's intense passion lights them up like nothing else. What might it grow into?","prompt":"Picture it.","options":["A real skill","A future path","Just pure joy"],"affirm":"An intense interest is a strength to feed; given space, today's passion can grow into skill, confidence or a path.","relearn":"Your child's intense passion is a strength to feed; with space it can grow into skill, confidence and joy.","persona":"any","source":"passion grows"},
  {"id":"nd-1189","cat":"strengths-and-wellbeing","type":"reflect","hook":"Lensy: a child celebrated for who they are, not just corrected, grows up at home in their own skin. Worth aiming for?","prompt":"What's your take?","options":["Worth aiming for","At home in themselves","That's the goal"],"affirm":"A child who feels celebrated, not constantly corrected, grows up with self-worth and at home in their own skin.","relearn":"Aim to celebrate your child for who they are, not just correct them; it grows a lifelong sense of self-worth.","persona":"Meena","source":"celebrated not corrected"},
  {"id":"nd-1190","cat":"strengths-and-wellbeing","type":"spot","hook":"Spot the two lines that punish overwhelm instead of soothing it.","scene":[{"id":"a","text":"'Let's go somewhere quieter together'","trick":false},{"id":"b","text":"'Stop crying or no dinner for you'","trick":true},{"id":"c","text":"'I'll hold your hand till it passes'","trick":false},{"id":"d","text":"'You're doing this on purpose to spite me'","trick":true},{"id":"e","text":"'Take a slow breath with me'","trick":false}],"why":"Threatening 'no dinner' and accusing 'on purpose to spite me' punish overwhelm; offering quiet, a hand and a breath soothe it.","relearn":"Soothe overwhelm with calm and closeness; threats and 'you're doing it on purpose' punish a child who is flooded, not defiant.","persona":"Meena","source":"soothe not punish overwhelm"},
  {"id":"nd-1191","cat":"strengths-and-wellbeing","type":"spot","hook":"Spot the two lines that shame a child's strengths instead of feeding them.","scene":[{"id":"a","text":"'I love hearing about your rockets'","trick":false},{"id":"b","text":"'Stop obsessing, it's embarrassing'","trick":true},{"id":"c","text":"'Your honesty is a real gift'","trick":false},{"id":"d","text":"'Nobody cares about your weird facts'","trick":true},{"id":"e","text":"'Show me what you built today'","trick":false}],"why":"Calling a passion an embarrassing 'obsession' and 'weird facts nobody cares about' shame a strength; the other lines feed it with interest.","relearn":"Feed a child's passion with genuine interest; calling it an embarrassing 'obsession' shames a real strength.","persona":"any","source":"feed not shame strengths"},
  {"id":"nd-1192","cat":"strengths-and-wellbeing","type":"spot","hook":"Spot the two lines that compare and diminish your child.","scene":[{"id":"a","text":"'You're exactly who you're meant to be'","trick":false},{"id":"b","text":"'Why can't you be normal like them'","trick":true},{"id":"c","text":"'I'm proud of how you tried today'","trick":false},{"id":"d","text":"'Your sister never gives me this trouble'","trick":true},{"id":"e","text":"'There's no one quite like you'","trick":false}],"why":"'Why can't you be normal' and the sibling comparison diminish your child; the rest value who they are.","relearn":"Value your child for who they are; comparing them to a 'normal' kid or a sibling chips at self-worth.","persona":"Meena","source":"value not compare"},
  {"id":"nd-1193","cat":"strengths-and-wellbeing","type":"role-play","persona":"Vikram","source":"protect stimming","hook":"Grandma is staying for a week, and your son flaps his hands when excited or worried.","setup":"She spots him flapping at the dining table.","steps":[{"prompt":"Grandma says: \"Stop that bad habit at once! Sit properly.\"","options":[{"text":"\"It helps him calm down, Ma. It's how he copes.\"","then":"Grandma frowns. \"Calm down from what? He's only sitting,\" she says.","best":true},{"text":"\"Ma, please, he's only a child. Let him be.\"","then":"Grandma huffs. \"A child must learn manners,\" she says, and the scolding lingers."},{"text":"\"Stop that at once. You're upsetting your grandmother.\"","then":"Your son freezes with his hands tucked under his legs. Grandma nods, satisfied."},{"text":"\"Don't tell me how to raise my son, Ma.\"","then":"She stiffens. \"I raised four children,\" she says, and turns back to her plate."}],"why":"Explaining what flapping does for him protects his calm and gives Grandma a reason to stop."},{"prompt":"Grandma asks: \"But why does he do it? Other children don't.\"","options":[{"text":"\"When he's worried, flapping helps him settle.\"","then":"She watches him a while. \"Like a bird,\" she says slowly.","best":true},{"text":"\"He picked it up from television. It will pass.\"","then":"She scowls at the TV. Tomorrow she switches it off, and the flapping continues."},{"text":"\"The doctor says we'll train him out of it.\"","then":"She nods approvingly. Your son overhears that he needs to be trained."},{"text":"\"Nobody knows, Ma. Please let's not discuss it.\"","then":"She purses her lips. The question hangs in the room."}],"why":"A simple reason helps her see flapping as his way of settling, not a habit to break."},{"prompt":"At dinner, Grandma waits until he flaps, then says: \"Look, he's doing it again!\"","options":[{"text":"\"Ma, it's how he calms down. Please pass the dal.\"","then":"Grandma passes the dal. Your son keeps flapping, eyes bright.","best":true},{"text":"\"Yes, I noticed too. We're working on it, Ma.\"","then":"Grandma smiles. \"Good,\" she says, and your son goes still."},{"text":"\"Beta, hands down. Grandma is watching you.\"","then":"Your son's hands drop to his lap. His eyes go dull."},{"text":"\"Ma, I've told you before. Do you want to upset him?\"","then":"Grandma says nothing more. Her jaw is tight and the meal is silent."}],"why":"A calm, brief reminder keeps peace at the table and keeps him free to stim."},{"prompt":"The next day, Grandma asks: \"What should I do when he flaps?\"","options":[{"text":"\"Just let him. If he seems upset, sit with him quietly.\"","then":"She nods. Later you see her beside him, watching the birds together.","best":true},{"text":"\"Give him something to hold so his hands stay still.\"","then":"He holds the toy and his hands go tight. Grandma looks pleased."},{"text":"\"Pretend you don't see it. Look away when he does it.\"","then":"She turns her head each time. Your son notices and stops flapping near her."},{"text":"\"Tell him kindly to do it in his room instead.\"","then":"He goes to his room whenever he flaps and comes out flat."}],"why":"Letting him flap, and staying close if he is upset, gives Grandma a simple job to do."}],"relearn":"Defending a child's stimming as self-soothing, not a 'bad habit' to stop, protects both his calm and his self-worth."},
  {"id":"nd-1194","cat":"strengths-and-wellbeing","type":"role-play","persona":"Meena","source":"name the transition win","hook":"Your son just managed a hard transition that usually ends in tears.","setup":"The five-minute timer rang, and he is walking calmly to the car.","steps":[{"prompt":"Your son says: \"I did the car all by myself, Mummy.\"","options":[{"text":"\"You left the park by yourself. That was hard.\"","then":"He puffs out his chest. \"The swings were hard to leave,\" he says.","best":true},{"text":"\"Finally, a day at the park with no drama for once.\"","then":"His face falls. \"Was I always dramatic?\" he asks."},{"text":"\"Well done. Now do the same thing again tomorrow, okay?\"","then":"He nods, but he starts to worry about tomorrow."},{"text":"\"Nice. Let's get home before you change your mind.\"","then":"He hurries into the car, tense and quiet."}],"why":"Naming exactly what he did, and that it was hard, builds real pride."},{"prompt":"At home, he asks: \"Can I go back to the park tomorrow?\"","options":[{"text":"\"Yes. We'll set the timer again before it's time to go.\"","then":"He runs to find the kitchen timer and hugs it, grinning.","best":true},{"text":"\"Only if you promise to leave without crying.\"","then":"He nods, then worries all evening about whether he can promise."},{"text":"\"Maybe. Let's see how you behave today.\"","then":"He goes quiet, trying to behave perfectly for the rest of the day."},{"text":"\"No, it was too hard on you. We'll skip it.\"","then":"He nods, relieved and a little sad. Days pass before you try the park again."}],"why":"Keeping the supports that worked, and saying yes, tells him he can succeed again."},{"prompt":"On the next park visit, the timer rings and he says: \"Five more minutes, please.\"","options":[{"text":"\"Two more swings, then the car. I'll count.\"","then":"He swings twice, counting aloud, then takes your hand and walks to the car.","best":true},{"text":"\"No. The timer said it is time to go. Come on.\"","then":"He drops off the swing and crumples into tears at the gate."},{"text":"\"Fine. Stay as long as you like, all afternoon.\"","then":"He stays another half hour. The next transition gets harder, not easier."},{"text":"\"If you cry at the gate, we're never coming back.\"","then":"His lip trembles. He follows you, silent and scared, and doesn't enjoy the ride home."}],"why":"A small, clear extension with a count keeps the transition gentle and predictable."},{"prompt":"A week later, his teacher asks: \"What helps him with changes at home?\"","options":[{"text":"\"Warnings, a timer, and praise for small wins.\"","then":"The teacher writes it down. \"I'll try the timer in class tomorrow,\" she says.","best":true},{"text":"\"We tell him firmly to try harder. Do the same.\"","then":"The teacher nods and tells him to try harder at school too. He stiffens."},{"text":"\"Nothing much. He's just growing up, I think.\"","then":"The teacher nods. Nothing changes in class."},{"text":"\"I'm not really sure. It might just be luck.\"","then":"The teacher shrugs. Without a method, she keeps doing what she did."}],"why":"Sharing what works lets the teacher use it, so the win carries into school."}],"relearn":"Naming a hard-won transition as a real win, with specific warmth, builds confidence far more than relief framed as 'finally'."},
  {"id":"nd-1195","cat":"strengths-and-wellbeing","type":"role-play","persona":"Meena","source":"calm into the storm","hook":"Mid-meltdown, your daughter is sobbing on the kitchen floor.","setup":"You crouch down beside her.","steps":[{"prompt":"Your daughter sobs: \"Everything is too loud! Make it stop!\"","options":[{"text":"\"I'm here. You're safe. We'll breathe together.\"","then":"Her sobs slow to hiccups. She grabs your sleeve and copies your breathing.","best":true},{"text":"\"Tell me what happened and I'll fix it right now.\"","then":"She can't answer. Her crying rises as she fails to find the words."},{"text":"\"Get up right now. This is not the way to behave.\"","then":"She wails louder and curls into a ball."},{"text":"\"Nothing is loud. Just calm down, and stop crying.\"","then":"She covers her ears and screams that you don't understand."}],"why":"Calm, safe, present words help her wave pass, and demands only add to the overload."},{"prompt":"She whispers: \"Can you turn off the lights? They hurt.\"","options":[{"text":"\"Yes. I'll dim them and get your headphones.\"","then":"The room dims. She presses the headphones on and sags against you.","best":true},{"text":"\"Let's go outside where it's bright and fresh.\"","then":"The sun stings her eyes. She burrows into your side and sobs."},{"text":"\"I'll turn them off, but only if you stop crying.\"","then":"She tries to stop crying and hiccups harder. The light stays on."},{"text":"\"The lights are fine. Try closing your eyes.\"","then":"She shuts her eyes, but the crying rises again."}],"why":"Trusting what she says hurts is the fastest way to make her feel safe."},{"prompt":"A little later she asks: \"Are you cross with me?\"","options":[{"text":"\"Not one bit. That was big, and you got through it.\"","then":"She rubs her eyes. \"I didn't like that,\" she says, and leans on you.","best":true},{"text":"\"No. But please tell me before it gets that bad.\"","then":"She nods, though she doesn't know how to tell you before it happens."},{"text":"\"Only a bit. It was a lot of noise for everyone here.\"","then":"She flinches. \"Sorry,\" she says in a very small voice."},{"text":"\"Let's not talk about it now. Have some water first.\"","then":"She sips it, still watching your face for the answer."}],"why":"Reassurance that isn't conditional rebuilds her safety after a hard storm."},{"prompt":"Later that week, her teacher calls: \"Shall we make a plan for when this happens at school?\"","options":[{"text":"\"Yes, please. A quiet corner and signal card would help.\"","then":"The teacher writes it down. \"A blue card and the library corner, then,\" she says.","best":true},{"text":"\"Just call me and I'll come to get her every time.\"","then":"You get five calls that week. She learns nobody at school can help."},{"text":"\"It won't happen at school. She only does it at home.\"","then":"The teacher pauses. \"Well, we saw something like it on Monday,\" she says."},{"text":"\"Send her to the principal if she screams.\"","then":"She is sent to the principal and learns that screaming means trouble."}],"why":"A clear plan at school gives her ways out before the storm builds."}],"relearn":"Calm, safe, present words co-regulate a meltdown; demanding she get up and behave adds shame to overwhelm."},
  {"id":"nd-1196","cat":"strengths-and-wellbeing","type":"role-play","persona":"Meena","source":"reframe i'm stupid","hook":"Your son has been struggling with reading, and today was a hard day.","setup":"He drops his bag by the door after school.","steps":[{"prompt":"Your son says: \"I'm so stupid. Everyone in class is better than me.\"","options":[{"text":"\"You're not stupid. Your brain works differently.\"","then":"He looks up. \"Different how?\" he asks, and wipes his nose.","best":true},{"text":"\"Don't say that. Just try harder than them.\"","then":"He nods, shoulders sinking. He thinks it means he isn't trying hard enough."},{"text":"\"Who said that? I'll speak to the teacher today.\"","then":"He panics. \"Don't tell her,\" he begs, and now he fears what she will say."},{"text":"\"Everyone feels like that sometimes. Forget it, beta.\"","then":"He shrugs and goes to his room. The words stay with him."}],"why":"Telling him he isn't stupid, and why, answers the feeling with something true."},{"prompt":"Later, he asks: \"Why is reading so hard for me?\"","options":[{"text":"\"It's not laziness. Let's ask an expert what helps you.\"","then":"He blinks. \"So I'm not lazy?\" he asks, and you shake your head.","best":true},{"text":"\"Because you don't practise reading enough at home.\"","then":"He opens a book and stares, hopeless, until you ask him to stop."},{"text":"\"It isn't hard. You just need to concentrate more.\"","then":"He tries to concentrate. The letters swim and he cries."},{"text":"\"Maybe you're just tired of school and homework lately.\"","then":"He shrugs. The question is still there tomorrow."}],"why":"Saying it isn't laziness, and that an expert can find what helps, lifts a burden he carries."},{"prompt":"At dinner he says: \"Amit reads faster. He's better than me at everything.\"","options":[{"text":"\"Amit reads faster. You notice things Amit misses.\"","then":"He almost smiles. \"Like the bird on the wall today,\" he says slowly.","best":true},{"text":"\"Then practise every night until you catch up with Amit.\"","then":"He agrees, but his shoulders slump. Every night becomes a race he is losing."},{"text":"\"Don't compare yourself to Amit. It's not helpful.\"","then":"He stops talking. He compares himself silently all evening."},{"text":"\"Amit is just lucky. Ignore him and his marks.\"","then":"He scowls. \"He isn't lucky. He's smart,\" he says."}],"why":"Naming his own strengths beside Amit's stops the comparison from becoming the whole story."},{"prompt":"Weeks later, his teacher says: \"He's very hard on himself. Any ideas?\"","options":[{"text":"\"Praise his strengths, and let's get his reading assessed.\"","then":"The teacher nods. \"I'll ask about an assessment, and send a strengths note on Fridays,\" she says.","best":true},{"text":"\"Just tell him to stop being so negative about himself.\"","then":"The teacher tries it. He goes quiet, hiding the feeling."},{"text":"\"Maybe give him easier work so he feels good about school.\"","then":"The work gets easier and duller. He starts to feel it's because he can't."},{"text":"\"Let him sit at the back so nobody notices him much.\"","then":"He sits at the back and drifts. He speaks less each week."}],"why":"Praise for effort, plus a proper reading assessment, rebuilds how he sees himself and gets him support."}],"relearn":"Reframing 'I'm stupid' as a differently-wired, capable brain rebuilds self-worth; 'try harder' leaves the shame in place."},
  {"id":"nd-1198","cat":"strengths-and-wellbeing","type":"strike-rewrite","hook":"\"If I keep co-regulating his meltdowns, he'll never learn to cope on his own.\"","myth":{"un":"If I keep co-regulating his meltdowns, he'll never learn to cope on his own.","re":"Co-regulation is the launchpad for self-regulation; a child borrows your calm now and slowly grows their own.","why":"Independence is built on early support, not denial of it."},"relearn":"Co-regulation isn't a crutch; it's the launchpad from which a child's own coping skills grow over time.","persona":"Meena","source":"co-regulation is a launchpad"},
  {"id":"nd-1199","cat":"strengths-and-wellbeing","type":"sort","hook":"Sort: this honours your child's interest, or this dismisses it?","items":[{"id":"a","text":"Asking them to teach you about it"},{"id":"b","text":"'Not that boring topic again'"},{"id":"c","text":"Finding a book on their passion"},{"id":"d","text":"Rolling your eyes when they start"},{"id":"e","text":"Joining their game on their terms"},{"id":"f","text":"'Real kids don't care about that'"}],"bins":[{"id":"honour","label":"Honours the interest","valence":"pos"},{"id":"dismiss","label":"Dismisses it","valence":"neg"}],"key":{"a":"honour","b":"dismiss","c":"honour","d":"dismiss","e":"honour","f":"dismiss"},"relearn":"Asking, reading and joining in honour a child's passion; eye-rolls and 'boring again' dismiss a real strength.","persona":"any","source":"honour vs dismiss interest"},
  {"id":"nd-1200","cat":"strengths-and-wellbeing","type":"sort","hook":"Sort: a sign of co-occurring anxiety to take seriously, or an ordinary good day?","items":[{"id":"a","text":"Refusing to leave the house for days"},{"id":"b","text":"Happily showing you a new drawing"},{"id":"c","text":"Stomach aches every school morning"},{"id":"d","text":"Playing easily with a cousin"},{"id":"e","text":"Waking with nightmares most nights"},{"id":"f","text":"Laughing along at a silly video"}],"bins":[{"id":"watch","label":"Take seriously","valence":"uhoh"},{"id":"fine","label":"An ordinary good day","valence":"pos"}],"key":{"a":"watch","b":"fine","c":"watch","d":"fine","e":"watch","f":"fine"},"relearn":"House refusal, daily stomach aches and nightmares are anxiety signs to take seriously; play, drawing and laughter are just a good day.","persona":"Divya","source":"anxiety sign vs good day"},
  {"id":"nd-1201","cat":"strengths-and-wellbeing","type":"branch","persona":"any","source":"proud painting","hook":"Your child proudly shows you a 'messy' painting they spent an hour on.","steps":[{"prompt":"They hold it up, paint still wet, and wait for your face. What do you do?","options":[{"text":"Light up and ask them to tell you all about it","then":"They talk for five minutes about the storm they painted, pointing at each splash.","best":true},{"text":"Point out where it's wrong so they can improve","then":"Their smile fades. They put the painting face down on the table."},{"text":"Say it's lovely and go back to what you were doing","then":"They say okay, and take the painting back to their room."},{"text":"Show them a neater way to paint, then praise it","then":"They listen, then look at their own splashes as if they were mistakes."}],"why":"Delight first tells them their creativity is treasured, before any teaching."},{"prompt":"Next day, a cousin sees the painting and says it looks like a mess. What do you do?","options":[{"text":"Say you love its bold colours, and move on","then":"Your child hears you and stands a little taller. The cousin says, \"Bold, yes.\"","best":true},{"text":"Laugh and say children's art is always messy","then":"The cousin chuckles. Your child looks at the floor."},{"text":"Tell the cousin to keep her opinions to herself","then":"The cousin shrugs and leaves. Your child looks between you, unsure."},{"text":"Quietly put the painting away to spare feelings","then":"The painting goes into a drawer. Your child asks where it went."}],"why":"Defending their work out loud teaches them it deserves to be seen."},{"prompt":"A week later they ask to paint again but say they'll do it better. What do you say?","options":[{"text":"Cheer their wish to try again, and get the brushes","then":"They grin and paint a purple sky. Nothing on it is careful, and they are happy.","best":true},{"text":"Suggest they copy a picture from a book first","then":"They trace the book picture carefully. Their own colours stay in the tin."},{"text":"Say yes, after you show them what to fix this time","then":"They nod and paint slowly, stopping to check each stroke."},{"text":"Say sure, and offer to guide their brush so it comes out tidy","then":"You guide their brush. The painting looks tidy, and they lose interest halfway."}],"why":"Trusting their own way of painting builds joy and confidence."}],"debrief":"Meet a child's proud creation with delight first; corrections-first chips at the joy.","relearn":"Celebrate creative effort first; leading with what's 'wrong' says their best isn't enough."},
  {"id":"nd-1202","cat":"strengths-and-wellbeing","type":"branch","persona":"Vikram","source":"party overstimulation","hook":"At a birthday party, your son covers his ears and starts rocking as the music blares.","steps":[{"prompt":"Other kids are staring as he rocks harder. What do you do?","options":[{"text":"Step outside with him for a calm break, no fuss","then":"Out in the garden, his breathing slows and he leans against your leg.","best":true},{"text":"Tell him to stop rocking and sit properly like the others","then":"He freezes, then rocks faster under the table, out of sight."},{"text":"Stay put and let him get used to the noise","then":"The noise keeps building. He starts to cry and hide his face."},{"text":"Offer him cake and tell him to focus on that","then":"He takes it, but his ears stay covered and the cake goes untouched."}],"why":"A calm break outside eases the overload, and rocking is how he soothes himself."},{"prompt":"Before the games start, he says he wants to join in. What do you do?","options":[{"text":"Join in together, and agree a signal for leaving","then":"You agree he will tug your sleeve if it's too loud. He nods and heads to the games.","best":true},{"text":"Say no, since the party is nearly over anyway","then":"He watches the games from a chair and stays quiet."},{"text":"Send him to the games alone so he learns to cope","then":"He hovers at the edge of the games, then returns to you."},{"text":"Tell him to stay near the music to get used to it","then":"He stands by the speakers. Within minutes his hands are on his ears again."}],"why":"A shared signal lets him return safely and leave the moment he needs to."},{"prompt":"A parent says quietly that he shouldn't rock in front of the kids. What do you say?","options":[{"text":"Say rocking helps him settle, and he is doing fine","then":"She looks surprised. \"Oh, I didn't know that,\" she says, and offers him a seat.","best":true},{"text":"Apologise and promise he'll sit still next time","then":"She nods. Your son, hearing it, tucks his hands under his legs."},{"text":"Say he is just excited, and change the subject","then":"She smiles politely. Your son hears you explain him away."},{"text":"Snap that her own children are not so perfect either","then":"Her cheeks flush. The chatter around you dips."}],"why":"Explaining rocking as self-soothing protects his calm and his self-worth."},{"prompt":"On the way home, he asks why the others don't rock. What do you say?","options":[{"text":"Say everyone calms in their own way, and rocking is his","then":"He thinks about it. \"Then what do the others do?\" he asks, and you name a few.","best":true},{"text":"Say they don't need to rock because they are calmer","then":"He looks at his hands, wondering why he is not calm like them."},{"text":"Say he can rock at home, but not in front of other people","then":"He nods. Next time he holds himself stiff in public, and the party ends early."},{"text":"Say you'll teach him to sit still like the others","then":"He tries to sit still on the ride home, jaw tight."}],"why":"Telling him everyone soothes differently keeps rocking from becoming a source of shame."}],"debrief":"Rocking and ear-covering are self-soothing, not misbehaving; offer a calm break.","relearn":"Let an overstimulated child take a calm break; rocking is self-soothing, not bad behaviour."},
  {"id":"nd-1203","cat":"strengths-and-wellbeing","type":"match","hook":"Match each moment to the wellbeing response it calls for.","pairs":[{"left":"A win they're proud of","right":"Celebrate it out loud"},{"left":"The storm of a meltdown","right":"Calm, safety, co-regulation"},{"left":"Shame after melting down","right":"Reassurance, not reproach"},{"left":"Weeks of low, flat mood","right":"Take it seriously, seek support"},{"left":"A passion lighting them up","right":"Feed it with time and interest"}],"relearn":"A win, a meltdown, post-meltdown shame, a long low mood and a passion each call for a different, caring response.","persona":"Meena","source":"moment to response"},
  {"id":"nd-1204","cat":"strengths-and-wellbeing","type":"match","hook":"Match each child's self-doubt to a truthful, kind reframe.","pairs":[{"left":"'I'm so stupid'","right":"'Your brain just works differently'"},{"left":"'Everyone hates me'","right":"'You feel alone right now, I'm here'"},{"left":"'I always mess up'","right":"'You tried something hard today'"},{"left":"'I'm a burden to you'","right":"'You're a joy I chose and love'"},{"left":"'I'll never fit in'","right":"'The right people will love you as you are'"}],"relearn":"Each harsh self-belief a child voices can be met with a truthful, warm reframe that rebuilds their self-worth.","persona":"Meena","source":"self-doubt to reframe"},
  {"id":"nd-1205","cat":"strengths-and-wellbeing","type":"reflect","hook":"Lensy: looking back, which of your child's 'difficult' traits is secretly a strength in disguise?","prompt":"Sit with that.","options":["Their deep focus","Their honesty","Their boundless energy"],"affirm":"Many traits called 'difficult' are strengths in disguise; naming them as strengths changes how your child sees themselves.","relearn":"A trait that looks 'difficult' is often a strength in disguise; naming it as one reshapes your child's self-image.","persona":"any","source":"strength in disguise"},
  {"id":"nd-1206","cat":"strengths-and-wellbeing","type":"reflect","hook":"Lensy: when your child is most overwhelmed, what does the calmest version of you sound like?","prompt":"Picture it.","options":["Soft and slow","'I'm right here'","Quiet and steady"],"affirm":"The calmest version of you is the anchor a flooded child borrows; your steadiness is what co-regulation is made of.","relearn":"Your calm, steady voice is the anchor an overwhelmed child borrows to find their way back to calm.","persona":"Meena","source":"calmest version of you"},
  {"id":"nd-1207","cat":"strengths-and-wellbeing","type":"spot","hook":"Spot the two lines that punish self-soothing instead of allowing it.","scene":[{"id":"a","text":"'Squeeze your fidget toy if it helps'","trick":false},{"id":"b","text":"'Stop flapping, people will laugh'","trick":true},{"id":"c","text":"'Rock as long as you need to'","trick":false},{"id":"d","text":"'Sit still and stop the noises'","trick":true},{"id":"e","text":"'Your headphones are right here'","trick":false}],"why":"'Stop flapping' and 'sit still, stop the noises' punish self-soothing; the rest allow the stims and tools that calm your child.","relearn":"Allow stimming, rocking and sensory tools that self-soothe your child; punishing them adds stress, not control.","persona":"any","source":"allow self-soothing"},
  {"id":"nd-1208","cat":"strengths-and-wellbeing","type":"role-play","persona":"Meena","source":"called weird at school","hook":"Your daughter had a hard day at school because of what some kids said.","setup":"She climbs into the auto beside you, eyes red.","steps":[{"prompt":"Your daughter says: \"They called me weird. Am I weird?\"","options":[{"text":"\"Different isn't weird. Your mind sees what theirs can't.\"","then":"She sniffles. \"Like what things?\" she asks, leaning towards you.","best":true},{"text":"\"Just try to act a bit more like the other girls do.\"","then":"She goes still and watches the other girls on the pavement, as if to learn from them."},{"text":"\"Kids can be mean. Ignore them and they will stop.\"","then":"She nods but doesn't believe it. The hurt stays."},{"text":"\"You're not weird. You're just a little bit quirky.\"","then":"She frowns. \"Quirky is the same as weird,\" she says."}],"why":"Reframing 'weird' as a special way of seeing builds her self-worth, not a mask."},{"prompt":"At home she says: \"I don't want to go to school tomorrow.\"","options":[{"text":"\"Tell me more. What would help you tomorrow?\"","then":"She thinks. \"Maybe sitting with Nisha,\" she says, and looks less alone.","best":true},{"text":"\"You have to go. Running away won't help you.\"","then":"She nods, pale, and stays awake half the night."},{"text":"\"Okay, you can stay home till it blows over.\"","then":"She relaxes at once. Two days later she goes back, dreading it even more."},{"text":"\"Just say hi to them first and they'll be friendly.\"","then":"She tries it. No one answers her, and she comes home crushed."}],"why":"Listening for what would help her lets you plan together, not make a demand."},{"prompt":"Later that week she asks: \"Nisha told them to stop. Was that okay?\"","options":[{"text":"\"Yes. Friends who stand up for you are precious.\"","then":"She beams. \"I'll make her a card,\" she says, and starts drawing.","best":true},{"text":"\"Nisha shouldn't fight your battles. Handle it yourself.\"","then":"She looks down. She feels she cannot count on anyone."},{"text":"\"Tell Nisha not to bother. It only makes things worse.\"","then":"She nods, and Nisha is quieter the next day."},{"text":"\"Nisha is the only friend you need, beta.\"","then":"She writes Nisha's name in her diary. Other kids stay strangers."}],"why":"Valuing friends who stand up for her helps her build a circle of people she can rely on."},{"prompt":"A week later she asks: \"Can I wear my sparkly headphones to school? Some kids will laugh.\"","options":[{"text":"\"Yes, if they help. Shall I tell your teacher?\"","then":"She grins and nods. The teacher lets her keep them on and will watch for teasing.","best":true},{"text":"\"Only if you take them off in the corridor.\"","then":"She tugs them off at the door and walks in flinching."},{"text":"\"Wear a cap instead, so it looks more normal.\"","then":"She wears the cap, and the noise still hurts. She hates it."},{"text":"\"No, they'll only make things worse for you.\"","then":"She nods, and leaves the headphones on her desk. School feels louder."}],"why":"Backing her tool and telling the teacher, with her okay, says she deserves comfort and help, not camouflage."}],"relearn":"Reframing 'weird' as a special way of seeing builds a child's self-worth; 'act like the others' teaches her to mask."},
  {"id":"nd-1209","cat":"strengths-and-wellbeing","type":"role-play","persona":"any","source":"finished the puzzle","hook":"Your child finally finished a puzzle that had frustrated them for days.","setup":"They hold up the last piece with shaking hands.","steps":[{"prompt":"Your child says: \"I did it! It took forever!\"","options":[{"text":"\"You stuck with it even when it was hard. Look at that.\"","then":"They grin and point at the tricky corner. \"That bit made me so cross,\" they say.","best":true},{"text":"\"About time. You should have finished ages ago.\"","then":"Their grin fades. They push the puzzle away."},{"text":"\"Great. Now try a harder one, since this was easy.\"","then":"They frown. \"It wasn't easy,\" they say, and the joy dips."},{"text":"\"Well done. Now clear up all the pieces, please.\"","then":"They nod, sweeping the pieces into the box, the glow gone."}],"why":"Naming their effort and patience turns a hard win into real pride."},{"prompt":"They ask: \"Can I do the big one now?\"","options":[{"text":"\"Yes. Pick it, and we'll take breaks if needed.\"","then":"They choose it eagerly and set a snack next to the box.","best":true},{"text":"\"Not yet. Do a few easy ones first, okay?\"","then":"They sigh and sort corner pieces they finished long ago."},{"text":"\"Sure, but it's harder, so don't get upset.\"","then":"They pick up the box but check your face after each piece."},{"text":"\"That one is for older kids. Stick with this.\"","then":"They put the box on the shelf, looking at it now and then."}],"why":"Trusting them with the next challenge, with breaks built in, feeds their confidence."},{"prompt":"Later, they say: \"I threw a piece when I was stuck. Am I bad?\"","options":[{"text":"\"No. You felt stuck, and you kept going.\"","then":"They nod slowly. \"Next time I'll take a walk,\" they say.","best":true},{"text":"\"Yes, throwing is wrong. Don't do it again.\"","then":"They go quiet and fold the puzzle away in the box."},{"text":"\"Don't worry. Everyone throws things sometimes.\"","then":"They shrug, and don't quite believe it."},{"text":"\"You shouldn't have got so frustrated in the first place.\"","then":"They study their hands, ashamed of the feeling itself."}],"why":"Accepting the frustration while praising persistence teaches them feelings aren't bad."}],"relearn":"Naming persistence and effort behind a hard-won win builds confidence; 'about time' sours it with shame."},
  {"id":"nd-1260","cat":"support-and-you","type":"strike-rewrite","hook":"\"A good mother manages her child alone and never needs anyone's help.\"","myth":{"un":"A good mother manages her child alone and never needs anyone's help.","re":"Leaning on a support network sustains you; doing it all alone is how devoted parents burn out.","why":"A sustained parent can sustain their child."},"relearn":"A good parent isn't one who copes alone; sharing the load and leaning on support keeps you going.","persona":"Meena","source":"not alone"},
  {"id":"nd-1261","cat":"support-and-you","type":"strike-rewrite","hook":"\"My own rest is selfish; every minute must go to my neurodiverse child.\"","myth":{"un":"My own rest is selfish; every minute must go to my neurodiverse child.","re":"Your rest isn't selfish; a rested parent has the patience and energy their child needs day after day.","why":"You can't pour from an empty cup."},"relearn":"Resting isn't selfish; your own wellbeing is part of your child's support, not a betrayal of it.","persona":"Divya","source":"rest not selfish"},
  {"id":"nd-1262","cat":"support-and-you","type":"strike-rewrite","hook":"\"There's a quick cure online if I just pay enough. It'll fix my child.\"","myth":{"un":"There's a quick cure online if I just pay enough. It'll fix my child.","re":"There's no miracle cure to buy; understanding, accommodation and qualified support are what truly help.","why":"Anyone selling a cure is selling false hope."},"relearn":"Chasing a paid 'cure' wastes hope and money; real support comes from understanding and qualified help.","persona":"any","source":"no miracle cure"},
  {"id":"nd-1263","cat":"support-and-you","type":"strike-rewrite","hook":"\"I have to be the expert and know every answer about my child's needs.\"","myth":{"un":"I have to be the expert and know every answer about my child's needs.","re":"You don't have to know it all; a learning, loving, supported parent is exactly what your child needs.","why":"Loving and learning beats knowing everything."},"relearn":"You don't have to be all-knowing; a learning, loving, supported parent is enough for your child.","persona":"any","source":"learning is enough"},
  {"id":"nd-1264","cat":"support-and-you","type":"strike-rewrite","hook":"\"Asking a relative to help means admitting I can't cope as a parent.\"","myth":{"un":"Asking a relative to help means admitting I can't cope as a parent.","re":"Bringing a willing relative in doubles your child's champions; asking for help is strength, not weakness.","why":"More hands mean more love around your child."},"relearn":"Asking a relative to help isn't failure; it shares the load and gives your child another champion.","persona":"Vikram","source":"ask for help"},
  {"id":"nd-1265","cat":"support-and-you","type":"strike-rewrite","hook":"\"Joining a parent support group is just sitting around complaining.\"","myth":{"un":"Joining a parent support group is just sitting around complaining.","re":"A parent support group offers real understanding and practical tips from people who truly get it.","why":"Shared experience hands you tools and relief."},"relearn":"A parent support group isn't just complaining; it gives understanding and practical tips that help.","persona":"any","source":"support group helps"},
  {"id":"nd-1266","cat":"support-and-you","type":"strike-rewrite","hook":"\"If I admit I'm struggling, people will think I don't love my child.\"","myth":{"un":"If I admit I'm struggling, people will think I don't love my child.","re":"Being honest that it's hard isn't a lack of love; it opens the door to the support that sustains you both.","why":"You can love fiercely and still be tired."},"relearn":"Admitting it's hard doesn't mean you love your child less; honesty lets the support you need in.","persona":"Divya","source":"honesty not failure"},
  {"id":"nd-1267","cat":"support-and-you","type":"strike-rewrite","hook":"\"A diagnosis app or quiz can tell me exactly what my child has.\"","myth":{"un":"A diagnosis app or quiz can tell me exactly what my child has.","re":"An app or quiz can't diagnose; only a qualified professional can assess and guide your child's care.","why":"A tool points you to a professional, never replaces one."},"relearn":"An app can't diagnose your child; a qualified professional assesses and guides specific care.","persona":"any","source":"not a quiz"},
  {"id":"nd-1268","cat":"support-and-you","type":"match","hook":"Match each parent worry to the right kind of support.","pairs":[{"left":"Feeling utterly alone","right":"Other parents who truly get it"},{"left":"Unsure of the diagnosis","right":"A qualified professional's assessment"},{"left":"Out of patience and energy","right":"Your own wellbeing care (g63)"},{"left":"No idea what strategy fits","right":"A therapist's tailored plan"},{"left":"A relative who wants to help","right":"A simple way to understand and act"}],"relearn":"Loneliness, uncertainty, exhaustion, strategy and a willing relative each have a support that fits.","persona":"any","source":"worry to support"},
  {"id":"nd-1269","cat":"support-and-you","type":"match","hook":"Match each helper to what they best offer a parent.","pairs":[{"left":"A peer parent","right":"Lived understanding and practical tips"},{"left":"A child therapist","right":"Assessment and tailored strategies"},{"left":"Looking After You (g63)","right":"Care for your own energy"},{"left":"A grandparent","right":"Extra hands and steady love"},{"left":"Tele-MANAS","right":"Free mental-health support, 14416"}],"relearn":"Peers, therapists, g63, family and Tele-MANAS each give a parent a different, real kind of support.","persona":"any","source":"helper to offer"},
  {"id":"nd-1270","cat":"support-and-you","type":"match","hook":"Match each tired moment to a small step that refills you.","pairs":[{"left":"Running on no sleep","right":"Trade a night shift with your partner"},{"left":"Haven't seen a friend in weeks","right":"A short call while the kettle boils"},{"left":"Carrying it all in your head","right":"Write one worry down and share it"},{"left":"No moment to yourself","right":"Ten quiet minutes that are just yours"},{"left":"Stuck on a hard day","right":"Message a parent who understands"}],"relearn":"Even on a hard day, small steps like a swap, a call, a note or ten minutes quietly refill a parent.","persona":"Divya","source":"tired to step"},
  {"id":"nd-1271","cat":"support-and-you","type":"match","hook":"Match each question a parent has to who can best answer it.","pairs":[{"left":"\"Does my child need assessing?\"","right":"A qualified professional"},{"left":"\"How did you handle bedtime?\"","right":"Another neurodiverse child's parent"},{"left":"\"What helps him learn at school?\"","right":"His teacher and a learning-support plan"},{"left":"\"Why am I so drained?\"","right":"Looking After You (g63)"},{"left":"\"Can I just talk to someone now?\"","right":"Tele-MANAS, 14416"}],"relearn":"Each parent question has a right place to ask: assessment, daily tips, school support, your own energy, someone now.","persona":"any","source":"question to who"},
  {"id":"nd-1272","cat":"support-and-you","type":"match","hook":"Match each way to bring family in to what it gives your child.","pairs":[{"left":"Explain his profile simply","right":"Relatives who understand, not judge"},{"left":"Give one concrete task","right":"A grandparent who helps, not hovers"},{"left":"Share what calms him","right":"Aunts and uncles who soothe, not scold"},{"left":"Invite them to a good day","right":"Bonds built on his strengths"},{"left":"Set a respectful limit","right":"Family who back you up"}],"relearn":"Explaining, giving a task, sharing what calms, inviting them in and setting limits turn family into champions.","persona":"Vikram","source":"family in"},
  {"id":"nd-1273","cat":"support-and-you","type":"match","hook":"Match each thing a parent might chase to whether it truly helps.","pairs":[{"left":"A 'special diet that cures it'","right":"False hope, no real help"},{"left":"A qualified assessment","right":"A real door to support"},{"left":"Coping in total silence","right":"Isolation that wears you down"},{"left":"A peer parent group","right":"Understanding and shared tips"},{"left":"Honest 'I need help'","right":"Support that sustains you"}],"relearn":"Cures and silence wear a parent down; assessment, peers and honest asks truly help.","persona":"any","source":"chase or help"},
  {"id":"nd-1274","cat":"support-and-you","type":"match","hook":"Match each parent feeling to a gentle reminder.","pairs":[{"left":"\"I should manage alone\"","right":"Support is wise, not weak"},{"left":"\"I must be perfect\"","right":"Learning and loving is enough"},{"left":"\"My rest is selfish\"","right":"A rested parent shows up better"},{"left":"\"No one understands\"","right":"Peer parents truly do"},{"left":"\"It's all on me\"","right":"Champions can be invited in"}],"relearn":"Each heavy feeling has a truer reminder: support is wise, learning is enough, rest helps, you're not alone.","persona":"any","source":"feeling to reminder"},
  {"id":"nd-1275","cat":"support-and-you","type":"match","hook":"Match each support route to the relief it brings.","pairs":[{"left":"A WhatsApp group of ND parents","right":"Quick tips at 2am from people who get it"},{"left":"A standing weekly handover","right":"One evening that's reliably yours"},{"left":"A therapist on retainer","right":"Strategies tailored to your child"},{"left":"A trusted relative on call","right":"Backup when you're stretched thin"},{"left":"Your own check-in via g63","right":"Catching burnout before it lands"}],"relearn":"A parent group, a handover, a therapist, a relative and a self check-in each bring their own real relief.","persona":"any","source":"route to relief"},
  {"id":"nd-1276","cat":"support-and-you","type":"branch","persona":"Divya","source":"arrange a break","hook":"You haven't slept in weeks and snapped at your child today.","steps":[{"prompt":"Your child is quiet after your outburst, and you feel wrung out. What do you do?","options":[{"text":"Ask a relative to take a night shift","then":"Your mother agrees to take the night. You lie down at eight and wake at six.","best":true},{"text":"Vow to try harder and push through alone","then":"You clench your jaw and keep going. By afternoon your patience is thinner."},{"text":"Plan to sleep properly once things calm down","then":"Things never calm down. The tiredness stacks up behind the plan."},{"text":"Stay awake blaming yourself and replaying it","then":"You lie awake replaying it till three. Morning arrives with no rest."}],"why":"A real break needs someone else to take a shift, and it starts with asking."},{"prompt":"The next day, your child asks why you were so cross yesterday. What do you say?","options":[{"text":"Say you were tired and sorry, and it was not his fault","then":"He nods slowly and leans his head on your arm. \"Okay,\" he says.","best":true},{"text":"Say he was being difficult and you had had enough","then":"He goes still and watches your face for the rest of the day."},{"text":"Say nothing was wrong, and change the subject","then":"He frowns. He knows something was wrong, and stops asking."},{"text":"Promise you will never be cross with him again","then":"He holds you to it, and looks stricken the next time you sigh."}],"why":"Owning the outburst, and saying it wasn't his fault, repairs trust with him."},{"prompt":"A neighbour says you look worn out and offers to help. What do you say?","options":[{"text":"Say yes, and ask her to sit with him on Saturday","then":"She turns up at nine with a book. You sleep until noon, undisturbed.","best":true},{"text":"Say you're fine and don't want to be a burden","then":"She nods and leaves, unsure. You lie awake that night thinking of the offer."},{"text":"Say thanks, but don't say what you actually need","then":"She says to call anytime. You never do, because you never named a need."},{"text":"Say you'll call if things ever get much worse","then":"She agrees. Things get worse, and you don't call."}],"why":"Naming exactly what you need turns a kind offer into real rest."},{"prompt":"A month on, your partner says you are still doing too much. What do you do?","options":[{"text":"Sit down and split the tasks into a weekly plan","then":"You share a chart. He takes mornings and you take evenings. Sundays are yours.","best":true},{"text":"Insist to him that you have it all under control","then":"He shrugs. The strain returns within a week."},{"text":"Hand him everything and step away for a week","then":"He struggles for days without a plan, and the household frays."},{"text":"Keep a mental list of everything he isn't doing","then":"The list grows quietly. Resentment sits between you at dinner."}],"why":"A shared, written plan spreads the load so no one runs on empty."}],"debrief":"When worn down, arrange a real break. A rested parent sustains their child.","relearn":"Don't just push harder on empty; arrange a break and share a shift so you can keep showing up."},
  {"id":"nd-1277","cat":"support-and-you","type":"branch","persona":"any","source":"check the cure","hook":"A neighbour swears a special diet cured a child's autism.","steps":[{"prompt":"She hands you a printed diet plan at the gate. What do you do?","options":[{"text":"Thank her, and check with your professional first","then":"She nods. \"Let me know what they say,\" she says. You put the plan in a drawer.","best":true},{"text":"Let the family decide about the plan over dinner","then":"Everyone has a view, and the questions about when you will start come daily."},{"text":"Start the diet strictly tonight, before asking anyone","then":"Your child eats almost nothing for three days and cries at mealtimes."},{"text":"Read reviews about it online for a week first","then":"The reviews glow and none is from a professional. You feel more tempted."}],"why":"Checking with a professional keeps your child safe, and no diet cures autism."},{"prompt":"At the appointment, the professional asks about your child's food. What do you do?","options":[{"text":"Share what your child eats and mention the plan","then":"She listens, then suggests gentle food steps that fit their sensory needs.","best":true},{"text":"Hide the plan, fearing she will think you gullible","then":"She goes on without knowing. The plan stays in your bag."},{"text":"Say doctors are too quick to dismiss natural cures","then":"She explains gently, but the visit turns into a debate and the time runs out."},{"text":"Ask her to prescribe the neighbour's diet","then":"She explains politely that she cannot. The visit ends in frustration."}],"why":"Being open about what you are hearing lets the professional guide you safely."},{"prompt":"Weeks later, the neighbour asks how the diet is going. What do you say?","options":[{"text":"Say you checked with your professional, and thank her","then":"She nods, a little embarrassed. \"I only wanted to help,\" she says.","best":true},{"text":"Say it's going well, to avoid an awkward talk","then":"She tells three other mothers it works. Soon they ask you for the plan."},{"text":"Say her diet is a scam and she should stop pushing it","then":"She goes pale and stops speaking to you at the gate."},{"text":"Say you'll give it a proper go soon, to keep her happy","then":"She beams and checks on you every week. The pressure builds."}],"why":"Thanking her while naming your professional keeps the friendship and the facts."}],"debrief":"Run any 'cure' claim past a professional; no diet cures neurodivergence.","relearn":"There's no miracle cure; check any big claim with a professional rather than chasing it on hope."},
  {"id":"nd-1278","cat":"support-and-you","type":"branch","persona":"Divya","source":"find peers","hook":"You feel completely alone, as if no one understands your child.","steps":[{"prompt":"Your child is finally asleep and the house is quiet. What do you do?","options":[{"text":"Look for a parent group for neurodiverse kids","then":"You find two groups. One meets on Saturdays and has an online chat you can read tonight.","best":true},{"text":"Decide no one could understand and stay silent","then":"The evening passes in silence. The loneliness settles a little deeper."},{"text":"Scroll social media for other families' perfect days","then":"The smiling photos make your tired house feel smaller."},{"text":"Vent to your relatives about how nobody helps you","then":"They sympathise, then offer advice that doesn't fit. You feel more unheard."}],"why":"Other parents of neurodiverse children understand in a way few others can."},{"prompt":"A friend forwards an online parent group's welcome post for new members. What do you do?","options":[{"text":"Write a short hello, saying you're new and tired","then":"Five people reply within an hour. One writes, \"Same here. Welcome. It gets easier.\"","best":true},{"text":"Read every post and never write anything","then":"You read for an hour. Nobody knows you are there, and you feel outside a window."},{"text":"Ask if anyone knows a doctor to fix your child","then":"Replies pile up with sales pitches for costly programmes, and few kind ones."},{"text":"Wait until you feel surer about joining in","then":"The week passes. The welcome post slides down the page."}],"why":"A short hello is enough to be seen, and it lets others reach for you."},{"prompt":"The group posts an open coffee meet for parents on Saturday. What do you do?","options":[{"text":"Go, and allow yourself to leave after an hour","then":"Six parents share a table and a plate of samosas. Nobody asks you to explain anything.","best":true},{"text":"Skip it, since you're too tired to be good company","then":"You stay home, and Saturday feels long."},{"text":"Ask the organiser what the others are like first","then":"The organiser sends photos and names. By the time you decide, the meet has moved."},{"text":"Say you'll come, then cancel that morning","then":"You send a sorry text at nine. The organiser replies with a heart, and you feel worse."}],"why":"Showing up for an hour, even tired, is how these connections start."},{"prompt":"Two weeks later, your sister-in-law asks how you have really been. What do you say?","options":[{"text":"Say you've felt alone, and ask her to learn with you","then":"She puts down her cup. \"Show me what I should know,\" she says softly.","best":true},{"text":"Say it's nothing, just a busy few weeks","then":"She smiles and drops it. The loneliness stays a secret you carry alone."},{"text":"Say she wouldn't understand it anyway, so why explain","then":"Her face closes. \"Fine,\" she says, and keeps her distance."},{"text":"Tell her about the new group, but not how you feel","then":"She says she's glad you found them. The loneliness at home stays unsaid."}],"why":"Telling her you feel alone, and inviting her in, opens the door to family support."},{"prompt":"A new mother at pickup says she feels completely alone with her child. What do you do?","options":[{"text":"Tell her you felt this too, and share one tip","then":"She lets out a breath. \"That helps more than you know,\" she says.","best":true},{"text":"Smile, say all mothers feel that, and hurry off","then":"She nods and goes quiet, still unsure anyone hears her."},{"text":"Tell her it will get easier, and nothing more","then":"She thanks you politely. The message feels thin."},{"text":"Give her a long list of therapies to try","then":"She reads it and feels the pressure of everything she is not doing."}],"why":"Telling another parent she isn't alone, and swapping what helps, builds the network."}],"debrief":"Seek other parents of neurodiverse kids; their tips remind you you're not alone.","relearn":"You're not alone; find a parent group whose understanding and tips lighten the load."},
  {"id":"nd-1279","cat":"support-and-you","type":"branch","persona":"Vikram","source":"share with partner","hook":"Your partner Kavya says you are better with your son and steps back.","steps":[{"prompt":"Kavya heads out as your son's homework meltdown begins. What do you do?","options":[{"text":"Handle it now, then ask her calmly to talk later","then":"It passes. That night Kavya listens, arms folded, and says she is scared of getting it wrong.","best":true},{"text":"Sigh and handle it silently, as you always do","then":"You calm him alone, as before. The heaviness in your chest settles in."},{"text":"Call after her that she never helps with him","then":"Kavya stops in the hall. \"That's not fair,\" she says, and the evening cools."},{"text":"Tell yourself she is just tired and let it pass","then":"You excuse her. The pattern repeats the next day."}],"why":"Handling it now and talking calmly later keeps your son safe and opens the real issue."},{"prompt":"Kavya says she is afraid of making things worse with him. What do you say?","options":[{"text":"Say you were unsure too, and offer to learn together","then":"She looks up at you. \"Would you show me what calms him?\" she asks.","best":true},{"text":"Say she just needs to try harder to bond with him","then":"She turns away. \"Try harder? I try every day,\" she says."},{"text":"Say you'll keep handling it, so she needn't worry","then":"She sighs with relief and keeps her distance. The load stays yours."},{"text":"Say nothing and hope she works it out herself","then":"The silence stretches. Kavya goes to bed early, still unsure."}],"why":"Admitting you were unsure too makes it safe for her to step in."},{"prompt":"On Saturday, Kavya offers to try the morning routine while you watch. What do you do?","options":[{"text":"Watch quietly, then share one thing that worked","then":"The morning is rocky, but your son lets her hold the toothbrush. She grins at you.","best":true},{"text":"Correct her at every step so it goes right","then":"She stops trying by breakfast. The routine goes back to you."},{"text":"Say it's quicker if you just do it yourself","then":"She hands over the toothbrush. She looks relieved and small."},{"text":"Leave the room so she can manage alone","then":"Without any tips, it goes messy. She says she never wants to try again."}],"why":"Letting her try, with one gentle tip, builds her confidence and his trust."},{"prompt":"A month later, your son asks Kavya for help with his shoes. What do you do?","options":[{"text":"Stay quiet and let them work it out together","then":"She kneels down and finds a way. He beams. \"Mama did it,\" he says.","best":true},{"text":"Step in quickly, in case she is too slow","then":"He turns to you. Kavya sits back, shoulders dropping."},{"text":"Tell your son to ask you, since you know how","then":"He shifts to you, and Kavya's face falls."},{"text":"Offer a tip aloud so she does it your way","then":"She stiffens. \"I know,\" she says, and the ease is gone."}],"why":"Holding back lets your son see two champions, and lets her grow."}],"debrief":"Don't carry it all alone; bring your co-parent in to share the load as a team.","relearn":"Invite your co-parent to learn and share the load; two champions beat one exhausted parent."},
  {"id":"nd-1280","cat":"support-and-you","type":"branch","persona":"Divya","source":"reach for yourself","hook":"You suspect your own low mood has tipped into something heavier.","steps":[{"prompt":"The heaviness has stayed for weeks and getting up is hard. What do you do?","options":[{"text":"Call Tele-MANAS 14416 and tell them how you feel","then":"A calm voice at Tele-MANAS listens without hurrying. You cry a little, and they stay with you.","best":true},{"text":"Tell yourself you have no right to struggle and bury it","then":"You smile through the day. At night the weight is heavier."},{"text":"Wait until your child is more settled to look after yourself","then":"Your child settles a little. Then a new worry arrives. The weight is still there."},{"text":"Push through with extra work so you don't think","then":"The extra work fills your hours. The heaviness is waiting when you stop."}],"why":"Feeling this way is not your fault or a failing. Reaching out is how you keep going for your child."},{"prompt":"A friend notices you seem flat and asks gently how you are. What do you say?","options":[{"text":"Tell her honestly that you've been struggling lately","then":"Her face softens. \"Thank you for telling me. What would help most?\" she asks.","best":true},{"text":"Say you're fine, just tired, and change the subject","then":"She lets it go for now, but you catch her watching you."},{"text":"Say you don't want to burden her with it","then":"She says she wouldn't mind. You still say no, and she looks unsure."},{"text":"Joke that all mothers feel like this sometimes","then":"She laughs along, but her eyes stay worried."}],"why":"Telling one person the truth breaks the silence and brings real support closer."},{"prompt":"A week later, your friend comes back to it and suggests seeing a professional. What do you say?","options":[{"text":"Yes. Will you help me find someone? I'll book.","then":"She finds two names by evening. You book the earlier one and feel your shoulders drop.","best":true},{"text":"I'll think about it after the school term ends","then":"The term ends and another begins. You keep saying soon."},{"text":"I don't need a professional. I just need sleep","then":"She nods, unsure. The low mood shows in your face all week."},{"text":"Just send me some tips, and I'll handle it at home","then":"She sends a few links. You read one, and the heaviness stays."}],"why":"Booking help while someone stands beside you makes the first step real."}],"debrief":"Your low mood matters and is not your fault. Reach out to Tele-MANAS 14416 or Looking After You.","relearn":"Your wellbeing matters too; reach out to Tele-MANAS 14416 or Looking After You rather than burying it."},
  {"id":"nd-1281","cat":"support-and-you","type":"branch","persona":"any","source":"guide grandparent in","hook":"Since your child's diagnosis, their Nani hovers nearby, unsure what to do.","steps":[{"prompt":"Your child's Nani says she wants to help but does not get it. What do you do?","options":[{"text":"Give her a simple explanation and one way to help","then":"She listens and nods. \"I can pick them up from school on Tuesdays,\" she says.","best":true},{"text":"Wave her off, since explaining feels like too much","then":"She retreats to her kitchen. The offer sits unused between you."},{"text":"Hand her a long article and expect her to read it","then":"She squints at the printout and puts it aside. It stays unread."},{"text":"Tell her to just love your child and not worry","then":"She smiles, reassured, and still doesn't know what to do."}],"why":"A simple explanation plus one clear task turns willingness into real help."},{"prompt":"A week later, a meltdown starts while Nani is with your child, and she calls you. What do you say?","options":[{"text":"Tell her to stay calm, keep them safe, and wait","then":"Nani sits on the floor beside them. When it passes she says it was hard for them.","best":true},{"text":"Tell her to firmly order them to stop it","then":"Nani tries. The screaming grows and she calls again in a panic."},{"text":"Say you'll come at once and take over from her","then":"You rush over. She feels she failed and doesn't offer again."},{"text":"Tell her to give them sweets to quieten them","then":"The sweet goes ignored. Nani looks helpless."}],"why":"A calm, simple instruction lets her help right away and keeps your child safe."},{"prompt":"Weeks later, Nani says a neighbour told her diets can cure your child. What do you say?","options":[{"text":"Say no diet cures it, then ask the professional","then":"Nani nods. \"Yes, ask her. I don't want to harm them,\" she says.","best":true},{"text":"Say you'll try it, if it makes her happy","then":"Nani starts the diet with joy. Your child eats little and grows tired."},{"text":"Say she must stop listening to the neighbours","then":"Nani's face closes. She says less about your child after that."},{"text":"Say nothing and let her try new things quietly","then":"Nani slips new foods onto the plate. Your child refuses lunch for days."}],"why":"Working together with the professional keeps Nani included and your child safe."}],"debrief":"Guide a willing grandparent in with a simple explanation and a task.","relearn":"Bring a willing relative in with a simple explanation and one concrete task; don't waste the offer."},
  {"id":"nd-1282","cat":"support-and-you","type":"branch","persona":"Divya","source":"guilt-free break","hook":"Your friend Nisha offers to watch your child for two hours so you can rest, and guilt creeps in.","steps":[{"prompt":"Nisha is at the door, bag in hand. What do you do?","options":[{"text":"Cancel, saying he is too much for anyone else","then":"Nisha shrugs and leaves. You stay home, and your shoulders stay tight all afternoon."},{"text":"Thank her, leave a short note on his routine and go","then":"Nisha reads the note and waves you off. You walk out slower than you expected to.","best":true},{"text":"Go, but check your phone every ten minutes","then":"You sit in the cafe with your phone face up. Nisha sends photos, and you barely taste your tea."},{"text":"Accept, then spend the two hours scrubbing the kitchen","then":"When Nisha leaves, you are more tired than before, and the kitchen is spotless."}],"why":"A real break, with his routine shared, lets you rest and return steadier."},{"prompt":"Later that day, the guilt returns about needing a rest at all. What do you tell yourself?","options":[{"text":"I will earn this rest by doing extra tomorrow","then":"You start a list of chores for tomorrow. The rest feels borrowed, not yours."},{"text":"I will take proper breaks once things settle down","then":"You nod, but things rarely settle. The rest you promise yourself keeps slipping away."},{"text":"Rest is part of how I look after him","then":"The thought settles. You let yourself sit quietly for a few minutes.","best":true},{"text":"Other parents don't seem to need breaks like this","then":"You picture a mother from the playground who never complains. Your chest tightens."}],"why":"Seeing rest as part of caring for him lets you refill without borrowing guilt."},{"prompt":"Nisha texts that she can come again next week. What do you do?","options":[{"text":"Say maybe, and see how the week goes","then":"Nisha replies that it is no problem. The week fills up and the slot disappears."},{"text":"Say yes, but only for an hour, to be safe","then":"She agrees. An hour is barely enough to reach the cafe and come back."},{"text":"Say thanks, but you will manage on your own","then":"Nisha sends a heart. You manage, and your energy keeps sliding."},{"text":"Say yes, and fix a regular day","then":"Nisha suggests Thursdays. You mark it in your calendar and it starts to feel real.","best":true}],"why":"A regular slot makes rest dependable, so you refill before you run empty."}],"debrief":"Take the offered break without guilt; your own refill is part of your child's support.","relearn":"A break isn't neglect; let it refill you so you return steadier and more present."},
  {"id":"nd-1283","cat":"support-and-you","type":"sort","hook":"Sort: a wise step for a parent, or one to rethink?","items":[{"id":"a","text":"Joining a parent support group"},{"id":"b","text":"Chasing a paid 'miracle cure'"},{"id":"c","text":"Seeing a qualified professional"},{"id":"d","text":"Coping in silence and isolation"},{"id":"e","text":"Being honest you need help"},{"id":"f","text":"Running on empty alone"}],"bins":[{"id":"wise","label":"Wise step","valence":"pos"},{"id":"rethink","label":"Rethink it","valence":"neg"}],"key":{"a":"wise","b":"rethink","c":"wise","d":"rethink","e":"wise","f":"rethink"},"relearn":"Groups, professionals and honest asks are wise; cures, silence and running on empty need a rethink.","persona":"any","source":"wise vs rethink"},
  {"id":"nd-1284","cat":"support-and-you","type":"sort","hook":"Sort: sustains a parent for the long haul, or burns them out?","items":[{"id":"a","text":"Sharing the load with someone"},{"id":"b","text":"Never once asking for help"},{"id":"c","text":"Resting when you can"},{"id":"d","text":"Carrying every task alone"},{"id":"e","text":"Leaning on a support network"},{"id":"f","text":"Skipping all your own needs"}],"bins":[{"id":"sustain","label":"Sustains you","valence":"pos"},{"id":"burn","label":"Burns you out","valence":"neg"}],"key":{"a":"sustain","b":"burn","c":"sustain","d":"burn","e":"sustain","f":"burn"},"relearn":"Sharing, resting and a network sustain you; never asking, doing it all and skipping your needs burn you out.","persona":"any","source":"sustain vs burn"},
  {"id":"nd-1285","cat":"support-and-you","type":"sort","hook":"Sort: who can a parent turn to for real support, or not the right place?","items":[{"id":"a","text":"A qualified professional for assessment"},{"id":"b","text":"A stranger selling a 'cure'"},{"id":"c","text":"Other parents of neurodiverse kids"},{"id":"d","text":"An anonymous forum's medical 'advice'"},{"id":"e","text":"Tele-MANAS for mental-health support"},{"id":"f","text":"A salesman pushing a gadget fix"}],"bins":[{"id":"real","label":"Real support","valence":"pos"},{"id":"not","label":"Not the place","valence":"neg"}],"key":{"a":"real","b":"not","c":"real","d":"not","e":"real","f":"not"},"relearn":"Professionals, peer parents and Tele-MANAS are real support; cure-sellers and gadget pitches are not.","persona":"any","source":"real support or not"},
  {"id":"nd-1286","cat":"support-and-you","type":"sort","hook":"Sort: a sign you need to refill, or a sign you're coping well?","items":[{"id":"a","text":"Snapping at everyone lately"},{"id":"b","text":"Letting a relative take a shift"},{"id":"c","text":"Dreading every morning"},{"id":"d","text":"Resting without guilt"},{"id":"e","text":"Crying alone and hiding it"},{"id":"f","text":"Asking for help early"}],"bins":[{"id":"refill","label":"Time to refill","valence":"uhoh"},{"id":"coping","label":"Coping well","valence":"pos"}],"key":{"a":"refill","b":"coping","c":"refill","d":"coping","e":"refill","f":"coping"},"relearn":"Snapping, dread and hidden tears say refill; sharing shifts, guilt-free rest and asking early show coping.","persona":"Divya","source":"refill or coping"},
  {"id":"nd-1287","cat":"support-and-you","type":"sort","hook":"Sort: brings family in as champions, or pushes them away?","items":[{"id":"a","text":"Explaining his profile simply"},{"id":"b","text":"Snapping 'you wouldn't understand'"},{"id":"c","text":"Giving a relative a concrete task"},{"id":"d","text":"Hiding everything from family"},{"id":"e","text":"Sharing what calms your child"},{"id":"f","text":"Refusing every offer of help"}],"bins":[{"id":"in","label":"Brings them in","valence":"pos"},{"id":"away","label":"Pushes them away","valence":"neg"}],"key":{"a":"in","b":"away","c":"in","d":"away","e":"in","f":"away"},"relearn":"Explaining, giving a task and sharing what calms bring family in; snapping, hiding and refusing push them away.","persona":"Vikram","source":"family in or away"},
  {"id":"nd-1288","cat":"support-and-you","type":"sort","hook":"Sort: a kind thing to tell yourself, or an unfair pressure?","items":[{"id":"a","text":"\"Learning and loving is enough\""},{"id":"b","text":"\"I must have every answer\""},{"id":"c","text":"\"Asking for help is okay\""},{"id":"d","text":"\"I should never be tired\""},{"id":"e","text":"\"My rest helps my child too\""},{"id":"f","text":"\"A good parent copes alone\""}],"bins":[{"id":"kind","label":"Kind to yourself","valence":"pos"},{"id":"unfair","label":"Unfair pressure","valence":"neg"}],"key":{"a":"kind","b":"unfair","c":"kind","d":"unfair","e":"kind","f":"unfair"},"relearn":"Learning is enough, asking is okay and your rest helps; needing every answer or coping alone is unfair pressure.","persona":"any","source":"kind or pressure"},
  {"id":"nd-1289","cat":"support-and-you","type":"sort","hook":"Sort: a healthy way to handle a hard day, or one that wears you thinner?","items":[{"id":"a","text":"Texting a parent who gets it"},{"id":"b","text":"Doom-scrolling 'cures' till 2am"},{"id":"c","text":"Naming one thing that went okay"},{"id":"d","text":"Bottling it all up inside"},{"id":"e","text":"Taking ten quiet minutes"},{"id":"f","text":"Skipping meals to keep going"}],"bins":[{"id":"healthy","label":"Healthy","valence":"pos"},{"id":"thinner","label":"Wears you thin","valence":"neg"}],"key":{"a":"healthy","b":"thinner","c":"healthy","d":"thinner","e":"healthy","f":"thinner"},"relearn":"Texting a peer, naming a win and quiet minutes help; scrolling cures, bottling up and skipping meals wear you thin.","persona":"Divya","source":"healthy or thin"},
  {"id":"nd-1290","cat":"support-and-you","type":"sort","hook":"Sort: what this tool can do for you, or what only a professional can?","items":[{"id":"a","text":"Offer understanding and support"},{"id":"b","text":"Diagnose your specific child"},{"id":"c","text":"Point you to where help lives"},{"id":"d","text":"Prescribe your child's care plan"},{"id":"e","text":"Lift shame with honest reframes"},{"id":"f","text":"Formally assess your child"}],"bins":[{"id":"tool","label":"This tool can","valence":"pos"},{"id":"pro","label":"Only a professional","valence":"neutral"}],"key":{"a":"tool","b":"pro","c":"tool","d":"pro","e":"tool","f":"pro"},"relearn":"This tool offers understanding, signposting and reframes; diagnosis, a care plan and assessment need a professional.","persona":"any","source":"tool vs professional"},
  {"id":"nd-1291","cat":"support-and-you","type":"reflect","hook":"Lensy: looking after yourself isn't taking from your child. It's part of how you support them. Sit right?","prompt":"What's your take?","options":["Sits right","My wellbeing counts","Part of support"],"affirm":"Caring for yourself isn't stealing from your child; your wellbeing is part of the support you give them.","relearn":"Looking after yourself is part of supporting your child, not a betrayal of them.","persona":"Divya","source":"self-care is support"},
  {"id":"nd-1292","cat":"support-and-you","type":"reflect","hook":"Lensy: you don't have to be the perfect parent. A learning, loving, supported one is enough. Land okay?","prompt":"What do you think?","options":["Lands okay","Enough as I am","Learning is fine"],"affirm":"You don't have to be perfect or all-knowing; a learning, loving, supported parent is exactly what your child needs.","relearn":"You don't have to be perfect; a learning, loving, supported parent is enough.","persona":"any","source":"enough as you are"},
  {"id":"nd-1293","cat":"support-and-you","type":"reflect","hook":"Lensy: a parent who is sustained can sustain their child. You matter to this too. Resonate?","prompt":"What's your take?","options":["Resonates","I matter too","Sustained to sustain"],"affirm":"A sustained parent sustains their child; tending to your own energy is part of caring for them.","relearn":"A sustained parent sustains their child; you matter to your child's support too.","persona":"Meena","source":"you matter too"},
  {"id":"nd-1294","cat":"support-and-you","type":"reflect","hook":"Lensy: asking for help isn't a confession of failure. It's a sign you're parenting wisely. Agree?","prompt":"What do you think?","options":["Agree","Asking is wise","Not failure"],"affirm":"Asking for help is wise parenting, not a confession of failure; strong parents lean on support.","relearn":"Asking for help is wisdom, not failure; it's part of parenting well.","persona":"Vikram","source":"asking is wise"},
  {"id":"nd-1295","cat":"support-and-you","type":"reflect","hook":"Lensy: somewhere, other parents are walking this exact road. You are not alone in it. Sit right?","prompt":"What's your take?","options":["Sits right","Not alone","Others get it"],"affirm":"Other parents are walking this same road; their understanding reminds you that you are not alone.","relearn":"You're not alone; other parents walk this road and truly understand it.","persona":"Divya","source":"not alone in it"},
  {"id":"nd-1296","cat":"support-and-you","type":"reflect","hook":"Lensy: it's okay to grieve the hard days and still adore your child fiercely. Both can be true. Land okay?","prompt":"What do you think?","options":["Lands okay","Both true","Hard and loving"],"affirm":"You can find the days hard and love your child fiercely at once; honest feelings don't shrink your love.","relearn":"It's okay to find days hard and adore your child at once; both feelings can be true.","persona":"any","source":"both can be true"},
  {"id":"nd-1297","cat":"support-and-you","type":"reflect","hook":"Lensy: every champion you let in, like a partner, relative or friend, is one more person loving your child. Worth it?","prompt":"What's your take?","options":["Worth it","More champions","Let them in"],"affirm":"Each person you bring in to understand and help is one more champion loving and supporting your child.","relearn":"Every champion you let in is one more person loving and supporting your child.","persona":"Vikram","source":"more champions"},
  {"id":"nd-1298","cat":"support-and-you","type":"reflect","hook":"Lensy: you've learned to understand, accommodate, advocate and drop the shame. Now hold yourself gently too. Ready?","prompt":"What do you think?","options":["Ready","Gentle with me","I'm doing my best"],"affirm":"You've learned to understand, accommodate, advocate and drop the shame; holding yourself gently too is the last piece.","relearn":"Understand, accommodate, advocate, drop the shame, and be gentle with yourself too.","persona":"any","source":"gentle with yourself"},
  {"id":"nd-1299","cat":"support-and-you","type":"role-play","persona":"Priya","source":"you're not alone","hook":"Rashid, a fellow parent of a neurodiverse child, has looked more drained every week this term.","setup":"He catches you at the school gate.","steps":[{"prompt":"Rashid says: \"Some days I feel completely alone with this.\"","options":[{"text":"\"Honestly, I don't know how any of us survive it.\"","then":"Rashid laughs bitterly. \"Same. Same.\""},{"text":"\"Others have it worse. Try to stay positive.\"","then":"Rashid nods, but his eyes drop."},{"text":"\"You're not alone. Let's swap what helps.\"","then":"Rashid exhales. \"Really? I'd like that.\"","best":true},{"text":"\"You need a proper rest. Take a holiday.\"","then":"Rashid smiles wryly. \"A holiday. Right.\""}],"why":"Telling him he's not alone and offering to swap tips gives him company and something practical."},{"prompt":"A few days later, Rashid messages: \"I feel guilty complaining about my own child.\"","options":[{"text":"\"Then maybe keep it to yourself. Why worry others?\"","then":"Rashid writes: \"You're right. I'll stay quiet.\""},{"text":"\"I feel guilty too. Let's just talk about the good things.\"","then":"Rashid writes: \"True. Good things are good.\""},{"text":"\"Your child is wonderful. Focus on that, not the hard parts.\"","then":"Rashid sends a thumbs up. The guilt stays."},{"text":"\"Sharing a hard day isn't complaining. It's how we cope.\"","then":"Rashid writes: \"Okay. I'll try saying it out loud more.\"","best":true}],"why":"Naming a hard day as normal lifts the guilt and keeps him talking."},{"prompt":"Rashid says: \"There's a parent meet on Sunday. I'm nervous to go alone.\"","options":[{"text":"\"Good for you. Tell me how it goes.\"","then":"Rashid says, \"Sure.\" His smile is polite, and he goes quiet."},{"text":"\"I have a family thing that day. Maybe another time.\"","then":"Rashid says, \"No problem.\" The plan drifts away."},{"text":"\"Don't go if you're nervous. Wait until you feel ready.\"","then":"Rashid hesitates. \"Maybe next month, then.\""},{"text":"\"I'll come with you. We can sit together.\"","then":"Rashid grins. \"Thank you. I'll save two seats.\"","best":true}],"why":"Going with him turns his nerves into a first step toward a network."}],"relearn":"Telling an isolated parent they're not alone and offering to swap tips builds the network that sustains you both."},
  {"id":"nd-1300","cat":"support-and-you","type":"role-play","persona":"Vikram","source":"bring partner in","hook":"Your partner Asha loves your son but steps back whenever he gets upset.","setup":"It is late evening and the house is finally quiet.","steps":[{"prompt":"Asha says: \"You handle him. You're just better at it.\"","options":[{"text":"\"You're right. I'll keep handling it.\"","then":"Asha smiles with relief. The load stays exactly where it was."},{"text":"\"Fine. I'll just do all of it myself, like always.\"","then":"Asha looks away. \"That's not what I meant.\""},{"text":"\"That's not fair. You never even try.\"","then":"Asha's jaw tightens. \"I do try. You just don't see it.\""},{"text":"\"He needs us both. Let's learn this together.\"","then":"Asha glances up. \"Both of us? I wouldn't know how.\"","best":true}],"why":"Saying he needs you both and offering to learn together shares the load without blame."},{"prompt":"The next Saturday, Asha says: \"I never know what to say when he is upset.\"","options":[{"text":"\"Just stay calm and it will pass.\"","then":"Asha tries, but she is unsure what calm looks like."},{"text":"\"Leave it to me. It's quicker if I do it.\"","then":"Asha steps back, relieved and a little sidelined."},{"text":"\"Ask the therapist. They will tell you what to do.\"","then":"Asha says, \"Okay,\" and puts it off until the next appointment."},{"text":"\"Let's watch what calms him, together.\"","then":"Asha nods. \"Okay. Show me what you've noticed.\"","best":true}],"why":"Watching together and sharing what works gives her skills, not just instructions."},{"prompt":"Asha says: \"I feel bad that you carry more. What should I take on?\"","options":[{"text":"\"Whatever you like.\"","then":"Asha says: \"That doesn't help me decide.\""},{"text":"\"Nothing really. I'm used to it by now.\"","then":"Asha's shoulders drop. \"Alright.\""},{"text":"\"Take him to all his appointments, and I'll rest.\"","then":"Asha's eyes widen. \"All of them? With my work?\""},{"text":"\"Mornings are hardest. Could you take those?\"","then":"Asha nods. \"Mornings. I can do that.\"","best":true}],"why":"A clear split you both agree on means neither of you carries it alone."}],"relearn":"Inviting your co-parent to learn together shares the load and gives your child two engaged champions."},
  {"id":"nd-1301","cat":"support-and-you","type":"role-play","persona":"Divya","source":"be honest with a friend","hook":"Your friend Meher has a knack for noticing when you are struggling.","setup":"She catches you after school pick-up.","steps":[{"prompt":"Meher asks: \"You look worn out. How are you really doing?\"","options":[{"text":"\"Oh, we're absolutely fine. Nothing to worry about.\"","then":"Meher smiles, unconvinced, and lets it go for now."},{"text":"\"It's just a busy phase. It will pass.\"","then":"Meher nods. \"Okay. Well, you know where I am.\""},{"text":"\"I love him too much to complain.\"","then":"Meher says, \"Of course you do.\" The talk moves on."},{"text":"\"Honestly, it's hard and I'm tired. I could use support.\"","then":"Meher squeezes your arm. \"I'm glad you said it. I'm here.\"","best":true}],"why":"Being honest that it's hard opens the door to help."},{"prompt":"The next week, Meher asks: \"You do so much for him. Who looks after you?\"","options":[{"text":"\"I'm fine. I'll sleep more soon.\"","then":"Meher tilts her head. \"You've said that before.\""},{"text":"\"His father helps a bit. That's enough.\"","then":"Meher says, \"Okay,\" but doesn't look convinced."},{"text":"\"Nobody has time for me, and I understand.\"","then":"Meher looks sad. \"That sounds so lonely.\""},{"text":"\"Nobody yet. Could we walk together twice a week?\"","then":"Meher smiles. \"Tuesdays and Fridays. Done.\"","best":true}],"why":"Saying you need care and asking for something specific gives her a way to give it."},{"prompt":"Two weeks on, Meher asks: \"How are you holding up now?\"","options":[{"text":"\"Fine. Same as before, really. Nothing new.\"","then":"Meher says, \"Okay,\" and doesn't push."},{"text":"\"Tired, but I don't want to bother you.\"","then":"Meher says: \"You're not a bother.\" You don't take her up on it."},{"text":"\"Much better. I don't need anything now.\"","then":"Meher smiles. \"Great.\" She stops checking in after that."},{"text":"\"Up and down. Can I call you on the bad days?\"","then":"Meher nods. \"Any time. And let's walk every week.\"","best":true}],"why":"A simple routine of support keeps you steady, better than waiting for a crash."}],"relearn":"Being honest that it's hard and you need support opens the door to the help that keeps you going."},
  {"id":"nd-1302","cat":"support-and-you","type":"role-play","persona":"any","source":"guide grandparent rp","hook":"Nanaji, your child's grandfather, is visiting for the first time since the diagnosis and seems unsure around him.","setup":"He is sitting with you on the veranda after lunch.","steps":[{"prompt":"Nanaji says: \"I don't understand all this. Maybe I should stay out of it.\"","options":[{"text":"\"Just leave it. It's too complicated to explain.\"","then":"Nanaji nods and goes quiet, but he keeps glancing at the boy."},{"text":"\"Okay. It's probably easier if you don't.\"","then":"Nanaji looks relieved. \"Yes, better.\" Still, his eyes follow the boy."},{"text":"\"You could learn if you tried. It's not that hard.\"","then":"Nanaji bristles. \"I raised four children, you know.\""},{"text":"\"Please don't. Let me explain it simply.\"","then":"Nanaji straightens. \"Yes. Please do.\"","best":true}],"why":"Explaining simply, instead of closing the door, keeps a willing grandfather in."},{"prompt":"That evening, the boy covers his ears at the TV. Nanaji asks: \"What should I know about him?\"","options":[{"text":"\"He's just wired differently. There's nothing more to say.\"","then":"Nanaji nods, but he still doesn't know what to do."},{"text":"\"The doctor said a lot. I'll send you the report.\"","then":"Nanaji frowns. \"A report? I'll ask your uncle to read it.\""},{"text":"\"He'll settle down when he's older.\"","then":"Nanaji nods, comforted. \"Children change. I'll wait and see.\""},{"text":"\"Loud noise is too much for him. He loves trains.\"","then":"Nanaji smiles. \"Trains. I have an old train set upstairs.\"","best":true}],"why":"It's lifelong, so simple facts about who he is give Nanaji something real to connect to."},{"prompt":"Before he leaves, Nanaji asks: \"Is there anything I can do for him?\"","options":[{"text":"\"Just love him. That's all he needs.\"","then":"Nanaji says: \"That I know how to do.\" Nothing concrete is planned."},{"text":"\"Be strict when he acts up, so he learns.\"","then":"Nanaji straightens. \"Strict I can do.\" At the next upset, he scolds, and it gets worse."},{"text":"\"Nothing for now. I'll tell you when I need you.\"","then":"Nanaji shrugs. \"As you like.\""},{"text":"\"Play trains with him on Sundays. He adores you.\"","then":"Nanaji's eyes shine. \"Trains? Sundays, then. I'll find my old set.\"","best":true}],"why":"Upsets are overwhelm, not naughtiness; one task he enjoys turns his goodwill into steady support."}],"relearn":"A simple explanation and one concrete task turn a willing grandparent into real, steady support."},
  {"id":"nd-1303","cat":"support-and-you","type":"role-play","persona":"any","source":"decline the cure","hook":"Your uncle Prakash dotes on your son and has been reading about his diagnosis online.","setup":"He finds you over tea at a family gathering.","steps":[{"prompt":"Prakash says: \"There's a clinic with a cure for this. It costs a lot, but it works.\"","options":[{"text":"\"Maybe you're right. Perhaps we should try it, for his sake.\"","then":"Prakash beams. \"Let me tell you what I've read.\""},{"text":"\"You don't understand anything about this.\"","then":"Prakash's face hardens. \"I'm only trying to help.\""},{"text":"\"Send me the details and I'll think about it properly.\"","then":"Prakash nods. \"I'll send it tonight. They have limited seats.\""},{"text":"\"There's no cure to buy. Support helps.\"","then":"He frowns. \"But this doctor promises results.\"","best":true}],"why":"A kind, plain \"no cure to buy\" protects your money and hope without a fight."},{"prompt":"Prakash goes on: \"Other families paid, and their children changed completely.\"","options":[{"text":"\"If it worked for them, maybe it will for us too.\"","then":"Prakash smiles. \"I have the number right here.\" The fee makes you go quiet."},{"text":"\"We can't afford it right now. Maybe later.\"","then":"Prakash says: \"I'll lend you the money.\" You don't know how to answer."},{"text":"\"Please stop. This is our family's business.\"","then":"Prakash stiffens. \"I only care about the boy.\""},{"text":"\"He's already doing well with support. That's our path.\"","then":"Prakash pauses. \"Doing well. Hm. Fair enough.\"","best":true}],"why":"Naming what actually helps, kindly, ends the pressure and keeps the focus on him."},{"prompt":"Later, Prakash says quietly: \"I just want to do something for the boy. I feel so helpless.\"","options":[{"text":"\"Nothing. Please just stop bringing it up at family gatherings.\"","then":"Prakash says: \"Fine.\" He barely speaks to you at dinner."},{"text":"\"Pay for his tuition. That would help him the most.\"","then":"Prakash nods. \"Money I can do.\" He looks as if he wants to give more than that."},{"text":"\"Just keep him in your thoughts.\"","then":"Prakash nods. \"I already do, every day. It doesn't feel like enough.\""},{"text":"\"Come to the park with us on Saturday.\"","then":"Prakash's face eases. \"I'd like that. Saturday?\"","best":true}],"why":"Inviting him into your child's life turns his worry into time spent with the boy."}],"relearn":"Gently naming that there's no cure to buy protects your money, your hope and your child from quackery."},
  {"id":"nd-1304","cat":"support-and-you","type":"role-play","persona":"Divya","source":"accept the help","hook":"You have not had a full night's rest in weeks, and taking help makes you feel guilty.","setup":"Your sister Rekha calls on a Friday evening.","steps":[{"prompt":"Rekha says: \"Let me take him tomorrow so you can rest. You look so tired.\"","options":[{"text":"\"No, no. I should be the one doing everything.\"","then":"Rekha says: \"Are you sure? The offer stands.\""},{"text":"\"Maybe next month. This month is too busy.\"","then":"Rekha says: \"Okay.\" The next month is just as busy."},{"text":"\"Sure, but I'll do the laundry while you're here.\"","then":"Rekha pauses. \"Fine. I'll come at ten. But laundry isn't rest.\""},{"text":"\"Thank you, yes. I need a real rest.\"","then":"Rekha laughs softly. \"Good. I'll come at ten.\"","best":true}],"why":"Accepting help and resting fully helps you return steadier for him."},{"prompt":"Rekha asks: \"Whenever I do come, I don't want to get anything wrong. What does he need?\"","options":[{"text":"\"Nothing special. He'll be fine with you.\"","then":"Rekha says: \"Okay. But I'm not sure what to do at lunch.\""},{"text":"\"Just keep him away from noise. I'll be back soon.\"","then":"Rekha says: \"How do I keep noise away, though?\""},{"text":"\"Maybe I should stay nearby, just in case.\"","then":"Rekha shrugs. \"Then what's the point of me coming?\""},{"text":"\"He likes a quiet routine. I'll write it down.\"","then":"\"Perfect,\" says Rekha. \"Lunch at one?\"","best":true}],"why":"A short routine note lets Rekha help with confidence, so your rest is real."},{"prompt":"Rekha says: \"I can do Saturdays for a while. Should I come?\"","options":[{"text":"\"I'll see. I feel like I'm taking too much.\"","then":"Rekha says: \"Okay. Tell me when you know.\""},{"text":"\"No, it isn't fair on you.\"","then":"Rekha says: \"I offered because I want to.\""},{"text":"\"Maybe. But don't tell Ma I'm leaving him.\"","then":"Rekha says: \"Why would I hide it?\""},{"text":"\"Yes please. Every second Saturday?\"","then":"Rekha nods. \"Every second Saturday. It's in my diary.\"","best":true}],"why":"A regular arrangement keeps your rest steady, and it is support, not neglect."}],"relearn":"Accepting offered help and rest is support, not neglect; it refills you so you return steadier."},
  {"id":"nd-1305","cat":"support-and-you","type":"role-play","persona":"any","source":"open at group","hook":"You have come to your first parent support group for neurodiverse children.","setup":"The chairs are in a circle and tea is being poured.","steps":[{"prompt":"Lata, who runs the group, asks: \"So what brings you here today?\"","options":[{"text":"\"Oh, I'm just here to watch. I don't really have problems.\"","then":"Lata nods. \"Okay. Sit anywhere.\""},{"text":"\"My relatives sent me. I'm not sure I need this.\"","then":"Lata says: \"That's fine.\" She turns to someone else."},{"text":"\"I'm here for my partner. They're the one who is struggling.\"","then":"Lata nods politely, and the talk moves on without you."},{"text":"\"I'm raising an autistic son. I'd like to learn from people who get it.\"","then":"Lata smiles. \"Welcome. We've all sat where you are.\"","best":true}],"why":"Saying plainly why you came lets people welcome you and share what helps."},{"prompt":"Lata says: \"We swap tips here. What's the hardest part of your week?\"","options":[{"text":"\"Nothing really. We're managing.\"","then":"Lata says: \"Lucky you.\" The tea goes round."},{"text":"\"Mostly other people's opinions. I can't talk about it.\"","then":"Lata nods gently. \"We all know that one.\" The circle moves on."},{"text":"\"Let me hear what you all do first.\"","then":"The tips go around. You take notes but say nothing about your son."},{"text":"\"Mornings. Getting to school takes an hour of tears.\"","then":"Two parents nod. \"Try a picture schedule,\" one says. \"It helped us.\"","best":true}],"why":"Naming one real struggle gives the group something specific to help with."},{"prompt":"Lata says: \"We stay in touch on a WhatsApp group. Want to join?\"","options":[{"text":"\"I'll think about it. I'm not much of a phone person.\"","then":"Lata smiles. \"No pressure.\" You leave without joining."},{"text":"\"Yes, but I'll only read. I won't post anything.\"","then":"Lata says: \"Fine by us.\" You read for weeks and no one knows your name."},{"text":"\"Is there a doctor in the group who can see him?\"","then":"Lata says: \"Not here. Your paediatrician can guide you to an assessment. We share, that's all.\""},{"text":"\"Yes, please. Here's my number.\"","then":"Lata adds you. Within minutes, three welcome messages appear.","best":true}],"why":"Joining the group keeps the support going after tonight."}],"relearn":"Being open in a support group lets in the understanding and practical tips it exists to share."},
  {"id":"nd-1306","cat":"support-and-you","type":"role-play","persona":"Vikram","source":"ask clearly","hook":"Months of long nights with your son have brought you close to breaking point.","setup":"Your spouse Meera finds you alone in the kitchen late at night.","steps":[{"prompt":"Meera asks: \"You look wrecked. What do you need?\"","options":[{"text":"\"Nothing. I'm fine. Don't worry about me at all.\"","then":"Meera hesitates, then goes to bed. You stay in the kitchen."},{"text":"\"You should already know what I need.\"","then":"Meera sighs. \"I don't. That's why I'm asking.\""},{"text":"\"I need everything to be less hard. I can't explain it.\"","then":"Meera says softly: \"Okay.\" She sits with you, and neither of you knows what comes next."},{"text":"\"A proper break this weekend. Can you take the mornings?\"","then":"Meera nods. \"Yes. Saturday and Sunday mornings are mine.\"","best":true}],"why":"Asking for one clear thing gives your partner something she can actually do."},{"prompt":"A few days later, Meera says: \"I want to help properly. What does a good week look like?\"","options":[{"text":"\"Just do what you can. I don't want to be demanding.\"","then":"Meera says: \"That's hard to plan around.\""},{"text":"\"Whatever you do is fine. I'll manage the rest.\"","then":"She nods, relieved. The week looks the same as before."},{"text":"\"If you had noticed sooner, we wouldn't be here.\"","then":"Meera flinches. \"That's not fair.\""},{"text":"\"Two evenings off for me. Let's write it down.\"","then":"Meera pulls out her phone. \"Okay. I'll put it on the calendar.\"","best":true}],"why":"A clear plan you both write down shares the load and makes it last."},{"prompt":"Two weeks on, Meera asks: \"How is it going now?\"","options":[{"text":"\"It's fine. I don't want to complain again.\"","then":"Meera says: \"Okay.\" The tiredness builds again."},{"text":"\"It's not enough. You still aren't doing your share.\"","then":"Meera stiffens. \"I'm trying my best.\""},{"text":"\"Can we just get through this month first, then see?\"","then":"Meera hesitates. \"If you're sure.\" The month drags on."},{"text":"\"Still tired. I'd like to talk to someone too.\"","then":"Meera nods. \"Yes. Let's find someone together.\"","best":true}],"why":"An honest update and outside support keep you going before you crash."}],"relearn":"Asking clearly for what you need lets your partner share the load before you reach a crash."},
  {"id":"nd-1307","cat":"support-and-you","type":"role-play","persona":"Priya","source":"reassure new parent","hook":"A new parent in your circle, Zoya, is panicking after a fresh diagnosis for her child.","setup":"She calls you from the clinic car park.","steps":[{"prompt":"Zoya says: \"They said autism. I don't know what to do. Is this the end of everything?\"","options":[{"text":"\"Yes, brace yourself. It only gets harder from here.\"","then":"Zoya's breathing quickens. \"How much harder?\""},{"text":"\"Don't cry. Lots of children have it. You'll be fine.\"","then":"Zoya's voice cracks. \"Okay. I'll try not to.\""},{"text":"\"Get a second opinion right away. Maybe they're wrong.\"","then":"Zoya says: \"You think they're wrong?\" Her panic rises again."},{"text":"\"It's a key to support, not a tragedy. You're not alone.\"","then":"Zoya cries quietly. \"I needed to hear that.\"","best":true}],"why":"Calm words that it is a key to support, and that she's not alone, steady her."},{"prompt":"Zoya asks: \"Did I do something wrong? Was it the phone? The pregnancy?\"","options":[{"text":"\"Maybe cut screen time, just to be safe.\"","then":"Zoya nods slowly. \"I'll cut it all today.\""},{"text":"\"Let's not go into why. It doesn't matter now.\"","then":"Zoya swallows. \"But I keep going back to it.\""},{"text":"\"Everyone wonders that. Try not to think about it.\"","then":"Zoya says: \"I can't stop thinking about it.\""},{"text":"\"No. Nothing you did caused this. It's no one's fault.\"","then":"Zoya breathes out. \"I've been asking myself that all week.\"","best":true}],"why":"Saying plainly that it is no one's fault lifts a blame that weighs on new parents."},{"prompt":"Zoya says: \"What do I do first? I feel completely lost.\"","options":[{"text":"\"Read everything online tonight and decide tomorrow.\"","then":"Zoya says: \"Okay. I'll read all night.\""},{"text":"\"Try every therapy people recommend.\"","then":"Zoya says: \"All of them? That's so much.\""},{"text":"\"Nothing yet. Just wait and see how he does.\"","then":"Zoya nods. \"Maybe I should just wait.\""},{"text":"\"Ask the team about next steps. I'll come to a parent group with you.\"","then":"Zoya nods. \"Okay. One thing at a time.\"","best":true}],"why":"One small step, with company, beats overwhelm and lets her begin steadily."}],"relearn":"Telling a frightened new parent it's a key, not a tragedy, and they're not alone steadies them."},
  {"id":"nd-1308","cat":"support-and-you","type":"role-play","persona":"Divya","source":"real with counsellor","hook":"You have felt low for weeks, and tonight you call Tele-MANAS 14416 for yourself.","setup":"After a short wait, a counsellor picks up.","steps":[{"prompt":"The counsellor asks: \"Thank you for calling. What has been going on for you?\"","options":[{"text":"\"It's nothing really. I just have a lot on.\"","then":"She says gently: \"Okay. I'm here if it's more.\""},{"text":"\"It's about my son's behaviour. Can you give me tips for him?\"","then":"She says: \"I can point you to that too. How are you doing?\""},{"text":"\"I'm not sure I should be calling. Others have it worse.\"","then":"She says: \"Take your time.\""},{"text":"\"I'm exhausted and low. I need support for myself.\"","then":"\"Thank you for saying that,\" she says. \"Tell me more.\"","best":true}],"why":"Being real about yourself lets a counsellor actually help you."},{"prompt":"The counsellor asks: \"How have your sleep and days been lately?\"","options":[{"text":"\"Fine, mostly. Just a bit tired, nothing serious.\"","then":"She says gently: \"Okay. You did call, though. That matters.\""},{"text":"\"I keep going. I have to, for my child, every single day.\"","then":"She says gently: \"You carry a lot. Someone should carry you too.\""},{"text":"\"Bad, but it's my own fault. A better parent would cope.\"","then":"She says gently: \"Struggling isn't a failing. It's a heavy load.\""},{"text":"\"I barely sleep. I cry in the bathroom. It's been weeks.\"","then":"\"That sounds heavy.\" She pauses. \"Let's talk about what could help.\"","best":true}],"why":"Sharing what your days are really like gives her the picture she needs. Feeling this low is not your fault."},{"prompt":"The counsellor says: \"I'd like to help you set up ongoing support. Is that okay?\"","options":[{"text":"\"Maybe once things calm down. I'm too busy now.\"","then":"She says: \"I hear you. Busy weeks can turn into months.\""},{"text":"\"No thanks. Talking today was enough.\"","then":"She says: \"Alright. This number is here any time.\""},{"text":"\"Only for my child. I'll cope on my own.\"","then":"She says: \"We can start with him. And what about you?\""},{"text":"\"Yes. And I'll tell someone I trust too.\"","then":"She says: \"Then let's begin. I'll explain how it works.\"","best":true}],"why":"Saying yes to ongoing support, and letting someone you trust in, keeps you steady over time."}],"relearn":"Being real about your own struggle lets a counsellor actually help; minimising it shuts the door."},
  {"id":"nd-1309","cat":"support-and-you","type":"role-play","persona":"Vikram","source":"give a role","hook":"Your co-parent Nikhil has been pulling back from your child's care for weeks.","setup":"He sits at the edge of the sofa while you settle your child.","steps":[{"prompt":"Nikhil mutters: \"I'm no use here. You do it better.\"","options":[{"text":"\"It's okay. You're no good at this stuff. I'll handle it.\"","then":"Nikhil nods. \"Yeah. I know.\""},{"text":"\"Stop feeling sorry for yourself. Just help.\"","then":"Nikhil's face closes. \"I don't know how.\""},{"text":"\"You're not useless. Let's talk about it later.\"","then":"Nikhil shrugs. \"Later never comes.\""},{"text":"\"You're brilliant at bedtime. Could that be yours?\"","then":"Nikhil looks up. \"You really think so?\"","best":true}],"why":"Naming a real strength and a clear role invites him in better than reassurance does."},{"prompt":"Later, Nikhil says quietly: \"Maybe I could try his bedtime. What if he gets upset?\"","options":[{"text":"\"You won't get it wrong. Just do what you always do.\"","then":"Nikhil shrugs. \"Okay.\" He stays tense."},{"text":"\"If he gets upset, just call me.\"","then":"Nikhil says: \"Right.\" He plans to call at the first sign."},{"text":"\"Maybe wait until he's calmer with new things.\"","then":"Nikhil says: \"Good idea.\" He waits, and the chance keeps slipping."},{"text":"\"He may. We'll watch what calms him together.\"","then":"Nikhil smiles a little. \"Okay. Together, the first few nights.\"","best":true}],"why":"Learning together makes mistakes safe, which helps him keep going."},{"prompt":"A week later, Nikhil asks: \"Honestly, what difference do I make here?\"","options":[{"text":"\"A big one. You're doing great.\"","then":"Nikhil nods, unconvinced. \"Okay.\""},{"text":"\"Honestly? I still end up handling most things.\"","then":"Nikhil's shoulders drop. \"Then why bother?\""},{"text":"\"Maybe try a bit harder with him for a while.\"","then":"Nikhil frowns. \"I'm trying.\""},{"text":"\"He lights up with you. Could Saturdays be yours?\"","then":"Nikhil's eyes brighten. \"Saturdays. I can do that.\"","best":true}],"why":"Specific praise and a clear role of his own make him feel needed."}],"relearn":"Giving a hesitant co-parent a clear, valued role draws them in instead of letting them drift away."},
  {"id":"nd-1310","cat":"support-and-you","type":"role-play","persona":"any","source":"hold your ground","hook":"You have started seeing a counsellor and taking evenings off, and your aunt Sarla has noticed.","setup":"She brings it up over a family lunch.","steps":[{"prompt":"Aunty Sarla says: \"You're spoiling yourself with all this counselling and time off.\"","options":[{"text":"\"You're right. I should push through without help.\"","then":"Sarla nods, satisfied. Your stomach sinks."},{"text":"\"Please don't say that. You don't know what I go through.\"","then":"Sarla bristles. \"I'm only saying what everyone thinks.\""},{"text":"\"It's only once a month. Please don't tell anyone.\"","then":"Sarla says: \"I won't. But it isn't necessary, you know.\""},{"text":"\"Getting support keeps me steady for my child.\"","then":"Sarla purses her lips. \"I don't see why you need it.\"","best":true}],"why":"A calm, plain reason holds your ground without a fight."},{"prompt":"Sarla says: \"We managed alone. Nobody needed counsellors.\"","options":[{"text":"\"You're old-fashioned. Things have changed.\"","then":"Sarla draws herself up. \"Old-fashioned, is it?\""},{"text":"\"You're right. I'm just weak.\"","then":"Sarla says: \"I didn't say weak.\""},{"text":"\"Sit down and let me explain everything properly.\"","then":"Sarla folds her arms. \"Go on, then. Convince me.\""},{"text":"\"You managed a lot. I want to manage with help.\"","then":"Sarla pauses. \"Hm. Maybe that's not so bad.\"","best":true}],"why":"Respecting what she did without giving up your support ends the argument kindly."},{"prompt":"Sarla asks: \"Well, what does the counsellor do for you, exactly?\"","options":[{"text":"\"It's none of your business. Stop asking.\"","then":"Sarla looks hurt. \"I only asked.\""},{"text":"\"Nothing much. It's just a chat.\"","then":"Sarla says: \"Then why waste time?\""},{"text":"\"She says my family isn't helping enough.\"","then":"Sarla's face darkens. \"Oh, so we are the problem.\""},{"text":"\"She helps me rest and plan, so I can be there for my child.\"","then":"Sarla nods slowly. \"That sounds sensible.\"","best":true}],"why":"Saying simply what support does turns suspicion into understanding."}],"relearn":"Naming that support keeps you steady defends your wellbeing against the 'spoiling yourself' jibe."},
  {"id":"nd-1311","cat":"support-and-you","type":"role-play","persona":"any","source":"steer from cures","hook":"Imran, another parent, is chasing every \"cure\" and burning out.","setup":"He looks drained outside the clinic.","steps":[{"prompt":"Imran says: \"I tried another treatment last week. It cost a fortune. I'm exhausted.\"","options":[{"text":"\"Keep at it. One of them is bound to work eventually.\"","then":"Imran perks up. \"That's what I think too.\""},{"text":"\"You're wasting your money. Stop this nonsense.\"","then":"Imran's jaw tightens. \"It's my child. I'll try what I want.\""},{"text":"\"Ask the treatment centre for a refund and a guarantee.\"","then":"Imran says: \"They said no refunds.\" He looks even more tired."},{"text":"\"There's no cure to chase. Support and rest helped us.\"","then":"Imran's shoulders drop. \"Rest? I haven't had any in months.\"","best":true}],"why":"Naming that there is no cure to chase, and offering rest, meets his exhaustion."},{"prompt":"Imran says: \"Sometimes I think of stopping. Then I feel I'm giving up on him.\"","options":[{"text":"\"Then take a short break and start again after that.\"","then":"Imran nods. \"A short break. Then I'll restart.\""},{"text":"\"He would want you to keep fighting for him.\"","then":"Imran straightens. \"Yes. I owe it to him.\" Then he rubs his eyes."},{"text":"\"Maybe try one more treatment first, then decide.\"","then":"Imran says: \"One more. Just one.\""},{"text":"\"Stopping the chase isn't giving up. It's choosing.\"","then":"Imran's eyes fill. \"I never thought of it like that.\"","best":true}],"why":"Seeing stopping as choosing what helps frees him from the guilt of the chase."},{"prompt":"Later, Imran asks quietly: \"If I ever did stop, what would I even do instead?\"","options":[{"text":"\"Nothing. Just relax and let things happen.\"","then":"Imran looks doubtful. \"That feels like doing nothing.\""},{"text":"\"Find a better cure. Ask around at the clinic. Someone will know.\"","then":"Imran says: \"I'll ask the receptionist.\""},{"text":"\"Ask your family for money for more treatments. They'll help.\"","then":"Imran says: \"They'd never agree.\""},{"text":"\"See a professional, join a parent group, sleep.\"","then":"Imran writes down the group's name. \"Sleep. I'll try.\"","best":true}],"why":"Support, a professional and rest replace the chase with things that really help."}],"relearn":"Gently steering a burning-out parent toward support and rest, not cures, protects them and their child."},
  {"id":"nd-1312","cat":"support-and-you","type":"role-play","persona":"Vikram","source":"concrete ask","hook":"Your sister Pooja adores your son but has never spent time alone with him.","setup":"She stops by with sweets on a Sunday.","steps":[{"prompt":"Pooja asks: \"How can I help? Tell me honestly.\"","options":[{"text":"\"Oh, there's nothing really. We're managing fine.\"","then":"Pooja hesitates. \"Okay. But if that changes...\""},{"text":"\"Just keep in touch. That's enough.\"","then":"Pooja says: \"Of course. I'll call more.\""},{"text":"\"Could you talk to the relatives and explain things?\"","then":"Pooja goes pale. \"I wouldn't know what to say.\""},{"text":"\"Could you take him to the park on Saturdays?\"","then":"Pooja beams. \"Yes! Saturdays at four.\"","best":true}],"why":"A specific, doable task lets her help right away."},{"prompt":"Pooja asks: \"If I do take him somewhere, what should I do if he gets upset?\"","options":[{"text":"\"Tell him to stop and behave.\"","then":"Pooja hesitates. \"Firm. Alright.\" She looks unsure it will help."},{"text":"\"Just call me straight away and I'll come.\"","then":"Pooja says: \"Okay.\" She'd call at the first sign."},{"text":"\"He won't get upset. He loves the park.\"","then":"Pooja says: \"Good. That's a relief.\""},{"text":"\"Stay calm and give him space. Take his headphones.\"","then":"Pooja takes them. \"Calm and space. I can do that.\"","best":true}],"why":"An upset is overwhelm, not naughtiness, so a calm plan and his headphones help her through it."},{"prompt":"Pooja says: \"I'd like to do more for him. Where should I start?\"","options":[{"text":"\"Nothing more. What you do is plenty.\"","then":"Pooja says: \"Alright,\" and looks a little let down."},{"text":"\"Could you handle his therapy appointments on your own?\"","then":"Pooja looks nervous. \"On my own? I'd need to learn first.\""},{"text":"\"Learn everything about the diagnosis first, then decide.\"","then":"Pooja says: \"Okay.\" She buries herself in websites."},{"text":"\"Come to his school event in March. He'd love that.\"","then":"Pooja smiles. \"I'll be in the front row.\"","best":true}],"why":"A small, clear invitation keeps her involved and close to him."}],"relearn":"Giving a willing relative a concrete, doable task turns goodwill into real support for you both."},
  {"id":"nd-1313","cat":"support-and-you","type":"role-play","persona":"Divya","source":"reframe the break","hook":"You catch yourself apologising to your partner Ajay for taking an evening off.","setup":"You are at the door with your bag while Ajay sits with your child.","steps":[{"prompt":"Ajay asks: \"Why do you keep saying sorry for going out?\"","options":[{"text":"\"I really shouldn't be doing this. I'm being selfish.\"","then":"Ajay frowns. \"Then why go at all?\""},{"text":"\"I don't know. I just feel bad.\"","then":"Ajay says gently: \"Okay.\" The guilt goes with you to the cafe."},{"text":"\"Sorry. I'll be back in an hour, promise.\"","then":"Ajay says: \"Take longer.\" You hurry home in fifty minutes."},{"text":"\"It's not a luxury. It's how I keep showing up.\"","then":"Ajay nods slowly. \"I hadn't seen it that way.\"","best":true}],"why":"Calling the break fuel, not a luxury, frees you to refill without guilt."},{"prompt":"The next week, Ajay says: \"Going out again tonight? Mum says you're always out.\"","options":[{"text":"\"No, I'll stay home. I don't want Mum to think I'm selfish.\"","then":"Ajay looks uncertain. \"If you want.\""},{"text":"\"Mum should mind her own business, not mine.\"","then":"Ajay winces. \"That's my mother you're talking about.\""},{"text":"\"Maybe I'll go less often. Just once a month.\"","then":"Ajay says: \"If that works for you.\""},{"text":"\"Yes. It's my rest, and it helps him too.\"","then":"Ajay pauses. \"Okay. I'll tell Mum it's our plan.\"","best":true}],"why":"Naming your rest as shared family care turns pressure into support."},{"prompt":"Ajay says: \"Tell me what these evenings do for you. I want to understand.\"","options":[{"text":"\"Nothing much. It's just some time off for me.\"","then":"Ajay shrugs. \"Fine. Whatever helps.\""},{"text":"\"I'll explain later. I'm running late.\"","then":"Ajay nods. \"Sure.\" The question stays unanswered."},{"text":"\"You wouldn't understand. You aren't home all day like me.\"","then":"Ajay's face closes. \"That's unfair.\""},{"text":"\"I get my patience back. He gets a calmer me.\"","then":"Ajay smiles. \"Then let's make them regular.\"","best":true}],"why":"Saying what the break gives you turns guilt into a shared, regular plan."}],"relearn":"Reframing a break as fuel, not a luxury, frees a parent to refill without guilt."},
  {"id":"nd-1314","cat":"support-and-you","type":"spot","hook":"Spot the 2 red flags: the moves that burn a parent out.","scene":[{"id":"a","text":"Leaning on a support network","trick":false},{"id":"b","text":"Carrying every single task alone","trick":true},{"id":"c","text":"Resting when you can","trick":false},{"id":"d","text":"Never once asking for help","trick":true},{"id":"e","text":"Sharing the load with family","trick":false}],"why":"Carrying it all alone and never asking for help are the red flags: they burn a devoted parent out.","relearn":"Doing everything alone and never asking for help burn you out; sharing, resting and a network sustain you.","persona":"any","source":"burnout flags"},
  {"id":"nd-1315","cat":"support-and-you","type":"spot","hook":"Spot the 2 red flags: the 'support' that isn't real support.","scene":[{"id":"a","text":"A qualified professional's assessment","trick":false},{"id":"b","text":"A stranger selling a 'miracle cure'","trick":true},{"id":"c","text":"Other parents who truly get it","trick":false},{"id":"d","text":"A forum diagnosing your child for you","trick":true},{"id":"e","text":"Tele-MANAS mental-health support","trick":false}],"why":"The cure-seller and the forum 'diagnosis' are the red flags: neither is real, qualified support.","relearn":"Professionals, peer parents and Tele-MANAS are real support; cure-sellers and forum 'diagnoses' aren't.","persona":"any","source":"fake support flags"},
  {"id":"nd-1316","cat":"support-and-you","type":"spot","hook":"Spot the 2 red flags: the unfair pressures a parent puts on themselves.","scene":[{"id":"a","text":"\"Learning and loving is enough\"","trick":false},{"id":"b","text":"\"I must know every answer\"","trick":true},{"id":"c","text":"\"Asking for help is okay\"","trick":false},{"id":"d","text":"\"A good parent never tires\"","trick":true},{"id":"e","text":"\"My rest helps my child too\"","trick":false}],"why":"\"I must know every answer\" and \"a good parent never tires\" are the red flags: impossible, unfair demands.","relearn":"Needing every answer or never tiring is unfair pressure; learning, asking and resting are enough.","persona":"any","source":"pressure flags"},
  {"id":"nd-1317","cat":"support-and-you","type":"spot","hook":"Spot the 2 red flags: the signs a parent is running on empty.","scene":[{"id":"a","text":"Resting without guilt","trick":false},{"id":"b","text":"Snapping at everyone lately","trick":true},{"id":"c","text":"Asking for help early","trick":false},{"id":"d","text":"Dreading every single morning","trick":true},{"id":"e","text":"Letting a relative take a shift","trick":false}],"why":"Snapping at everyone and dreading every morning are the red flags: your tank is empty and needs refilling.","relearn":"Snapping and dread say you're running empty; rest, asking early and sharing shifts refill you.","persona":"Divya","source":"empty-tank flags"},
  {"id":"nd-1318","cat":"support-and-you","type":"spot","hook":"Spot the 2 red flags: the moves that push willing family away.","scene":[{"id":"a","text":"Explaining his profile simply","trick":false},{"id":"b","text":"Snapping 'you'll never understand'","trick":true},{"id":"c","text":"Giving a relative a concrete task","trick":false},{"id":"d","text":"Hiding everything from them","trick":true},{"id":"e","text":"Sharing what calms your child","trick":false}],"why":"Snapping 'you'll never understand' and hiding everything are the red flags: they push willing family away.","relearn":"Snapping and hiding push family away; explaining, giving a task and sharing what calms bring them in.","persona":"Vikram","source":"push-away flags"},
  {"id":"nd-1319","cat":"support-and-you","type":"spot","hook":"Spot the 2 red flags: the things this tool can NOT do for your child.","scene":[{"id":"a","text":"Offer understanding and support","trick":false},{"id":"b","text":"Formally diagnose your child","trick":true},{"id":"c","text":"Point you toward real help","trick":false},{"id":"d","text":"Replace your child's professional","trick":true},{"id":"e","text":"Lift shame with honest reframes","trick":false}],"why":"Diagnosing and replacing a professional are the red flags: only a qualified professional does those.","relearn":"This tool supports and signposts; it can't diagnose or replace the professional who assesses your child.","persona":"any","source":"tool-limit flags"},
  {"id":"nd-1320","cat":"support-and-you","type":"spot","hook":"Spot the 2 red flags: the ways a parent isolates instead of reaching out.","scene":[{"id":"a","text":"Texting a parent who understands","trick":false},{"id":"b","text":"Bottling every worry up inside","trick":true},{"id":"c","text":"Joining a support group","trick":false},{"id":"d","text":"Insisting 'no one can help me'","trick":true},{"id":"e","text":"Calling Tele-MANAS on a hard night","trick":false}],"why":"Bottling it up and insisting no one can help are the red flags: isolation that quietly wears a parent down.","relearn":"Bottling up and 'no one can help' isolate you; texting peers, a group and Tele-MANAS reach out.","persona":"any","source":"isolation flags"},
  {"id":"nd-1350","cat":"understand-your-child","type":"strike-rewrite","hook":"\"If I just push harder, my child will become a normal kid.\"","myth":{"un":"If I just push harder, my child will become a normal kid.","re":"There is no single 'normal' brain to push toward; your job is to understand your child's wiring, not erase it.","why":"Brains naturally vary; the goal is understanding, not erasing."},"relearn":"You can't push a child into being 'normal'; understand their wiring, the goal isn't to erase who they are.","persona":"Meena","source":"no normal to push toward"},
  {"id":"nd-1351","cat":"understand-your-child","type":"strike-rewrite","hook":"\"My nephew is just very shy, every quiet child is the same.\"","myth":{"un":"My nephew is just very shy; every quiet child is the same.","re":"Every child's profile is their own; 'quiet' can mean many things, so understand this child, not a stereotype.","why":"No single profile fits every child."},"relearn":"Every child's profile is their own; understand the actual child in front of you, not a one-size label.","persona":"Priya","source":"every profile is individual"},
  {"id":"nd-1352","cat":"understand-your-child","type":"strike-rewrite","hook":"\"A diagnosis will define and limit my daughter for life.\"","myth":{"un":"A diagnosis will define and limit my daughter for life.","re":"A diagnosis is information that unlocks support; it's a key, not a verdict, and your child is unchanged by it.","why":"The child is the same; only your understanding grows."},"relearn":"A diagnosis is a key to support, not a verdict that limits your child; she is unchanged by the label.","persona":"Divya","source":"key not verdict"},
  {"id":"nd-1353","cat":"understand-your-child","type":"strike-rewrite","hook":"\"My son's autism means he can't feel love or connect with us.\"","myth":{"un":"My son's autism means he can't feel love or connect with us.","re":"Autistic children feel and connect deeply; they may just show it in their own way, which is yours to learn.","why":"Different expression isn't absent feeling."},"relearn":"Autistic children feel and connect deeply; they show it their own way, which is yours to learn to read.","persona":"Meena","source":"connection shown differently"},
  {"id":"nd-1354","cat":"understand-your-child","type":"strike-rewrite","hook":"\"His intense focus on trains is an obsession we must break.\"","myth":{"un":"His intense focus on trains is an obsession we must break.","re":"A deep interest is a real strength to feed, not break; it can grow confidence, skills and even a future path.","why":"A passion fed becomes a strength, not a problem."},"relearn":"An intense interest is a strength to feed, not an obsession to break; it can grow into something amazing.","persona":"Meena","source":"interest is a strength"},
  {"id":"nd-1355","cat":"understand-your-child","type":"strike-rewrite","hook":"\"Dyslexia just means my child is slow and not very bright.\"","myth":{"un":"Dyslexia just means my child is slow and not very bright.","re":"Dyslexia is a different way of processing print, not low intelligence; it often pairs with big-picture thinking.","why":"Reading difficulty isn't a measure of intelligence."},"relearn":"Dyslexia is a different way of reading, not low intelligence; it often comes with strong big-picture thinking.","persona":"Divya","source":"dyslexia not low intelligence"},
  {"id":"nd-1356","cat":"understand-your-child","type":"strike-rewrite","hook":"\"My ADHD kid is just lazy and unmotivated, that's all it is.\"","myth":{"un":"My ADHD kid is just lazy and unmotivated, that's all it is.","re":"ADHD is a difference in attention and regulation, not laziness; the energy and quick thinking are real strengths.","why":"A wiring difference isn't a character flaw."},"relearn":"ADHD is a difference in attention, not laziness; the energy and quick thinking that come with it are real strengths.","persona":"Vikram","source":"adhd not lazy"},
  {"id":"nd-1357","cat":"understand-your-child","type":"strike-rewrite","hook":"\"Comparing him to his cousin shows me how far behind he is.\"","myth":{"un":"Comparing him to his cousin shows me how far behind he is.","re":"Measure your child against their own profile and pace, not a cousin's milestones; comparison misses who they are.","why":"Your child's pace is the only fair yardstick."},"relearn":"Meet your child's own profile and pace, not a cousin's milestones; comparison only hides who your child really is.","persona":"Meena","source":"their own pace not comparison"},
  {"id":"nd-1358","cat":"understand-your-child","type":"strike-rewrite","hook":"\"Once he grows up, he'll grow out of all of this.\"","myth":{"un":"Once he grows up, he'll grow out of all of this.","re":"Neurodivergence is lifelong; children don't grow out of it, but understanding and support help them thrive.","why":"It's how the brain is wired, not a phase."},"relearn":"Neurodivergence is lifelong; a child doesn't grow out of it, but understanding and support help them truly thrive.","persona":"Meena","source":"lifelong not a phase"},
  {"id":"nd-1359","cat":"understand-your-child","type":"strike-rewrite","hook":"\"He doesn't make eye contact, so he must not be listening.\"","myth":{"un":"He doesn't make eye contact, so he must not be listening.","re":"Many neurodiverse children listen better without forced eye contact; looking away can be how they focus.","why":"Eye contact and listening aren't the same thing."},"relearn":"Many neurodiverse children listen best without eye contact; looking away can be how they focus, not how they ignore.","persona":"Meena","source":"eye contact isn't listening"},
  {"id":"nd-1360","cat":"understand-your-child","type":"strike-rewrite","hook":"\"There's nothing special about her, she's just difficult.\"","myth":{"un":"There's nothing special about her, she's just difficult.","re":"Seeing her strengths, not only the struggles, changes how she comes to see herself; she's far more than 'difficult'.","why":"What you notice in her shapes her self-image."},"relearn":"Seeing your child's strengths, not just the struggles, shapes how she sees herself; she is so much more than 'difficult'.","persona":"Divya","source":"see strengths shapes self"},
  {"id":"nd-1361","cat":"understand-your-child","type":"reflect","hook":"Lensy: your child is a whole, wonderful person, far more than any diagnosis. Sit right with you?","prompt":"What's your take?","options":["Sits right","More than a label","A whole person"],"affirm":"Your child is a whole, wonderful person, far more than a diagnosis; seeing all of them is what matters most.","relearn":"Your child is a whole person, far more than a diagnosis; loving all of who they are matters most.","persona":"Meena","source":"more than a label"},
  {"id":"nd-1362","cat":"understand-your-child","type":"reflect","hook":"Lensy: the first step of support is learning how your child actually experiences the world. Resonate?","prompt":"What do you think?","options":["Resonates","Learn how they feel it","First step"],"affirm":"Asking how your child experiences the world, rather than judging them by a template, is the first real step of support.","relearn":"The first step of support is learning how your child experiences the world, not measuring them against a template.","persona":"Meena","source":"experience first"},
  {"id":"nd-1363","cat":"understand-your-child","type":"reflect","hook":"Lensy: brains varying is just part of being human, like different heights or voices. Feel true?","prompt":"What's your view?","options":["Feels true","Part of being human","Natural variation"],"affirm":"Brains varying is natural human variation, like different heights or voices; your child's way of thinking is valid.","relearn":"Brains varying is natural human variation; your child's way of thinking is valid, not a flaw to fix.","persona":"any","source":"variation is human"},
  {"id":"nd-1364","cat":"understand-your-child","type":"reflect","hook":"Lensy: when you stop asking 'why won't he behave' and start asking 'what's he telling me', things shift. Agree?","prompt":"What do you feel?","options":["Agree","Behaviour is a message","Worth a try"],"affirm":"Swapping 'why won't he behave' for 'what is he telling me' turns frustration into understanding of your real child.","relearn":"Asking 'what is my child telling me' instead of 'why won't he behave' turns frustration into real understanding.","persona":"Divya","source":"behaviour is communication"},
  {"id":"nd-1365","cat":"understand-your-child","type":"reflect","hook":"Lensy: it's okay to grieve the picture you imagined, then turn fully toward the child you have. Land for you?","prompt":"What's your take?","options":["Lands","Grief is allowed","Turn toward them"],"affirm":"Allowing yourself to grieve the imagined child, then turning toward the real one, lets you meet who they truly are.","relearn":"It's okay to grieve the child you pictured, then turn fully toward the wonderful child you actually have.","persona":"Divya","source":"allow the grief then turn"},
  {"id":"nd-1366","cat":"understand-your-child","type":"reflect","hook":"Lensy: your child's honesty and deep focus are gifts the world often forgets to value. Worth holding onto?","prompt":"What's your view?","options":["Worth it","Honesty is a gift","Focus is a gift"],"affirm":"Honesty, deep focus and noticing what others miss are real gifts; naming them aloud helps your child treasure them too.","relearn":"Your child's honesty and deep focus are real gifts; naming them aloud helps your child value them as well.","persona":"Meena","source":"name the gifts"},
  {"id":"nd-1367","cat":"understand-your-child","type":"reflect","hook":"Lensy: understanding your child isn't a test to pass perfectly, it's a relationship you keep learning. Sit right?","prompt":"What do you think?","options":["Sits right","Keep learning","Not a test"],"affirm":"Understanding your child is an ongoing, imperfect relationship, not a test to ace; a learning parent is exactly enough.","relearn":"Understanding your child is a relationship you keep learning, not a test to pass; a learning parent is exactly enough.","persona":"Vikram","source":"a relationship not a test"},
  {"id":"nd-1368","cat":"understand-your-child","type":"reflect","hook":"Lensy: who your child is today is worth celebrating, not just who they might become. True for you?","prompt":"What's your take?","options":["True","Celebrate today","Not just later"],"affirm":"Your child is worth celebrating exactly as they are today, not only for who they might grow into later.","relearn":"Celebrate who your child is today, not only who they might become; they are worth delighting in right now.","persona":"Meena","source":"celebrate who they are now"},
  {"id":"nd-1369","cat":"understand-your-child","type":"sort","hook":"Sort: a real strength a neurodiverse child may bring, or a deficit-only label?","items":[{"id":"a","text":"Notices tiny details others miss"},{"id":"b","text":"'Just can't sit still'"},{"id":"c","text":"Honest, says what's true"},{"id":"d","text":"'Always in his own world'"},{"id":"e","text":"Remembers facts vividly"},{"id":"f","text":"'Never pays attention'"}],"bins":[{"id":"strength","label":"A real strength","valence":"pos"},{"id":"deficit","label":"Deficit-only label","valence":"neg"}],"key":{"a":"strength","b":"deficit","c":"strength","d":"deficit","e":"strength","f":"deficit"},"relearn":"Noticing details, honesty and vivid memory are real strengths; 'can't sit still, own world, never pays attention' see only deficits.","persona":"any","source":"strength vs deficit label"},
  {"id":"nd-1370","cat":"understand-your-child","type":"sort","hook":"Sort: a true statement about neurodivergence, or a myth?","items":[{"id":"a","text":"It's lifelong wiring"},{"id":"b","text":"Bad parenting causes it"},{"id":"c","text":"Each child's profile differs"},{"id":"d","text":"You grow out of it"},{"id":"e","text":"Strengths come with it"},{"id":"f","text":"It means low intelligence"}],"bins":[{"id":"true","label":"True","valence":"pos"},{"id":"myth","label":"Myth","valence":"neg"}],"key":{"a":"true","b":"myth","c":"true","d":"myth","e":"true","f":"myth"},"relearn":"Lifelong wiring, individual profiles and real strengths are true; 'bad parenting, grow out of it, low intelligence' are myths.","persona":"any","source":"true vs myth"},
  {"id":"nd-1371","cat":"understand-your-child","type":"sort","hook":"Sort: which everyday strength tends to go with which profile? (every child is still individual)","items":[{"id":"a","text":"Deep focus on a topic"},{"id":"b","text":"Burst of energy and ideas"},{"id":"c","text":"Honest, literal answers"},{"id":"d","text":"Quick, creative problem-solving"},{"id":"e","text":"Spotting visual patterns"},{"id":"f","text":"Big-picture, spatial thinking"}],"bins":[{"id":"autism","label":"Often autism","valence":"neutral"},{"id":"adhd","label":"Often ADHD","valence":"neutral"},{"id":"dyslexia","label":"Often dyslexia","valence":"neutral"}],"key":{"a":"autism","b":"adhd","c":"autism","d":"adhd","e":"autism","f":"dyslexia"},"relearn":"Deep focus, honesty and pattern-spotting often go with autism; energy and quick ideas with ADHD; big-picture thinking with dyslexia.","persona":"any","source":"strength by profile"},
  {"id":"nd-1372","cat":"understand-your-child","type":"sort","hook":"Sort: a way of understanding your child, or judging them?","items":[{"id":"a","text":"'How does he experience this?'"},{"id":"b","text":"'Why won't he be normal?'"},{"id":"c","text":"'What does she need here?'"},{"id":"d","text":"'She's doing this to annoy me'"},{"id":"e","text":"'What is he good at?'"},{"id":"f","text":"'He's just being difficult'"}],"bins":[{"id":"understand","label":"Understanding","valence":"pos"},{"id":"judge","label":"Judging","valence":"neg"}],"key":{"a":"understand","b":"judge","c":"understand","d":"judge","e":"understand","f":"judge"},"relearn":"Asking how a child experiences things and what they need understands them; 'why won't he be normal, doing it to annoy me' judges.","persona":"Meena","source":"understand vs judge"},
  {"id":"nd-1373","cat":"understand-your-child","type":"sort","hook":"Sort: what a diagnosis actually is, or what it is not?","items":[{"id":"a","text":"Information to guide support"},{"id":"b","text":"A tragedy to mourn forever"},{"id":"c","text":"A key that opens help"},{"id":"d","text":"A verdict on your child"},{"id":"e","text":"A shared word with school"},{"id":"f","text":"Proof something is broken"}],"bins":[{"id":"is","label":"What it is","valence":"pos"},{"id":"isnot","label":"What it is not","valence":"neg"}],"key":{"a":"is","b":"isnot","c":"is","d":"isnot","e":"is","f":"isnot"},"relearn":"A diagnosis is information, a key and a shared word for support; it is not a tragedy, a verdict, or proof your child is broken.","persona":"Divya","source":"diagnosis is vs isnt"},
  {"id":"nd-1374","cat":"understand-your-child","type":"sort","hook":"Sort: a behaviour that's overwhelm to understand, or genuine defiance to discipline?","items":[{"id":"a","text":"Meltdown in a loud mall"},{"id":"b","text":"Hands over ears at a party"},{"id":"c","text":"Refusing a sudden plan change"},{"id":"d","text":"Stimming when excited"},{"id":"e","text":"Hitting a sibling for a toy"},{"id":"f","text":"Lying to dodge a chore"}],"bins":[{"id":"overwhelm","label":"Overwhelm","valence":"uhoh"},{"id":"choice","label":"A choice to guide","valence":"neutral"}],"key":{"a":"overwhelm","b":"overwhelm","c":"overwhelm","d":"overwhelm","e":"choice","f":"choice"},"relearn":"Meltdowns, covering ears, resisting sudden changes and stimming are overwhelm; hitting for a toy or lying are ordinary choices to guide.","persona":"Meena","source":"overwhelm vs choice"},
  {"id":"nd-1375","cat":"understand-your-child","type":"sort","hook":"Sort: a strengths-first thought, or a deficit-first one?","items":[{"id":"a","text":"'She learns best by doing'"},{"id":"b","text":"'He can't do anything right'"},{"id":"c","text":"'His memory amazes me'"},{"id":"d","text":"'She's so far behind'"},{"id":"e","text":"'He cares so deeply'"},{"id":"f","text":"'Why is he always a problem?'"}],"bins":[{"id":"strengths","label":"Strengths-first","valence":"pos"},{"id":"deficit","label":"Deficit-first","valence":"neg"}],"key":{"a":"strengths","b":"deficit","c":"strengths","d":"deficit","e":"strengths","f":"deficit"},"relearn":"Noticing how she learns, his memory and how deeply he cares is strengths-first; 'can't do anything, so behind, a problem' is deficit-first.","persona":"any","source":"strengths-first vs deficit-first"},
  {"id":"nd-1376","cat":"understand-your-child","type":"sort","hook":"Sort: a kind, accurate thing to say to your child, or a harmful one?","items":[{"id":"a","text":"'Your brain works its own way'"},{"id":"b","text":"'There's something wrong with you'"},{"id":"c","text":"'I love how your mind works'"},{"id":"d","text":"'Why can't you be normal?'"},{"id":"e","text":"'We'll figure this out together'"},{"id":"f","text":"'You're too much to handle'"}],"bins":[{"id":"kind","label":"Kind and true","valence":"pos"},{"id":"harmful","label":"Harmful","valence":"neg"}],"key":{"a":"kind","b":"harmful","c":"kind","d":"harmful","e":"kind","f":"harmful"},"relearn":"'Your brain works its own way, I love your mind, we'll figure it out' protect a child; 'something's wrong, be normal, too much' wound them.","persona":"Meena","source":"kind vs harmful words"},
  {"id":"nd-1377","cat":"understand-your-child","type":"match","hook":"Match each profile to a common strength (every child is still their own person).","pairs":[{"left":"Autism","right":"Deep focus and honesty"},{"left":"ADHD","right":"Energy and creative thinking"},{"left":"Dyslexia","right":"Big-picture, spatial thinking"},{"left":"Dyspraxia","right":"Determined, creative problem-solving"},{"left":"Dyscalculia","right":"Strong verbal and story skills"}],"relearn":"Each profile commonly brings real strengths: autism deep focus, ADHD energy, dyslexia big-picture thinking, though every child is unique.","persona":"any","source":"profile to strength"},
  {"id":"nd-1378","cat":"understand-your-child","type":"match","hook":"Match each behaviour to what it may really be communicating.","pairs":[{"left":"Covering ears","right":"This noise hurts me"},{"left":"Lining up toys","right":"Order helps me feel calm"},{"left":"Repeating a phrase","right":"I'm soothing or processing"},{"left":"Refusing new food","right":"This texture feels wrong"},{"left":"Running off in a crowd","right":"I'm overwhelmed and need space"}],"relearn":"Behaviour is communication: covering ears means noise hurts, lining up brings calm, repeating soothes, refusing food is texture, running is overwhelm.","persona":"Meena","source":"behaviour to meaning"},
  {"id":"nd-1379","cat":"understand-your-child","type":"match","hook":"Match each myth to the truth that replaces it.","pairs":[{"left":"Caused by bad parenting","right":"It's simply how the brain is wired"},{"left":"They'll grow out of it","right":"It's lifelong; support helps them thrive"},{"left":"It means low intelligence","right":"It's a difference, not a measure of smarts"},{"left":"A diagnosis is a verdict","right":"It's a key that opens support"},{"left":"Just naughtiness","right":"Often overwhelm, not defiance"}],"relearn":"Myths fall to truth: not parenting but wiring, lifelong not outgrown, difference not low intelligence, a key not a verdict, overwhelm not naughtiness.","persona":"any","source":"myth to truth"},
  {"id":"nd-1380","cat":"understand-your-child","type":"match","hook":"Match each parent question to the understanding it opens.","pairs":[{"left":"What is he good at?","right":"Builds on strengths"},{"left":"How does she experience this?","right":"Sees through her senses"},{"left":"What does this behaviour say?","right":"Reads it as communication"},{"left":"What's his own pace?","right":"Drops the comparison trap"},{"left":"What does she need now?","right":"Moves from blame to support"}],"relearn":"Better questions open understanding: strengths, her senses, behaviour as a message, his own pace, and what she needs over blame.","persona":"Divya","source":"question to understanding"},
  {"id":"nd-1381","cat":"understand-your-child","type":"match","hook":"Match each child's everyday moment to the gift hiding inside it.","pairs":[{"left":"Asks 'why' a hundred times","right":"A curious, hungry mind"},{"left":"Won't bend the rules of a game","right":"A strong sense of fairness"},{"left":"Talks endlessly about dinosaurs","right":"Deep, expert-level passion"},{"left":"Notices a tiny change in the room","right":"Sharp, detailed attention"},{"left":"Says exactly what she thinks","right":"Refreshing honesty"}],"relearn":"Everyday moments hide gifts: endless 'why' is curiosity, rigid rules are fairness, a passion runs deep, noticing is attention, bluntness is honesty.","persona":"Meena","source":"moment to gift"},
  {"id":"nd-1382","cat":"understand-your-child","type":"match","hook":"Match each neurodiverse trait to a fair, everyday way to picture it.","pairs":[{"left":"Sensory overload","right":"Like a too-loud, too-bright room"},{"left":"Trouble with sudden change","right":"Like losing the map mid-journey"},{"left":"Hyperfocus","right":"Like the world going quiet around one thing"},{"left":"Needing routine","right":"Like a handrail on the stairs"},{"left":"Stimming","right":"Like tapping a foot to settle"}],"relearn":"Fair pictures build empathy: overload is a too-loud room, change is a lost map, hyperfocus is quiet focus, routine is a handrail, stimming is settling.","persona":"any","source":"trait to picture"},
  {"id":"nd-1383","cat":"understand-your-child","type":"match","hook":"Match each profile to a daily moment where its strength can shine.","pairs":[{"left":"Pattern-spotter","right":"Sorting and organising a collection"},{"left":"High-energy thinker","right":"An active, hands-on task"},{"left":"Big-picture mind","right":"Planning the whole trip at once"},{"left":"Deep specialist","right":"Becoming the family expert on a topic"},{"left":"Honest observer","right":"Giving a true, useful opinion"}],"relearn":"Strengths shine in daily life: a pattern-spotter organises, an energetic mind builds, a big-picture mind plans, a specialist teaches, an honest child advises.","persona":"any","source":"profile to shining moment"},
  {"id":"nd-1384","cat":"understand-your-child","type":"branch","persona":"Meena","source":"hold the diagnosis","hook":"A diagnosis for your son arrived today, and you are holding the report.","steps":[{"prompt":"You sit alone with it after he has gone to sleep. What do you do?","options":[{"text":"Read only the first page and shut it","then":"The first page is all difficulty. You lie awake without seeing the rest."},{"text":"Cry until dawn, sure it is the worst news of your life","then":"You cry until morning. He wakes at seven, smiling and the same as ever."},{"text":"Decide the doctor is wrong and put it away","then":"The report goes into a drawer. Your worry about him doesn't go with it."},{"text":"Read it as a guide to how he is wired","then":"You underline a line about his memory. It sounds just like him.","best":true}],"why":"Reading it as a guide gives you a map to your actual child."},{"prompt":"The next morning, your husband asks what the report means for you all. What do you say?","options":[{"text":"That it is terrible and we must brace for it","then":"His face falls. He goes to work without breakfast."},{"text":"That we should keep going as before","then":"He shrugs, relieved. The report stays unopened between you."},{"text":"That it is a guide, and we can learn together","then":"He nods. \"A guide. Okay. Show me what it says.\"","best":true},{"text":"That we should find another doctor for a better answer","then":"He starts searching for clinics. The same words might come back."}],"why":"Treating it as a guide you learn together turns fear into a shared plan."},{"prompt":"A week later, his school asks about the report. What do you do?","options":[{"text":"Say nothing so he isn't labelled","then":"The school keeps treating his meltdowns as bad behaviour."},{"text":"Send it with a note demanding immediate changes","then":"The teacher feels attacked. The meeting is tense and short."},{"text":"Share it but say you are sure it will pass","then":"The teacher notes it. Little changes because nothing is asked for."},{"text":"Share it and ask what supports could help","then":"The teacher reads it and asks for a meeting. \"Let's plan together.\"","best":true}],"why":"Sharing it with a clear ask brings the school in as a partner."}],"debrief":"Hold a diagnosis as information that helps you support your child, not a tragedy or a verdict.","relearn":"A diagnosis is a guide to support, not the worst news or a thing to ignore; your child is unchanged."},
  {"id":"nd-1385","cat":"understand-your-child","type":"branch","persona":"Meena","source":"meltdown as overwhelm","hook":"Your daughter melts down every time you visit the noisy market.","steps":[{"prompt":"At the market, she covers her ears and starts to cry. What do you do?","options":[{"text":"Tell her firmly to stop because people are looking","then":"She cries louder and covers her face. You feel heat on your neck."},{"text":"Buy her a sweet to calm her down","then":"She takes it, but her hands are still shaking."},{"text":"Move to a quiet corner and stay calm beside her","then":"Her breathing slows after a few minutes. She leans into you.","best":true},{"text":"Hurry through and finish the shopping quickly","then":"You pull her along. She melts down again at the next stall."}],"why":"A quiet corner and your calm give her senses a break."},{"prompt":"Next week, you need vegetables again. What do you plan?","options":[{"text":"Take her as usual and hope it goes better","then":"The noise hits her at the gate. She freezes."},{"text":"Skip the market for good and order online","then":"The trips stop. She never gets to ease into places."},{"text":"Promise a toy if she behaves this time","then":"She nods, but halfway through the toy no longer matters."},{"text":"Go early when it is quiet, with her headphones","then":"The market is half empty. She holds the headphones and looks around.","best":true}],"why":"Adjusting the trip to her senses helps more than asking her to cope."},{"prompt":"Your mother-in-law says the girl just needs toughening up. What do you say?","options":[{"text":"Agree, to keep the peace","then":"She nods, pleased. You feel a knot in your stomach."},{"text":"Argue that she is being unkind","then":"She snaps back, and lunch ends early."},{"text":"Say you will think about it","then":"She takes that as a yes and plans a market trip."},{"text":"Explain the noise overwhelms her, and show what helps","then":"She watches you hand over the headphones. \"I didn't know.\"","best":true}],"why":"Explaining calmly, and showing what helps, shifts blame into understanding."},{"prompt":"A month later, your daughter says she wants to come to the market with you. What do you do?","options":[{"text":"Say yes, but skip the headphones so she gets used to it","then":"The noise catches her at the gate. She turns and hides her face."},{"text":"Say not yet, because it feels too risky","then":"She looks down. The invitation isn't repeated."},{"text":"Say yes, then leave the planning to her","then":"She forgets to check the time. The market is at its loudest."},{"text":"Say yes, and plan the time and supports together","then":"She picks the blue headphones and a time. She looks proud.","best":true}],"why":"Planning with her makes the outing hers, with supports in place."}],"debrief":"A meltdown in a loud place is overwhelm to understand, not naughtiness to punish.","relearn":"Market meltdowns are sensory overwhelm to understand and adjust for, not naughtiness to scold away."},
  {"id":"nd-1386","cat":"understand-your-child","type":"branch","persona":"Divya","source":"watch how he learns","hook":"Your son takes his time with schoolwork, and you want to understand how he learns.","steps":[{"prompt":"At Sunday lunch, an uncle calls your son slow again. What do you do?","options":[{"text":"Laugh it off so nobody feels awkward","then":"The table relaxes. Your son stops eating and stares at his plate."},{"text":"Snap that the uncle knows nothing","then":"The uncle stands up, offended, and lunch ends in silence."},{"text":"Quietly agree that he is a bit slow","then":"Your uncle nods, satisfied. Your son hears every word."},{"text":"Say calmly that he learns differently","then":"The uncle grunts but says no more. Your son looks up at you.","best":true}],"why":"A calm, short reply protects him and leaves you free to watch how he learns."},{"prompt":"That evening, your son struggles with his reading worksheet. What do you do?","options":[{"text":"Make him repeat it until it is done","then":"He cries at page two. The worksheet stays unfinished and your patience runs out."},{"text":"Finish it for him so he can sleep","then":"He goes to bed relieved. You still don't know how he learns."},{"text":"Tell him his cousins finished theirs in ten minutes","then":"He goes silent. The pencil stays down for the rest of the night."},{"text":"Sit with him and notice what makes it click","then":"He explains the story with drawings, then reads a line aloud. You note it down.","best":true}],"why":"Watching how he learns shows you what works for him, not what he lacks."},{"prompt":"A week later, his teacher says he seems slow to follow instructions. What do you do?","options":[{"text":"Agree, and say you will practise more at home","then":"The teacher nods. He gets more homework and less play."},{"text":"Ask her not to label him","then":"The teacher stiffens. \"I'm only describing what I see.\""},{"text":"Say nothing and hope it will pass","then":"The teacher writes \"slow\" in his report. It stays on the file."},{"text":"Say he learns differently and ask what would help","then":"The teacher listens. \"Tell me what helps him, and I'll try it.\"","best":true}],"why":"Asking for support instead of a label gives the teacher a way to help."},{"prompt":"Your son proudly shows a working bridge he built from cardboard. What do you do?","options":[{"text":"Say well done and go back to the cooking","then":"He nods and puts it aside. The explanation stays inside him."},{"text":"Say he must bring this focus to his homework now","then":"His smile drops. The bridge goes back into the box."},{"text":"Show it to the uncle to prove he isn't slow","then":"The uncle says \"Nice.\" Your son feels used as evidence."},{"text":"Ask him to explain how it works, and listen","then":"He talks for ten minutes. You realise how much he understands.","best":true}],"why":"Listening to his explanation shows how much he knows and how he thinks."}],"debrief":"Understand your child by watching how he learns, not by accepting 'slow' or forcing a pace.","relearn":"Understand your child by observing how he learns, not by trusting 'slow' or forcing a cousin's pace."},
  {"id":"nd-1387","cat":"understand-your-child","type":"branch","persona":"Meena","source":"feed the passion","hook":"Your son loves maps and can talk about them for hours.","steps":[{"prompt":"He spreads an atlas on the floor and starts explaining rivers. What do you do?","options":[{"text":"Tell him to put it away and do something useful","then":"He closes the atlas slowly. His shoulders slump."},{"text":"Nod while you cook, without really listening","then":"He keeps talking to the empty room. Then he stops."},{"text":"Ask him to talk about something else for a change","then":"He looks puzzled. \"But maps are what I like.\""},{"text":"Sit down and ask him to show you his favourite map","then":"He shows you a river that flows north. He is beaming.","best":true}],"why":"Joining him shows his interest is welcome and a strength to build on."},{"prompt":"His teacher says he only talks about maps in class. What do you say?","options":[{"text":"Apologise and promise to stop the map talk at home","then":"She nods. That night you tell him to stop, and he asks why."},{"text":"Say it's a phase and it will pass","then":"She nods, unconvinced. The maps stay, and so does the tension."},{"text":"Ask her to stop him during lessons","then":"She says she will. He is corrected daily and stops speaking in class."},{"text":"Suggest using maps in lessons, like maths or stories","then":"The teacher pauses. \"Maps in maths? That could work.\"","best":true}],"why":"Using his interest in lessons turns it into a bridge to learning."},{"prompt":"A cousin laughs at his map talk at a party. What do you do?","options":[{"text":"Take your son away from the party quietly","then":"He goes with you. He doesn't ask to go to parties after that."},{"text":"Tell your son to talk about cricket instead","then":"He tries, but goes silent. The party lasts an hour longer."},{"text":"Laugh along so it doesn't become a fuss","then":"The cousin grins. Your son notices you laughing too."},{"text":"Invite the cousin to see one of his map skills","then":"The cousin looks surprised, then curious. Your son opens his atlas.","best":true}],"why":"Inviting others to see his skill turns laughter into interest."}],"debrief":"An intense interest is a strength to feed and explore together, not an obsession to shut down.","relearn":"Explore your child's passion together; a deep interest is a strength to feed, not a flaw to suppress."},
  {"id":"nd-1388","cat":"understand-your-child","type":"branch","persona":"Meena","source":"own pace not comparison","hook":"You keep comparing your son to every child at the family function.","steps":[{"prompt":"Your son sits by the samosas while the cousins race around. What do you do?","options":[{"text":"Count what the cousins can do that he can't","then":"The list grows. Your chest tightens, and he sees you watching him."},{"text":"Push him to join the cousins' game","then":"He stands up but doesn't move. His eyes search for the door."},{"text":"Ask the cousins' mothers what their kids do at school","then":"Their answers are long, and your list of worries grows."},{"text":"Sit with him and ask what he is enjoying","then":"He tells you about the pattern on the tablecloth. You smile.","best":true}],"why":"Sitting with him shows you what he enjoys, not what he lacks."},{"prompt":"A relative asks whether he speaks as much as cousin Rohan. What do you say?","options":[{"text":"Say he will catch up soon","then":"She smiles. You feel the weight of that promise."},{"text":"Say Rohan is a talker and change the subject","then":"She lets it go. You still feel the comparison."},{"text":"List everything he can't do yet","then":"She looks uncomfortable. You feel worse for saying it."},{"text":"Say he speaks in his own way, and share a recent win","then":"She nods. \"Oh, that's lovely. Tell me more.\"","best":true}],"why":"Sharing his own progress moves the talk away from a race."},{"prompt":"On the drive home, you feel tempted to set a deadline for him to catch up. What do you do?","options":[{"text":"Set a year-end target and tell him about it","then":"He asks what happens if he misses it. You have no answer."},{"text":"Sign him up for extra coaching to catch up","then":"You ring the coaching centre from the car, saying he is behind. He hears it and goes quiet."},{"text":"Say nothing, but keep the target in your head","then":"The deadline sits with you at bedtime. Today's wins go unspoken."},{"text":"Name three wins from today with him","then":"You say them out loud. He smiles from the back seat.","best":true}],"why":"Naming today's wins builds on his own pace, not a deadline."},{"prompt":"A month on, his teacher shares a small step he took this term. What do you do?","options":[{"text":"Ask when he will reach the class level","then":"The teacher smiles thinly. \"He is on his own path.\""},{"text":"Tell him well done, then point to the next step","then":"He nods. The joy fades within a minute."},{"text":"Compare it with the cousins' progress","then":"You feel worse. He is quiet."},{"text":"Celebrate it with him and ask what helped","then":"He says the teacher let him sit by the window. You pass it on to her.","best":true}],"why":"Celebrating the step and finding what helped keeps his progress in view."}],"debrief":"Meet your child's own profile and pace; comparison to other children hides the progress that's there.","relearn":"Refocus on your child's own pace and wins; comparing him to others only hides his real progress."},
  {"id":"nd-1389","cat":"understand-your-child","type":"branch","persona":"Meena","source":"nothing is wrong","hook":"Your son has been quieter than usual since his new school term began.","steps":[{"prompt":"He looks up from his homework and asks if something is wrong with him. What do you say?","options":[{"text":"Tell him you are working to fix it, so not to worry","then":"He goes quiet. \"So there is something to fix,\" he whispers."},{"text":"Brush it off and change the subject","then":"He picks up his pencil. The question stays in his head."},{"text":"Tell him everyone feels different sometimes","then":"He nods slowly. \"But not like me,\" he says."},{"text":"Tell him nothing is wrong and his brain works its own way","then":"His shoulders loosen. \"Really?\" he asks, and moves closer.","best":true}],"why":"Telling him he is whole protects his sense of worth."},{"prompt":"The next day, he says a classmate called him strange. What do you do?","options":[{"text":"Tell him to ignore them and try to act more like the other kids","then":"He nods, but the next day he stays in at break."},{"text":"Say you will speak to the classmate's mother this very evening","then":"He looks alarmed. \"Please don't. It will be worse.\""},{"text":"Say kids are unkind and it doesn't matter, so he should forget it","then":"He shrugs. He doesn't mention it again."},{"text":"Say different isn't strange, then ask how it felt","then":"He tells you the whole story. He leans on your arm.","best":true}],"why":"Listening first and naming his difference as valid keeps him talking to you."},{"prompt":"At bedtime, he asks what his brain is good at. What do you say?","options":[{"text":"Say he is good at everything","then":"He frowns. \"That's not true. I can't tie my laces.\""},{"text":"Say you will find out from the doctor at the next visit","then":"He nods. \"When will you know?\""},{"text":"Say it is best not to think about it any more","then":"He turns to the wall. The question stays with him."},{"text":"Name strengths you have really seen in him","then":"He counts on his fingers. \"Remembering dates. Drawing trains.\"","best":true}],"why":"Naming real strengths helps him see himself as whole, not lacking."}],"debrief":"Tell your child nothing is wrong; their brain works its own way, with real gifts.","relearn":"Tell your child nothing is wrong; their brain works its own brilliant way, protecting their self-worth."},
  {"id":"nd-1390","cat":"understand-your-child","type":"branch","persona":"Vikram","source":"reframe abnormal","hook":"A teacher has just called your son \"a bit abnormal\", with him sitting right beside you.","steps":[{"prompt":"Everyone waits for your reply. What do you do?","options":[{"text":"Agree, apologise and smooth it over quickly","then":"The teacher nods, relieved. Your son looks down at his shoes."},{"text":"Snap angrily at her and storm out of the room","then":"The door slams. The teacher looks shaken, and your son follows you out in tears."},{"text":"Say nothing and quietly take him home now","then":"The meeting ends politely. He is quiet all the way home."},{"text":"Say calmly that his brain works differently","then":"The teacher blinks. \"Oh. I hadn't thought of it that way.\"","best":true}],"why":"A calm reframe protects him and opens the teacher to understanding."},{"prompt":"The next day, the teacher phones and asks what she could do differently in class. What do you suggest?","options":[{"text":"Ask her to be a bit kinder and more patient with him","then":"She says she always tries to be kind. Nothing changes in class."},{"text":"Send her a long article about neurodiversity to read","then":"She thanks you. Weeks pass, and the article stays unread."},{"text":"Say he would be better off in another school","then":"She sounds hurt. The call ends, and nothing improves."},{"text":"Suggest a quiet seat and warnings before changes","then":"She writes them down. \"I can do those. Thank you.\"","best":true}],"why":"Specific supports give her something she can do tomorrow."},{"prompt":"That evening, your son asks what abnormal means. What do you tell him?","options":[{"text":"Tell him not to worry and to think of something else","then":"He nods, but keeps thinking about it in bed."},{"text":"Tell him the teacher is silly and to ignore her","then":"He giggles, then looks uneasy. \"But I have to see her tomorrow.\""},{"text":"Tell him it means he needs to work harder at school","then":"His face falls. He starts whispering his sums to himself."},{"text":"Tell him nothing is wrong with him","then":"He relaxes. \"So she just doesn't get it?\"","best":true}],"why":"Telling him nothing is wrong, and that others misuse the word, keeps the label off him."},{"prompt":"A month later, the teacher praises something he did. What do you do?","options":[{"text":"Thank her and say you told her so all along","then":"Her smile tightens. The good mood cools."},{"text":"Thank her, but say you doubt it will last","then":"She senses your doubt and says less next time."},{"text":"Tell your son to keep it up so she won't say that word again","then":"His smile fades. He carries the label again."},{"text":"Thank her and share how he likes praise","then":"She listens. \"Quiet praise, then. I'll try that.\"","best":true}],"why":"Building on the good moment, and sharing what works, strengthens the partnership."}],"debrief":"When someone calls your child 'abnormal', calmly reframe it as a different way of being.","relearn":"When a teacher calls your child 'abnormal', calmly reframe it as different wiring; don't accept it or explode."},
  {"id":"nd-1391","cat":"understand-your-child","type":"branch","persona":"Divya","source":"name a strength when tired","hook":"You are exhausted and tempted to see your daughter as \"the difficult one\".","steps":[{"prompt":"It is eight in the evening and she refuses dinner for the third night. What do you do?","options":[{"text":"Tell her she is being difficult again tonight","then":"She pushes the plate away. The word stays in the room."},{"text":"Give her biscuits, just so the evening ends","then":"She munches quietly. You are too tired to feel anything."},{"text":"Tell yourself she does this only to test you","then":"Your jaw tightens, and dinner ends in a stand-off."},{"text":"Pause and name one thing you love in her","then":"You think of her laugh at the dog. Your shoulders drop a little.","best":true}],"why":"A pause and one named strength remind you who she really is."},{"prompt":"Later, her father asks how the day went. What do you say?","options":[{"text":"Say she was impossible again, as always","then":"He sighs. \"She always is these days.\" The label sticks."},{"text":"Say it was fine and nothing more","then":"He nods and returns to his phone. You stay tired and alone with it."},{"text":"Say it's all your fault for being a poor mother","then":"He says: \"Don't say that.\" But the guilt stays."},{"text":"Say it was hard, and share one good thing","then":"He nods. \"Tell me the lovely part first.\"","best":true}],"why":"Sharing the hard and the lovely keeps you both seeing all of her."},{"prompt":"A friend calls your daughter a handful. What do you say?","options":[{"text":"Agree and laugh about how tiring she can be","then":"You both laugh. Later you feel a sting."},{"text":"Say nothing and change the subject quickly","then":"The friend moves on. The label hangs in the air."},{"text":"Complain about her at length","then":"The friend listens. You feel lighter, but she is now a case to discuss."},{"text":"Say she is spirited and name a strength","then":"Your friend laughs. \"I can see that. Tell me more.\"","best":true}],"why":"Naming what you admire shapes how others, and she, see her."},{"prompt":"At school pick-up, her teacher says she was kind to a new classmate today. What do you do?","options":[{"text":"Say good, but ask why she can't be like that always","then":"Her smile fades. \"I was trying.\""},{"text":"Nod quickly and hurry to the car","then":"She walks behind you, quiet. The moment is gone."},{"text":"Tell the teacher she is usually a handful at home","then":"The teacher blinks. Your daughter hears every word."},{"text":"Tell her it sounds just like her","then":"She grins. \"I was just being me.\"","best":true}],"why":"Saying it aloud reminds her, and you, of who she really is."}],"debrief":"Even when tired, see your child's strengths, not only the struggle; what you notice shapes her.","relearn":"When tired, pause and name a strength in your child; what you keep noticing shapes how she sees herself."},
  {"id":"nd-1392","cat":"understand-your-child","type":"spot","hook":"Spot the two lines that misunderstand a neurodiverse child.","scene":[{"id":"a","text":"'His brain works its own way, that's okay'","trick":false},{"id":"b","text":"'He's just doing this for attention'","trick":true},{"id":"c","text":"'Let me learn how he sees the world'","trick":false},{"id":"d","text":"'If I scold him enough, he'll be normal'","trick":true},{"id":"e","text":"'What's he good at? Let's build on that'","trick":false}],"why":"'Doing it for attention' and 'scold him normal' misunderstand him; the others seek to understand and build on strengths.","relearn":"Understand your child by learning how he sees the world and building on strengths, not scolding him 'normal'.","persona":"Meena","source":"two misunderstandings"},
  {"id":"nd-1393","cat":"understand-your-child","type":"spot","hook":"Spot the two myths about neurodivergence in this conversation.","scene":[{"id":"a","text":"'Brains naturally vary, this is human'","trick":false},{"id":"b","text":"'Too much screen time made him this way'","trick":true},{"id":"c","text":"'Every child's profile is their own'","trick":false},{"id":"d","text":"'He'll just grow out of it by ten'","trick":true},{"id":"e","text":"'It comes with real strengths too'","trick":false}],"why":"'Screens caused it' and 'he'll grow out of it' are myths; brains vary, each profile differs, and strengths come too.","relearn":"Screens don't cause neurodivergence and kids don't grow out of it; brains vary and real strengths come too.","persona":"any","source":"two hidden myths"},
  {"id":"nd-1394","cat":"understand-your-child","type":"spot","hook":"Spot the two reactions that turn a diagnosis into a verdict.","scene":[{"id":"a","text":"'This helps me understand and support her'","trick":false},{"id":"b","text":"'Our family's future is ruined now'","trick":true},{"id":"c","text":"'She's the same girl she was yesterday'","trick":false},{"id":"d","text":"'She'll never achieve anything in life'","trick":true},{"id":"e","text":"'Now I know how to get her the right help'","trick":false}],"why":"'Future is ruined' and 'never achieve anything' treat a diagnosis as a verdict; it's information, your child is unchanged.","relearn":"A diagnosis is information to guide support, not a verdict; your child is the same, with help now in reach.","persona":"Divya","source":"diagnosis not a verdict"},
  {"id":"nd-1395","cat":"understand-your-child","type":"spot","hook":"Spot the two deficit-only thoughts in this list of observations.","scene":[{"id":"a","text":"'She remembers everything she reads'","trick":false},{"id":"b","text":"'He's hopeless, can't do anything right'","trick":true},{"id":"c","text":"'He notices what everyone else misses'","trick":false},{"id":"d","text":"'She's nothing but a constant problem'","trick":true},{"id":"e","text":"'Her honesty is actually refreshing'","trick":false}],"why":"'Hopeless' and 'nothing but a problem' see only deficits; the others notice memory, attention and honesty as strengths.","relearn":"Lead with strengths like memory, attention and honesty; 'hopeless' or 'a problem' sees only deficits and wounds a child.","persona":"any","source":"two deficit thoughts"},
  {"id":"nd-1396","cat":"understand-your-child","type":"spot","hook":"Spot the two responses that misread overwhelm as bad behaviour.","scene":[{"id":"a","text":"'The party was too loud, let's step out'","trick":false},{"id":"b","text":"'Stop the drama right now or else'","trick":true},{"id":"c","text":"'You're safe, I'm here, breathe with me'","trick":false},{"id":"d","text":"'He's just being defiant to embarrass us'","trick":true},{"id":"e","text":"'Sudden change is hard for him, I'll warn him'","trick":false}],"why":"'Stop the drama' and 'defiant to embarrass us' misread overwhelm as bad behaviour; the others meet it with calm and warning.","relearn":"Meltdowns are overwhelm, not drama or defiance; meet them with calm, safety and warning, not 'stop it or else'.","persona":"Meena","source":"two misreadings of overwhelm"},
  {"id":"nd-1397","cat":"understand-your-child","type":"spot","hook":"Spot the two things you should never say to a child about their wiring.","scene":[{"id":"a","text":"'I love the way your mind works'","trick":false},{"id":"b","text":"'There's something wrong with you'","trick":true},{"id":"c","text":"'We'll figure this out together'","trick":false},{"id":"d","text":"'Why can't you just be like other kids?'","trick":true},{"id":"e","text":"'Your brain has its own superpowers'","trick":false}],"why":"'Something wrong with you' and 'be like other kids' wound a child; the others affirm their mind is loved and not alone.","relearn":"Never tell a child something's wrong or to be like others; affirm their mind is loved and they're not alone.","persona":"Meena","source":"two things never to say"},
  {"id":"nd-1398","cat":"understand-your-child","type":"spot","hook":"Spot the two beliefs that confuse a child's profile with their worth.","scene":[{"id":"a","text":"'He's a whole, wonderful person'","trick":false},{"id":"b","text":"'He's basically just his diagnosis'","trick":true},{"id":"c","text":"'There's so much more to her than this'","trick":false},{"id":"d","text":"'Her label is the only thing that matters'","trick":true},{"id":"e","text":"'I love him for exactly who he is'","trick":false}],"why":"'Just his diagnosis' and 'the label is all' shrink a child to a profile; the others see the whole, wonderful person they are.","relearn":"A child is a whole person, far more than a diagnosis; never shrink them to a label, love all of who they are.","persona":"Meena","source":"two shrinking beliefs"},
  {"id":"nd-1399","cat":"understand-your-child","type":"spot","hook":"Spot the two 'cure' promises a parent should distrust.","scene":[{"id":"a","text":"'Understanding and support help him thrive'","trick":false},{"id":"b","text":"'This diet will cure his autism fast'","trick":true},{"id":"c","text":"'A professional can guide what helps'","trick":false},{"id":"d","text":"'One course will make him fully normal'","trick":true},{"id":"e","text":"'His wiring is lifelong, and that's okay'","trick":false}],"why":"'A diet that cures autism' and 'a course to make him normal' are false promises; neurodivergence is lifelong, helped by support.","relearn":"Distrust anyone selling a cure; neurodivergence is lifelong and helped by support, not diets or 'normalising' courses.","persona":"Divya","source":"two cure promises"},
  {"id":"nd-1400","cat":"understand-your-child","type":"role-play","persona":"Meena","source":"not spoiled, wired differently","hook":"Your mother is staying with you, and she disapproves of how you handle your son's upsets.","setup":"She speaks up while he plays with his trains in the next room.","steps":[{"prompt":"Your mother says: \"He is just spoiled. He needs strict discipline.\"","options":[{"text":"\"Maybe you're right. I'll be a lot tougher on him.\"","then":"Ma nods, pleased. In the next room the train tracks fall silent."},{"text":"\"Don't tell me how to raise my own child, Ma.\"","then":"Ma's face closes. \"I only wanted to help.\""},{"text":"\"Let's not talk about it now. Have some more tea.\"","then":"Ma sips her tea. \"Fine. But he needs it.\""},{"text":"\"He isn't spoiled, Ma. His brain works differently.\"","then":"Ma frowns. \"In my day, we had no such words.\"","best":true}],"why":"Naming the difference calmly stops the blame without starting a fight."},{"prompt":"Ma says: \"We never let you get away with anything. Look how you turned out.\"","options":[{"text":"\"That was another time, Ma. Things have changed a lot.\"","then":"Ma stiffens. \"Some things don't change.\""},{"text":"\"You're right. Look how I turned out. I survived it.\"","then":"\"Good,\" says Ma. You feel a small ache."},{"text":"\"He isn't like me. Please stop comparing us both.\"","then":"Ma says: \"I'm not comparing. I'm remembering.\""},{"text":"\"You raised me with love. He needs different care.\"","then":"Ma softens. \"Different how?\"","best":true}],"why":"Honouring her love while naming a different need keeps her listening."},{"prompt":"A few days later, he covers his ears at the mixer, and Ma asks: \"Why does he do that?\"","options":[{"text":"\"It's hard to explain. You wouldn't understand it, Ma.\"","then":"Ma's face falls. \"Try me.\""},{"text":"\"The doctor has a name for it. I'll show you the full report.\"","then":"Ma takes it but frowns at the long words."},{"text":"\"He just needs a little time. He'll be fine, Ma.\"","then":"Ma says: \"Time and discipline, then.\""},{"text":"\"Loud noise overwhelms him. It isn't defiance.\"","then":"Ma listens. \"Like the band at the wedding. Was that it?\"","best":true}],"why":"Giving her one clear, concrete example helps her see overwhelm instead of defiance."},{"prompt":"Ma says: \"I want to help. What should I do when he refuses to come to the table?\"","options":[{"text":"\"Tell him firmly that he must come to the table right now.\"","then":"Ma says: \"Firm I can do.\" He comes to the table crying."},{"text":"\"Let him skip the meal. It's easier.\"","then":"Ma says: \"Skip? He'll go hungry.\" She looks worried."},{"text":"\"Call me. I'll handle it.\"","then":"Ma says: \"You'll come every time?\" She sounds tired."},{"text":"\"Warn him two minutes before, and let him bring a toy.\"","then":"Ma nods. \"Two minutes. I can do that.\"","best":true}],"why":"A warning and a comfort object give her a calm, doable way to help."}],"relearn":"Telling a relative your child isn't spoiled but wired differently, needing understanding over strictness, protects him from blame."},
  {"id":"nd-1401","cat":"understand-your-child","type":"role-play","persona":"Divya","source":"different isn't weird","hook":"Your daughter has been dragging her feet about school all week.","setup":"She drops her bag and stands at the door.","steps":[{"prompt":"Your daughter says: \"Everyone calls me weird at school.\"","options":[{"text":"\"Just try to act more like the other kids.\"","then":"She looks down. \"I already try. It's so tiring.\""},{"text":"\"Ignore them. They're just jealous.\"","then":"She shrugs. \"Jealous of what?\""},{"text":"\"Don't be silly. You're not weird.\"","then":"She goes quiet. \"You didn't ask what happened.\""},{"text":"\"Different isn't weird. Your mind is brilliant.\"","then":"She sniffs. \"Do you think so?\"","best":true}],"why":"Saying different isn't weird tells her she is fine as she is."},{"prompt":"Later, she asks: \"Why do they laugh when I flap my hands?\"","options":[{"text":"\"You could try keeping your hands in your pockets.\"","then":"She nods, but her hands shake in her pockets at lunch."},{"text":"\"They laugh because they are silly.\"","then":"She giggles, then stops. \"It still hurts.\""},{"text":"\"Tell me who laughed. I'll speak to their parents.\"","then":"She looks alarmed. \"No. That will make it worse.\""},{"text":"\"Flapping shows your joy. They don't get it yet.\"","then":"She looks at her hands. \"It does feel happy.\"","best":true}],"why":"Explaining that flapping shows joy tells her her body is not wrong."},{"prompt":"She asks: \"Can I still be me at school? Or do I have to hide it?\"","options":[{"text":"\"Hide it a little, just at school.\"","then":"She nods. Her shoulders creep up around her ears."},{"text":"\"Do whatever feels comfortable. I'll leave it to you.\"","then":"She shrugs. \"Okay.\" She looks unsure."},{"text":"\"You must learn to fit in, for your own good.\"","then":"Her eyes fill. \"I don't know how.\""},{"text":"\"You can be you. We'll ask your teacher to help.\"","then":"She smiles. \"Can you come with me on Monday?\"","best":true}],"why":"Telling her she needn't hide, with a plan to ask for help, backs her up."}],"relearn":"Reframing 'weird' as a different, brilliant way of being protects a child's self-worth instead of asking her to mask."},
  {"id":"nd-1402","cat":"understand-your-child","type":"role-play","persona":"Meena","source":"invite the co-parent in","hook":"You have been noticing small things about your son for months, and tonight you bring them up.","setup":"Your husband Rohan is scrolling on the sofa.","steps":[{"prompt":"Rohan says: \"There's nothing different about him. You're imagining it.\"","options":[{"text":"\"Fine. Forget I said anything. I'll handle it alone.\"","then":"Rohan shrugs. \"Good. There's nothing to handle.\""},{"text":"\"You never notice anything about him.\"","then":"Rohan puts down his phone. \"That's not fair.\""},{"text":"\"You're right. Maybe I'm overthinking it.\"","then":"Rohan says: \"Exactly.\" You lie awake that night."},{"text":"\"I'm not imagining it. Let's learn about him together.\"","then":"Rohan looks up. \"Learn what?\"","best":true}],"why":"Inviting him to learn together opens the door without a fight."},{"prompt":"The next evening, Rohan asks: \"What exactly is it that you have noticed?\"","options":[{"text":"\"A hundred things. It's exhausting to explain.\"","then":"Rohan says: \"Then it can't be that serious.\""},{"text":"\"His teacher says it too. Ask her.\"","then":"Rohan says: \"She's just one teacher.\" He isn't convinced."},{"text":"\"I've made a list of everything that's wrong with him.\"","then":"Rohan bristles. \"Don't say wrong. He's my son.\""},{"text":"\"He covers his ears at the mixer. Watch with me.\"","then":"Rohan nods. \"All right. A week.\"","best":true}],"why":"One concrete example, and an invitation to watch, is easier to hear than a list."},{"prompt":"A week on, Rohan says: \"I've been thinking about it. What would you like me to do?\"","options":[{"text":"\"Nothing. Just don't dismiss me again.\"","then":"Rohan looks stung. \"I'll try.\""},{"text":"\"Read every article I've sent you first.\"","then":"Rohan groans. \"There are fifty.\""},{"text":"\"Nothing. I'll do it myself, as always.\"","then":"Rohan nods, relieved and a little ashamed."},{"text":"\"Come with me to see a specialist. We'll ask together.\"","then":"Rohan nods. \"Okay. Book it. I'll take the day off.\"","best":true}],"why":"A shared, concrete step turns his openness into action."},{"prompt":"A few days later, Rohan says: \"My mother says you're overreacting. What should I tell her?\"","options":[{"text":"\"Tell her she's wrong and to stay out of it.\"","then":"Rohan sighs. \"That'll start a war.\""},{"text":"\"Just say everything is fine.\"","then":"Rohan nods. \"Easier that way.\" The question will come back."},{"text":"\"You tell her. She's your mother.\"","then":"Rohan says: \"Fine.\" He avoids the call for days."},{"text":"\"Say we're learning and would love her support.\"","then":"Rohan nods. \"I can say that. I'll call her tonight.\"","best":true}],"why":"A united, kind message brings family in without a fight."}],"relearn":"Inviting a co-parent to learn together, rather than going silent, doubles a child's champions instead of leaving one parent alone."},
  {"id":"nd-1403","cat":"understand-your-child","type":"role-play","persona":"Vikram","source":"honour the passion","hook":"Your son proudly explains planets for ten minutes straight.","setup":"You are stirring dal when he comes in with his book.","steps":[{"prompt":"Your son says: \"Did you know Jupiter has so many moons? And Saturn's rings are made of ice!\"","options":[{"text":"\"Okay, that's enough space talk for today.\"","then":"His face falls. He closes his book."},{"text":"\"Mm-hm, that's nice, beta.\"","then":"He waits. Then he says it all again, louder."},{"text":"\"Where do you learn these things? Focus on homework.\"","then":"His shoulders drop. \"I did homework already.\""},{"text":"\"I love how much you know. Tell me about Saturn.\"","then":"He beams. \"The rings are ice and dust. Can I draw them?\"","best":true}],"why":"Showing delight in his knowledge tells him his passion is treasured."},{"prompt":"He says: \"My friend says planets are boring. Am I boring?\"","options":[{"text":"\"Maybe talk about football with him instead.\"","then":"He frowns. \"But I don't like football.\""},{"text":"\"Forget your friend. He's silly.\"","then":"He giggles, then goes quiet. \"But he's my only friend at lunch.\""},{"text":"\"A little, when you go on and on.\"","then":"He blinks. \"Oh.\" He puts the book away."},{"text":"\"You're not boring. Your interest is wonderful.\"","then":"He nods slowly. \"Can I show him my drawing?\"","best":true}],"why":"Naming his interest as wonderful protects his confidence with friends."},{"prompt":"He says: \"Can we go to the planetarium on Sunday? There's a show.\"","options":[{"text":"\"Maybe next month. This month is busy.\"","then":"He nods. His face dims. \"Okay.\""},{"text":"\"Only if you clean your room and do all your homework.\"","then":"He sighs. \"That's so much.\""},{"text":"\"Sure, but don't talk about planets all day there.\"","then":"He nods. \"I'll try.\" He is already thinking about what not to say."},{"text":"\"Yes, let's go. We'll bring your headphones.\"","then":"He jumps. \"I'll pack my star chart.\"","best":true}],"why":"Saying yes and planning for his senses feeds his passion in the real world."}],"relearn":"Honouring a child's deep interest as a treasured strength feeds his confidence, rather than teaching him his passion is a bother."},
  {"id":"nd-1404","cat":"understand-your-child","type":"role-play","persona":"Meena","source":"nothing to cure","hook":"Your neighbour has heard about your son's diagnosis through the colony grapevine.","setup":"She leans over the fence while he plays in the yard.","steps":[{"prompt":"Your neighbour asks: \"So when will he be cured and normal?\"","options":[{"text":"\"We're trying lots of treatments. Hopefully he'll be normal soon.\"","then":"She nods, pleased. \"Good. Keep trying.\""},{"text":"\"Please don't ask me that.\"","then":"She looks embarrassed. \"Sorry. I only meant well.\""},{"text":"\"That's a rude question.\"","then":"She stiffens. \"I was only asking.\""},{"text":"\"There's nothing to cure. He's wired his own way.\"","then":"She blinks. \"Oh. I didn't know it worked like that.\"","best":true}],"why":"Saying plainly there is nothing to cure rejects the false cure framing calmly."},{"prompt":"She adds: \"My aunt says children like him grow out of it if you try hard.\"","options":[{"text":"\"Maybe. We're hoping for the best.\"","then":"She smiles. \"That's the spirit.\""},{"text":"\"Everyone has their own views on it.\"","then":"She says: \"I think he will grow out of it.\""},{"text":"\"I'm too tired to explain this.\"","then":"She says: \"I understand. Never mind.\""},{"text":"\"It's lifelong, and that's okay. Support helps him flourish.\"","then":"She looks thoughtful. \"Lifelong. I see.\"","best":true}],"why":"Saying it is lifelong, and that support helps, corrects the myth without fear."},{"prompt":"The neighbour says: \"My cousin's son went to a special healer. Shall I give you the number?\"","options":[{"text":"\"Yes, please. It can't hurt to try.\"","then":"She recites the number. \"Ask for Mr Sharma.\""},{"text":"\"Maybe. Let me think about it.\"","then":"She says: \"Take your time. Their fees are steep.\""},{"text":"\"No. Don't interfere in our lives.\"","then":"She flinches. \"I meant no harm.\""},{"text":"\"Thanks, but there's no cure to buy.\"","then":"She nods. \"Alright. I hope it goes well.\"","best":true}],"why":"Kindly declining a cure keeps your money, hope and child safe."},{"prompt":"Days later, she asks: \"What can I do to be a good neighbour to him?\"","options":[{"text":"\"Just leave him alone.\"","then":"She says: \"Alright.\" She stops waving at him."},{"text":"\"Just treat him exactly like the other kids.\"","then":"She nods. \"Easy.\" The next day, she takes his silence as rudeness."},{"text":"\"Nothing. We're fine on our own.\"","then":"She says: \"If you say so.\""},{"text":"\"Greet him warmly and give him time to answer.\"","then":"She grins. \"I'll say hello tomorrow.\"","best":true}],"why":"A simple, warm greeting is a concrete way for a neighbour to help."}],"relearn":"Saying there's nothing to cure, just a different wiring supported to thrive, rejects the false cure framing and the shame behind it."},
  {"id":"nd-1405","cat":"understand-your-child","type":"role-play","persona":"Divya","source":"wonderfully you","hook":"Your daughter's classmates laughed at her again today.","setup":"She has curled up on her bed after school.","steps":[{"prompt":"Your daughter sobs: \"Why am I not like everyone else?\"","options":[{"text":"\"Don't say that. Just try harder to fit in.\"","then":"She cries harder. \"I do try.\""},{"text":"\"You are like everyone else. Stop crying.\"","then":"She turns to the wall. \"You don't get it.\""},{"text":"\"Who said that to you? I'll go to the school.\"","then":"She sits up, alarmed. \"No. Don't go.\""},{"text":"\"Because you're wonderfully you.\"","then":"She wipes her nose. \"Like what?\"","best":true}],"why":"Telling her she is wonderfully herself gives her a truer story than fitting in."},{"prompt":"A little later, she says: \"I can't even do maths as fast as the others.\"","options":[{"text":"\"You're smart at other things, so it doesn't matter.\"","then":"She frowns. \"It matters to me, though.\""},{"text":"\"Maths isn't important. Forget it.\"","then":"She looks doubtful. \"It's in every test.\""},{"text":"\"We'll get a tutor and you'll catch up.\"","then":"She nods flatly. \"More work.\""},{"text":"\"You notice tiny details others miss.\"","then":"She sniffs. \"Like the typo I found in the maths book?\"","best":true}],"why":"Naming a real strength she has shown makes it concrete for her."},{"prompt":"She asks: \"But being different is hard. Will they ever stop laughing?\"","options":[{"text":"\"Yes, they'll get bored and stop very soon.\"","then":"She brightens for a moment. \"Really? When?\""},{"text":"\"Only if you change how you act around them.\"","then":"Her face crumples. \"I don't know how.\""},{"text":"\"Don't care at all what they think of you.\"","then":"She says: \"But I do care.\""},{"text":"\"Some will. Shall we tell your teacher?\"","then":"She hugs her pillow. \"Okay. If you come with me.\"","best":true}],"why":"An honest answer, and her teacher's help at her pace, steadies her more than a promise. It is not her fault they laugh."},{"prompt":"She says: \"I want a friend who gets me. How do I find one?\"","options":[{"text":"\"Just be yourself and the right friends will come.\"","then":"She sighs. \"But how?\""},{"text":"\"Copy how the others talk and they'll like you.\"","then":"She tries at lunch. It feels like wearing a costume."},{"text":"\"You have me. You don't need friends.\"","then":"She smiles sadly. \"I do need them, though.\""},{"text":"\"Let's try the art club. I'll come along.\"","then":"She perks up. \"Okay. Will they have clay?\"","best":true}],"why":"Finding a shared interest, with you beside her, is a practical way to find friends."},{"prompt":"At bedtime, she asks: \"Mumma, is it okay that I sometimes feel sad about all this?\"","options":[{"text":"\"Don't be sad. You're such a wonderful girl.\"","then":"She says: \"But I still feel it.\""},{"text":"\"You shouldn't feel sad. Be grateful for what you have.\"","then":"She turns away. \"Okay.\""},{"text":"\"Sadness fades. Think of something happy.\"","then":"She tries. Her eyes fill again."},{"text":"\"Yes. Feeling sad is okay. I'm here.\"","then":"She nods, eyes heavy. \"Stay till I sleep?\"","best":true}],"why":"Letting her feel sad, with you beside her, keeps her feelings safe to share."}],"relearn":"Reframing 'not like everyone' as a gift rather than a flaw to fix protects a child's sense of being whole and valued."},
  {"id":"nd-1406","cat":"understand-your-child","type":"role-play","persona":"Meena","source":"no one's fault","hook":"Your younger sister has been quiet all evening since hearing about your son's diagnosis.","setup":"She corners you in the kitchen at a family dinner.","steps":[{"prompt":"Your sister whispers: \"Didi, did you do something during the pregnancy? These things don't come from nowhere.\"","options":[{"text":"\"Maybe it was something I did. I keep wondering too.\"","then":"She squeezes your hand. \"We'll never know.\""},{"text":"\"How dare you say that in my house?\"","then":"She flushes. \"I only asked.\""},{"text":"\"Please don't say that. Not tonight.\"","then":"She nods. The question hangs in the kitchen."},{"text":"\"It's no one's fault, Chhoti. This is how he's wired.\"","then":"She blinks. \"Really? Ma said it might be something you ate.\"","best":true}],"why":"Saying it is no one's fault refuses the blame myth for you and for him."},{"prompt":"She says: \"But Ma says it could be karma. Or the screen time.\"","options":[{"text":"\"It could be. I shouldn't have let him watch so much TV.\"","then":"She nods sadly. \"Maybe cut it down.\""},{"text":"\"Let's not talk about karma at dinner.\"","then":"She says: \"Okay. But Ma believes it.\""},{"text":"\"Ma always says silly things.\"","then":"She giggles, then looks uneasy. \"Don't tell her I said.\""},{"text":"\"Neither. Screens and karma don't cause this.\"","then":"She frowns. \"Then what does?\"","best":true}],"why":"Naming the myths and dismissing them clears the blame for good."},{"prompt":"Later, she asks quietly: \"What do the doctors say causes it? I want to understand.\"","options":[{"text":"\"It must come from his father's side, not ours.\"","then":"She nods slowly. \"So it's their fault, then.\""},{"text":"\"I don't know. Ask the doctor.\"","then":"She nods. \"Okay.\" She still whispers to Ma later."},{"text":"\"Some things just happen for a reason.\"","then":"She says: \"Like karma?\" and looks pleased."},{"text":"\"Brains vary. Nothing a parent did caused it.\"","then":"She listens. \"So you were never at fault.\"","best":true}],"why":"Saying brains vary, and that no parent causes it, gives her something true to pass on."},{"prompt":"Ma joins in and says: \"We should not tell anyone else in the family about this.\"","options":[{"text":"\"Okay, Ma. We'll keep it quiet.\"","then":"Ma nods, satisfied. You feel heavy."},{"text":"\"Tell them if you like. I don't care.\"","then":"Ma says: \"I'll say it the right way, then.\""},{"text":"\"We'll tell only close family, and swear them to secrecy.\"","then":"Ma says: \"Good. Secrecy protects us.\""},{"text":"\"I'll tell people when I choose. I won't hide him.\"","then":"Ma sighs. \"As you wish. People will talk.\"","best":true}],"why":"Sharing on your own terms keeps shame from settling in your home."}],"relearn":"Stating plainly it's no one's fault, just how the brain is wired, refuses the blame myths that hurt both parent and child."},
  {"id":"nd-1407","cat":"understand-your-child","type":"role-play","persona":"Divya","source":"explain to a sibling","hook":"Your older son Kabir has been getting impatient with his younger brother Ishaan lately.","setup":"He comes to find you while you tidy the toys.","steps":[{"prompt":"Kabir asks: \"Why does Ishaan act so strange sometimes?\"","options":[{"text":"\"He's just being annoying. Ignore him when he does that.\"","then":"Kabir shrugs. \"He's so annoying.\""},{"text":"\"You'll understand all this when you're older.\"","then":"Kabir sighs. \"You always say that.\""},{"text":"\"Be nice to him. He can't help it, poor thing.\"","then":"Kabir frowns. \"But I'm always the nice one.\""},{"text":"\"Loud places overwhelm him. He isn't strange.\"","then":"Kabir nods slowly. \"So that's why he hates the mela.\"","best":true}],"why":"Explaining that loud places overwhelm him replaces othering with understanding."},{"prompt":"Kabir says: \"It's not fair. Ishaan gets to leave the table and I don't.\"","options":[{"text":"\"Life isn't fair, so get used to it.\"","then":"Kabir crosses his arms. \"Not fair at all.\""},{"text":"\"Fine. You can leave the table too if you want.\"","then":"Kabir grins, then looks confused. \"Really?\""},{"text":"\"He's the special one here. You must understand that.\"","then":"Kabir mutters: \"I'm not special.\""},{"text":"\"It feels unfair. What would help?\"","then":"Kabir thinks. \"A turn to choose the game.\"","best":true}],"why":"Hear his feeling. Ask what he needs. Different needs get different help."},{"prompt":"Kabir asks: \"Can I help him? I don't know how.\"","options":[{"text":"\"No, leave it to me. You're just a child.\"","then":"Kabir shrugs. \"Okay.\" He feels shut out."},{"text":"\"Just don't shout at him or grab his things.\"","then":"Kabir nods. \"I don't shout.\" He looks hurt."},{"text":"\"Teach him to behave like the other kids do.\"","then":"Kabir grimaces. \"How?\""},{"text":"\"Yes. Sit beside him when it gets too loud.\"","then":"Kabir beams. \"I can do that. I'll start after dinner.\"","best":true}],"why":"Giving Kabir a real way to help builds acceptance and closeness."}],"relearn":"Explaining a sibling's wiring with warmth teaches the older child acceptance and empathy instead of othering their brother."},
];

